/* ==== js/map.js ==== */
// ============================================================
//  MAP KIT - every map lives in js/maps/<name>.js and calls defineMap().
//
//  Inside build(k) you can use:
//    k.box(x, y, z, width, height, depth, color, opts)   solid block. x/z = center, y = BOTTOM
//         opts.rot = turn it around the vertical axis (radians), collision follows
//    k.deco(...same...)                                   looks like a box, but you walk through it
//    k.ramp(x, z, width, depth, lowY, highY, upDir, color, opts)
//         upDir = which way it goes UP: '+x' '-x' '+z' '-z'
//         opts.slick = true   -> water slide: you always slide on it
//         opts.base  = height of the ramp's bottom (for ramps on top of things)
//    k.pad(x, y, z, width, depth, power, opts)            jump pad on a surface at height y
//         opts.push = {x, z}  -> also launches you sideways (m/s)
//         opts.hidden = true  -> invisible (bouncy floors)
//    k.water(x, y, z, width, depth, color, opacity)       see-through water surface
//    k.balls(x, y, z, width, depth, count, colors)        pile of balls
//    k.net(x, y, z, width, height, depth, color)          see-through net wall
//    k.wall(x, y, z, width, height, depth)                invisible wall (collision only, can't be wall-kicked)
//    k.bellRope(x, y, z, length, color)                   rope hanging from (x, y, z): walk into it and it swings + rings
//  No up/down or sliding platforms on tag maps please (they feel clunky) - spinning ones (k.mover type 'spin')
//  are fine. Race courses may use sliding ones (pistons, ferries, lifts).
//    k.mover(x, y, z, width, height, depth, color, motion) moving solid box (rides you along, shoves you)
//         motion = { type: 'slide', dx, dy, dz, period, phase }  glides out by (dx,dy,dz) and back
//                  { type: 'spin', speed, phase }                 spins around its center (rad/s)
//    k.balloons(x, y, z, width, height, depth, count, colors)  room of floating balloons that dodge players
//         (x/z = center of the room, y = floor). Soft: never block anyone.
//
//  Box opts: { tex: 'kick' (wall-kick surface: always bright orange-red) | 'net' (see-through)
//              | 'nokick' (old frosted glass - now an ordinary kickable panel, always a neutral grey),
//              noShadow: true, emissive: '#color', opacity: 0..1 }
//  Everything is flat color - other tex/uv values are left over from old textures and do nothing.
//
//  Helpers below: ground(), enclose(), slab(), posts(), stairs(), tower(), bridge(),
//  kickShaft(), pile(), container().
//
//  Environments (env in defineMap):
//    'void'    black void, steel rafters + spotlights
//    'indoor'  build walls + ceiling with enclose(); ceiling lights
//    'sky'     daylight sky with sea at `sea` height
//    'fog'     just the sky color + fog. fogDensity: 0.05 = real exponential fog
//    'space'   black sky, stars and a planet
//
//  Variants (a map that changes with the number of players - The Express's trains):
//    variant(n) -> a short key for n players ('t3c7'...); layout(key) -> { spawns, seekerSpawn, centerSpot };
//    build(k, key) gets the key. The host picks the key; everyone rebuilds the map with it.
//
//  Other defineMap fields:
//    move: { gravity: 13, ... }     override CONFIG.move values on this map (e.g. low gravity)
//    centerSpot: [x, y, z]          where a dropped crown lands (King of the Tag). Default seekerSpawn
//    wrap: 40                       endless map: the 40x40 tile (centered on 0,0) repeats forever -
//                                   walk off an edge and you come in the other side. wrapRings = how
//                                   many copies to draw around it (default 1). Pair it with fog.
//    kind: 'race'                   a race course instead of a tag map, with
//    race: { yaw, finish: { x, y, z, w, h, d }, route: [[x, y, z], ...] }
//         spawns = the start line, finish = the goal box (y = bottom), route = the course's path
//         from start to finish (used for "meters to go" on the leaderboard)
//
//  Handy numbers for designing:
//    - a jump clears ~1.6m; standing height 1.8 -> keep ceilings 3.6m+ above any floor
//    - floors are 4m apart (FLOOR). Jump + mantle reaches ledges ~3.4m up, so a full floor
//      needs stairs, a pad, or a kick shaft to climb
//    - a running jump crosses ~6m gaps, a slide-jump more
//    - kick shafts: two walls 2.6-3m apart, use kickShaft()
//    - a pad with power P launches you about P*P/52 meters up
// ============================================================
const MAPS = [];
const FLOOR = 4;

function defineMap(def) {
  MAPS.push(Object.assign({
    env: 'void',
    sky: '#000000',             // background + fog color
    fog: [45, 130],
    hemi: ['#dff2ff', '#46505e', 0.75],
    sun: [0.8, 30, 60, 20],     // intensity, direction x/y/z
    size: 50,                   // half-size of the area that gets shadows
    killY: -15,                 // fall below this and the void gets you
    menuCam: { r: 40, y: 22 },  // orbit camera behind the main menu
    kind: 'tag',
  }, def));
}

function getMap(id) {
  return MAPS.find((m) => m.id === id) || MAPS[0];
}

// floating floor (top at y = 0) centered on x/z, with a darker edge band underneath
function ground(k, w, d, color, o = {}, x = 0, z = 0) {
  k.box(x, -1.2, z, w, 1.2, d, color, o);
  k.deco(x, -1.7, z, w - 0.4, 0.4, d - 0.4, '#111318', { tex: 'none' });
}

// four walls + a ceiling around a w x d floor centered on 0,0
function enclose(k, w, d, h, wall, ceiling, o = {}) {
  const t = 1, look = { tex: o.tex || 'tiles', uv: o.uv || 0.5 };
  k.box(0, 0, -d / 2 - t / 2, w + 2 * t, h, t, wall, look);
  k.box(0, 0, d / 2 + t / 2, w + 2 * t, h, t, wall, look);
  k.box(-w / 2 - t / 2, 0, 0, t, h, d, wall, look);
  k.box(w / 2 + t / 2, 0, 0, t, h, d, wall, look);
  k.box(0, h, 0, w + 2 * t, 0.6, d + 2 * t, ceiling, Object.assign({ noShadow: true }, look));
}

// thin floor slab whose TOP is at height `top`
function slab(k, x, top, z, w, d, color, o = {}) {
  k.box(x, top - (o.t || 0.5), z, w, o.t || 0.5, d, color, o);
}

// support posts from y0 up to y1 at each [x, z]
function posts(k, list, y0, y1, color, size = 0.4) {
  for (const [x, z] of list) k.box(x, y0, z, size, y1 - y0, size, color, { tex: 'none' });
}

// staircase. (x, z) = center of the bottom edge, dir = direction it climbs.
// The steps are just looks - you walk up a smooth hidden ramp, so it never feels bumpy. The ramp
// runs along the step noses (starting one step before the stairs), so feet never sink into a step.
function stairs(k, x, z, dir, width, y0, y1, color, o = {}) {
  const n = Math.ceil((y1 - y0) / 0.4), run = o.run || 0.7, sg = dir[0] === '+' ? 1 : -1, L = n * run;
  const vis = Object.assign({}, o, { ghost: true });
  for (let i = 0; i < n; i++) {
    const top = y0 + (y1 - y0) * (i + 1) / n, off = (i + 0.5) * run * sg;
    if (dir[1] === 'x') k.box(x + off, y0, z, run, top - y0, width - 0.04, color, vis);
    else k.box(x, y0, z + off, width - 0.04, top - y0, run, color, vis);
  }
  const mid = sg * (n - 2) * run / 2, top = sg * (n - 0.5) * run, H = { hidden: true, base: y0 };
  if (dir[1] === 'x') {
    k.ramp(x + mid, z, L, width, y0, y1, dir, color, H);
    k.ramp(x + top, z, run, width, y1, y1, dir, color, H);
  } else {
    k.ramp(x, z + mid, width, L, y0, y1, dir, color, H);
    k.ramp(x, z + top, width, run, y1, y1, dir, color, H);
  }
}

// slab (top at `top`) covering x0..x1 / z0..z1 with an optional rectangular hole [hx0, hx1, hz0, hz1]
function slabHole(k, x0, x1, z0, z1, top, hole, color, o = {}) {
  const t = o.t || 0.4;
  const put = (a0, a1, b0, b1) => {
    if (a1 - a0 > 0.01 && b1 - b0 > 0.01) k.box((a0 + a1) / 2, top - t, (b0 + b1) / 2, a1 - a0, t, b1 - b0, color, o);
  };
  if (!hole) return put(x0, x1, z0, z1);
  const [hx0, hx1, hz0, hz1] = hole;
  put(x0, hx0, z0, z1);
  put(hx1, x1, z0, z1);
  put(hx0, hx1, z0, hz0);
  put(hx0, hx1, hz1, z1);
}

// Open multi-floor structure (min 10 x 6) with switchback stairs up the inside.
//   x, z       center        w, d     size (x, z)
//   floors     floors above `base`, each `fh` tall (default 4). The roof is walkable.
//   floor      false = don't build a slab at `base` (when it already stands on a roof)
//   flip       stairs run along the +z side instead of -z
//   walls      sides to wall in, e.g. ['+x', '-z']. Each floor gets a doorway in the middle of each wall
//   stairFloors  only this many floors get stairs; above that, a jump pad in the stairwell sends you up
//              through the hole to the next floor
//   color / wall / stair / post / tex / uv    looks
function tower(k, o) {
  const { x, z, w, d, floors, base = 0, fh = FLOOR, color = '#cccccc', flip = false } = o;
  const look = { tex: o.tex, uv: o.uv };
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
  const run = 0.7, L = Math.ceil(fh / 0.4) * run;
  const sA = flip ? [z1 - 2, z1] : [z0, z0 + 2], sB = flip ? [z1 - 4, z1 - 2] : [z0 + 2, z0 + 4];
  const xs = x0 + 1.3, xe = xs + L;
  if (base > 0 && o.floor !== false) slabHole(k, x0, x1, z0, z1, base, null, color, look);
  for (let i = 0; i < floors; i++) {
    const y0 = base + i * fh, y1 = y0 + fh, even = i % 2 === 0, s = even ? sA : sB;
    if (o.stairFloors === undefined || i < o.stairFloors) stairs(k, even ? xs : xe, (s[0] + s[1]) / 2, even ? '+x' : '-x', 2, y0, y1, o.stair || color, Object.assign({ run }, look));
    else k.pad((xs + xe) / 2, y0, (s[0] + s[1]) / 2, 1.6, 1.6, Math.sqrt(52 * (fh + 1.6)), {});
    slabHole(k, x0, x1, z0, z1, y1, [xs, xe, s[0], s[1]], color, look);
    for (const side of o.walls || []) {
      const t = 0.3, gap = 1.3, top = y1 - 0.4, ax = side[1] === 'x', sg = side[0] === '+' ? 1 : -1;
      const c = ax ? z : x, half = ax ? d / 2 : w / 2, pos = ax ? (sg > 0 ? x1 - t / 2 : x0 + t / 2) : (sg > 0 ? z1 - t / 2 : z0 + t / 2);
      const seg = (a, b) => ax ? k.box(pos, y0, (a + b) / 2, t, top - y0, b - a, o.wall || color, look)
                               : k.box((a + b) / 2, y0, pos, b - a, top - y0, t, o.wall || color, look);
      const trim = ax ? 0.32 : 0.02;   // x-side walls stop at the z-side walls' inner faces
      seg(c - half + trim, c - gap);
      seg(c + gap, c + half - trim);
      if (ax) k.box(pos, y0 + 2.6, c, t, top - y0 - 2.6, 2 * gap, o.wall || color, look);
      else k.box(c, y0 + 2.6, pos, 2 * gap, top - y0 - 2.6, t, o.wall || color, look);
    }
  }
  const pc = o.post || '#888888', top = base + floors * fh - 0.4;
  posts(k, [[x0 + 0.2, z0 + 0.2], [x1 - 0.2, z0 + 0.2], [x0 + 0.2, z1 - 0.2], [x1 - 0.2, z1 - 0.2]], base, top, pc, 0.35);
}

// straight walkway between two points that share an x or a z
function bridge(k, ax, az, bx, bz, top, width, color, o = {}) {
  if (ax === bx) slab(k, ax, top, (az + bz) / 2, width, Math.abs(bz - az), color, Object.assign({ t: 0.4 }, o));
  else slab(k, (ax + bx) / 2, top, az, Math.abs(bx - ax), width, color, Object.assign({ t: 0.4 }, o));
}

// Two parallel walls `gap` apart that you climb by wall-kicking back and forth.
// The walls run along `axis` ('x' or 'z') for `len`, centered on x/z, from y0 to y1.
// Striped so you can spot them. Put the top (y1) level with the floor you want to reach.
function kickShaft(k, x, z, axis, len, y0, y1, color, gap = 2.8) {
  const t = 0.5, off = gap / 2 + t / 2, K = { tex: 'kick', uv: 0.5 };
  if (axis === 'x') {
    k.box(x, y0, z - off, len, y1 - y0, t, color, K);
    k.box(x, y0, z + off, len, y1 - y0, t, color, K);
  } else {
    k.box(x - off, y0, z, t, y1 - y0, len, color, K);
    k.box(x + off, y0, z, t, y1 - y0, len, color, K);
  }
}

// brick-stacked shipping containers: each layer is two 6m boxes side by side, alternating direction.
// Climb it layer by layer (each layer overhangs the one below on two sides).
// hollow = list of layer numbers whose containers are open tunnels
function pile(k, x, z, layers, o = {}) {
  const C = 2.6, W = 2.4, colors = o.colors || ['#a8322d', '#23408e'];
  for (let l = 0; l < layers; l++) {
    const alongX = (l + (o.start || 0)) % 2 === 0;
    for (const s of [-1, 1]) {
      const cx = alongX ? x : x + s * W / 2, cz = alongX ? z + s * W / 2 : z;
      container(k, cx, l * C, cz, alongX ? 'x' : 'z', 6, (o.hollow || []).includes(l), colors[(l + (s > 0 ? 1 : 0) + (o.seed || 0)) % colors.length]);
    }
  }
}

// darken a '#rrggbb' color (k < 1) or lighten it (k > 1)
function shade(hex, k) {
  const n = parseInt(hex.slice(1), 16), c = (v) => Math.max(0, Math.min(255, Math.round(v * k)));
  return '#' + [n >> 16, (n >> 8) & 255, n & 255].map((v) => c(v).toString(16).padStart(2, '0')).join('');
}

// one shipping container. bottom at y. hollow ones are open at both ends (run through them).
// rot = extra turn (radians) for skewed containers
function container(k, x, y, z, orient, L, hollow, color, rot = 0) {
  const C = 2.6, W = 2.4, T = 0.15, R = { tex: 'ribs', uv: 0.35, rot }, along = orient === 'x';
  const sx = along ? L : W, sz = along ? W : L;
  // offset a point (lx, lz) from the container center by the skew rotation
  const at = (lx, lz) => [x + lx * Math.cos(rot) + lz * Math.sin(rot), z - lx * Math.sin(rot) + lz * Math.cos(rot)];
  const part = (lx, ly, lz, w, h, d, c, o) => { const [px, pz] = at(lx, lz); return (o.ghost ? k.deco : k.box)(px, y + ly, pz, w, h, d, c, Object.assign({ rot }, o)); };
  if (!hollow) {
    part(0, 0, 0, sx, C, sz, color, R);
    // door panels on the ends: a slightly darker skin, only 2cm proud of the end
    const dc = shade(color, 0.78);
    for (const e of [-1, 1]) {
      if (along) part(e * (L / 2 + 0.01), 0.06, 0, 0.02, C - 0.12, W - 0.1, dc, { ghost: true });
      else part(0, 0.06, e * (L / 2 + 0.01), W - 0.1, C - 0.12, 0.02, dc, { ghost: true });
    }
    return;
  }
  part(0, 0, 0, sx, T, sz, color, R);
  part(0, C - T, 0, sx, T, sz, color, R);
  const DK = '#121620', LO = { ghost: true, tex: 'ribs', outline: false }, off = W / 2 - T - 0.05;
  if (along) {
    part(0, 0, -W / 2 + T / 2, L, C, T, color, R);
    part(0, 0, W / 2 - T / 2, L, C, T, color, R);
    part(0, T + 0.03, -off, L - 0.06, C - 2 * T - 0.06, 0.02, DK, LO);
    part(0, T + 0.03, off, L - 0.06, C - 2 * T - 0.06, 0.02, DK, LO);
  } else {
    part(-W / 2 + T / 2, 0, 0, T, C, L, color, R);
    part(W / 2 - T / 2, 0, 0, T, C, L, color, R);
    part(-off, T + 0.03, 0, 0.02, C - 2 * T - 0.06, L - 0.06, DK, LO);
    part(off, T + 0.03, 0, 0.02, C - 2 * T - 0.06, L - 0.06, DK, LO);
  }
}

;
/* ==== js/maps/rooftops.js ==== */
// ROOFTOPS - a 4x4 city block floating in the void. Buildings are 11m square with 3m alleys, so
// every alley is a kick chimney - fall in and you can still kick your way back up.
// Everything works in floors of 4m:
//   roofs          4 to 24 high
//   penthouses     two stacked blocks on some roofs (hop the step blocks up), linked to neighbours by sky bridges
//   fire escapes   switchback stairs on facades: jump across the alley onto the bottom landing, run up
//                  (C -> B has a plate across the alley: walk straight on)
//   kick signs     big signs standing on a low roof's edge, 3m from a taller building - kick between
//                  the sign (orange) and the facade to climb. Below the roof the alley continues the
//                  chimney all the way down, so they're also the way back up after a fall
//   planks, pads   plank ramps one floor up across an alley (E-A, P-O, G-K, J-I), launch pads for the big height jumps
//   roof toys      stair bulkheads (3m - pull yourself up), slide-under pipe runs
// Kept deliberately plain: three facade colors, one window pattern (lit or dark), one neon color,
// one bulkhead, one pipe - no water towers, skylights or one-off perches.
//
//   roofs (x across, z down):  A  8   B 12   C  4   D 16
//                              E  4   F 24   G 16   H  8
//                              I 12   J  8   K 20   L 12
//                              M  4   N 16   O  8   P  4
defineMap({
  id: 'rooftops',
  accent: ['#1b2140', '#ffd9a0'],
  name: 'Rooftops',
  blurb: 'City roofs over the void. Kick up the alleys, climb fire escapes, cross sky bridges.',
  sky: '#3a3358',                  // dusk: a violet horizon (the fog fades into it)...
  skyGrad: ['#0e1126'],            // ...deep navy overhead
  fog: [55, 170],
  hemi: ['#d6e0ff', '#4a5070', 1.9],
  sun: [1.1, 25, 60, 15],
  size: 32,
  killY: -6,
  menuCam: { r: 42, y: 33 },
  spotHeight: 40,
  spots: [
    { x: -14, z: -14, color: '#ffd9a0', intensity: 2.6 }, { x: 14, z: -14, color: '#a0c8ff', intensity: 2.6 },
    { x: -14, z: 14, color: '#ffa0d0', intensity: 2.6 }, { x: 14, z: 14, color: '#ffd9a0', intensity: 2.6 },
    { x: 0, z: 0, color: '#ffffff', intensity: 2.6 },
  ],
  spawns: [
    [-9.5, 12, -24.5], [5, 4, -18], [23.5, 16, -17.5], [-18.5, 4, -9], [-4, 24, -4], [9, 16, -10],
    [-19, 12, 9.5], [3.5, 20, 3.5], [-5.5, 16, 21], [23, 4, 18], [-10.5, 12, 4.5],
    [10, 12, 23], [23, 16, 8],
  ],
  seekerSpawn: [7, 16, -9],

  build(k) {
    const X = [-21, -7, 7, 21], Z = [-21, -7, 7, 21], B = 11, HB = B / 2;
    const H = [
      [8, 12, 4, 16],    // z = -21   A B C D
      [4, 24, 16, 8],    // z = -7    E F G H
      [12, 8, 20, 12],   // z = 7     I J K L
      [4, 16, 8, 4],     // z = 21    M N O P
    ];
    const FACADE = ['#8a5a44', '#6c7a89', '#a0845c'];   // red, blue, grey (palette.js) - (c + 2r) % 3: neighbours never match
    const ROOF = '#3a3d44', WOOD = '#9c7a4c', STEEL = '#59636e', CONC = '#9aa0a8', DARK = '#2b2f35';
    const NO = { tex: 'none' };
    let seed = 5;
    const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);

    // facades that carry a fire escape get no windows (keeps the balconies readable)
    const noWin = new Set(['1,1,-z', '2,1,-z', '2,2,-x', '0,2,-z', '0,2,+z', '3,2,+z', '1,0,+x']);

    // --- buildings: body + tar roof + cornice, ribbon windows on the upper floors ---
    Z.forEach((z, r) => X.forEach((x, c) => {
      const top = H[r][c];
      k.box(x, -40, z, B, top + 39.7, B, FACADE[(c + 2 * r) % 3]);
      k.box(x, top - 0.3, z, B, 0.3, B, ROOF);
      k.deco(x, top - 0.6, z, B + 0.3, 0.3, B + 0.3, '#c9c3b8', NO);
      for (const face of ['+x', '-x', '+z', '-z']) {
        if (noWin.has(`${c},${r},${face}`)) continue;
        const ax = face[1] === 'x', sg = face[0] === '+' ? 1 : -1, f = (ax ? x : z) + sg * HB;
        for (let y = top - 2.8; y > Math.max(top - 24, -18); y -= 4) {
          for (let i = 0; i < 3; i++) {
            const along = (ax ? z : x) + (i - 1) * 3.3, lit = rnd() < 0.5;
            const col = lit ? '#ffd27a' : '#2a2f3a', em = lit ? '#c98a2a' : undefined;
            const o = { tex: 'none', outline: false, emissive: em };
            if (ax) k.deco(f, y, along, 0.12, 1.5, 2.9, col, o);
            else k.deco(along, y, f, 2.9, 1.5, 0.12, col, o);
          }
        }
      }
    }));

    // --- the street, far below: just the roads ---
    const GY = -40;
    k.deco(0, GY - 1, 0, 220, 1, 220, '#25282e', NO);
    for (const c of [-28, -14, 0, 14, 28]) {
      k.deco(c, GY, 0, 3, 0.05, 220, '#3a3e46', NO);
      k.deco(0, GY + 0.06, c, 220, 0.05, 3, '#3a3e46', NO);
    }

    // --- low parapets (0.7) along the city's outer edge: you don't slide off by accident, and you
    // can still vault them on purpose ---
    for (let r = 0; r < 4; r++) for (let c = 0; c < 4; c++) {
      const top = H[r][c], x = X[c], z = Z[r];
      if (r === 0) k.box(x, top, z - HB + 0.2, B, 0.7, 0.4, CONC);
      if (r === 3) k.box(x, top, z + HB - 0.2, B, 0.7, 0.4, CONC);
      if (c === 0) k.box(x - HB + 0.2, top, z, 0.4, 0.7, B, CONC);
      if (c === 3) k.box(x + HB - 0.2, top, z, 0.4, 0.7, B, CONC);
    }

    // --- penthouses: two stacked blocks on the roof (no stairwells) - hop the step block, pull up
    // onto the lower block (+4), then the next step block onto the upper one (+8) ---
    //   [x0, x1, z0, z1] of the lower block, the upper block, its base, and the two step blocks
    const penthouse = (base, lo, up, step1, step2) => {
      k.box((lo[0] + lo[1]) / 2, base, (lo[2] + lo[3]) / 2, lo[1] - lo[0], 4, lo[3] - lo[2], CONC);
      k.box((up[0] + up[1]) / 2, base + 4, (up[2] + up[3]) / 2, up[1] - up[0], 4, up[3] - up[2], '#d8d2c4');
      k.box(step1[0], base, step1[1], 1.2, 1.2, 1.2, STEEL);
      k.box(step2[0], base + 4, step2[1], 1.2, 1.2, 1.2, STEEL);
    };
    penthouse(8, [-26, -16, -25, -17], [-26, -20, -25, -19], [-17.5, -16.2], [-19.2, -22]);   // A
    penthouse(8, [17, 24.5, -10, -3], [17, 23, -10, -5], [21, -2.2], [23.8, -8]);              // H (1.5m+ of roof all round it)
    penthouse(8, [-11, -3, 3, 10], [-9, -3, 6, 10], [-7, 2.2], [-9.8, 8]);                   // J (1.5m+ of roof all round it)
    penthouse(8, [2, 12, 17, 24.4], [2, 8, 17, 22], [7, 25.2], [8.8, 20]);                      // O
    penthouse(12, [16, 26, 3, 11], [16, 20, 3, 9], [21, 11.8], [20.8, 6]);                   // L

    // --- sky bridges (12, 16 and 20) ---
    bridge(k, -16, -21, -12.5, -21, 12, 2, STEEL);   // A penthouse 12 -> B
    bridge(k, 17, -9, 12.5, -9, 16, 2, STEEL);       // H penthouse roof -> G
    bridge(k, 21, -10, 21, -15.5, 16, 2, STEEL);     // H penthouse roof -> D
    bridge(k, -11, 7, -15.5, 7, 12, 2, STEEL);       // J penthouse 12 -> I
    bridge(k, -7, 10, -7, 15.5, 16, 2, STEEL);       // J penthouse roof -> N
    bridge(k, 2, 18.5, -1.5, 18.5, 16, 2, STEEL);    // O penthouse roof -> N
    bridge(k, 21, 3, 21, -3, 16, 2, STEEL);          // L penthouse 16 -> H penthouse roof
    bridge(k, 16, 4, 12.5, 4, 20, 2, STEEL);         // L penthouse roof -> K

    // --- plank ramps across alleys (one floor up) ---
    k.ramp(15, 21, 5, 1.2, 4, 8, '-x', WOOD, { base: 3.8 });     // P -> O
    k.ramp(-21, -13, 1.2, 5, 4, 8, '-z', WOOD, { base: 3.8 });   // E -> A
    k.ramp(3.5, 0, 1.2, 5, 16, 20, '+z', WOOD, { base: 15.8 });   // G -> K
    k.ramp(-14, 11.5, 5, 1.2, 8, 12, '-x', WOOD, { base: 7.8 });  // J -> I

    // --- launch pads for the big height jumps ---
    k.pad(10.6, 16, -7, 1.4, 1.4, 22, {});   // G -> the 24 tower F
    k.pad(10, 4, -17.5, 1.4, 1.4, 26, {});     // C -> G
    k.pad(-21, 4, 25.4, 1.4, 1.4, 23, {});    // M -> I

    // --- fire escapes: real stairs. Two lanes against the facade (2m out into the 3m alley): a
    // flight up the inner lane, a landing, a flight back down the outer lane... one floor (4m) per
    // flight, landings at both ends. Jump across the alley onto the bottom landing (it's level with
    // the roof across the way) and run up; the last landing is level with the roof.
    // face = which side of building (c, r) they hang on; they climb from `low` to the roof
    const fireEscape = (c, r, face, low, gang) => {
      const top = H[r][c], ax = face[1] === 'x', sg = face[0] === '+' ? 1 : -1;
      const f = (ax ? X[c] : Z[r]) + sg * HB, mid = ax ? Z[r] : X[c];
      const LW = 1.0, LAND = 1.4, RUN = 0.55, FL = Math.ceil(4 / 0.4) * RUN;   // a flight: 10 steps, 5.5m
      const a0 = mid - (LAND * 2 + FL) / 2, a1 = a0 + LAND + FL;                // the two landing ends
      const IRON = '#3d434c', RAIL = '#2a2e35';
      // something along the facade: lane offset `o` out from it, from a to b along it
      const put = (a, b, o, d, y, h, color, deco) => {
        const cx = f + sg * o, ca = (a + b) / 2, la = b - a;
        if (ax) (deco ? k.deco : k.box)(cx, y, ca, d, h, la, color, NO);
        else (deco ? k.deco : k.box)(ca, y, cx, la, h, d, color, NO);
      };
      const flights = (top - low) / 4;
      for (let i = 0; i <= flights; i++) {
        const y = low + i * 4, atStart = i % 2 === 0, la = atStart ? a0 : a1;
        // landing across both lanes (the top one is level with the roof)
        put(la, la + LAND, 1.0, 2 * LW, y - 0.3, 0.3, IRON);
        put(la, la + LAND, 2 * LW - 0.03, 0.06, y, 1.0, RAIL, true);   // rail on the outside
        if (i === flights) break;
        // the flight up to the next landing: inner lane going one way, outer lane coming back
        const inner = i % 2 === 0, lane = inner ? LW / 2 : LW * 1.5;
        const along = inner ? a0 + LAND : a1, dir = (inner ? '+' : '-') + (ax ? 'z' : 'x');
        if (ax) stairs(k, f + sg * lane, along, dir, LW, y, y + 4, IRON, { run: RUN, tex: 'none' });
        else stairs(k, along, f + sg * lane, dir, LW, y, y + 4, IRON, { run: RUN, tex: 'none' });
        if (!inner) put(a0 + LAND, a1, 2 * LW - 0.03, 0.06, y + 0.9, 0.06, RAIL, true);   // handrail along the outer flight
      }
      // gang: a plate across the rest of the alley from the bottom landing to the roof opposite
      if (gang) put(a0, a0 + LAND, 2.5, 1.0, low - 0.3, 0.3, IRON);
    };
    fireEscape(1, 1, '-z', 12);   // B 12 -> F 24
    fireEscape(2, 1, '-z', 4);    // C 4  -> G 16
    fireEscape(2, 2, '-x', 8);    // J 8  -> K 20
    fireEscape(0, 2, '-z', 4);    // E 4  -> I 12
    fireEscape(0, 2, '+z', 4);    // M 4  -> I 12 (the way down onto M without the big drop - CPUs use it too)
    fireEscape(3, 2, '+z', 4);    // P 4  -> L 12
    fireEscape(1, 0, '+x', 4, true);    // C 4  -> B 12, walk straight onto it

    // --- kick signs: stand on a low roof's edge, 3m from the taller facade across the alley ---
    const NEON = '#ffb13d';
    const kickSign = (x, z, alongZ, len, y0, y1, side) => {
      if (alongZ) k.box(x, y0, z, 0.4, y1 - y0, len, DARK, { tex: 'kick' });
      else k.box(x, y0, z, len, y1 - y0, 0.4, DARK, { tex: 'kick' });
      // lit panel on the back of the sign (the side facing the low roof)
      const o = { tex: 'none', emissive: NEON, outline: false }, h = Math.min(6, y1 - y0 - 2);
      if (alongZ) k.deco(x + side * 0.24, y0 + 1.2, z, 0.1, h, len - 1, NEON, o);
      else k.deco(x, y0 + 1.2, z + side * 0.24, len - 1, h, 0.1, NEON, o);
    };
    kickSign(12.3, -21, true, 6, 4, 16, -1);     // C -> D
    kickSign(-15.7, 21, true, 6, 4, 16, -1);     // M -> N
    kickSign(7, 15.7, false, 6, 8, 20, 1);       // O -> K
    kickSign(-15.7, -7, true, 6, 4, 24, -1);     // E -> F (the long one)
    kickSign(15.7, -3.4, true, 3.8, 8, 16, 1);   // H -> G

    // --- the tower's antenna ---
    k.deco(-7, 24, -7, 0.3, 8, 0.3, '#bbbbbb', NO);
    k.deco(-7, 32, -7, 0.5, 0.5, 0.5, '#ff2030', { tex: 'none', emissive: '#ff2030' });

    // --- stair bulkheads (3m: jump and pull up), all alike ---
    const bulk = (x, y, z) => k.box(x, y, z, 3, 3, 3, CONC);
    bulk(-4, 12, -23.5); bulk(4, 4, -23.5); bulk(-24, 4, -9); bulk(9.5, 16, -3.5); bulk(-23, 4, 23.5);
    bulk(24, 4, 24);

    // --- for chases on the open roofs: slide-under pipe runs (bottom 1.15m) ---
    const pipe = (x, z, top, len, alongX) => {
      const h = len / 2;
      for (const e of [-1, 1]) k.box(alongX ? x + e * (h + 0.15) : x, top, alongX ? z : z + e * (h + 0.15), 0.3, 1.45, 0.3, STEEL, NO);
      k.box(x, top + 1.15, z, alongX ? len : 0.3, 0.3, alongX ? 0.3 : len, '#c8ccd2', NO);
    };
    pipe(5.5, -20.5, 4, 4.5, true); // C
    pipe(-22, -4.5, 4, 4, false); // E
    pipe(-19.5, 22, 4, 4, false); // M
    pipe(18, 19, 4, 4, false); // P
  },
});

;
/* ==== js/maps/shipyard.js ==== */
// CONTAINER YARD - a port terminal of container piles on a dock, sea all around.
//   piles      4 x 4 grid of brick-stacked piles, 1 to 7 layers (2.6m each, up to 18.2m).
//              Each layer overhangs the one below, so you climb them ledge by ledge.
//   alleys     3-4m between piles - wall-kick up them
//   bridges    hollow containers laid across alleys between piles of the same height:
//              run through them at pile-top level, or along their roofs
//   skewed     containers dumped at angles on the dock and on top of piles (real collision)
//   leaners    containers tipped against the edge piles as ramps
//   crane      gantry beam 21m up; the pad on the tallest pile launches you onto it. Its trolley
//              and hanging spreader are solid - the spreader is a perch over the middle alley
//   kick lanes  an orange shaft up one alley (to 15.6, past the shorter pile) and at both ends of the crane
defineMap({
  id: 'shipyard',
  accent: ['#a8322d', '#23408e'],
  name: 'Container Yard',
  blurb: 'A port terminal by the sea. Container piles up to 18m, container bridges, skewed stacks, a crane.',
  env: 'sky',
  sky: '#a9d6ff',
  fog: [90, 300],
  hemi: ['#eaf4ff', '#5a6470', 0.9],
  sun: [1.0, 30, 55, 20],
  size: 30,
  sea: -2,
  killY: -4,
  menuCam: { r: 34, y: 24 },
  spawns: [
    [-9, 0, -9], [0, 0, 0], [9, 0, 9], [-9, 0, 9], [9, 0, -9], [0, 0, -9], [0, 0, 9],
    [-9, 0, 0], [9, 0, 0], [-21, 0, -6], [21, 0, 4], [-13.5, 7.8, -4.5],
  ],
  seekerSpawn: [4.5, 18.2, 6],

  build(k) {
    const RED = '#a8322d', BLUE = '#23408e', GREY = '#b9bcc1', GREEN = '#2f7d4f', R = { tex: 'ribs', uv: 0.35 };
    ground(k, 52, 52, '#646a73');
    for (const [x, z, w, d] of [[0, -25.8, 52, 0.4], [0, 25.8, 52, 0.4], [-25.8, 0, 0.4, 52], [25.8, 0, 0.4, 52]]) {
      k.deco(x, 0, z, w, 0.03, d, '#ffd23f', { tex: 'none' });
    }
    for (let v = -22; v <= 22; v += 11) for (const s of [-1, 1]) {
      k.box(v, 0, s * 25.2, 0.5, 0.7, 0.5, '#2b2f35', { tex: 'none' });
      if (v !== 0) k.box(s * 25.2, 0, v, 0.5, 0.7, 0.5, '#2b2f35', { tex: 'none' });   // (the kick towers stand at v = 0)
    }

    // --- the piles: LAYERS[row][col], row = z, col = x ---
    const P = [-13.5, -4.5, 4.5, 13.5];
    const LAYERS = [
      [2, 2, 4, 1],
      [3, 6, 6, 4],
      [4, 6, 7, 2],
      [1, 4, 4, 2],
    ];
    const HOLLOW = { '0,1': [0], '1,0': [0, 2], '1,2': [1], '2,3': [0], '3,2': [0], '2,0': [2], '0,2': [0], '3,1': [1] };
    LAYERS.forEach((row, r) => row.forEach((n, c) => {
      pile(k, P[c], P[r], n, {
        start: (r + c) % 2, seed: r * 3 + c, hollow: HOLLOW[`${r},${c}`] || [],
        colors: (r + c) % 3 === 2 ? [GREY, RED] : [RED, BLUE],
      });
    }));

    // --- container bridges between equal-height piles (hollow: run through or over) ---
    container(k, -9.3, 5.2, -13.5, 'x', 6, true, GREEN);     // (-13.5,-13.5) <-> (-4.5,-13.5) at 5.2
    container(k, -0.3, 15.6, -4.5, 'x', 6, true, GREY);      // (-4.5,-4.5)  <-> (4.5,-4.5)   at 15.6
    container(k, -4.5, 15.6, 0.3, 'z', 6, true, GREEN);      // (-4.5,-4.5)  <-> (-4.5,4.5)   at 15.6
    container(k, -0.3, 10.4, 13.5, 'x', 6, true, BLUE);      // (-4.5,13.5)  <-> (4.5,13.5)   at 10.4

    // --- skewed containers ---
    container(k, 4.5, 10.4, -13.5, 'x', 6, false, BLUE, 0.5);    // dumped askew on top of a pile
    container(k, -13.5, 2.6, 13.5, 'z', 6, false, RED, -0.35);
    container(k, 13.5, 5.2, 4.5, 'x', 6, false, GREY, 0.3);
    container(k, -21, 0, 8, 'z', 6, false, BLUE, 0.4);           // on the dock
    container(k, 21.5, 0, -12, 'z', 6, true, RED, -0.45);
    container(k, 11, 0, 21.5, 'x', 6, false, GREY, 0.2);
    container(k, 11, 2.6, 21.3, 'x', 6, false, RED, -0.15);
    container(k, -10, 0, -21.5, 'x', 6, false, GREEN, -0.3);

    // --- leaners against the edge piles ---
    k.ramp(-19, -13.5, 5, 2.4, 0, 2.6, '+x', BLUE, R);
    k.ramp(19, -4.5, 5, 2.4, 0, 2.6, '-x', RED, R);
    k.ramp(-4.5, 18.4, 2.4, 5, 0, 2.6, '-z', RED, R);
    k.ramp(13.5, -19, 2.4, 5, 0, 2.6, '+z', BLUE, R);

    // --- gantry crane over the middle alley (z = 0) ---
    const Y = '#f1c40f';
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 21, 0, sz * 2.2, 1.2, 21, 1.2, Y, { tex: 'none' });
    k.box(0, 21, 0, 43.2, 0.8, 3, Y, { tex: 'grid' });
    // trolley, cable and spreader - all solid, hung over the east end (clear of the pad's flight)
    k.box(13.5, 19.4, 0, 3, 1.6, 2.6, '#c0392b');
    k.box(13.5, 12, 0, 0.14, 7.4, 0.14, '#222222', { tex: 'none' });
    k.box(13.5, 11.4, 0, 4.4, 0.6, 2.6, '#c0392b');
    k.pad(4.5, 18.2, 3, 1.2, 1.2, 15, { aim: [4.5, 0, 2.8] });
    // kick towers just past each end of the beam: wall-kick up from the dock, step onto the beam
    for (const s of [-1, 1]) kickShaft(k, s * 23.5, 0, 'x', 3, 0, 21.8, Y);
    // CPU climb route: up the alley past the 3-layer pile (7.8) to 15.6 (the other alleys are chimneys
    // between two piles already)
    kickShaft(k, -9, -7, 'z', 3, 0, 15.6, '#ff6a3d');
    k.ramp(6.5, -0.5, 1.2, 4.2, 15.6, 18.2, '+z', '#9c7a4c', { base: 15.4 });
    slab(k, 6.5, 18.2, 2, 1.2, 0.8, '#9c7a4c', { t: 0.3 });
    container(k, 13.5, 0, 17.7, 'x', 6, false, BLUE);

    // --- for chases on the dock: pipe racks across the lanes (bottom 1.2m - slide under) and low
    // crates to vault or circle round ---
    const rack = (x, z, len, alongX) => {
      const h = len / 2;
      for (const e of [-1, 1]) k.box(alongX ? x + e * (h + 0.15) : x, 0, alongX ? z : z + e * (h + 0.15), 0.3, 1.5, 0.3, '#2b2f35', { tex: 'none' });
      k.box(x, 1.2, z, alongX ? len : 0.3, 0.3, alongX ? 0.3 : len, '#f1c40f', { tex: 'none' });
    };
    rack(4.5, -9, 2.4, false);
    rack(-4.5, 9, 2.4, false);
    rack(-9, -4.5, 2.4, true);
    rack(9, 4.5, 2.4, true);
    for (const [x, z] of [[0, -4.5], [0, 4.5], [-4.5, 0], [4.5, 0], [-19, -17.5], [19, 17.5], [-17.5, 19], [17.5, -19]]) {
      k.box(x, 0, z, 1.3, 1.0, 1.3, '#b49a7c', { tex: 'none' });
    }
  },
});

;
/* ==== js/maps/corridors.js ==== */
// THE CORRIDORS - two floors of looping 3m-wide hallways (an office maze). Built from the ASCII
// grids below - each character is a 3x3m cell, so you can redraw the map right here.
//
//   ground floor (G)                upper floor (U)
//   #  wall                         #  wall
//   .  corridor                     .  corridor (floor on top of the ground floor)
//   v  vent - 3m crawl tunnel       w  low wall to vault
//   w  low wall to vault            o  shaft: hole down to the ground floor. The corridor under it
//   c  crate to juke around            is a kick chimney - wall-kick up through it, or drop down
//                                   S  stairwell hole (stairs below)
//
// Ground floor ceiling is 3.6m up, upper floor ceiling 4.4m up - nothing to bump your head on.
const CORRIDOR_G = [
  '#############',
  '#..c..#.....#',
  '#.###.#.###.#',
  '#.#.......#.#',
  '#.#.##w##.#.#',
  '#...#...#...#',
  '###.v.#.v.###',
  '#...#...#...#',
  '#.#.##w##.#.#',
  '#.#.......#.#',
  '#.###.#.###.#',
  '#.....#..c..#',
  '#############',
];
const CORRIDOR_U = [
  '#############',
  '#...........#',
  '#.##.###.##S#',
  '#o#.......#S#',
  '#.#.#.#.#.#S#',
  '#.....#.....#',
  '#.##w.#.w##.#',
  '#.....#.....#',
  '#S#.#.#.#.#.#',
  '#S#.......#o#',
  '#S##.###.##.#',
  '#...........#',
  '#############',
];

defineMap({
  id: 'corridors',
  accent: ['#c3a6ff', '#a8dcef'],
  name: 'The Corridors',
  blurb: 'Two floors of looping 3m hallways. Vents to slide through, kick shafts between floors, stairwells.',
  env: 'indoor',
  sky: '#141824',
  fog: [22, 60],
  hemi: ['#ffffff', '#7a86a3', 1.25],
  sun: [0.45, 4, 60, 6],
  size: 22,
  spotHeight: 8,
  spots: [-12, 0, 12].flatMap((x) => [-12, 0, 12].map((z) => ({ x, z }))),
  menuCam: { path: [[-15, 5.8, 15], [9, 5.8, 15]] },   // drifts down the long south corridor upstairs
  spawns: [
    [-15, 0, -15], [15, 0, 15], [-15, 0, 15], [15, 0, -15], [-3, 0, 0], [3, 0, 0],
    [0, 0, -9], [0, 0, 9], [-6, 4, -15], [6, 4, 15], [-15, 4, 0], [15, 4, 0],
  ],
  seekerSpawn: [-3, 0, 0],

  build(k) {
    const N = 13, S = 3, F1 = 4, TOP = 8.4;
    const X = (c) => (c - (N - 1) / 2) * S, Z = (r) => (r - (N - 1) / 2) * S;
    const W = N * S;
    const T = { tex: 'tiles', uv: 0.5 };
    const REGION = ['#8fb4ff', '#ff8fa3', '#7ed6c8', '#ffd166'];   // wall colors by quarter
    const col = (r, c) => REGION[(r < N / 2 ? 0 : 2) + (c < N / 2 ? 0 : 1)];
    const g = (r, c) => (CORRIDOR_G[r] || '')[c] || '#';
    const u = (r, c) => (CORRIDOR_U[r] || '')[c] || '#';

    ground(k, W, W, '#e3e8ef', T);
    enclose(k, W, W, TOP, '#eef2f6', '#f6f8fb');

    const hole = (r, c) => u(r, c) === 'o' || u(r, c) === 'S';
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
      const x = X(c), z = Z(r), G = g(r, c), U = u(r, c);
      const wall = { tex: 'grid', uv: 0.5 };
      // ground floor (walls stop under the upper floor slab)
      if (G === '#') k.box(x, 0, z, S, F1 - 0.4, S, col(r, c), wall);
      else if (G === 'v') k.box(x, 1.2, z, S, F1 - 1.6, S, '#b7bcc6', { tex: 'grid', uv: 0.5 });   // crawl under
      else if (G === 'w') k.box(x, 0, z, S, 1.0, S, '#f2f4f7', { tex: 'foam' });
      else if (G === 'c') k.box(x, 0, z, 1.4, 1.2, 1.4, '#c7a77a', { tex: 'planks' });
      // upper floor
      if (U === '#') k.box(x, F1, z, S, TOP - F1, S, col(r, c), wall);
      else if (U === 'w') k.box(x, F1, z, S, 1.0, S, '#f2f4f7', { tex: 'foam' });
    }
    // the upper floor: one slab per row, broken only by the shaft and stairwell holes
    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N;) {
        if (hole(r, c)) { c++; continue; }
        let e = c;
        while (e + 1 < N && !hole(r, e + 1)) e++;
        slab(k, (X(c) + X(e)) / 2, F1, Z(r), (e - c + 1) * S, S, '#e3e8ef', Object.assign({ t: 0.4 }, T));
        c = e + 1;
      }
    }

    // stairwells (under the S holes), 7m long, topping out where the hole meets the upper floor:
    // the west one climbs north, the east one climbs south
    const RUN = 7;
    stairs(k, X(1), Z(8) - S / 2 + RUN, '-z', S, 0, F1, '#c3a6ff', T);
    stairs(k, X(11), Z(4) + S / 2 - RUN, '+z', S, 0, F1, '#c3a6ff', T);

    // --- for chases: slide bars (bottom 1.2m - slide under, you keep your speed) and posts to
    // circle round in the long straight runs ---
    const BAR = '#3a3f4b', POST = '#f2f4f7';
    for (const [x, y, z, alongZ] of [[-6, 0, -9, true], [6, 0, 9, true], [-3, 0, 12, false], [3, 0, -12, false], [0, F1, -9, true], [0, F1, 9, true]]) {
      k.box(x, y + 1.2, z, alongZ ? 0.3 : S, 0.3, alongZ ? S : 0.3, BAR, { tex: 'none' });
    }
    for (const [x, z] of [[3, -15], [-3, 15]]) k.box(x, 0, z, 0.8, F1 - 0.4, 0.8, POST);
    for (const [x, z] of [[-6, 15], [6, -15]]) k.box(x, F1, z, 0.8, TOP - F1, 0.8, POST);
  },
});

;
/* ==== js/maps/fog.js ==== */
// FOG - one suburban street at dusk, swallowed by thick drifting fog. Hedges ring the block, with
// an invisible wall on top so nobody can leave. Three ways around, and they cross everywhere:
//   street      parked cars and a van to hop, streetlights, trees whose crowns you can stand on
//   yards       front yards, then backyards split by vaultable fences (1m) and privacy fences (2m)
//   roofs       gable roofs (eaves 3.8, ridges 5.8) you run straight over, a garage roof (3.0),
//               a two-storey corner house (7.6) with a water tank and a back balcony
// Getting up:  the side alleys (3m) are wall-kick chimneys up the house walls to the eaves; sheds and
//              the garage are steps; trampolines bounce you onto roofs; a treehouse rope bridge runs
//              to the balcony. The park has a kick tower, a fort, a lookout deck, a merry-go-round.
// Ceilings: nothing low hangs over a floor - overhangs and canopies are 3.8m+ up.
defineMap({
  id: 'fog',
  accent: ['#8f98a8', '#ffd88a'],
  name: 'Fog',
  blurb: 'A suburban street lost in fog. Run the roofs, hop the fences, kick up the side alleys.',
  env: 'fog',
  sky: '#7f889a',
  fog: [7, 40],
  fogDensity: 0.055,       // real (exponential) fog, thicker with distance
  hemi: ['#e2e8f5', '#5a6070', 2.5],
  sun: [1.3, 20, 50, 30],
  size: 26,
  menuCam: { path: [[-20, 2.6, 0.6], [15, 2.6, 0.6]] },
  spawns: [
    [-14, 0, 0], [14, 0, 0], [-4, 0, 1.5], [3, 0, -1.5],
    [-17.5, 0, -18], [-11.5, 0, -20], [4, 0, -16.5], [21.5, 0, -21],
    [-17, 0, 17], [-10.5, 0, 16.5], [0, 0, 10], [8.5, 0, 16.5], [21.5, 0, 18.5],
    [6.5, 5.8, -11], [-9, 5.8, 11], [18.5, 7.6, -11],
  ],
  seekerSpawn: [0, 0, 0],

  build(k) {
    // palette: a handful of bold colors
    const GRASS = '#6b7d5c', ROAD = '#474b54', CURB = '#a9a59c', HEDGE = '#4a5f44';
    const FENCE = '#e6e0d4', WOOD = '#9c7653', TRUNK = '#5e4a3a', LEAF = '#5a7550', TRIM = '#e6e0d4';
    const SAND = '#d8bf8f', SAGE = '#8fa8a4', BRICK = '#b8644a', SLATE = '#4c5260', RUST = '#7a463c', RED = '#b5524b', BLUE = '#3f5a7a';
    const LIT = { emissive: '#9a6a20' }, KICK = { tex: 'kick' };
    const E = 3.8, R = 2.0, O = 0.3;   // eave height, roof rise, eave overhang

    // ---- ground, street, sidewalks, hedge ring with an invisible wall above it ----
    ground(k, 49, 49, GRASS);
    for (const s of [-1, 1]) {
      k.box(0, 0, s * 24, 47, 3, 1, HEDGE);                 // back hedges
      k.box(s * 24, 0, 0, 1, 3, 49, HEDGE);                 // side hedges (they close off the street too)
      k.wall(0, 3, s * 24, 49, 40, 1);
      k.wall(s * 24, 3, 0, 1, 40, 49);
    }
    k.deco(0, 0, 0, 47, 0.02, 6, ROAD);
    for (const s of [-1, 1]) k.box(0, 0, s * 3.75, 47, 0.15, 1.5, CURB);

    // ---- houses ----
    // ridge 'x' = roof slopes to the front and back (gables face the alleys); ridge 'z' = slopes
    // left and right. ov = overhang per side [west, east, north, south] (only on eave sides, and
    // never over an alley or a back wall - an overhang above you would cap your jumps there).
    let wi = 0;
    const win = (x, y, z, alongX, lit) => {
      const o = lit ? LIT : {};
      if (alongX) k.deco(x, y, z, 1.2, 1.3, 0.08, lit ? '#ffd88a' : '#3b4250', o);
      else k.deco(x, y, z, 0.08, 1.3, 1.2, lit ? '#ffd88a' : '#3b4250', o);
    };
    const house = (x0, x1, z0, z1, body, roof, ridge, ov, door, frontNorth) => {
      const w = x1 - x0, d = z1 - z0, cx = (x0 + x1) / 2, cz = (z0 + z1) / 2;
      k.box(cx, 0, cz, w, E, d, body);
      const [ow, oe, on, os] = ov;
      // the two halves overlap a hair at the ridge, so there's no seam to slip through
      const q = 0.02;
      // (the second half is 1cm narrower along the ridge so the two gable ends never share a face)
      if (ridge === 'x') {
        k.ramp(cx, (z0 - on + cz + q) / 2, w, cz + q - z0 + on, E, E + R, '+z', roof, { base: E });
        k.ramp(cx, (cz - q + z1 + os) / 2, w - 0.01, z1 + os - cz + q, E, E + R, '-z', roof, { base: E });
      } else {
        k.ramp((x0 - ow + cx + q) / 2, cz, cx + q - x0 + ow, d, E, E + R, '+x', roof, { base: E });
        k.ramp((cx - q + x1 + oe) / 2, cz, x1 + oe - cx + q, d - 0.01, E, E + R, '-x', roof, { base: E });
      }
      // front: door + porch step + two windows; back: two windows
      const fz = frontNorth ? z0 : z1, fs = frontNorth ? -1 : 1, bz = frontNorth ? z1 : z0;
      k.deco(cx, 0.3, fz + fs * 0.04, 1.1, 2.2, 0.08, door);
      k.box(cx, 0, fz + fs * 0.6, 1.8, 0.3, 1.2, TRIM);
      for (const wx of [x0 + 1.8, x1 - 1.8]) win(wx, 1.1, fz + fs * 0.04, true, (wi++ % 3) !== 1);
      void bz;
      // picket fence with a gap for the walkway
      const fzl = frontNorth ? 4.575 : -4.575;
      for (const [a, b] of [[x0 + 0.4, cx - 0.9], [cx + 0.9, x1 - 0.4]]) k.box((a + b) / 2, 0, fzl, b - a, 0.9, 0.15, FENCE);
    };

    // north row (fronts face the street at z = -7)
    house(-23.5, -15.5, -15, -7, SAND, SLATE, 'z', [O, 0, 0, 0], RED, false);
    house(-12.5, -4.5, -15, -7, SAGE, RUST, 'x', [0, 0, 0, O], BLUE, false);
    house(2.5, 10.5, -15, -7, BRICK, SLATE, 'x', [0, 0, 0, O], BLUE, false);
    // south row (fronts face the street at z = 7)
    house(-23.5, -16, 7, 15, BRICK, SLATE, 'x', [0, 0, O, 0], BLUE, true);
    house(-13, -5, 7, 15, SAND, RUST, 'z', [0, O, 0, 0], RED, true);
    house(5, 13, 7, 15, SAGE, SLATE, 'x', [0, 0, O, 0], RED, true);
    house(16, 23.5, 7, 15, SAND, RUST, 'z', [0, O, 0, 0], BLUE, true);
    // chimneys on the ridges (a little vault while you run the roofline)
    k.box(-10, E, -11, 0.8, R + 0.9, 0.8, RUST);
    k.box(-9, E, 9.2, 0.8, R + 0.9, 0.8, RUST);
    k.box(11, E, 11, 0.8, R + 0.9, 0.8, RUST);

    // two-storey corner house (flat roof 7.6, parapet on the street + hedge sides, water tank)
    const T = 7.6;
    k.box(18.5, 0, -11, 10, T, 8, BRICK);
    k.box(18.5, T, -7.15, 10, 0.6, 0.3, SAND);
    k.box(23.35, T, -11.15, 0.3, 0.6, 7.7, SAND);
    k.box(20.5, T, -12, 2.2, 2.0, 2.2, WOOD);
    k.deco(18.5, 0.3, -6.96, 1.1, 2.2, 0.08, BLUE);
    k.box(18.5, 0, -6.4, 1.8, 0.3, 1.2, TRIM);
    for (const wx of [15.5, 21.5]) { win(wx, 1.1, -6.96, true, true); win(wx, 4.6, -6.96, true, wx > 20); }
    win(18.5, 4.6, -6.96, true, false);
    for (const [a, b] of [[13.9, 17.6], [19.4, 23.1]]) k.box((a + b) / 2, 0, -4.575, b - a, 0.9, 0.15, FENCE);
    // back balcony at 4.4 (rail on part of the back + the east side)
    slab(k, 17.5, 4.4, -17.4, 5, 4.8, FENCE, { t: 0.3 });
    posts(k, [[15.2, -19.6], [19.8, -19.6]], 0, 4.1, FENCE, 0.3);
    k.box(18.75, 4.4, -19.74, 2.5, 1.0, 0.12, FENCE);
    k.box(19.94, 4.4, -17.34, 0.12, 1.0, 4.68, FENCE);
    k.deco(17, 4.4, -15.04, 1.1, 2.2, 0.08, BLUE);
    k.box(16, 0, -20.8, 1.2, 1.2, 1.2, WOOD);                 // crates: steps up to the balcony
    k.box(16, 1.2, -21.0, 0.8, 0.6, 0.8, WOOD);

    // ---- garage between the north houses + its driveway ----
    k.box(-2.5, 0, -11.5, 4, 3.0, 7, CURB);
    k.deco(-2.5, 0, -7.96, 3.2, 2.4, 0.08, FENCE);

    // ---- side alleys: no kick panels - wall-kick up the houses themselves ----
    // north-east alley: plain walls (still kickable), a gate to vault
    k.box(12, 0, -12.5, 3, 1.0, 0.15, FENCE);

    // ---- backyard fences (1m pickets to vault, 2m privacy fences to climb) ----
    const fenceZ = (x, z0, z1, h, c) => k.box(x, 0, (z0 + z1) / 2, 0.15, h, z1 - z0, c);
    fenceZ(-14, -23.5, -15, 1.0, FENCE);
    fenceZ(-4.5, -23.5, -15, 2.0, WOOD);
    fenceZ(1, -23.5, -15, 1.0, FENCE);
    fenceZ(12, -23.5, -20.2, 2.0, WOOD); fenceZ(12, -18.6, -15, 2.0, WOOD);   // gate gap (clear of the shed's corner)
    fenceZ(-14.5, 15, 23.5, 1.0, FENCE);
    fenceZ(14.5, 15, 23.5, 1.0, FENCE);
    k.box(-5, 0, 19.25, 0.8, 1.2, 8.5, HEDGE);                 // park edges
    fenceZ(5, 15, 23.5, 2.0, WOOD);

    // ---- north yards ----
    k.box(-20, 0, -20, 2.4, 2.6, 2.4, WOOD);                     // shed
    k.pad(-0.7, 0, -22.3, 1.6, 1.6, 16, { look: 'tramp', color: BLUE });
    k.box(-1.8, 0, -20, 1.8, 0.75, 0.9, WOOD);                    // picnic table + benches
    k.box(-1.8, 0, -21, 1.8, 0.45, 0.35, WOOD);
    k.box(-1.8, 0, -19, 1.8, 0.45, 0.35, WOOD);
    // treehouse: trunk, platform at 4.4, shed to climb, rope bridge to the balcony, canopy on top
    k.box(6.2, 0, -19, 0.9, 4.1, 0.9, TRUNK);
    slab(k, 6.2, 4.4, -19, 4.4, 4, WOOD, { t: 0.3 });
    k.box(4.1, 4.4, -19, 0.15, 1.0, 3.9, TRUNK);
    k.box(5.3375, 4.4, -20.9, 2.325, 1.0, 0.15, TRUNK);       // leaves the shed side open
    k.box(6.2, 4.4, -19, 0.6, 3.6, 0.6, TRUNK);               // (solid, but too high to climb onto)
    k.box(6.2, 8.0, -19, 3.6, 1.8, 3.2, LEAF);
    k.wall(6.2, 9.8, -19, 3.6, 30, 3.2);   // nobody on the canopy (a running jump off the corner house reached it - a perch no CPU could follow you to)
    k.box(10.2, 0, -21.4, 2.4, 2.6, 2.4, SAGE);                    // shed
    slab(k, 11.7, 4.4, -19, 6.6, 1.2, WOOD, { t: 0.3 });          // rope bridge

    // ---- south yards ----
    k.box(-20.2, 0, 20.2, 2.4, 2.6, 2.4, SAGE);                    // shed
    k.box(-9.5, 0, 19.5, 5, 0.9, 5, FENCE);                        // raised pool
    // its water like Lighthouse Rocks' sea: clear blue, a band of pale shallows and a white line of
    // foam round the rim (looks only: flat layers 2cm apart on the pool's top)
    const POOL = { tex: 'none', outline: false, noShadow: true };
    k.deco(-9.5, 0.9, 19.5, 4.4, 0.02, 4.4, '#f2fbff', POOL);
    k.deco(-9.5, 0.92, 19.5, 4.1, 0.02, 4.1, '#2f9cc0', POOL);
    k.deco(-9.5, 0.94, 19.5, 3.1, 0.02, 3.1, '#13609a', POOL);
    k.box(9.25, 0, 21, 4.5, 3.0, 5, CURB);                         // detached garage
    k.deco(9.25, 0, 18.46, 3.4, 2.4, 0.08, FENCE);
    k.pad(17.2, 0, 18.6, 1.6, 1.6, 16, { look: 'tramp', color: RED });

    // ---- the park (between the south houses): fort + slide, lookout deck, kick tower, tree ----
    k.deco(0, 0, 14.5, 9.2, 0.02, 15, SAND);
    k.box(-3.65, 0, 18.75, 1.9, 2.6, 2.5, BLUE);                  // (well clear of the deck's post and the kick wall)
    k.ramp(-3.4, 15.75, 1.0, 3.5, 0, 2.6, '+z', RED);
    slab(k, 0, 4.4, 18.75, 3, 3.5, FENCE, { t: 0.3 });
    posts(k, [[-1.35, 17.15], [1.35, 17.15], [-1.35, 20.35], [1.35, 20.35]], 0, 4.1, FENCE, 0.3);
    k.box(0, 4.4, 20.44, 3, 1.0, 0.12, FENCE);
    k.box(-1.7, 0, 14.9, 0.3, 4.4, 4.2, '#e86a3d', KICK);
    k.box(1.7, 0, 14.9, 0.3, 4.4, 4.2, '#e86a3d', KICK);
    k.box(3.4, 0, 14.5, 0.7, 5.2, 0.7, TRUNK);                // the park tree: a tall poplar, solid, its top out of reach
    k.box(3.6, 5.2, 14.5, 2.7, 4.6, 4, LEAF);
    posts(k, [[-3.9, 9.5], [-0.9, 9.5]], 0, 2.6, SLATE, 0.2);  // swing frame
    k.box(-2.4, 2.6, 9.5, 3.2, 0.15, 0.2, SLATE);
    k.mover(2.6, 0, 9.8, 2.4, 0.35, 2.4, SAND, { type: 'spin', speed: 1.1 });   // merry-go-round

    // ---- street: parked cars, a van, trees you can climb, streetlights ----
    const car = (x, z, c) => {
      k.box(x, 0, z, 4.2, 1.0, 1.9, c);
      k.box(x - 0.2, 1.0, z, 2.4, 0.6, 1.7, FENCE);
    };
    car(-19, -1.9, BLUE); car(-8, -1.9, RED); car(6.5, -1.9, SAGE);
    car(-10, 1.9, SAND); car(9, 1.9, BRICK);
    k.box(19, 0, 1.9, 5, 2.4, 2.1, FENCE);                         // van
    const tree = (x, z) => { k.box(x, 0, z, 0.4, E, 0.4, TRUNK); k.box(x, E, z, 2.6, 1.2, 2.6, LEAF); };
    tree(-14, -5.3); tree(14.5, 5.3);
    const lamp = (x, z, s) => {
      k.box(x, 0, z, 0.18, 4.6, 0.18, '#3d434d');
      k.deco(x, 4.6, z - s * 0.5, 0.12, 0.12, 1.0, '#3d434d');
      k.deco(x, 4.42, z - s * 0.9, 0.4, 0.18, 0.5, '#fff1c4', { emissive: '#e8c87a' });
    };
    lamp(-17, -3.9, -1); lamp(4.5, -3.9, -1); lamp(18, -3.9, -1);
    lamp(-19, 3.9, 1); lamp(-2.5, 3.9, 1); lamp(11, 3.9, 1);

    // --- for chases: flatbed trailers parked in the street (deck bottom 1.2m - slide under, or
    // climb on top), and low garden walls to vault in the back yards ---
    for (const [x, z] of [[18, -1.5], [-18.2, 1.5]]) {
      k.box(x, 1.2, z, 4.4, 0.3, 1.9, CURB);
      k.box(x, 1.5, z - 0.8, 4.4, 0.6, 0.3, SLATE);
      k.box(x, 1.5, z + 0.8, 4.4, 0.6, 0.3, SLATE);
      for (const ex of [-1, 1]) for (const ez of [-1, 1]) k.box(x + ex * 2.05, 0, z + ez * 0.8, 0.3, 1.2, 0.3, '#2b2f35', { tex: 'none' });
    }
    k.box(18, 0, -18.5, 3.2, 1.0, 0.5, FENCE);
    k.box(-20, 0, 17, 0.5, 1.0, 3.0, FENCE);
  },
});

