/* ==== js/maps/playhouse.js ==== */
// THE PLAYHOUSE - a soft-play hall: a 3x3 grid of big padded play towers in four bold colors, with
// 3m alleys between them. Every alley is a kick chimney.
//   towers        hollow 10x10 rooms, 4.4 / 8.8 / 13.2 tall, a floor every 4.4. Doors on most sides
//                 of every level, so the ground is a maze of rooms and alleys, and the upper doors
//                 face each other across the alleys - jump door to door.
//                 Inside, a step block under a hole in each floor: hop, pull up, keep climbing.
//                 Every room also has a cream vault block in a free corner, and every roof under
//                 13.2 a cream cap block (2.2) - a hop up toward the next tower.
//   balloon room  the middle cell, two floors tall and open on top, full of balloons that dodge
//                 you. A rope bridge crosses it at 4.4 between two windows.
//   alleys        vault walls, slide bars (a vault and a bar on every outer side), and slide-under
//                 plugs that break the outer loop
//   trampolines   at two alley crossings: up onto the blue roof (8.8) and the blue lookout (13.2)
// Ceilings are 4.0 over every floor and 3.8 over the 13.2 lookouts - no head bumping.
defineMap({
  id: 'playhouse',
  accent: ['#e5484d', '#2f6fdb'],
  name: 'The Playhouse',
  blurb: 'A soft-play hall of big colored towers and kick alleys, with a room full of balloons in the middle.',
  env: 'indoor',
  sky: '#141824',
  fog: [45, 110],
  hemi: ['#ffffff', '#c4cbe0', 1.5],
  sun: [0.5, 4, 60, 6],
  size: 24,
  spotHeight: 16.7,
  spots: [-13, 0, 13].flatMap((x) => [-13, 0, 13].map((z) => ({ x, z }))),
  menuCam: { path: [[-19.5, 11, -6.5], [19.5, 11, -6.5]] },
  spawns: [
    [-19.5, 0, -19.5], [19.5, 0, 19.5], [-19.5, 0, 0], [19.5, 0, 0], [10, 0, -19.5], [-10, 0, 19.5],
    [3, 0, -6.5], [2, 0, 6.5], [-13, 0, -13], [13, 0, 13], [-13, 0, 0], [13, 0, 0],
    [0, 4.4, -13], [-13, 4.4, 0], [13, 4.4, 13], [0, 8.8, 13],
  ],
  seekerSpawn: [-6.5, 0, -6.5],

  build(k) {
    const LV = 4.4, TOP = 17, T = 10, A = 3, C = [-13, 0, 13], t = 0.6, half = T / 2;
    const RED = '#e5484d', BLUE = '#2f6fdb', YEL = '#f5c331', GREEN = '#2fb36b', CREAM = '#f2efe8', DARK = '#2b3038';
    const solid = (x0, x1, y0, y1, z0, z1, c, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, c, o);
    // a straight wall from A to B with rectangular holes {a, b, y0, y1}
    const PH_segs = (a0, b0, h, holes, put) => {
      const cuts = [a0, b0, ...holes.flatMap((o) => [o.a, o.b])].filter((v) => v >= a0 && v <= b0).sort((p, q) => p - q);
      for (let i = 0; i < cuts.length - 1; i++) {
        const a = cuts[i], b = cuts[i + 1], m = (a + b) / 2;
        if (b - a < 0.01) continue;
        let y = 0;
        for (const o of holes.filter((q) => q.a <= m && q.b >= m).sort((p, q) => p.y0 - q.y0)) {
          if (o.y0 > y) put(a, b, y, o.y0);
          y = Math.max(y, o.y1);
        }
        if (y < h) put(a, b, y, h);
      }
    };
    const door = (c, lvl) => ({ a: c - 1.5, b: c + 1.5, y0: lvl * LV, y1: lvl * LV + 3.6 });
    const crawl = (c) => ({ a: c - 1, b: c + 1, y0: 0, y1: 1.2 });
    const win = (c, lvl) => ({ a: c - 1.5, b: c + 1.5, y0: lvl * LV, y1: lvl * LV + 3.6 });

    ground(k, 42, 42, '#d6dbe2');
    enclose(k, 42, 42, TOP, '#3a4260', '#2e3550');

    // ---- a tower: hollow room stack. doors = { n: [levels], e: [...], s: [...], w: [...] } ----
    let holeN = 0;
    const tower = (cx, cz, H, color, doors, crawls = {}) => {
      const x0 = cx - half, x1 = cx + half, z0 = cz - half, z1 = cz + half;
      const holesFor = (side, c) => (doors[side] || []).map((l) => door(c, l)).concat(side in crawls ? [crawl(c + crawls[side])] : []);
      // north/south walls span the full width, east/west walls sit between them
      PH_segs(x0, x1, H, holesFor('n', cx), (a, b, y0, y1) => solid(a, b, y0, y1, z0, z0 + t, color));
      PH_segs(x0, x1, H, holesFor('s', cx), (a, b, y0, y1) => solid(a, b, y0, y1, z1 - t, z1, color));
      PH_segs(z0 + t, z1 - t, H, holesFor('w', cz), (a, b, y0, y1) => solid(x0, x0 + t, y0, y1, a, b, color));
      PH_segs(z0 + t, z1 - t, H, holesFor('e', cz), (a, b, y0, y1) => solid(x1 - t, x1, y0, y1, a, b, color));
      // a floor every 4.4 (the last one is the roof), each with a hole in a corner and a step block
      // under it on the floor below
      const n = Math.round(H / LV), qs = [];
      const corner = (q, d) => [cx + (q % 2 ? 1 : -1) * d, cz + (q > 1 ? 1 : -1) * d];
      for (let l = 1; l <= n; l++) {
        const q = (holeN++) % 4, sx = q % 2 ? 1 : -1, sz = q > 1 ? 1 : -1;
        qs[l] = q;
        const hx = cx + sx * 2.6, hz = cz + sz * 2.6;   // the hole is 3.6 wide so you clear its edge when you hop on the block
        slabHole(k, x0 + t, x1 - t, z0 + t, z1 - t, l * LV, [hx - 1.8, hx + 1.8, hz - 1.8, hz + 1.8], l === n ? color : CREAM, { t: 0.4 });
        solid(hx - 1, hx + 1, (l - 1) * LV, (l - 1) * LV + 2.2, hz - 1, hz + 1, CREAM);
      }
      // every room gets a cream vault block in a free corner; every roof under 13.2 a cream cap
      // block (2.2) to climb on - roofs sit at 4.4 / 6.6 / 8.8 / 11.0 / 13.2, one hop apart
      for (let m = 0; m < n; m++) {
        const [vx, vz] = corner((qs[Math.max(1, m)] + 2) % 4, 2.6);
        solid(vx - 0.8, vx + 0.8, m * LV, m * LV + 1.0, vz - 0.8, vz + 0.8, CREAM);
      }
      if (n < 3) {
        const [ux, uz] = corner((qs[n] + 2) % 4, 3.3);
        solid(ux - 1, ux + 1, n * LV, n * LV + 2.2, uz - 1, uz + 1, CREAM);
      }
    };
    //            x      z     height  color   doors by side (levels)                      crawl holes
    tower(C[0], C[0], 2 * LV, RED,   { e: [0, 1], s: [0, 1], w: [0] }, { n: 0 });
    tower(C[1], C[0], LV,     YEL,   { e: [0], s: [0], w: [0] });
    tower(C[2], C[0], 3 * LV, BLUE,  { w: [0, 1, 2], s: [0, 1, 2], n: [0] });
    tower(C[0], C[1], LV,     GREEN, { n: [0], e: [0], s: [0] }, { w: 0 });
    tower(C[2], C[1], 2 * LV, RED,   { w: [0, 1], n: [0, 1], s: [0] });
    tower(C[0], C[2], 3 * LV, YEL,   { n: [0, 1], e: [0, 1, 2] }, { w: 0 });
    tower(C[1], C[2], 2 * LV, BLUE,  { n: [0], w: [0, 1], e: [0, 1] });
    tower(C[2], C[2], LV,     GREEN, { n: [0], w: [0], s: [0] }, { e: 0 });

    // ---- the balloon room: the middle cell, two floors of walls, open on top ----
    {
      const H = 2 * LV, x0 = -half, x1 = half, z0 = -half, z1 = half, W = '#f2efe8';
      PH_segs(x0, x1, H, [door(0, 0)], (a, b, y0, y1) => solid(a, b, y0, y1, z0, z0 + t, W));
      PH_segs(x0, x1, H, [door(0, 0)], (a, b, y0, y1) => solid(a, b, y0, y1, z1 - t, z1, W));
      PH_segs(z0 + t, z1 - t, H, [door(-2.5, 0), win(0, 1)], (a, b, y0, y1) => solid(x0, x0 + t, y0, y1, a, b, W));
      PH_segs(z0 + t, z1 - t, H, [door(2.5, 0), win(0, 1)], (a, b, y0, y1) => solid(x1 - t, x1, y0, y1, a, b, W));
      slab(k, 0, LV, 0, T - 2 * t, 2.4, DARK, { t: 0.4 });                      // rope bridge, window to window
      solid(1.5, 3.5, 0, 2.2, 2.4, 4.2, CREAM);                                 // step back up to it
      k.balloons(0, 0, 0, T - 2 * t, H, T - 2 * t, 75,
        ['#e5484d', '#2f6fdb', '#f5c331', '#2fb36b', '#ff8a3d', '#8f5bff', '#ffffff'], { seed: 5 });
    }

    // ---- kick chimneys in the alleys: panels on both walls of each, in the towers' own colors
    // (the tower walls are kickable anyway - no orange needed) ----
    const pair = (axis, mid, a, b, h, c0, c1) => {
      // axis 'x': the alley runs along z at x = mid; panels on both walls from z = a..b
      if (axis === 'x') { solid(mid - 1.5, mid - 1.3, 0, h, a, b, c0); solid(mid + 1.3, mid + 1.5, 0, h, a, b, c1); }
      else { solid(a, b, 0, h, mid - 1.5, mid - 1.3, c0); solid(a, b, 0, h, mid + 1.3, mid + 1.5, c1); }
    };
    pair('x', -6.5, -17.5, -14.6, LV, RED, YEL);        // red NW / yellow N -> the yellow roof
    pair('z', -6.5, 8.2, 11.3, 2 * LV, BLUE, RED);      // blue NE / red E -> the red roof
    pair('z', 6.5, 8.2, 11.3, LV, RED, GREEN);          // red E / green SE -> the green roof
    pair('z', -6.5, -17.5, -14.6, LV, RED, GREEN);      // red NW / green W -> the green roof
    pair('x', -6.5, 14.6, 17.5, 2 * LV, YEL, BLUE);     // yellow SW / blue S -> the blue roof
    pair('x', 6.5, 14.6, 17.5, LV, BLUE, GREEN);        // blue S / green SE -> the green roof

    // ---- the alleys: vaults, slide bars, and plugs you slide under (they break the outer loop) ----
    const vaultX = (x, z) => solid(x - 0.3, x + 0.3, 0, 1.0, z - 1.5, z + 1.5, CREAM);
    const vaultZ = (x, z) => solid(x - 1.5, x + 1.5, 0, 1.0, z - 0.3, z + 0.3, CREAM);
    vaultZ(-6.5, 0); vaultZ(6.5, 13); vaultX(0, -6.5); vaultX(-13, 6.5);
    const barX = (x, z) => solid(x - 0.2, x + 0.2, 1.25, 1.6, z - 1.5, z + 1.5, DARK);
    const barZ = (x, z) => solid(x - 1.5, x + 1.5, 1.25, 1.6, z - 0.2, z + 0.2, DARK);
    barZ(6.5, -2); barX(13, -6.5); barX(-2, 6.5); barZ(-6.5, 11);
    // the outer alley: a vault and a slide bar on every side
    vaultZ(19.5, 10); vaultZ(-19.5, -10); vaultX(10, 19.5); vaultX(-10, -19.5);
    barZ(-19.5, 16); barZ(19.5, -13); barX(16, -19.5); barX(-16, 19.5);
    // outer alley plugs: solid 1.2..4.4 across the alley - slide under, or run over the top
    const plug = (x0, x1, z0, z1, c) => solid(x0, x1, 1.2, LV, z0, z1, c);
    plug(-21, -18, 4.5, 8.5, GREEN);
    plug(18, 21, -8.5, -4.5, RED);
    plug(-8.5, -4.5, 18, 21, YEL);
    plug(4.5, 8.5, -21, -18, BLUE);

    // ---- trampolines at two alley crossings ----
    k.pad(5.8, 0, -5.8, 1.6, 1.6, 27.5, { look: 'tramp', color: BLUE });  // -> the blue lookout (13.2)
    k.pad(-6.5, 0, 6.5, 1.6, 1.6, 24, { look: 'tramp', color: RED });     // -> the blue tower roof (8.8)
  },
});

;
/* ==== js/maps/moon.js ==== */
// MOON BASE - a lunar base on a slab of rock floating in space. Low gravity: jumps are high and
// long (apex ~2.4m, a running jump clears ~11m) and you fall slowly, so everything is spaced out.
//   the rift      a 10m chasm down the middle, straight into the void. Cross it on the south
//                 catwalk, through the north tube, over the gantry at 10 - or just jump it
//   west          three habitat modules (A north, C middle, B south) joined by tubes. Doors on every
//                 side, side doors in the tubes, and the roofs (5m) make a second path on top (a
//                 wall kick off any hab wall gets you up - low gravity)
//   the deck      a 10m platform, reached by the orange kick shaft or the crate + storage rack.
//                 The gantry runs from it across the rift to the comm tower
//   comm tower    14m. Up by the gantry balcony, the orange kick shaft on its east face, or the
//                 zig-zag ledges on its south face
//   east          lander (run under it, climb on it from the crate), a cargo stack, the rover,
//                 solar panels to slide under, and a crater whose pad throws you up to the dish
// Heights: hab roofs 5, containers 5.2, lander 6.4, dish 6, deck/gantry 10, tower 14.
defineMap({
  id: 'moon',
  accent: ['#c3a6ff', '#1b1f2e'],
  name: 'Moon Base',
  blurb: 'Low gravity on a rock floating in space. Habitats and tubes, a rift, a gantry, a comm tower.',
  env: 'space',
  sky: '#04050a',
  fog: [90, 240],
  hemi: ['#f2f4ff', '#3a3f55', 2.1],
  sun: [1.3, 30, 60, 20],
  size: 36,
  killY: -14,
  planet: { x: -150, y: 95, z: -230, r: 38, color: '#5b8fd8', land: '#7fc48f' },
  move: {
    gravity: 14,       // a bit over half: floaty, but you still come down in time to keep chasing
    jumpSpeed: 8.2,    // apex ~2.4m, ~1.2s in the air
    wallKickUp: 7.6,   // ~2m per kick
    wallKickForward: 6.5,
    maxFall: 24,
    coyoteTime: 0.14,
  },
  menuCam: { r: 44, y: 26 },
  spawns: [
    [-21, 0, 18], [-22, 0, 1], [-21, 0, -16], [8, 0, 19], [-9, 0, 9], [-6, 0, -20],
    [14, 0, -9], [22.5, 0, 4.5], [25.5, 0, -13], [26, 0, 15], [-28.5, 0, -4], [-28.5, 0, 25.5],
    [19, 0, 25.5], [-21, 5, 9],
  ],
  seekerSpawn: [-9, 10, -2],

  build(k) {
    const ROCK = '#7c808b', ROCK2 = '#686c77', ROCK3 = ROCK, DUST = '#9a9ea8';
    const HAB = '#f6f4ee', LILAC = '#c3a6ff', MINT = '#7ed6c8', PINK = '#ff8fa3', BLUE = '#8fb4ff', YEL = '#ffd166';
    const STEEL = '#59606e', PANEL = '#3c4f8c', DARK = '#2b2f38';

    // ---------- the rock: two halves with the rift between, and a crater hole in the east ----------
    const rock = (x0, x1, z0, z1, top = 0) => k.box((x0 + x1) / 2, -6, (z0 + z1) / 2, x1 - x0, top + 6, z1 - z0, DUST);
    rock(-30, -5, -27, 27);                 // west
    rock(5, 28, -27, 13);                   // east, south of the crater
    rock(5, 13, 13, 27);                    // east, beside the crater
    rock(23, 28, 13, 27);
    rock(13, 23, 23, 27);
    k.box(18, -6, 18, 10, 3, 10, ROCK2);    // crater floor at -3
    // the underside: smaller and smaller chunks, so it reads as a floating rock
    k.deco(-17.5, -9, 0, 22, 3, 48, ROCK2);
    k.deco(16.5, -9, -2, 20, 3, 44, ROCK2);
    k.deco(-17, -12, 2, 14, 3, 32, ROCK2);
    k.deco(16, -12, -4, 14, 3, 28, ROCK2);

    // ---------- helpers ----------
    // habitat module: walls 5 high with the roof set between them (ceiling 4.6), so the outside is
    // one clean ledge to pull up onto. doors = [[side, offset along the wall], ...]
    const DW = 2.8, DH = 3.4, WH = 5, T = 0.4;
    const wallRun = (side, cx, cz, len, doors, color, h = WH) => {
      // a straight wall along one side, cut by door openings (offsets from its middle)
      const ax = side === 'x';   // wall runs along x
      const cuts = doors.slice().sort((a, b) => a - b);
      let a = -len / 2;
      const seg = (s0, s1) => {
        if (s1 - s0 < 0.05) return;
        const m = (s0 + s1) / 2, L = s1 - s0;
        if (ax) k.box(cx + m, 0, cz, L, h, T, color); else k.box(cx, 0, cz + m, T, h, L, color);
      };
      for (const c of cuts) {
        seg(a, c - DW / 2);
        if (h - DH > 0.05) { if (ax) k.box(cx + c, DH, cz, DW, h - DH, T, color); else k.box(cx, DH, cz + c, T, h - DH, DW, color); }
        a = c + DW / 2;
      }
      seg(a, len / 2);
    };
    const hab = (cx, cz, w, d, trim, doors, h = WH, wall = HAB) => {
      const D = (s) => doors.filter((x) => x[0] === s).map((x) => x[1]);
      wallRun('z', cx - w / 2 + T / 2, cz, d, D('-x'), wall, h);
      wallRun('z', cx + w / 2 - T / 2, cz, d, D('+x'), wall, h);
      wallRun('x', cx, cz - d / 2 + T / 2, w - 2 * T, D('-z'), wall, h);
      wallRun('x', cx, cz + d / 2 - T / 2, w - 2 * T, D('+z'), wall, h);
      slab(k, cx, h, cz, w - 2 * T, d - 2 * T, trim, { t: 0.4 });
    };
    // tube: walkway with walls and a roof (top 5), side doors at the given offsets
    const tube = (ax, x0, x1, at, sideDoors = [], floor = false) => {
      const len = x1 - x0, mid = (x0 + x1) / 2, off = DW / 2 + 0.2;
      const along = ax === 'x';
      for (const s of [-1, 1]) {
        if (along) wallRun('x', mid, at + s * off, len, sideDoors, HAB);
        else wallRun('z', at + s * off, mid, len, sideDoors, HAB);
      }
      if (along) slab(k, mid, 5, at, len, 2 * off - T, '#d9dce3', { t: 0.4 });
      else slab(k, at, 5, mid, 2 * off - T, len, '#d9dce3', { t: 0.4 });
    };
    const boulder = (x, z, w, h, d, rot = 0, c = ROCK) => k.box(x, 0, z, w, h, d, c, { rot });

    // ---------- west: habitats A (north), C (middle), B (south) ----------
    hab(-21, 18, 12, 9, LILAC, [['+x', 0], ['-z', 0], ['-x', -2], ['+z', -3]]);
    hab(-22, 1, 10, 8, MINT, [['+z', 1], ['-z', 1], ['+x', 0], ['-x', 2]]);
    hab(-21, -16, 12, 9, PINK, [['+z', 0], ['+x', -3], ['-z', -3], ['-x', 2]]);
    tube('z', 5, 13.5, -21, [0]);           // A <-> C, side doors in the middle
    tube('z', -11.5, -3, -21, [0]);         // C <-> B
    // north tube: A -> across the rift -> hab D. Side doors west of the rift.
    tube('x', -15, 5, 18, [-4]);
    k.box(0, -0.4, 18, 10, 0.4, 2 * (DW / 2 + 0.2) + T, '#d9dce3');   // its floor over the rift
    hab(8, 19, 6, 10, BLUE, [['-x', -1], ['+x', 1], ['+z', 0]]);

    // consoles / crates inside the habs to juke around
    k.box(-23.5, 0, 19.5, 2, 1.1, 1, STEEL);
    k.box(-18, 0, -17.5, 1.2, 1.1, 2.2, STEEL);
    k.box(-24, 0, 2, 1.2, 1.1, 1.2, STEEL);
    k.box(9.5, 0, 22, 1.4, 1.1, 1.4, STEEL);

    // ways up to the hab roofs (5): kick off a hab wall (low gravity: a kick or two and pull up), and crates
    k.box(-28.2, 0, 20.5, 2.4, 3, 2.4, YEL);                       // crates (3m: hop on, then onto a roof)
    k.box(-18, 0, -22.1, 2.4, 3, 2.4, PINK);

    // ---------- the deck (10) with its kick shaft, storage rack and gantry ----------
    kickShaft(k, -9, -8, 'z', 4, 0, 10, YEL, 3.0);                 // walls at x -10.75 / -7.25, z -10..-6
    slab(k, -8.5, 10, -3, 5, 6, '#d9dce3', { t: 0.5 });            // deck x -11..-6, z -6..0
    k.box(-11.5, 0, -3, 1, 10, 6, '#d9dce3');                      // its west end is a solid pier
    posts(k, [[-6.3, -0.3]], 0, 9.5, STEEL, 0.4);
    k.box(-13, 0, -1, 2, 6.4, 4, STEEL);                           // storage rack x -14..-12, z -3..1
    k.box(-13, 0, 3, 2.4, 2.6, 2.4, MINT);                         // crate -> rack -> deck
    bridge(k, -6, -4, 5, -4, 10, 2, STEEL);                         // gantry over the rift

    // ---------- comm tower (14) ----------
    k.box(8.8, 0, -4, 3.6, 14, 4, '#d9dce3');                       // core x 7..10.6
    k.box(10.8, 0, -4, 0.4, 12, 4, '#d9dce3');                      // its east face (kick side - kickable anyway)
    k.box(10.8, 12, -4, 0.4, 2, 4, '#d9dce3');
    k.box(14.25, 0, -4, 0.5, 12, 4, YEL, { tex: 'kick' });          // the other side of the shaft
    slab(k, 6, 10, -4, 2, 4, STEEL, { t: 0.5 });                    // gantry balcony x 5..7
    posts(k, [[5.3, -5.7], [5.3, -2.3]], 0, 9.5, STEEL, 0.3);
    // zig-zag ledges with a gap between them, so you never jump with one right over your head
    for (const [x, y] of [[7.7, 3.6], [10.3, 7.2], [7.7, 10.8]]) slab(k, x, y, -6.6, 1.4, 1.2, LILAC, { t: 0.4 });
    k.deco(9, 14, -4, 0.2, 4, 0.2, '#d9dce3');                      // mast
    k.deco(9, 18, -4, 0.45, 0.45, 0.45, '#ff3b4f', { emissive: '#ff3b4f' });

    // ---------- the middle tube over the rift: a third way across on foot, and a wall for the long views down the rift ----------
    tube('x', -5, 5, -12);
    k.box(0, -0.4, -12, 10, 0.4, 2 * (DW / 2 + 0.2) + T, '#d9dce3');

    // ---------- the south catwalk over the rift ----------
    k.box(0, -0.4, -22, 10, 0.4, 2.4, STEEL);
    posts(k, [[-4.8, -23.1], [-4.8, -20.9], [4.8, -23.1], [4.8, -20.9]], 0, 1.1, STEEL, 0.2);

    // ---------- lander ----------
    k.box(14, 3.2, -17, 6, 3.2, 6, HAB);                      // body x 11..17, z -20..-14: run under it
    for (const [x, z] of [[11.3, -19.7], [16.7, -19.7], [11.3, -14.3], [16.7, -14.3]]) k.box(x, 0, z, 0.5, 3.2, 0.5, STEEL);
    k.box(14, 2.4, -17, 1.6, 0.8, 1.6, DARK);                       // engine bell
    k.box(14, 6.4, -17, 2, 1.2, 2, YEL);                            // hatch on top
    k.box(19, 0, -17, 2.4, 3.1, 2.4, BLUE);                         // crate: hop on, then onto the lander

    // ---------- hangar (roof 6): jump over from the lander or the cargo stack, or off the crate ----------
    hab(24.5, -13, 7, 6, '#ffb37a', [['-x', -1], ['+z', 1.5], ['-z', -1.5]], 6, '#d9dce3');
    k.box(19.4, 0, -10.6, 2.4, 3, 2.4, MINT);

    // ---------- cargo stack ----------
    k.box(24, 0, -25, 6, 2.6, 2.4, PINK);
    k.box(24, 0, -21.6, 6, 2.6, 2.4, BLUE);
    k.box(24, 2.6, -23.2, 2.4, 2.6, 6, YEL);                        // laid across both: top 5.2

    // ---------- rover ----------
    k.box(-8.5, 0.6, -24, 3, 1.4, 4.2, '#d9dce3');
    k.box(-8.5, 2, -25, 2, 0.8, 1.6, LILAC);
    for (const [x, z] of [[-10.2, -25.4], [-6.8, -25.4], [-10.2, -22.6], [-6.8, -22.6]]) k.box(x, 0, z, 0.4, 1.1, 1.1, DARK);

    // ---------- solar panels: slide under, or run along the top ----------
    for (const z of [-7.8, -3.6, 0.6]) {
      slab(k, 22.5, 1.55, z, 10, 2.2, PANEL, { t: 0.15 });
      posts(k, [[18, z], [22.5, z], [27, z]], 0, 1.4, STEEL, 0.2);
    }

    // ---------- crater: rim rocks, and a pad that throws you up to the dish ----------
    boulder(11.5, 26.5, 1.6, 1.6, 2.4, 0.3, ROCK2);
    boulder(24.6, 15, 1.4, 1.4, 2.6, 0.15);
    boulder(24.8, 21.5, 1.8, 2.2, 1.8, -0.4, ROCK2);
    boulder(16, 24.6, 2.6, 1.2, 1.4, 0.25, ROCK3);
    k.pad(18, -3, 18, 1.6, 1.6, 17.5, { aim: [25, 24, 5] });          // (always flies at the dish, however you run onto it)
    slab(k, 25, 6, 24, 6, 6, '#d9dce3', { t: 0.5 });                // dish platform x 22..28, z 21..27
    posts(k, [[27.6, 21.4], [22.4, 26.6], [27.6, 26.6]], 0, 5.5, STEEL, 0.4);
    posts(k, [[22.4, 21.4]], -3, 5.5, STEEL, 0.4);                 // (this one stands in the crater: down to its floor)
    k.deco(25, 6, 24, 0.5, 2.2, 0.5, '#d9dce3');
    k.deco(25.6, 7.6, 23.4, 3.4, 0.25, 3.4, HAB, { rot: 0.6 });

    // ---------- tall rocks, a shed and a relay mast: break up the long views ----------
    boulder(25.5, 7, 3, 3.3, 2.4, -0.3, ROCK);
    boulder(-12.5, 10, 3, 3.3, 2.4, 0.25, ROCK2);
    boulder(-27.5, -25, 3.4, 4.8, 2.6, -0.2, ROCK);
    hab(-7.5, -17, 4, 3, '#9be3a8', [['-x', 0], ['+x', 0]], 3, '#d9dce3');   // shed: run through, or hop on (3m)
    k.box(-9, 0, 25, 1.2, 8, 1.2, '#d9dce3');                                   // relay mast
    k.deco(-9, 8, 25, 0.25, 2.5, 0.25, '#d9dce3');
    k.deco(-9, 10.5, 25, 0.4, 0.4, 0.4, '#7ed6c8', { emissive: '#3a8a80' });

    // ---------- rocks around the edges and in the open (cover, low hops) ----------
    for (const [x, z, w, h, d, r, c] of [
      [-28.6, -8, 1.8, 1.4, 2.6, -0.4, ROCK2], [-14, 25.4, 2.2, 2.6, 1.8, 0.4, ROCK2], [-6.2, 25.6, 1.6, 1.4, 1.6, 0.1, ROCK3],
      [-6.4, 11.5, 1.6, 1.8, 2.4, -0.3, ROCK], [-11.5, 13.2, 1.4, 1.2, 1.4, 0.6, ROCK3],
      [-18, -25.6, 2.6, 1.8, 1.6, -0.25, ROCK],
      [16.5, -10.5, 1.4, 1.2, 1.6, -0.3, ROCK3],
    ]) boulder(x, z, w, h, d, r, c);

    // ---------- cargo pods: the same 6m pod as the cargo stack, in piles that break up the open ground ----------
    // every layer is 2.6 (a jump and a pull-up in this gravity), the top one overhangs, lanes between are 2.3-4m
    const pod = (x, y, z, ax, c) => (ax === 'x' ? k.box(x, y, z, 6, 2.6, 2.4, c) : k.box(x, y, z, 2.4, 2.6, 6, c));
    const crate = (x, y, z, c) => k.box(x, y, z, 2.4, 2.4, 2.4, c);
    pod(9.5, 0, 3.8, 'x', PINK); pod(9.5, 0, 6.2, 'x', BLUE); pod(11.3, 2.6, 5, 'z', YEL);     // east field: top 5.2
    pod(16, 0, 3.2, 'z', MINT); crate(16, 2.6, 4.9, LILAC);                                       // its neighbour across a kick lane
    pod(20.5, 0, 10.6, 'x', PINK);                                                               // on the crater rim
    pod(9, 0, -25, 'x', BLUE); crate(7.4, 2.6, -25, PINK);                                       // south-east, by the catwalk
    crate(16.5, 0, -24.5, MINT);                                                                  // ...and between it and the cargo stack
    pod(12, 0, -11.5, 'x', LILAC);                                                                // in front of the middle tube's east door
    pod(-8.5, 0, 5.5, 'x', MINT);                                                                // west, under the deck
    pod(-13, 0, -24, 'z', BLUE);                                                                  // west, behind the rover

    // --- for chases (kept light): a slide-under pipe arch on the west strip, a low crate ---
    for (const x of [-29.6, -26]) k.box(x, 0, 10, 0.4, 1.6, 0.4, STEEL);
    k.box(-27.8, 1.2, 10, 4, 0.4, 0.4, YEL);
    k.box(-14, 0, 9, 1.3, 1.1, 1.3, STEEL);
  },
});

;
/* ==== js/maps/kitchen.js ==== */
// THE KITCHEN - you're tiny, the kitchen is not. Everything works in big kitchen heights:
//   floor 0       chair seats 3.2 (slide under them), sugar cubes, mugs, shakers, a dog bowl,
//                 a cereal box lying on its side (run through it), cookbooks
//   table 6.4     in the middle, chairs all round (seat -> table is a pull-up), a lamp above it
//   counters 8.4  the north counter (sink to drop into, toaster), the west counter (stove, an oven
//                 to hide in) and the island (tunnel through it, drawers to climb, a cutting-board
//                 ramp). A rolling pin bridges the north counter and the island
//   shelf 11.6    the spice shelf along the east wall, reached by the cookbook staircase
//   tops 15       upper cabinets, range hood, fridge and pantry - the high road. The toaster pops
//                 you onto the fridge, and the fridge/pantry gap is a kick chimney all the way up
// Kick routes: the gap between the counter and the fridge (floor -> counter), the gap between the
// fridge and the pantry (floor -> 15), and the west counter + the west chair's back.
// Big jump: fridge top -> island (12m out, 6.6m down - slide-jump it).
defineMap({
  id: 'kitchen',
  accent: ['#86a4d8', '#f2b880'],
  name: 'The Kitchen',
  blurb: "You're tiny. Climb drawers onto the counters, run the rolling pin, ride the toaster up to the fridge.",
  env: 'indoor',
  sky: '#2a2018',
  fog: [45, 120],
  hemi: ['#fff4e2', '#9a8268', 1.3],
  sun: [0.5, 4, 60, 6],
  size: 32,
  spotHeight: 18.6,
  spots: [-18, 0, 18].flatMap((x) => [-12, 12].map((z) => ({ x, z }))),
  menuCam: { r: 18, y: 13 },
  spawns: [
    [-12, 0, -12], [-3, 0, -12], [15, 0, -13.5], [24, 0, -6], [24, 0, 8], [16, 0, 10],
    [-9, 0, 20], [1, 0, 15.5], [-18, 0, -6], [-17, 0, 20], [10, 8.4, -4], [-24, 8.4, -20],
    [-12, 6.4, 4], [28.5, 11.6, 0], [14, 15, -22], [8, 0, -11],
  ],
  seekerSpawn: [8, 8.4, 3.5],

  build(k) {
    const FLOOR = '#ecdcc0', CHECK = '#dcc7a4', WALL = '#f3e6cf', CEIL = '#f8efe0';
    const CAB = '#86a4d8', TOP = '#f6efe2', DRAWER = '#6f8dc6';
    const WOOD = '#c4895a', CHAIR = '#d6a26e', ISLAND = '#f2b880', FRIDGE = '#e6edf2', PANTRY = '#b98b62';
    const STEEL = '#c3cbd3', DARK = '#3b3330', PINK = '#ff8fa3', BLUE = '#8fb4ff', YEL = '#ffd166';
    const KICK = { tex: 'kick' };
    const H = 8.4;                                   // counter height

    ground(k, 60, 50, FLOOR);
    enclose(k, 60, 50, 19, WALL, CEIL);
    // big checkerboard tiles
    for (let x = -28; x <= 28; x += 4) for (let z = -23; z <= 23; z += 4) {
      if (((x + z) / 4) % 2 === 0) k.deco(x, 0, z, 4, 0.02, 4, CHECK);
    }

    // a counter block from the floor to the top, with a thin countertop on it
    const counter = (x0, x1, z0, z1, color = CAB) => k.box((x0 + x1) / 2, 0, (z0 + z1) / 2, x1 - x0, H, z1 - z0, color);
    const top = (x0, x1, z0, z1) => k.deco((x0 + x1) / 2, H, (z0 + z1) / 2, x1 - x0, 0.06, z1 - z0, TOP);
    // drawers pulled out as a staircase (2.8 then 5.6, then pull up onto the counter)
    const drawers = (x0, z0, dir, along) => {
      // along 'x': drawers run along x from x0, sticking out from the face at z0 toward dir (+1/-1)
      for (let i = 0; i < 2; i++) {
        const h = 2.8 * (i + 1), a = x0 + i * 2.5 + 1.25;
        if (along === 'x') {
          k.box(a, 0, z0 + dir * 0.8, 2.5, h, 1.6, DRAWER);
        } else {
          k.box(z0 + dir * 0.8, 0, a, 1.6, h, 2.5, DRAWER);
        }
      }
    };

    // ---- north counter (z -25..-17): sink, open cabinet nook, toaster ----
    counter(-30, -16, -25, -17);
    top(-30, -16, -25, -17);
    // sink: a 6x6 basin 3m deep you can drop into and pull yourself out of
    k.box(-13, 0, -24.5, 6, H, 1, CAB); top(-16, -10, -25, -24);
    k.box(-13, 0, -17.5, 6, H, 1, CAB); top(-16, -10, -18, -17);
    k.box(-13, 0, -21, 6, 5.4, 6, STEEL);
    k.box(-13, 8.4, -24.6, 0.8, 3.2, 0.8, STEEL);                     // faucet
    k.box(-13, 10.8, -23, 0.8, 0.8, 2.4, STEEL);
    counter(-10, -6, -25, -17);
    top(-10, -6, -25, -17);
    // open cabinet: a nook at floor level
    // (its back wall is a solid block of the darker color, not a panel 1cm in front of the cabinet
    // face - those two flickered light/dark at a distance)
    k.box(-3, 0, -23, 6, 3.8, 4, DRAWER);
    k.box(-3, 3.8, -23, 6, H - 3.8, 4, CAB);
    k.box(-3, 3.8, -19, 6, H - 3.8, 4, CAB);
    top(-6, 0, -25, -17);
    k.box(-6.15, 0.3, -15, 0.3, 3.2, 3.6, CAB);                        // its door, swung open
    counter(0, 8, -25, -17);
    top(0, 8, -25, -17);
    drawers(-22, -17, 1, 'x');
    // toaster on the front of the counter: its slot throws you up onto the fridge
    k.box(3.5, H, -19, 3, 2.4, 3, BLUE);
    k.pad(3.8, H + 2.4, -19.1, 1.4, 1.4, 16, { color: YEL });
    // plates + a jar on the counter (front half - the upper cabinets hang over the back half)
    k.box(-26, H, -19, 3, 1.2, 3, '#ffffff');
    k.box(-2, H, -19.2, 2, 3, 2, YEL);

    // ---- west counter (x -30..-22): stove on top, oven underneath ----
    counter(-30, -22, -17, -8);
    // the oven's back wall is a dark block itself (not a dark panel 1cm in front of the cabinet face)
    k.box(-29, 0, -4, 2, 3.8, 8, DARK);                                 // inside of the oven
    k.box(-29, 3.8, -4, 2, H - 3.8, 8, CAB);
    k.box(-25, 3.8, -4, 6, H - 3.8, 8, STEEL);                          // oven front
    k.box(-20.5, 0, -4, 3, 0.35, 7.6, STEEL);                           // oven door, folded down
    counter(-30, -22, 0, 12);
    top(-30, -22, -17, 12);
    for (const [x, z] of [[-27.5, -6], [-27.5, -2], [-24.5, -6], [-24.5, -2]]) k.deco(x, H + 0.06, z, 2.2, 0.04, 2.2, DARK);   // burners
    drawers(-15, -22, 1, 'z');
    // beside the west chair: kick between the counter and the chair back up onto the counter
    k.box(-21.9, 0, 7, 0.2, H, 6, CAB);

    // ---- upper cabinets + range hood: the high road at 15 ----
    k.box(-11.5, 12.4, -23, 37, 2.6, 4, CAB);                            // north, x -30..7 (a 4m hop from the fridge)
    k.box(-28, 12.4, -14.5, 4, 2.6, 13, CAB);                            // west, z -21..-8
    k.box(-27, 12.4, -4, 6, 2.6, 8, STEEL);                              // range hood
    k.box(-28, 12.4, 5, 4, 2.6, 10, CAB);                                // west, z 0..10

    // ---- fridge + pantry, and the two kick chimneys ----
    k.box(14, 0, -21.5, 6, 15, 7, FRIDGE);
    k.box(8.1, 0, -21, 0.2, H, 8, CAB);                                  // counter end
    k.box(10.9, 0, -21.5, 0.2, 15, 7, FRIDGE);                           // fridge, west side
    k.box(17.1, 0, -21.5, 0.2, 15, 7, FRIDGE);                           // fridge, east side
    k.box(25, 0, -21.5, 10, 15, 7, PANTRY);
    k.box(19.9, 0, -21.5, 0.2, 15, 7, PANTRY);                           // pantry, west side

    // ---- the island: tunnel through the middle, drawers, cutting-board ramp ----
    k.box(8, 0, -3.75, 12, H, 4.5, ISLAND);
    k.box(8, 0, 3.75, 12, H, 4.5, ISLAND);
    k.box(8, 3.8, 0, 12, H - 3.8, 3, ISLAND);
    top(2, 14, -6, 6);
    drawers(3, 6, 1, 'x');
    k.ramp(19, 4.5, 10, 2.6, 0, H, '-x', WOOD);                         // cutting board
    k.box(11, H, 4, 2, 1, 3, '#ffffff');                                 // butter dish
    k.box(5, H, -3, 1, 3, 1, DARK);                                      // pepper grinder

    // ---- the rolling pin: a beam from the north counter to the island at counter height ----
    k.box(5, H - 1.2, -11.5, 1.2, 1.2, 11, '#e0b07a');

    // ---- table (6.4) and chairs (seat 3.2, slide under the seat) ----
    k.box(-8, 5.9, 7, 14, 0.5, 10, WOOD);
    for (const [x, z] of [[-14.5, 2.5], [-1.5, 2.5], [-14.5, 11.5], [-1.5, 11.5]]) k.box(x, 0, z, 1, 5.9, 1, WOOD);
    const chair = (x, z, back) => {
      k.box(x, 1.25, z, 3.5, 1.95, 3.5, CHAIR);
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * 1.5, 0, z + sz * 1.5, 0.5, 1.25, 0.5, CHAIR);
      if (back === '-z') k.box(x, 3.2, z - 2, 3.5, 5.4, 0.5, CHAIR);
      if (back === '+z') k.box(x, 3.2, z + 2, 3.5, 5.4, 0.5, CHAIR);
      if (back === '-x') k.box(x - 2, 3.2, z, 0.5, 5.4, 3.5, CHAIR);
    };
    chair(-11.5, 0, '-z'); chair(-4.5, 0, '-z');
    chair(-11.5, 14, '+z'); chair(-4.5, 14, '+z');
    chair(-17, 7, '-x');
    k.box(-3, 6.4, 9.5, 1.6, 2, 1.6, PINK);                              // a cup on the table
    k.ramp(0.5, 4, 3.02, 1.4, 6.4, 8.4, '+x', STEEL, { base: 6.0 });   // a spoon resting from the table up onto the island
    k.deco(-12, 6.4, 9.5, 2.6, 0.12, 2.6, '#ffffff');                    // plates
    k.deco(-3.5, 6.4, 4, 2.6, 0.12, 2.6, '#ffffff');
    k.pad(-12, 6.4, 6, 1.4, 1.4, 18.5, { color: YEL, aim: [-8, 7, 4] });   // up onto the lamp
    // the lamp over the table
    k.box(-8, 10.4, 7, 3, 1.4, 3, YEL, { emissive: '#6a5000' });
    k.deco(-8, 11.8, 7, 0.12, 7.2, 0.12, DARK);

    // ---- east wall: spice shelf (11.6) and the cookbook staircase up to it ----
    k.box(28.5, 11.2, 3.5, 3, 0.4, 43, WOOD);                            // z -18..25
    k.box(28.5, 11.6, -16.5, 2.4, 2.4, 2.4, PINK);                       // jar: step up onto the pantry
    k.box(28.5, 11.6, -4, 2, 3, 2, CAB);
    k.box(28.5, 11.6, 6, 2, 2.4, 2, YEL);
    const BOOK = [BLUE, PINK, YEL, BLUE, PINK, YEL, BLUE];
    for (let i = 0; i < 7; i++) k.box(11.4 + i * 2.4, 0, 23.5, 2.4, 1.6 * (i + 1), 3, BOOK[i]);

    // ---- floor clutter: things to juke around, slide under, hop on ----
    const CUBE = '#fbfbf7';
    for (const [x, z, n] of [[-2, -9, 1], [-0.4, -7.6, 2], [-19, -12, 1], [20.5, 1.5, 1], [19.5, 20, 2], [-8, -4.6, 1], [-25, 22, 1], [13, 12.5, 1], [5, 15.2, 2]]) {
      for (let i = 0; i < n; i++) k.box(x, i * 1.2, z, 1.2, 1.2, 1.2, CUBE);
    }
    // a fallen spatula you slide under, resting on two sugar-cube stacks
    for (const x of [17.4, 22.6]) k.box(x, 0, -6, 1.2, 2.4, 1.2, CUBE);
    k.box(20, 1.25, -6, 4, 0.4, 1.2, DARK);
    // salt + pepper (1.2 wide, not 1.4: CPUs can mantle onto a top this size too - on 1.4 tops a
    // runner was out of every CPU's reach)
    k.box(17, 0, -11, 1.2, 3.4, 1.2, '#ffffff');
    k.box(22, 0, -12, 1.2, 3.4, 1.2, DARK);
    // mugs
    for (const [x, z, c] of [[22, 10, PINK], [-13, 21.5, BLUE], [-1, -15.5, YEL]]) {
      k.box(x, 0, z, 2.4, 2.6, 2.4, c);
      k.box(x + 1.45, 0.6, z, 0.5, 1.4, 0.4, c);
    }
    // a cereal box standing up, and one lying on its side (run through it, climb on it)
    k.box(-4, 0, 20, 4.5, 6.5, 1.6, PINK);
    k.box(6, 0, 19.95 - 2, 7, 4.4, 0.25, YEL);
    k.box(6, 0, 19.95 + 2, 7, 4.4, 0.25, YEL);
    k.box(6, 4.15, 19.95, 7, 0.25, 3.75, YEL);
    k.box(23, 0, 16, 1.6, 6.5, 4.5, BLUE);
    // spoon on the floor (vault it)
    k.box(16, 0, 15, 1.2, 0.6, 7, STEEL);
    // dog bowl
    for (const [x, z, w, d] of [[-20, 17.2, 4, 0.4], [-20, 20.8, 4, 0.4], [-21.8, 19, 0.4, 3.2], [-18.2, 19, 0.4, 3.2]]) k.box(x, 0, z, w, 0.8, d, PINK);
    // ---- more of the same clutter in the open stretches (east floor, in front of the table, west
    // floor), so no aisle runs the whole kitchen: cereal boxes to hide behind (one knocked askew),
    // another to run through, mugs and sugar cubes to climb and vault ----
    k.box(25, 0, -9, 4.5, 6.5, 1.6, BLUE, { rot: 0.25 });                // east: standing, askew
    k.box(18, 0, 10.5, 1.6, 6.5, 4.5, PINK);                             // east: standing
    k.box(1.5, 0, 12.5, 1.6, 6.5, 4.5, YEL, { rot: -0.2 });              // by the table: standing, askew
    k.box(-12, 0, -10, 4.5, 6.5, 1.6, BLUE);                             // west floor: standing
    for (const sx of [-1.9, 1.9]) k.box(26.4 + sx, 0, 3.5, 0.25, 4.4, 7, PINK);   // east: lying on its side, run through
    k.box(26.4, 4.15, 3.5, 4, 0.25, 7, PINK);
    for (const [x, z, c] of [[26.5, -3.5, YEL], [8, 11, BLUE], [-15, -6, PINK]]) {
      k.box(x, 0, z, 2.4, 2.6, 2.4, c);
      k.box(x + 1.45, 0.6, z, 0.5, 1.4, 0.4, c);
    }
    for (const [x, z, n] of [[24, -3.5, 1], [24.5, -15, 2], [25.7, -15, 1], [15, -15, 1], [10, 13.8, 1], [-16.5, -9.5, 1], [-9, -13, 2], [-7.8, -13, 1]]) {
      for (let i = 0; i < n; i++) k.box(x, i * 1.2, z, 1.2, 1.2, 1.2, CUBE);
    }

    // jars on the counters and the island: cover up there too, and a step (3m) toward the high road
    for (const [x, z, c] of [[-24.2, -12, BLUE], [-24.2, 7, PINK], [-8, -19, BLUE], [12.5, -3.5, PINK], [3.5, -1, STEEL]]) k.box(x, H, z, 2, 3, 2, c);

    // trash can + step stool in the south-west corner: stool -> can -> west counter
    k.box(-27, 0, 16, 5, 6.4, 5, '#8a95a5');
    k.box(-22.5, 0, 16, 3, 3.2, 3, CHAIR);
  },
});

;
/* ==== js/maps/clocktower.js ==== */
// THE CLOCKTOWER - inside a giant clock. A 12x12 shaft runs up the middle and is crossed at every
// height: the big gear set into the floor, a balance beam at 5, a turning gear-arm bridge at 10,
// bridges at 15. Around it, 3x3 cells of 12m. Galleries at 5, 10 and 15 skip cells, so tall open
// atriums sit next to stacked rooms and every floor has holes to drop through.
//
//            L1 (5)        L2 (10)       L3 (15, bell deck)
//   floored  N S W NE SW   N E W NW SE   S W NE SE  (+ bridges across the shaft)
//
// Ways up (none of them the only one):
//   0 -> 5    crates by the shaft, stairs in E, step blocks in SE, wall kicks in the NW room's corners
//   5 -> 10   stairs in S, the NE gear on its axle, wall kicks in the SW room's corners
//   10 -> 15  stairs in NW, stairs in E, wall kicks in the N room's corners, the tall SW chimney (5 -> 15)
// Nothing moves up and down: only gears turn (and turn your view while you ride them).
// Run into a bell rope on the bell deck and the bell rings. Ceilings are 4.5m+ over every floor.
defineMap({
  id: 'clocktower',
  accent: ['#f1c40f', '#a8322d'],
  name: 'The Clocktower',
  blurb: 'Inside a giant clock. Ride the turning gears, kick up the chimneys, ring the bells on the bell deck.',
  env: 'indoor',
  sky: '#1d1712',
  fog: [45, 110],
  hemi: ['#fff6ea', '#a08a74', 2.1],
  sun: [0.5, 4, 60, 6],
  size: 22,
  spotHeight: 23.4,
  spots: [-12, 0, 12].flatMap((x) => [-12, 0, 12].map((z) => ({ x, z, color: '#ffe2b0' }))),
  menuCam: { r: 4.5, y: 6.5 },
  spawns: [
    [-15, 0, -15], [11, 0, 0], [14, 0, 15], [0, 0, -16], [-12, 0, 4], [0, 0, 13], [-15, 0, 15], [12, 0, -12],
    [3, 5, -9], [-12, 5, 3], [16, 5, -16], [-15, 5, 15],
    [9, 10, -3], [-16, 10, -16], [13, 10, 14], [-14, 10, -3],
    [13, 15, 13], [-12, 15, -3],
  ],
  seekerSpawn: [0, 0, 7.5],

  build(k) {
    // the Container Yard / Rooftops palette: a few bold flat colors
    // (dusty pastels, like the rest of the game; the gears and steel stay dark so they stand out)
    const BRICK = '#c98f74', CEIL = '#2b2f35', FLOOR0 = '#8d8780', STEEL = '#59636e', DARK = '#2b2f35';
    const NAVY = '#7f9cc9', GREEN = '#9cc3a4', RED = '#d0675e', GREY = '#b9bcc1', CREAM = '#e6dfcf';
    const GOLD = '#f1c40f', BRASS = '#d9a033', FACE = '#f4ecd8';
    const L = [0, 5, 10, 15], C = 12;   // floor heights, cell size

    ground(k, 36, 36, FLOOR0);
    enclose(k, 36, 36, 24, BRICK, CEIL);

    // ---------- galleries: one 12x12 slab per floored cell, one color per level ----------
    const cells = {
      1: ['N', 'S', 'W', 'NE', 'SW'],
      2: ['N', 'E', 'W', 'NW', 'SE'],
      3: ['S', 'W', 'NE', 'SE'],
    };
    const at = { N: [0, -1], S: [0, 1], E: [1, 0], W: [-1, 0], NE: [1, -1], NW: [-1, -1], SE: [1, 1], SW: [-1, 1] };
    const level = [null, NAVY, GREEN, RED];
    for (const lv of [1, 2, 3]) for (const c of cells[lv]) slab(k, at[c][0] * C, L[lv], at[c][1] * C, C, C, level[lv], { t: 0.5 });

    // pillars at the shaft corners, floor to the first gallery
    posts(k, [[-6, -6], [6, -6], [-6, 6], [6, 6]], 0, 4.5, STEEL, 0.8);

    // ---------- gears: two squares a quarter-turn apart (an 8-point star) plus a hub ----------
    // the second square starts 0.02 higher so the two never share a face
    const gear = (x, y, z, s, h, speed) => {
      const m = { type: 'spin', speed };
      k.mover(x, y, z, s, h, s, GOLD, m);
      k.mover(x, y + 0.02, z, s, h, s, BRASS, { type: 'spin', speed, phase: Math.PI / 4 });
      k.mover(x, y + h + 0.02, z, s * 0.25, 0.3, s * 0.25, DARK, m);
    };

    // ---------- the shaft ----------
    // the big gear set into the floor: low enough to run straight onto (and it turns you)
    gear(0, 0, 0, 6, 0.28, 0.3);
    // a wall closes the W room off from the shaft, so the crates beside it lead up onto the W gallery
    k.box(-6.2, 0, 0, 0.4, 4.5, 11.2, CREAM);
    k.box(-5.25, 0, 0.2, 1.4, 2.4, 1.4, GREY);
    k.box(-5.25, 0, 2.2, 1.4, 1.2, 1.4, GREY);
    // balance beam at 5, north to south, over the floor gear
    slab(k, 0, 5, 0, 1.6, 12, STEEL, { t: 0.3 });
    // at 10: a gear arm that turns slowly - when it lines up it bridges the W and E galleries
    k.mover(0, 9.6, 0, 11.6, 0.4, 2.6, GOLD, { type: 'spin', speed: 0.22 });
    k.mover(0, 10, 0, 2.2, 0.3, 2.2, DARK, { type: 'spin', speed: 0.22 });
    // bridges at 15: W deck along the north side of the shaft, a corner onto the NE deck, then
    // south over the E gallery to the SE deck
    slab(k, 0, 15, -5.5, 12, 3, STEEL, { t: 0.4 });
    slab(k, 7.5, 15, 0, 3, 12, STEEL, { t: 0.4 });

    // ---------- the NE gear, turning on its axle: from the gallery at 5 up toward 10 ----------
    // (it sits on a solid drum, so nobody gets stuck underneath it)
    k.box(12, 5, -12, 4.6, 1.88, 4.6, STEEL);
    gear(12, 6.9, -12, 5, 0.9, -0.3);

    // ---------- turning works under the roof (out of reach) ----------
    gear(-12, 21.6, -12, 6, 0.9, 0.25);
    gear(12, 21.6, 1, 7, 0.9, -0.18);
    gear(-11, 21.6, 12, 5, 0.9, 0.3);
    gear(13, 21.6, 13, 4, 0.9, -0.4);

    // ---------- stairs ----------
    stairs(k, 15, 3.1, '-z', 3, 0, 5, GREY);                       // E ground -> NE gallery (5)
    stairs(k, -3.1, 15, '+x', 3, 5, 10, GREY);                     // S gallery (5) -> SE gallery (10)
    stairs(k, -12, -15.1, '+z', 3, 10, 15, GREY);                  // NW gallery (10) -> W bell deck (15)
    stairs(k, 15, 3.1, '-z', 3, 10, 15, GREY);                     // E gallery (10) -> NE bell deck (15)

    // ---------- SE: step blocks up onto the S gallery (5) ----------
    k.box(9.6, 0, 12, 1.6, 1.2, 2.4, GREY);
    k.box(7.6, 0, 12, 2.4, 2.4, 2.4, STEEL);

    // ---------- kick chimney (orange): the tall one - elsewhere the rooms' own corners are the kick routes ----------
    kickShaft(k, -8.5, 14.5, 'x', 5, 5, 15, BRASS);                // SW (5) -> S bell deck (15)

    // ---------- clock faces: a big glowing square, two hands and a hub ----------
    const clock = (side, y, s, hourUp) => {
      const ax = side[1] === 'x', sg = side[0] === '+' ? 1 : -1;
      const part = (along, up, depth, a, b, col, o = {}) => {
        const w = sg * (18 - depth - 0.02), yb = y + up - b / 2;   // `depth` = how far it stands off the wall
        if (ax) k.deco(w, yb, along, 0.04, b, a, col, o); else k.deco(along, yb, w, a, b, 0.04, col, o);
      };
      part(0, 0, 0.04, s, s, FACE, { emissive: '#7a6230' });
      part(0, (hourUp ? 1 : -1) * s * 0.15, 0.1, 0.5, s * 0.3, DARK);   // hour hand: straight up or down
      part(s * 0.2, 0, 0.16, s * 0.4, 0.36, DARK);                       // minute hand: sideways
      part(0, 0, 0.22, 0.7, 0.7, RED);
    };
    clock('+x', 15, 8, true);
    clock('-z', 15, 8, false);
    clock('+z', 10, 7.6, true);
    clock('-x', 19.6, 7.2, false);

    // ---------- bells over the bell deck, each with a rope you can run into ----------
    const bell = (x, z) => {
      k.box(x, 18.8, z, 3.2, 0.6, 3.2, BRASS);
      k.box(x, 19.4, z, 2.6, 2.4, 2.6, GOLD);
      k.box(x, 21.8, z, 1.4, 0.8, 1.4, BRASS);
      k.box(x, 22.6, z, 0.5, 1.4, 0.5, DARK);
      k.bellRope(x + 0.9, 18.78, z + 0.9, 2.65, RED);
    };
    bell(0, 12);
    bell(-12, 1);
    bell(13, -13);

    // ---------- clockwork: vaults, slide-unders, blocks to juke around ----------
    // ground
    k.box(2, 0, -14, 5, 1, 2, GOLD);                               // N: gear housing to vault
    k.box(0.2, 1.25, -9, 11.6, 0.35, 0.35, DARK);                  // N: drive axle - slide under or hop it
    k.box(10, 0, -10, 1.6, 1.2, 1.6, GREY);
    k.box(15.5, 0, -15.5, 2, 1.2, 2, GREY);
    k.box(9, 0, -2, 1.4, 1.2, 1.4, GREY);
    k.box(14.5, 0, 8.5, 2.4, 2.6, 2.4, STEEL);                     // SE: spare counterweight
    k.box(0, 1.25, 9, 12, 0.35, 0.35, DARK);                       // S: axle
    k.box(3.5, 0, 15, 1.6, 1.2, 1.6, GREY);
    k.box(-9, 0, 12, 0.4, 4.5, 4, CREAM);                          // SW: a little room
    k.box(-14, 0, 9, 4, 4.5, 0.4, CREAM);
    k.box(-12, 0, -1, 3, 1, 3, GOLD);                              // W: machine
    // gallery 5
    k.box(2, 5, -14, 2.5, 1, 2.5, GOLD);
    k.box(16, 5, -10, 1.6, 1.2, 1.6, GREY);
    k.box(-3, 5, 9, 1.4, 1.2, 1.4, GREY);
    k.box(-12, 5, -2, 6, 4.5, 0.4, CREAM);                         // W: partition, run around either end
    k.box(-16, 5, 8, 1.6, 1.2, 1.6, GREY);
    // gallery 10
    k.box(-4, 10, -15, 1.4, 1.2, 1.4, GREY);
    k.box(9, 10, 3, 1.6, 1.2, 1.6, GREY);
    k.box(-12, 10, 2.5, 0.4, 4.5, 6, CREAM);                       // W: partition
    k.box(-16, 10, -12, 1.6, 1.2, 1.6, GREY);
    k.box(13, 10, 10, 2.5, 1, 2.5, GOLD);
    k.box(10, 11.25, 15, 0.35, 0.35, 6, DARK);                     // SE: axle to slide under
    // bell deck
    k.box(-3, 15, 15, 1.6, 1.2, 1.6, GREY);
    k.box(15.5, 15, 15.5, 1.6, 1.2, 1.6, GREY);

    // ---------- the works: cream partitions between the cells, each with a doorway ----------
    // so every 12m cell is a room you can turn a corner out of, not one long open ring.
    // Full-height ones tuck in under the gallery above (no thin ledges); free-standing ones are 2.4,
    // the same mantle height as the counterweights.
    // wall(axis, at, from, to, y, h, doors): a wall along `axis` ('x' or 'z') at the other coordinate `at`
    const wall = (axis, at, a0, a1, y, h, doors = []) => {
      let s = a0;
      for (const [d0, d1] of doors.concat([[a1, a1]])) {
        if (d0 - s > 0.3) axis === 'x' ? k.box((s + d0) / 2, y, at, d0 - s, h, 0.4, CREAM) : k.box(at, y, (s + d0) / 2, 0.4, h, d0 - s, CREAM);
        s = d1;
      }
    };
    // ground: the ring of rooms
    wall('z', 6, -18, -6.4, 0, 4.5, [[-13.5, -10.5]]);              // N | NE
    wall('x', -6.2, 6.4, 10.5, 0, 4.5);                             // NE | E   (then a doorway, then the E stairs)
    wall('x', 6, 6.4, 18, 0, 2.4, [[10.5, 13.5]]);                  // E | SE
    wall('z', 5.8, 6.4, 18, 0, 4.5, [[13.2, 16.2]]);                // SE | S   (the step blocks lean on it)
    wall('x', 6, -18, -6.4, 0, 4.5, [[-13.5, -10.5]]);              // SW | W
    wall('z', -6, 6.4, 18, 0, 4.5, [[10.5, 13.5]]);                 // S | SW
    wall('x', -5.8, -18, -6.4, 0, 4.5, [[-13.5, -10.5]]);           // W | NW
    wall('z', -5.8, -18, -6.4, 0, 4.5, [[-13.9, -10.1]]);           // NW | N
    // the shaft: a pinwheel of walls, so you never see straight through it
    wall('x', -6.2, -5.6, 5.6, 0, 4.5, [[1.5, 5.6]]);               // N side, doorway east
    wall('z', 6, -5.6, 5.6, 0, 2.4, [[1.5, 5.6]]);                  // E side, doorway south
    wall('x', 6.2, -5.6, 5.6, 0, 4.5, [[-5.6, -1.5]]);              // S side, doorway west
    // galleries: the same walls where two floored cells meet
    wall('z', 5.8, -18, -6, 5, 4.5, [[-13.5, -10.5]]);              // L1 N | NE
    wall('x', 5.8, -18, -6, 5, 4.5, [[-13.9, -10.1]]);              // L1 W | SW
    wall('z', -6, 6.2, 18, 5, 2.4, [[12.6, 16.4]]);                 // L1 S | SW: the doorway is the tall chimney
    wall('z', -6, -18, -6, 10, 2.4, [[-13.5, -10.5]]);              // L2 N | NW
    wall('x', -5.8, -10.3, -6.4, 10, 4.5);                          // L2 W | NW (west of it: the NW stairs, then open)
    wall('x', 6.2, 6, 18, 10, 4.5, [[10.5, 13.5]]);                 // L2 E | SE
    wall('z', 6, 6, 18, 15, 1.2, [[10.5, 13.5]]);                   // L3 S | SE: a rail to vault

    // ---------- counterweights: steel blocks 2.4 tall (one jump + mantle; 2.6 more onto a gallery edge) ----------
    // with a grey 1.2 crate beside some as a step, a few of them knocked askew
    const weight = (x, y, z, step, rot = 0) => {
      k.box(x, y, z, 2, 2.4, 2, STEEL);
      if (step) k.box(x + step[0], y, z + step[1], 1.6, 1.2, 1.6, GREY, rot ? { rot } : {});
    };
    // ground
    weight(-3.5, 0, -14.5, [0, 1.8]);                               // N
    weight(14.5, 0, -10.5, [-1.8, 0], 0.35);                        // NE
    weight(9.5, 0, 3.5);                                            // E
    weight(-3.5, 0, 14.5, [0, -1.8], -0.3);                         // S
    weight(-9.5, 0, 3.5);                                           // W
    weight(-15.5, 0, -10.5, [0, 1.8]);                              // NW
    k.box(15, 0, 12.5, 1.6, 1.2, 1.6, GREY, { rot: 0.4 });          // SE
    // galleries (under another gallery only the low crates fit)
    k.box(-3, 5, -13, 1.6, 1.2, 1.6, GREY, { rot: 0.3 });           // L1 N
    weight(3.5, 5, 14.5);                                           // L1 S
    weight(-2.5, 10, -12.5, [0, 1.8], 0.3);                         // L2 N
    weight(11.5, 10, -3.5);                                         // L2 E
    weight(-8.5, 10, -15.5);                                        // L2 NW
    // bell deck: only low crates, so the bells stay the top of the clock
    k.box(3.5, 15, 9.5, 1.6, 1.2, 1.6, GREY, { rot: 0.35 });        // L3 S
    k.box(-15.5, 15, 4.5, 1.6, 1.2, 1.6, GREY);                     // L3 W
    k.box(9.5, 15, -14.5, 1.6, 1.2, 1.6, GREY, { rot: -0.3 });      // L3 NE
    k.box(10.5, 15, 9.5, 1.6, 1.2, 1.6, GREY);                      // L3 SE
  },
});

;
/* ==== js/maps/lab.js ==== */
// THE TEST LAB - a closed research facility in the white-panel test-chamber style.
// A 3x3 block of rooms, 46m across, but no two alike: the atrium sits off-centre (x -10..7,
// z -7..10), so every wing and corner room is its own size, and each wing has its own job and heights:
//   ATRIUM   a frosted-glass core you can't kick (off to its north-west), crossed by two bridges at
//            4.4 (north-south and east-west, meeting east of the middle)
//   N  the TALL CHAMBER   full height, no mezzanine: a high gallery at 6.6 along the far wall, a
//                         pier at 4.4 running out to it from the bridge, an orange kick chimney
//                         (two free-standing walls - nothing else there to kick) up to the gallery,
//                         tall frosted columns
//   E  the LOW LAB        a deck at 3.0 over the whole wing with lab benches underneath (2.6 high):
//                         up through a hole by step blocks, or a launch plate through another
//   S  the GALLERY        two storeys: a U-shaped mezzanine at 4.4 round a well, stairs, step blocks,
//                         frosted pillars in the well
//   W  the TEST FLOOR     open, no mezzanine: test toys (vaults, lasers, frosted partitions) and the
//                         target - a platform at 4.4 with a launch plate under it, the bridge's end
//   corners  observation rooms (floor + upper room at 4.4), each with its own way up: NW stairs,
//            NE kick shaft (two free-standing walls), SE launch plate, SW step blocks; the NW and NE
//            rooms open onto the N gallery (a 2.2 cabinet up to its doors), the others onto the
//            mezzanine / deck / a balcony over the test floor
// Frosted grey panels (they used to be glass you couldn't kick - every wall kicks now). Orange walls are kick routes (only where
// there's no ordinary wall to kick - every wall kicks). Red bars: slide under (1.2m). Nothing moves
// up or down, and there is no void anywhere.
defineMap({
  id: 'lab',
  accent: ['#ff8a1f', '#2f8cff'],
  name: 'The Test Lab',
  blurb: 'A white test facility round an off-centre atrium: a tall chamber, a low lab, a two-storey gallery and an open test floor. Frosted panels, laser bars and launch plates.',
  env: 'indoor',
  sky: '#15171c',
  fog: [55, 120],
  hemi: ['#ffffff', '#a6aebb', 1.5],
  sun: [0.8, 12, 60, 24],
  size: 25,
  spotHeight: 9.7,
  spots: [{ x: -1.5, z: 1.5 }, { x: -1.5, z: -15 }, { x: -1.5, z: 16.5 }, { x: -16.5, z: 1.5 }, { x: 15, z: 1.5 }],
  menuCam: { path: [[-8, 6.2, 8], [5, 6.2, 8]] },
  spawns: [
    [-1, 0, 0], [5.5, 0, 6.5], [-8.5, 0, 0.5],
    [2, 0, -16], [-6, 6.6, -21.2], [2.5, 4.4, -13],
    [21, 0, 4], [12, 3, -3],
    [1.5, 0, 22], [-8, 4.4, 19],
    [-20, 0, -1], [-18.5, 4.4, 1.6],
    [-19, 0, -9.5], [11, 0, -20], [20, 0, 12.5], [-20, 0, 21],
    [-17, 4.4, -20.5], [10, 4.4, 20.5],
  ],
  seekerSpawn: [-1, 0, 3.5],

  build(k) {
    const PANEL = '#eceef1', FLOOR = '#a3a9b2', UPPER = '#cdd2d9', CEIL = '#f4f6f8', FRAME = '#2c3038';
    const OR = '#ff8a1f', BL = '#2f8cff', LASER = { emissive: '#ff2a10' }, GLOW = { emissive: '#fff1c8' };
    const GLASS = { tex: 'nokick' }, KICK = { tex: 'kick' };
    const EM = (col) => ({ emissive: col === OR ? '#663000' : '#123a66' });
    const TINT = (col) => (col === OR ? '#d9c4ae' : '#b7c3d3');
    const T = 0.5, L1 = 4.4, GAL = 6.6, DECK = 3.0, TOP = 10, E = 23;
    const XW = -10, XE = 7, ZN = -7, ZS = 10;          // the atrium's edges (off-centre)

    // fill a region with panels at most `step` long on each axis, so the outlines draw seams
    const panels = (x0, x1, y0, y1, z0, z1, col, o = {}, step = 8) => {
      const cuts = (a, b) => {
        const L = b - a;
        if (L < 1.01) return [[a, b]];
        const n = Math.max(1, Math.round(L / step)), out = [];
        for (let i = 0; i < n; i++) out.push([a + L * i / n, a + L * (i + 1) / n]);
        return out;
      };
      for (const [a0, a1] of cuts(x0, x1)) for (const [b0, b1] of cuts(y0, y1)) for (const [c0, c1] of cuts(z0, z1)) {
        k.box((a0 + a1) / 2, b0, (c0 + c1) / 2, a1 - a0, b1 - b0, c1 - c0, col, o);
      }
    };
    // a wall along ax ('x' or 'z') on line `at`, from a0 to a1, split around its doorways
    // holes: [{ c, w, y, h, col }]
    const wall = (ax, at, a0, a1, y0, y1, holes) => {
      const br = [a0, a1];
      for (const h of holes) br.push(h.c - h.w / 2, h.c + h.w / 2);
      const pts = [...new Set(br.map((v) => Math.round(v * 1000) / 1000))].sort((p, q) => p - q);
      const put = (b0, b1, c0, c1) => {
        if (b1 - b0 < 0.01 || c1 - c0 < 0.01) return;
        if (ax === 'x') panels(b0, b1, c0, c1, at - T / 2, at + T / 2, PANEL, {}, 6);
        else panels(at - T / 2, at + T / 2, c0, c1, b0, b1, PANEL, {}, 6);
      };
      for (let i = 0; i < pts.length - 1; i++) {
        const b0 = pts[i], b1 = pts[i + 1], m = (b0 + b1) / 2;
        const hs = holes.filter((q) => m > q.c - q.w / 2 && m < q.c + q.w / 2).sort((p, q) => p.y - q.y);
        let y = y0;
        for (const h of hs) { put(b0, b1, y, h.y); y = h.y + h.h; }
        put(b0, b1, y, y1);
      }
      // dark door frames (a little deeper than the wall), one accent bar above
      for (const h of holes) {
        const f = 0.15, Dp = T + 0.1, col = h.col || OR;
        if (ax === 'x') {
          k.box(h.c - h.w / 2 + f / 2, h.y, at, f, h.h, Dp, FRAME);
          k.box(h.c + h.w / 2 - f / 2, h.y, at, f, h.h, Dp, FRAME);
          k.box(h.c, h.y + h.h - f, at, h.w - 2 * f, f, Dp, FRAME);
          for (const s of [-1, 1]) k.deco(h.c, h.y + h.h + 0.25, at + s * (T / 2 + 0.03), h.w, 0.3, 0.06, col, EM(col));
        } else {
          k.box(at, h.y, h.c - h.w / 2 + f / 2, Dp, h.h, f, FRAME);
          k.box(at, h.y, h.c + h.w / 2 - f / 2, Dp, h.h, f, FRAME);
          k.box(at, h.y + h.h - f, h.c, Dp, f, h.w - 2 * f, FRAME);
          for (const s of [-1, 1]) k.deco(at + s * (T / 2 + 0.03), h.y + h.h + 0.25, h.c, 0.06, 0.3, h.w, col, EM(col));
        }
      }
    };
    // a laser bar to slide under (bottom 1.2) between two dark posts; along 'x' or 'z'
    const laser = (ax, x, z, len, y = 0) => {
      if (ax === 'x') {
        k.box(x, y + 1.2, z, len - 0.5, 0.18, 0.14, '#ff3a1c', LASER);
        for (const s of [-1, 1]) k.box(x + s * (len / 2 - 0.125), y, z, 0.25, 1.6, 0.3, FRAME);
      } else {
        k.box(x, y + 1.2, z, 0.14, 0.18, len - 0.5, '#ff3a1c', LASER);
        for (const s of [-1, 1]) k.box(x, y, z + s * (len / 2 - 0.125), 0.3, 1.6, 0.25, FRAME);
      }
    };
    // boxes / decos / slabs by their extents
    const bx = (x0, x1, z0, z1, y, h, col, o) => k.box((x0 + x1) / 2, y, (z0 + z1) / 2, x1 - x0, h, z1 - z0, col, o);
    const dc = (x0, x1, z0, z1, y, h, col, o) => k.deco((x0 + x1) / 2, y, (z0 + z1) / 2, x1 - x0, h, z1 - z0, col, o);
    const sl = (x0, x1, z0, z1, top, col, hole) => slabHole(k, x0, x1, z0, z1, top, hole || null, col);
    const tint = (x0, x1, z0, z1, col, y = 0) => dc(x0 + 0.75, x1 - 0.75, z0 + 0.75, z1 - 0.75, y, 0.02, TINT(col));

    // ---------------- shell: floor, ceiling, outer walls ----------------
    panels(-E, E, -0.5, 0, -E, E, FLOOR);
    k.box(0, TOP, 0, 2 * E + 1, 0.5, 2 * E + 1, CEIL, { noShadow: true });
    wall('x', -E - 0.25, -E - 0.5, E + 0.5, 0, TOP, []);
    wall('x', E + 0.25, -E - 0.5, E + 0.5, 0, TOP, []);
    wall('z', -E - 0.25, -E, E, 0, TOP, []);
    wall('z', E + 0.25, -E, E, 0, TOP, []);

    // ---------------- walls between the wings and the corner rooms (every one its own doors) ----------------
    const D = (c, w, y, h, col) => ({ c, w, y, h, col });
    wall('z', XW, -E, ZN + 0.25, 0, TOP, [D(-11.5, 4, 0, 3.2, OR), D(-21.25, 3, GAL, 2.6, OR)]);     // NW | N
    wall('z', XE, -E, ZN + 0.25, 0, TOP, [D(-16.5, 4, 0, 3.2, OR), D(-21.25, 3, GAL, 2.6, OR)]);     // N | NE
    wall('z', XW, ZS - 0.25, E, 0, TOP, [D(19, 4, 0, 3.2, BL), D(12.6, 3, L1, 3.2, BL)]);           // SW | S
    wall('z', XE, ZS - 0.25, E, 0, TOP, [D(16, 4, 0, 3.2, BL), D(20, 3, L1, 3.2, BL)]);             // S | SE
    wall('x', ZN, -E, XW - 0.25, 0, TOP, [D(-16, 4, 0, 3.2, OR), D(-21.5, 2.5, 0, 3.2, OR)]);        // NW | W
    wall('x', ZN, XE + 0.25, E, 0, TOP, [D(19, 3.5, 0, 2.5, BL), D(12, 3, L1, 3.2, BL)]);             // NE | E
    wall('x', ZS, XE + 0.25, E, 0, TOP, [D(11.5, 3.5, 0, 2.5, BL), D(18, 3, L1, 3.2, BL)]);             // SE | E
    wall('x', ZS, -E, XW - 0.25, 0, TOP, [D(-14, 4, 0, 3.2, OR), D(-20, 3, L1, 3.2, OR)]);          // SW | W (balcony)

    // ---------------- the atrium ----------------
    k.box(-5, 0, -2.5, 3.5, TOP, 3.5, null, GLASS);                    // the core: frosted glass, unkickable
    k.deco(-5, 0.01, -2.5, 5.5, 0.02, 5.5, BL, EM(BL));
    k.deco(-5, 0.02, -2.5, 4.1, 0.02, 4.1, FLOOR);
    // bridges at 4.4: north-south at x = 2 (on into the tall chamber as the pier), east-west at
    // z = 4 (from the test floor's target to the low lab's deck), split where they cross
    slab(k, 2, L1, 1.5, 3.5, ZS - ZN, UPPER, { t: 0.4 });
    slab(k, (-15 + 0.25) / 2, L1, 4, 15.25, 3.5, UPPER, { t: 0.4 });
    slab(k, (3.75 + XE + 0.25) / 2, L1, 4, XE + 0.25 - 3.75, 3.5, UPPER, { t: 0.4 });
    for (const s of [-1, 1]) k.deco(2 + s * 1.78, L1 - 0.3, 1.5, 0.04, 0.16, ZS - ZN - 0.4, OR, EM(OR));
    for (const s of [-1, 1]) k.deco(-7.4, L1 - 0.3, 4 + s * 1.78, 15, 0.16, 0.04, BL, EM(BL));
    // floor: a launch plate beside the north-south bridge, step blocks onto the east-west one,
    // a vault, a laser bar, juke posts
    k.pad(5.5, 0, -2.5, 1.6, 1.6, 18, { color: OR });
    bx(-4, -2, 5.75, 7.75, 0, 2.4, PANEL);
    bx(-4, -2, 7.75, 9.5, 0, 1.2, PANEL);
    bx(-9, -6, -5.6, -5, 0, 1.0, OR);
    laser('x', 4.5, 8.2, 4);
    for (const [x, z] of [[-1.5, -5.5], [-8, 7]]) k.box(x, 0, z, 1, 3.2, 1, FRAME);

    // ---------------- N: the tall chamber (x -10..7, z -23..-7) ----------------
    tint(XW, XE, -E, ZN, OR);
    sl(XW + 0.25, XE - 0.25, -E, -19.5, GAL, UPPER);                     // the high gallery at 6.6
    dc(XW + 0.25, XE - 0.25, -19.45, -19.42, GAL - 0.3, 0.16, OR, EM(OR));
    sl(0.25, 3.75, -19.5, ZN, L1, UPPER);                                // the pier: the bridge, on to the gallery
    for (const x of [0.22, 3.75]) dc(x, x + 0.03, -19.3, ZN, L1 - 0.3, 0.16, OR, EM(OR));
    bx(3.75, 5.75, -13, -11, 0, 2.4, PANEL);                             // step blocks up onto the pier
    bx(3.75, 5.75, -11, -9, 0, 1.2, PANEL);
    // the kick chimney: two free-standing walls up to the gallery's edge (the only kick route here)
    bx(-7.6, -7, -19.5, -15.5, 0, GAL, null, KICK);
    bx(-3.8, -3.2, -19.5, -15.5, 0, GAL, null, KICK);
    // tall frosted columns, a vault wall and a laser bar on the floor
    for (const [x, z] of [[-8, -10.5], [-4.5, -12.5], [-1.2, -9.5]]) bx(x - 0.7, x + 0.7, z - 0.7, z + 0.7, 0, TOP, null, GLASS);
    bx(-9.5, -7.5, -14.3, -13.7, 0, 1.0, OR);
    laser('z', -1, -15.5, 4.5);

    // ---------------- E: the low lab (x 7..23, z -7..10) ----------------
    // the deck at 3.0 over the whole wing (underside 2.6), with two holes: step blocks / a launch plate
    sl(XE + 0.25, E, ZN + 0.25, 1.5, DECK, UPPER, [17, 21, -4.5, -0.5]);
    sl(XE + 0.25, E, 1.5, ZS - 0.25, DECK, UPPER, [11.5, 15.5, 3.5, 7.5]);
    dc(XE + 0.22, XE + 0.25, ZN + 0.25, ZS - 0.25, DECK - 0.3, 0.16, BL, EM(BL));
    bx(17.5, 20.5, -4.5, -2.5, 0, 2.0, PANEL);
    bx(17.5, 20.5, -2.5, -0.5, 0, 1.0, PANEL);
    k.pad(13.5, 0, 6.1, 1.6, 1.6, 15, { color: BL, aim: [13.5, 12, 3] });   // flies up through the hole onto the deck
    // underneath: lab benches to slide under (too low under the deck to climb on), a laser bar,
    // light strips
    tint(XE, E, ZN, ZS, BL);
    const bench = (x0, x1, z0, z1, col) => {
      bx(x0, x1, z0, z1, 1.05, 0.15, col);
      for (const x of [x0 + 0.06, x1 - 0.06]) for (const z of [z0 + 0.06, z1 - 0.06]) k.box(x, 0, z, 0.12, 1.05, 0.12, FRAME);
    };
    bench(9, 14, -4.6, -3.4, PANEL);
    bench(9.5, 15.5, 0.4, 1.6, PANEL);
    bench(17, 22, 4.8, 6, PANEL);
    bench(19.3, 20.5, 1.2, 3.8, BL);
    laser('z', 16, 5.5, 4);
    for (const x of [11, 19]) k.deco(x, DECK - 0.46, 1.5, 0.4, 0.06, 12, '#fffdf5', GLOW);
    // on top: two cabinets to juke round, a frosted pane, a laser bar
    bx(10, 11.5, -5.5, -4, DECK, 1.2, PANEL);
    bx(19, 20.5, 7, 8.5, DECK, 1.2, PANEL);
    bx(15.5, 15.8, -2.5, 2.5, DECK, TOP - DECK, null, GLASS);
    laser('x', 11, 2, 4, DECK);

    // ---------------- S: the two-storey gallery (x -10..7, z 10..23) ----------------
    tint(XW, XE, ZS, E, BL);
    sl(XW + 0.25, XE - 0.25, ZS, 15, L1, UPPER);                         // the U: along the atrium...
    sl(XW + 0.25, -6, 15, E, L1, UPPER);                                 // ...and down both sides
    sl(3, XE - 0.25, 15, E, L1, UPPER);
    for (const [u0, u1] of [[XW + 0.25, -5.5], [-1.5, 0], [4, XE - 0.25]]) bx(u0, u1, ZS + 0.1, ZS + 0.4, 0, L1 - 0.4, null, GLASS);
    dc(-6, 3, 15.02, 15.05, L1 - 0.3, 0.16, BL, EM(BL));
    stairs(k, -4.5, 22.6, '-z', 3, 0, L1, OR);
    bx(1, 3, 17, 19, 0, 2.4, PANEL);                                     // step blocks: a second way up
    bx(1, 3, 19, 21, 0, 1.2, PANEL);
    for (const [x, z] of [[-1.2, 17.5], [-0.5, 21.5]]) bx(x - 0.7, x + 0.7, z - 0.7, z + 0.7, 0, TOP, null, GLASS);
    laser('z', -3, 12.6, 4.5, L1);
    k.box(-8, L1, 21, 2, 1.2, 2, PANEL);

    // ---------------- W: the open test floor (x -23..-10, z -7..10) ----------------
    tint(-E, XW, ZN, ZS, OR);
    sl(-19, -15, 1, 6, L1, UPPER, [-18, -16, 3, 5]);                     // the target, a launch plate under it
    for (const z of [0.97, 6]) dc(-19, -15, z, z + 0.03, L1 - 0.3, 0.16, OR, EM(OR));
    k.pad(-17, 0, 4, 1.6, 1.6, 18, { color: OR, aim: [-17, 0, 1.4] });     // up through the hole onto the target
    bx(-21, -17, -3.6, -3.3, 0, TOP, null, GLASS);                       // frosted partitions
    bx(-14.5, -14.2, -4, 1.5, 0, TOP, null, GLASS);
    bx(-22.5, -19.5, 8, 8.6, 0, 1.0, OR);                                // vault walls
    bx(-13, -12.4, 6.5, 9.5, 0, 1.0, OR);
    laser('x', -19.5, -5.3, 4.5);
    laser('z', -12, 0.5, 4);
    k.box(-21.5, 0, 1, 1, 3.2, 1, FRAME);

    // ---------------- corner observation rooms ----------------
    // NW: stairs up through the floor; a cabinet up to the gallery door
    sl(-E, XW - 0.25, -E, ZN - 0.25, L1, UPPER, [-21.8, -13.2, -16.5, -13.5]);
    tint(-E, XW, -E, ZN, BL);
    stairs(k, -21, -15, '+x', 3, 0, L1, BL);
    bx(-12.25, -10.25, -22.75, -20, L1, GAL - L1, PANEL);
    k.box(-20, 0, -20, 2, 1.2, 2, PANEL);
    laser('z', -20.75, -10.5, 4);
    bx(-17.5, -13.5, -11.7, -11.4, L1, TOP - L1, null, GLASS);
    // NE: a kick shaft (two free-standing walls 3m apart), climb out onto the upper room; a cabinet
    // up to the gallery door
    sl(XE + 0.25, E, -E, ZN - 0.25, L1, UPPER, [14.8, 17.8, -18.5, -13.5]);
    tint(XE, E, -E, ZN, OR);
    bx(14.2, 14.8, -18.5, -13.5, 0, L1 - 0.4, null, KICK);
    bx(17.8, 18.4, -18.5, -13.5, 0, L1 - 0.4, null, KICK);
    bx(XE + 0.25, XE + 2.25, -22.75, -20, L1, GAL - L1, PANEL);
    k.box(11, 0, -12, 2, 1.2, 2, PANEL);
    k.box(21, L1, -10, 2, 1.2, 2, PANEL);
    laser('x', 20.4, -16, 4.6, L1);
    bx(13.5, 17.5, -11.65, -11.35, L1, TOP - L1, null, GLASS);
    bx(11.35, 11.65, -18, -14, L1, TOP - L1, null, GLASS);
    // SE: a launch plate under a hole
    sl(XE + 0.25, E, ZS + 0.25, E, L1, UPPER, [14, 18, 15, 19]);
    tint(XE, E, ZS, E, BL);
    k.pad(16, 0, 17.6, 1.6, 1.6, 18, { color: BL, aim: [16, 24, 2.2] });
    k.box(20.5, 0, 21, 2, 1.2, 2, PANEL);
    laser('x', 11.5, 20.75, 4);
    laser('z', 20.5, 16.5, 4.5, L1);
    k.box(12, L1, 21.5, 2, 2.4, 2, PANEL);
    // SW: step blocks under a hole (1.2 -> 2.4 -> pull up onto the upper room)
    sl(-E, XW - 0.25, ZS + 0.25, E, L1, UPPER, [-18.5, -13.5, 14, 19]);
    tint(-E, XW, ZS, E, OR);
    k.box(-14.5, 0, 16.5, 2, 2.4, 2, PANEL);
    k.box(-16.5, 0, 16.5, 2, 1.2, 2, PANEL);
    k.box(-20.5, 0, 12.5, 2, 1.2, 2, PANEL);
    laser('x', -20.7, 16.5, 4, L1);
    k.box(-12, L1, 21.5, 2, 2.4, 2, PANEL);
    bx(-21, -17, 13.35, 13.65, L1, TOP - L1, null, GLASS);
    // ceiling light strips under the upper rooms
    for (const [x, z] of [[-16.5, -15], [15, -15], [15, 16.5], [-16.5, 16.5]]) k.deco(x, L1 - 0.46, z, 0.4, 0.06, 10, '#fffdf5', GLOW);
  },
});

;
/* ==== js/maps/skatepark.js ==== */
// THE SKATEPARK - a walled skatepark by the sea, built for speed. No void: walls all round
// (invisible above them). Same layout as before, ~15% tighter, and kept plain: concrete plus a
// few bold colors, like Rooftops and the Container Yard.
//   center   THE FUNBOX: a block (deck at 4) with launch ramps north and south, a slide tunnel
//            straight through it at ground level, and a crown block on top (8) - kick up its
//            orange chimney on the north or hop the step on the south
//   east     the blue tower: a long deck at 4 with a block on top at 8 (step or orange chimney),
//            bridged to the funbox and to the two east corner platforms at 4
//   west     the coral tower, the same idea mirrored
//   corners  four 4m platforms, each a different way up: stairs (SE), bank ramp (SW),
//            crate step (NE), wall kicks in the corner by the walls (NW)
//   ground   rails to vault, ledges, planters, slide bars across the side lanes, containers,
//            two shade roofs (5.2, reached from the containers next to them)
// Every floor has 3.6m+ above it. Levels: ground 0, decks 4, tops 8.
defineMap({
  id: 'skatepark',
  accent: ['#3fb8a0', '#4f86e8'],
  name: 'The Skatepark',
  blurb: 'A walled skatepark by the sea. Launch ramps, a slide tunnel through the funbox, decks and towers to run.',
  env: 'sky',
  sky: '#a9d6ff',
  sea: -3,
  fog: [90, 300],
  hemi: ['#eaf4ff', '#5a6470', 0.95],
  sun: [1.0, 30, 55, 20],
  size: 28,
  menuCam: { r: 26, y: 15 },
  spawns: [
    [-7, 0, -8.5], [7, 0, 8.5], [-8.5, 0, 8.5], [8.5, 0, -8.5], [0, 0, -12.6], [0, 0, 12.6],
    [-21.5, 0, -5], [21.5, 0, 5], [-11, 0, 0], [11, 0, 0],
    [-3.8, 4, -4.3], [0, 4, 4.7], [15.3, 4, -5], [-15.3, 4, 5], [19.4, 4, -19.4], [-19.4, 4, 19.4],
  ],
  seekerSpawn: [0, 4, 4.7],

  build(k) {
    const ASPHALT = '#4a4f5a', CONC = '#c9c4ba', CONC2 = '#a9a398';
    const TEAL = '#1f7a6c', CORAL = '#b8463c', BLUE = '#2f55a8', BUTTER = '#d9a62e', KICK = { tex: 'kick' };
    const H = 4, T = 8, WH = 7, HW = 24.5;   // deck, top, wall heights; wall center line

    // ---- ground and walls (7m) with an invisible wall above ----
    ground(k, 51, 51, ASPHALT);
    for (const s of [-1, 1]) {
      k.box(0, 0, s * HW, 51, WH, 2, CONC);
      k.box(s * HW, 0, 0, 2, WH, 47, CONC);
      k.wall(0, WH, s * HW, 51, 40, 2);
      k.wall(s * HW, WH, 0, 2, 40, 47);
    }

    // ---- THE FUNBOX (center) ----
    k.box(0, 0, -4.05, 10.2, H, 5.1, CONC2);            // north half
    k.box(0, 0, 4.05, 10.2, H, 5.1, CONC2);             // south half
    k.box(0, 1.2, 0, 10.2, H - 1.2, 3, CONC2);          // roof of the slide tunnel (1.2m high)
    k.ramp(0, -9.6, 6, 6, 0, H, '+z', TEAL);            // launch ramps north + south
    k.ramp(0, 9.6, 6, 6, 0, H, '-z', TEAL);
    // crown block on top (8): orange kick wall 3m off its north face, a step on the south
    k.box(0, H, 0, 4.5, T - H, 4.5, CORAL);
    k.box(0, H, -5.5, 4.5, T - H + 0.5, 0.5, '#ff6a3d', KICK);
    k.box(0, H, 3.25, 3, 1.2, 2, CONC);
    // side steps up onto the funbox from the ground (1.2, then pull up to 4)
    k.box(6.4, 0, 3.8, 2.6, 1.2, 3.4, CONC);
    k.box(-6.4, 0, -3.8, 2.6, 1.2, 3.4, CONC);

    // ---- side towers (east blue, west coral): deck at 4, block on top to 8 ----
    for (const s of [-1, 1]) {
      const x = s * 16.15, col = s > 0 ? BLUE : CORAL;
      k.box(x, 0, 0, 6.8, H, 11.9, col);
      k.box(x, H, s * -1.7, 6.8, T - H, 5.1, CONC);              // the 8m block toward one end
      k.box(x, H, s * 4.1, 6.8, T - H + 0.5, 0.5, '#ff6a3d', KICK);   // kick wall 3m off the block
      k.box(x + s * 2.1, H, s * -5.1, 2.6, 1.2, 1.7, CONC2);     // step (5.2) at the other end
      k.ramp(x - s * 1.95, 8.95, 3, 6, 0, H, '-z', TEAL);       // ramps up at both deck ends
      k.ramp(x - s * 1.95, -8.95, 3, 6, 0, H, '+z', TEAL);
      bridge(k, s * 5.1, s * -4.7, s * 12.75, s * -4.7, H, 3, CONC);   // funbox <-> tower at 4
    }

    // ---- corner platforms (4m), each a different way up, bridged to the tower decks ----
    const corner = (sx, sz, col) => {
      k.box(sx * 19.4, 0, sz * 19.4, 8, H, 8, col);
      bridge(k, sx * 17.9, sz * 5.95, sx * 17.9, sz * 15.4, H, 3, CONC);
    };
    corner(1, 1, BUTTER);     // SE: stairs
    corner(-1, 1, TEAL);      // SW: bank ramp
    corner(1, -1, TEAL);      // NE: crate step
    corner(-1, -1, BUTTER);   // NW: kick up the corner against the walls
    stairs(k, 8.4, 19.4, '+x', 3, 0, H, CONC2);
    k.ramp(-12.4, 19.4, 6, 4, 0, H, '-x', TEAL);
    k.box(13.9, 0, -19.4, 3, 1.2, 4, CONC2);

    // ---- ground: rails (vault), ledges, planters, slide bars, containers, shade roofs ----
    for (const [x, z, alongX] of [[-7.65, -12.75, true], [7.65, 12.75, true], [-11.6, 7.65, false], [11.6, -7.65, false]]) {
      k.box(x, 0, z, alongX ? 5 : 0.4, 1.0, alongX ? 0.4 : 5, CORAL);
    }
    for (const s of [-1, 1]) {
      k.box(0, 0, s * 20.5, 8.5, 1.2, 2, CONC2);                 // long ledges by the north/south walls
      k.box(s * 21.55, 1.25, 0, 3.9, 0.35, 0.4, '#3d4350');        // slide bars across the side lanes
    }
    for (const [x, z] of [[-21.3, -9.4], [21.3, 9.4], [21.3, -9.4], [-21.3, 9.4]]) k.box(x, 0, z, 2.6, 1.2, 2.6, TEAL);   // planters
    for (const [x, z, alongX, col] of [[8.5, -14.45, true, CORAL], [-8.5, 14.45, true, BLUE], [9.4, 8.5, false, BLUE], [-9.4, -8.5, false, CORAL]]) {
      k.box(x, 0, z, alongX ? 6 : 2.4, 2.6, alongX ? 2.4 : 6, col);
    }
    // shade roofs in front of the ledges: top 5.2, 4.8 clear underneath; hop on from the containers
    for (const s of [-1, 1]) {
      slab(k, 0, 5.2, s * 16.2, 10, 3.4, BUTTER, { t: 0.4 });
      posts(k, [[-4.8, s * 14.7], [4.8, s * 14.7], [-4.8, s * 17.7], [4.8, s * 17.7]], 0, 4.8, '#3d4350', 0.35);
    }
  },
});

;
/* ==== js/maps/estate.js ==== */
// THE ESTATE - a brutalist housing estate in raw concrete under an overcast sky. Walled in all
// round, no void. Heavy blocks, deep window recesses, pilotis, long footbridges.
//   center   THE COURT: sunken 2m, terraced steps down, a ramp on the east side. In the middle
//            the MONOLITH (top 10) - wall-kick up its orange chimney. A vent pad in the corner
//   north    THE SLAB: a long block on pilotis - run through the colonnade underneath, balconies at
//            4 and 8 (stairs at the west end, stairs up the east end), roof at 12 (orange chimney
//            off the east end), a lift-house on the roof (16)
//   east     THE STACK: concrete cells stacked off each other (4, 8, 12) - climb cell to cell
//            from the step blocks
//   south    THE CAR PARK: two decks (4, 8) with ramps up, low parapets to vault
//   west     THE CORE: a stepped block (ramp + step blocks, top 8) and long footbridges at 8: core -> the pod by the
//            court -> the slab's balcony (north) and the car park's top deck (south)
// Levels: court -2, ground 0, decks 4, 8, roofs 12. Every floor has 3.4m+ above it.
defineMap({
  id: 'estate',
  accent: ['#a5a198', '#3d5a8a'],
  name: 'The Estate',
  blurb: 'A brutalist concrete estate: a sunken court with a monolith, a slab block on pillars, stacked cells, a car park and long footbridges.',
  env: 'fog',
  sky: '#b4bcc5',
  fog: [60, 190],
  hemi: ['#f2f4f7', '#55595f', 1.25],
  sun: [1.35, 25, 60, 35],
  size: 34,
  menuCam: { r: 44, y: 26 },
  spawns: [
    [-15, 0, 9], [15, 0, -10], [0, 0, -14], [12, 0, 13], [-20, 0, -11], [9, 0, 26], [-21.5, 0, 12.5], [25.5, 0, -4.5],
    [-4.5, -2, 4.5], [4.5, -2, -4.5],
    [0, 4, -20.5], [-18, 4, 20.5], [26, 4, 0],
    [-11, 8, -0.5], [-20, 8, 22],
  ],
  seekerSpawn: [0, 0, -14],
  centerSpot: [-4.5, -2, 4.5],

  build(k) {
    // raw concrete in three strong values, near-black recesses, and two accents
    const PAVE = '#6f6b65', C1 = '#b9b3a8', C2 = '#8f8a80', C3 = '#5d5953', REC = '#26252a';
    const MUST = '#d9a62e', BLUE = '#3d5a8a', GREEN = '#6e8f5a', KICK = { tex: 'kick' }, KC = '#ff6a3d';
    const HW = 30, WH = 9;
    // deep window recesses on a face: rows of dark insets (just looks)
    const windows = (x0, x1, y0, y1, face, axis, out) => {
      for (let y = y0 + 0.9; y + 1.6 <= y1 - 0.4; y += 4) {
        for (let a = x0 + 1.2; a + 1.4 <= x1 - 0.6; a += 2.6) {
          if (axis === 'z') k.deco(a + 0.7, y, face + out * 0.03, 1.4, 1.8, 0.06, REC, { tex: 'none' });
          else k.deco(face + out * 0.03, y, a + 0.7, 0.06, 1.8, 1.4, REC, { tex: 'none' });
        }
      }
    };

    // ===== ground (top 0) with the court sunk 2m in the middle =====
    // the walls hug the blocks (x -29..28, z -27..27): no empty strips round the edge, players meet
    const X0 = -29, X1 = 28, Z0 = -27, Z1 = 27, XM = (X0 + X1) / 2, XW = X1 - X0, ZW = Z1 - Z0;
    slabHole(k, X0 - 1, X1 + 1, Z0 - 1, Z1 + 1, 0, [-8, 8, -8, 8], PAVE, { t: 2 });
    k.box(0, -3.2, 0, 16, 1.2, 16, C3);                                   // court floor (-2)
    // perimeter walls (9m) + invisible walls above
    for (const [z, s] of [[Z0, -1], [Z1, 1]]) {
      k.box(XM, 0, z + s * 0.5, XW + 2, WH, 1, C2);
      k.wall(XM, WH, z + s * 0.5, XW + 2, 40, 1);
      k.deco(XM, WH, z + s * 0.5, XW + 2.2, 0.5, 1.4, C3, { tex: 'none' });   // heavy coping
    }
    for (const [x, s] of [[X0, -1], [X1, 1]]) {
      k.box(x + s * 0.5, 0, 0, 1, WH, ZW, C2);
      k.wall(x + s * 0.5, WH, 0, 1, 40, ZW);
      k.deco(x + s * 0.5, WH, 0, 1.4, 0.5, ZW + 2.2, C3, { tex: 'none' });
    }

    // ===== THE COURT =====
    // terraces: a 1m step all round (jump down / hop up), a ramp on the east side
    k.box(0, -2, -7, 16, 1, 2, C2);
    k.box(-7, -2, 1, 2, 1, 14, C2);
    k.box(0, -2, 7, 12, 1, 2, C2);
    k.ramp(7, 1, 2, 12, -2, 0, '+x', C2, { base: -2 });   // gentle way out, east side
    // the monolith (top 10) + its orange kick chimney (wall 2.8 off its south face)
    k.box(0, -2, 0, 4, 12, 4, C1);
    k.box(0, -2, 4.95, 4, 12, 0.5, KC, KICK);
    k.deco(0, 9.4, 0, 4.3, 0.6, 4.3, C3, { tex: 'none' });   // a heavy cap band
    // vent pad in the court corner (run into it the way you want to fly)
    k.pad(-4.5, -2, -4.5, 1.6, 1.6, 23, { color: MUST });

    // ===== THE SLAB (north) =====
    // level 4 slab on two rows of pilotis (the colonnade), x -27..27, z -27..-19
    k.box(0, 3.4, -23, 54, 0.6, 8, C2);
    for (let x = -24; x <= 24; x += 6) for (const z of [-26.2, -19.8]) k.box(x, 0, z, 1, 3.4, 1, C3);
    // the mass above: back half, top 12, with deep window grids on its south face
    k.box(0, 4, -24.5, 44, 8, 5, C1);
    windows(-22, 22, 4, 12, -22, 'z', 1);
    // level 8 balcony along the front (open over the stairs at the east end)
    k.box(-5, 7.4, -20.6, 34, 0.6, 2.8, C2);
    k.box(23.3, 7.4, -20.6, 7.4, 0.6, 2.8, C2);   // meets the stairs' top step (x 19.6): no slot to drop down beside them
    k.box(-17.25, 8, -19.3, 9.5, 0.9, 0.3, MUST, { tex: 'none' });   // a low mustard rail (vault it),
    k.box(1.25, 8, -19.3, 21.5, 0.9, 0.3, MUST, { tex: 'none' });    // open where the footbridge lands
    // stairs: ground -> balcony 4 at the west end, balcony 4 -> 8 at the east end
    stairs(k, -25.5, -11.5, '-z', 2.6, 0, 4, C2);
    k.box(-25.5, 3.4, -18.75, 2.6, 0.6, 0.5, C2);   // the balcony's edge meets their top step (z -18.5): no slot to drop down
    stairs(k, 12.6, -20.6, '+x', 2.6, 4, 8, C2);
    // roof 12: orange chimney up the east end (wall 2.8 off the block's east face), lift-house (16)
    k.box(24.8 + 0.25, 4, -24.5, 0.5, 8.6, 4.6, KC, KICK);
    k.box(-15, 12, -24.5, 4, 4, 4, C2);
    k.box(-12.3, 12, -24.5, 1.4, 1.2, 1.4, C3);                  // step up to the lift-house
    windows(-17, -13, 12, 16, -22.5, 'z', 1);
    // beams across the colonnade at slide height
    for (const x of [-15, 3, 15]) k.box(x, 1.15, -23, 0.6, 0.6, 5.4, C3);

    // ===== THE STACK (east) =====
    const cell = (x, y, z, col) => { k.box(x, y, z, 6, 4, 6, col); windows(x - 3, x + 3, y, y + 4, z + 3, 'z', 1); windows(z - 3, z + 3, y, y + 4, x - 3, 'x', -1); };
    cell(24, 0, 2, C1);                 // top 4   x 21..27 z -1..5
    cell(21, 4, 6, C2);                 // top 8   x 18..24 z 3..9  (sits on the first, overhangs the ground)
    cell(25, 8, 10, C1);                // top 12  x 22..28 z 7..13
    k.box(19.6, 0, 0.5, 2, 1.2, 2, BLUE);    // step onto the first cell
    k.box(25.2, 4, 3.6, 1.6, 1.2, 1.6, BLUE);   // step onto the second
    k.box(20.6, 8, 7.6, 1.6, 1.2, 1.6, BLUE);   // step onto the third
    // the long footbridge from the second cell (8) across to the slab's upper balcony - the stack
    // is a loop, not a dead end
    bridge(k, 22, 3, 22, -19.2, 8, 2.4, C1);
    for (const z of [-4, -12]) k.box(22, 0, z, 0.8, 7.6, 0.8, C3);
    k.box(22, 8, -8, 2.4, 0.5, 0.3, C3);   // a kerb mid-bridge to hop
    k.box(18.6, 0, 8.4, 0.8, 4, 0.8, C3);   // pillars under the overhangs
    k.box(27.4, 0, 12.4, 0.8, 8, 0.8, C3);

    // ===== THE CAR PARK (south) =====
    k.box(-14, 3.4, 20.5, 20, 0.6, 13, C2);                      // deck A (top 4) x -24..-4 z 14..27
    k.box(-18, 7.4, 20.5, 12, 0.6, 13, C2);                      // deck B (top 8) x -24..-12
    for (const x of [-22, -16, -10, -5]) for (const z of [15, 20.5, 26]) k.box(x, 0, z, 0.8, 3.4, 0.8, C3);
    for (const x of [-22, -16]) for (const z of [15, 26]) k.box(x, 4, z, 0.8, 3.4, 0.8, C3);
    k.ramp(-1, 24.5, 6, 4, 0, 4, '-x', C2);                      // ground -> deck A (from the east)
    k.ramp(-8, 16.5, 8, 4, 4, 8, '-x', C2, { base: 4 });        // deck A -> deck B
    k.box(-3, 3.4, 16.5, 2, 0.6, 5, C2);                         // a landing at the ramp's foot
    // parapets to vault (1m)
    k.box(-14, 4, 26.75, 20, 1, 0.5, C3);
    k.box(-18, 8, 26.75, 12, 1, 0.5, C3);
    k.box(-2.25, 4, 16.5, 0.5, 1, 5, C3);

    // ===== THE CORE (west) + footbridges at 8 =====
    // the core: a solid stepped block (4, then 8) - a concrete ramp up its south side, step blocks
    k.box(-24, 0, 0, 10, 4, 6, C2);
    k.box(-26, 4, 0, 6, 4, 6, C1);
    windows(-29, -19, 0, 4, 3, 'z', 1);
    k.ramp(-24, 4.5, 10, 3, 0, 4, '-x', C2);
    k.box(-18.2, 0, -2, 1.4, 1.2, 1.4, BLUE);
    k.box(-22.2, 4, -2, 1.4, 1.2, 1.4, BLUE);
    // the pod: a platform at 8 on pilotis next to the court
    k.box(-11, 7.4, 0, 6, 0.6, 6, C2);
    for (const [x, z] of [[-13.5, -2.5], [-8.5, -2.5], [-13.5, 2.5], [-8.5, 2.5]]) k.box(x, 0, z, 0.7, 7.4, 0.7, C3);
    bridge(k, -23, 0, -14, 0, 8, 2.6, C1);                        // core -> pod
    bridge(k, -11, -3, -11, -19.2, 8, 2.6, C1);                   // pod -> the slab's balcony
    bridge(k, -13, 3, -13, 14, 8, 2.6, C1);                       // pod -> car park deck B
    for (const z of [-11, 8.5]) k.box(z < 0 ? -11 : -13, 0, z, 0.8, 7.6, 0.8, C3);   // bridge piers

    // ===== THE CANOPY (south-east): a thick concrete roof (4) on fat columns, a step up =====
    k.box(11, 3.2, 23.5, 10, 0.8, 7, C2);
    for (const [x, z] of [[7, 21], [15, 21], [7, 26], [15, 26]]) k.box(x, 0, z, 1.2, 3.2, 1.2, C3);
    k.box(17.4, 0, 21.2, 1.6, 1.2, 1.6, BLUE);
    k.deco(11, 3.75, 23.5, 10.2, 0.25, 7.2, C3, { tex: 'none' });   // its cap band, flush with the roof you stand on (it sat on top: feet sank 25cm into it)
    // ===== concrete fins in the open ground to circle and juke around =====
    for (const [x, z, r] of [[11, -4, 0.5], [-15, -14, -0.4], [5.5, -13, 0.3], [-19, 8, 0.9], [20, -12, -0.7]]) k.box(x, 0, z, 4, 3, 0.8, C2, { rot: r });
    // ===== plinths: one raw concrete block (4 x 4, 2.6 high - a jump and a pull-up), repeated over the open
    // ground so every lane is 2.5-4m and every deck at 4 has a plinth beside it to climb from. A second
    // block stacked on one makes a 5.2 step up to the 8s =====
    const plinth = (x, z, h = 2.6, c = C2) => k.box(x, 0, z, 4, h, 4, c);
    plinth(0, -17);                     // against the slab's balcony (4): plinth -> balcony
    plinth(9.5, -15.5, 2.6, C1);
    plinth(-20.5, -15.5, 2.6, C1);      // west, between the stairs and the fin
    plinth(14, 5, 2.6, C1);             // east, between the court and the stack
    plinth(-25, 10);                    // west, by car park deck A (4)
    plinth(19, 16.5, 2.6, C1);          // the south-east yard
    plinth(25.5, 20); k.box(26, 2.6, 19.5, 3, 2.6, 3, C1);   // ...a two-step block (5.2)
    plinth(20.5, 24.5);
    plinth(-12.5, -8, 2.6, C1);         // round the court: three more, so its ring is lanes, not a field
    plinth(15, -6.5);
    plinth(-4, 11.5, 2.6, C1);
    plinth(26, -8, 2.6, C1);            // under the east footbridge
    plinth(-25, -7);                    // west, by the core

    // ===== the ground: planters, low walls to vault, benches =====
    for (const [x, z] of [[-16, 6], [16, 20], [-6, -12], [4, 12]]) {
      k.box(x, 0, z, 2.4, 1, 2.4, C2);
      k.deco(x, 1, z, 2, 0.15, 2, GREEN, { tex: 'none' });
    }
    for (const [x, z, w, d] of [[-18, -6, 6, 0.6], [3, 17, 0.6, 5], [16, -16, 6, 0.6], [-6, -17, 0.6, 4], [5, -9.5, 4, 0.6]]) k.box(x, 0, z, w, 1, d, C3);
    for (const [x, z] of [[-10, 11], [11, -11], [0, 17]]) k.box(x, 0, z, 3, 0.5, 0.8, C1);
  },
});

;
/* ==== js/maps/bounce.js ==== */
// BOUNCE HOUSE - a long indoor trampoline park with a Z-shaped hall: the west half is wider to the
// north, the east half wider to the south, with angled corners where they meet.
//   runway       a long line of red mats down the middle of the hall - bounce end to end
//   west         a sunken foam pit (stepped foam blocks to climb out, a green tramp up to the
//                west terrace) and terraces stepping up the north wall: 2.2 -> 4.4 -> 6.6
//   east         terraces up the north wall (2.2 -> 4.4 -> 6.6), an 8.8 end balcony with an
//                kick chimney up to it (an orange wall 3m off its face), and a long bridge back along the south wall
//   middle       a bridge (4.4) across the runway from the west terraces to the south deck (4.4)
//   floor        foam stacks all along both sides of the runway: 3x3 cubes, 2.2 mustard and 4.4
//                teal, each in reach of the next (floor -> 2.2 -> 4.4 -> terraces and decks), with
//                3-4m lanes between, plus three padded columns - corners to turn, views broken up
// Loops: around the runway on the floor, and a figure-eight over the decks and bridges.
// Ceiling 15 - the strongest launch tops out well below it.
defineMap({
  id: 'bounce',
  accent: ['#e2463c', '#3b6fd4'],
  name: 'Bounce House',
  blurb: 'A long trampoline park: a bounce runway, a foam pit, terraces stepping up both ends, launch pads.',
  env: 'indoor',
  sky: '#1f2742',
  fog: [45, 120],
  hemi: ['#ffffff', '#8a93aa', 1.3],
  sun: [0.5, 4, 60, 6],
  size: 40,
  spotHeight: 14.6,
  spots: [-28, -14, 0, 14, 28].flatMap((x) => [-6, 6].map((z) => ({ x, z }))),
  menuCam: { path: [[-28, 8, 2], [26, 8, 2]] },
  spawns: [
    [-22, 0, -7], [-19, 0, 6.5], [-9.5, 0, -6], [-2, 0, -8], [2, 0, 8], [8, 0, -6], [16, 0, 7.5], [17.5, 0, -2.5],
    [27.5, 0, 2.5], [-24, 6.6, -13.5], [-12, 4.4, -13.5], [0, 2.2, -13.5], [2, 4.4, 13.5], [31.5, 6.6, -9],
    [36, 8.8, 6], [-18.5, 0, 10],
  ],
  seekerSpawn: [0, 0, -6],

  build(k) {
    const FLOOR = '#cfd5dd', WALL = '#2a3557', CEIL = '#1f2742', DECK = '#3b6fd4', DECK2 = '#5b8be0', BLOCK = '#f0b928',
      MAT = '#e2463c', LAUNCH = '#2f9e6a', CREAM = '#e9e4d8';
    const D = { tex: 'none' }, Q = Math.PI / 4;

    // ---- floor, with the foam pit sunk into the west end (pit x -36..-26, z -9..5, floor -2.5) ----
    k.box(-37, -3.7, 0, 2, 3.7, 32, FLOOR, D);
    k.box(-31, -3.7, -12.5, 10, 3.7, 7, FLOOR, D);
    k.box(-31, -3.7, 10.5, 10, 3.7, 11, FLOOR, D);
    k.box(6, -3.7, 0, 64, 3.7, 32, FLOOR, D);
    k.box(-31, -3.7, -2, 10, 1.2, 14, BLOCK, D);
    enclose(k, 76, 32, 15, WALL, CEIL, D);

    // ---- the Z-shaped footprint: solid strips fill the NE and SW, angled where they meet ----
    k.box(24, 0, -13.5, 28, 15, 5, WALL, D);              // NE strip   x 10..38, z -16..-11
    k.box(-24, 0, 13.5, 28, 15, 5, WALL, D);              // SW strip   x -38..-10, z 11..16
    k.box(10, 0, -11, 3, 15, 3, WALL, { tex: 'none', rot: Q });
    k.box(-10, 0, 11, 3, 15, 3, WALL, { tex: 'none', rot: Q });
    for (const [x, z, s] of [[-38, -16, 9], [38, 16, 6], [38, -11, 6], [-38, 11, 6]]) k.box(x, 0, z, s, 15, s, WALL, { tex: 'none', rot: Q });

    // ---- the runway: red mats down the middle (gap under the bridge at x -6) ----
    for (let x = -24; x <= 28; x += 2.8) {
      if (x < -22) continue;                                          // keep a run-up clear of the foam pit
      if (x > -8.6 && x < -3.4) continue;                            // the gap under the bridge
      k.pad(x, 0, 0, 2.4, 3, 12, { look: 'tramp', color: MAT });
    }

    // ---- west: terraces up the north wall, the foam pit ----
    k.box(-26, 0, -13.5, 16, 6.6, 5, DECK, D);            // 6.6  x -34..-18
    k.box(-11, 0, -13.5, 14, 4.4, 5, DECK2, D);           // 4.4  x -18..-4
    k.box(-1, 0, -13.5, 6, 2.2, 5, DECK, D);              // 2.2  x -4..2
    // foam blocks: stepped way out of the pit, set at angles
    for (const [x, z, r] of [[-27.4, -5, 0.4], [-27.6, 1.8, -0.3], [-33.5, 3.6, 0.7]]) k.box(x, -2.5, z, 2, 1.25, 2, BLOCK, { tex: 'none', rot: r });
    k.box(-27, -2.5, -8, 2, 1.25, 2, BLOCK, D);              // two square steps in the pit's east corners
    k.box(-27, -2.5, 4.25, 2, 1.25, 1.5, BLOCK, D);
    k.pad(-31, -2.5, 0.6, 2, 2, 23, { look: 'tramp', color: LAUNCH });   // pit -> 6.6 terrace
    k.pad(-31, -2.5, -4, 2, 2, 13, { look: 'tramp', color: MAT });                                  // just for fun

    // ---- middle: bridge over the runway (4.4) from the west terraces to the south deck (4.4) ----
    slab(k, -6, 4.4, 0, 3, 22, DECK2, { t: 0.4, tex: 'none' });          // x -7.5..-4.5, z -11..11
    slab(k, 2.25, 4.4, 13.5, 19.5, 5, DECK2, { t: 0.4, tex: 'none' });   // south deck x -7.5..12, z 11..16
    posts(k, [[-6, -5], [-6, 5], [0, 11.4], [10, 11.4]], 0, 4.0, CREAM, 0.5);
    k.pad(4, 0, 7.5, 1.6, 1.6, 17, { color: LAUNCH });       // floor -> south deck
    k.box(-2, 0, 7.8, 2, 1.2, 2, BLOCK, D);                                        // steps up to the deck
    k.box(-2, 0, 9.9, 2, 2.4, 2, BLOCK, D);

    // ---- east: terraces up the north side, the end balcony + chimney, the south bridge ----
    k.box(21, 0, -9, 6, 2.2, 4, DECK, D);                 // 2.2  x 18..24, z -11..-7
    k.box(26.5, 0, -9, 5, 4.4, 4, DECK2, D);              // 4.4  x 24..29
    k.box(31.75, 0, -9, 5.5, 6.6, 4, DECK, D);            // 6.6  x 29..34.5
    k.box(36.25, 0, 2.5, 3.5, 8.8, 27, DECK2, D);         // end balcony 8.8, x 34.5..38
    k.box(34.25, 0, 3, 0.5, 8.8, 4, DECK2, D);             // kick chimney: the balcony's face (plain - kickable anyway)...
    k.box(30.75, 0, 3, 0.5, 8.8, 4, '', { tex: 'kick' }); // ...and an orange wall 3m off it
    slab(k, 23.25, 8.8, 14.5, 22.5, 3, DECK, { t: 0.4, tex: 'none' });   // south bridge x 12..34.5, z 13..16
    posts(k, [[17, 14.5], [24, 14.5], [31, 14.5]], 0, 8.4, CREAM, 0.5);
    // banked ramps against the south wall under the bridge (slide down them for speed)
    k.ramp(20.5, 11.5, 3, 4, 0, 2.4, '+z', CREAM, D);
    k.ramp(27.5, 11.5, 3, 4, 0, 2.4, '+z', CREAM, D);
    k.pad(18.6, 0, 9, 1.6, 1.6, 25, { color: LAUNCH });   // floor -> end balcony

    // ---- foam stacks all over the floor: 3x3 foam cubes, 2.2 (mustard) and 4.4 (teal), always in
    // reach of each other (floor -> 2.2 -> 4.4 -> the terraces and decks), with 3-4m lanes between.
    // They break the long views down the hall and give every chase a corner to turn.
    const cube = (x, z, h, w = 3, d = 3) => k.box(x, 0, z, w, h, d, h > 3 ? DECK : BLOCK, D);
    cube(-21.5, -9.5, 4.4); cube(-18.5, -9.5, 2.2);         // west: a staircase up to the 6.6 terrace
    cube(-19.5, -4.5, 2.2);
    cube(-13, -4.5, 4.4); cube(-13, -7.5, 2.2);
    cube(-22, 9.5, 4.4); cube(-22, 6.5, 2.2);
    cube(-15.5, 4.5, 4.4); cube(-12.5, 4.5, 2.2); cube(-15.5, 9.5, 2.2);
    cube(-3, -4.5, 2.2);                                     // next to the bridge (pull up onto it)
    cube(3.25, -14.5, 2.2, 2.5); cube(6, -14.5, 4.4);        // middle: the north nook
    cube(4, -4.5, 2.2); cube(7.5, 4.5, 2.2);
    cube(11, -3, 4.4); cube(11, -6, 2.2); cube(11, 8, 2.2); // a stack beside the runway; a step to the south deck
    cube(16, -9.5, 4.4); cube(16, -6.5, 2.2);                // east
    cube(26.5, -5.5, 2.2);
    cube(14.5, 4.5, 4.4); cube(17.5, 4.5, 2.2);
    cube(24, 5, 2.2); cube(24, 8, 4.4);
    // three padded columns, floor to ceiling, set at 45 degrees like the hall's corners
    for (const [x, z] of [[4, -9.5], [21, -4.5], [-9.75, 7]]) k.box(x, 0, z, 3, 15, 3, WALL, { tex: 'none', rot: Q });
    // ---- floor: vaults and slide bars in the lanes ----
    k.box(31.5, 0, -4, 4, 1, 0.6, CREAM, D);
    k.box(1, 1.25, -5, 0.35, 0.35, 4, MAT, D);
    posts(k, [[1, -7.2], [1, -2.8]], 0, 1.6, CREAM, 0.4);
    k.box(20.5, 1.25, 1.5 + 3.5, 0.35, 0.35, 4, MAT, D);
    posts(k, [[20.5, 2.8], [20.5, 7.2]], 0, 1.6, CREAM, 0.4);
  },
});

;
/* ==== js/maps/infinite.js ==== */
// THE LOOP - an endless map. The 48x48 tile repeats forever in every direction: run off one edge
// and you come in at the other, and towers march off into the pastel haze. One tile has:
//   towers      two 8m towers (lilac + blue) on one diagonal, each ringed by four 4m balconies
//   blocks      two 4m blocks (pink + mint) on the other diagonal
//   bridges     every block edge has a 4m bridge to a tower balcony - half of them cross the seam
//               into the next tile, so the bridges form an endless grid of loops up high
//   ground      juke posts, slide bars, crate steps and a hut on the seams; orange kick walls,
//               crate steps and pads take you up to the blocks; corner steps take you up the towers
// Finding your way: the ground is tinted in four quarters, each the colour of the tower or block
// standing in it, and the seams (where the next copy starts) are a dark lilac stripe. Each tower wears
// its own band (lilac: white, blue: yellow) and each block has a coloured crate on top.
// Nothing low hangs over a floor: every bridge has 3.6m under it.
const INF_W = 48;

defineMap({
  id: 'infinite',
  accent: ['#c3a6ff', '#ff8fa3'],
  name: 'The Loop',
  blurb: 'An endless map: run off one edge and you come back from the other. Towers and bridges forever.',
  env: 'fog',
  sky: '#efe3f1',
  fog: [10, 50],
  fogDensity: 0.046,
  hemi: ['#ffffff', '#b9a9c9', 1.6],
  sun: [0.9, 20, 50, 30],
  size: INF_W,
  wrap: INF_W,
  menuCam: { path: [[-21.6, 5.5, 0.6], [21.6, 5.5, 0.6]] },
  spawns: [
    [0, 0, 7.2], [0, 0, -7.2], [7.2, 0, 0], [-7.2, 0, 0],
    [20.4, 0, -2.4], [-20.4, 0, 2.4], [2.4, 0, 15.6], [-2.4, 0, -15.6],
    [19.2, 0, 15.6], [-19.2, 0, -15.6],
    [15, 4, -15], [-15, 4, 15], [-12, 8, -12], [12, 8, 12],
  ],
  seekerSpawn: [0, 0, 0],

  build(k) {
    const LILAC = '#c3a6ff', BLUE = '#8fb4ff', PINK = '#ff8fa3', MINT = '#7ed6c8', YEL = '#ffd166';
    const WHITE = '#f6f3f8', BAL = { [LILAC]: '#d9c9ff', [BLUE]: '#b3cbff' }, CRATE = '#e0c49a';
    const KICK = { tex: 'kick' };
    const T = 12, HW = INF_W / 2;   // towers and blocks sit at (+-12, +-12)

    ground(k, INF_W, INF_W, '#ebe1ef', { outline: false });   // no outline, so the tiles meet without a seam line
    // the four quarters, tinted after what stands in them (looks only), and a white stripe down the seams
    const FLAT = { tex: 'none', outline: false };
    const tint = (sx, sz, col) => k.deco(sx * HW / 2, 0, sz * HW / 2, HW - 1, 0.02, HW - 1, col, FLAT);
    tint(-1, -1, '#d6c3fb'); tint(1, 1, '#c4d7fb'); tint(1, -1, '#fbc9d4'); tint(-1, 1, '#bfeadf');
    k.deco(HW, 0, 0, 0.9, 0.025, INF_W, '#a497bd', FLAT);
    k.deco(0, 0, HW, INF_W, 0.025, 0.9, '#a497bd', FLAT);

    // ---- towers (8m) with a balcony (4m) on every side and two corner steps (6m) ----
    const tower = (tx, tz, col, band) => {
      k.box(tx, 0, tz, 6, 8, 6, col);
      k.deco(tx, 6.6, tz, 6.06, 0.5, 6.06, band, { tex: 'none' });   // its own colour band near the top
      const b = BAL[col];
      k.box(tx + 4.5, 0, tz, 3, 4, 4, b);
      k.box(tx - 4.5, 0, tz, 3, 4, 4, b);
      k.box(tx, 0, tz + 4.5, 4, 4, 3, b);
      k.box(tx, 0, tz - 4.5, 4, 4, 3, b);
      // 6m steps tucked against the tower in two opposite corners: balcony (4) -> step (6) -> top (8)
      k.box(tx + 4, 0, tz + 3, 2, 6, 2, col);
      k.box(tx - 4, 0, tz - 3, 2, 6, 2, col);
    };
    tower(-T, -T, LILAC, WHITE);
    tower(T, T, BLUE, YEL);

    // ---- blocks (4m) on the other diagonal ----
    k.box(T, 0, -T, 8, 4, 8, PINK);
    k.box(-T, 0, T, 8, 4, 8, MINT);
    // a crate in the middle of each block top (6.8), painted the block's colour: a perch, and the
    // bridges no longer line up in one view
    k.box(T, 4, -T, 2.4, 2.8, 2.4, '#e8667f');
    k.box(-T, 4, T, 2.4, 2.8, 2.4, '#3fb3a1');

    // ---- bridges at 4m: every block edge to a tower balcony (some run across the seam) ----
    // block faces at T +- 4, balcony ends at T +- 6; the next tile's towers are at T + 48
    const B = (ax, az, bx, bz) => bridge(k, ax, az, bx, bz, 4, 2.5, WHITE);
    B(-T + 6, -T, T - 4, -T);                  // pink -> lilac (+x balcony)
    B(T, -T + 4, T, T - 6);                    // pink -> blue (-z balcony)
    B(T + 4, -T, -T - 6 + INF_W, -T);          // pink -> lilac in the next tile east
    B(T, T + 6 - INF_W, T, -T - 4);            // pink -> blue in the next tile north
    B(-T + 4, T, T - 6, T);                    // mint -> blue (-x balcony)
    B(-T, -T + 6, -T, T - 4);                  // mint -> lilac (+z balcony)
    B(T + 6 - INF_W, T, -T - 4, T);            // mint -> blue in the next tile west
    B(-T, T + 4, -T, -T - 6 + INF_W);          // mint -> lilac in the next tile south

    // ---- ways up onto the blocks ----
    // orange kick walls 3m off a block face
    k.box(T - 3, 0, -T - 7.25, 3, 4, 0.5, '#ff6a3d', KICK);     // pink, south face
    k.box(-T + 3, 0, T + 7.25, 3, 4, 0.5, '#ff6a3d', KICK);     // mint, north face
    // crate steps (1.4 -> 2.8 -> pull up onto 4)
    k.box(T + 5.2, 0, -T + 5.1, 2.4, 1.4, 2.4, CRATE);
    k.box(T + 5.2, 0, -T + 2.7, 2.4, 2.8, 2.4, CRATE);
    k.box(-T - 5.2, 0, T - 5.1, 2.4, 1.4, 2.4, CRATE);
    k.box(-T - 5.2, 0, T - 2.7, 2.4, 2.8, 2.4, CRATE);
    // pads by the towers (off a corner, 7.5m out each way): straight up onto the tower top
    k.pad(T - 7.5, 0, T + 7.5, 1.4, 1.4, 24, {});
    k.pad(-T + 7.5, 0, -T - 7.5, 1.4, 1.4, 24, {});

    // ---- the middle: four juke posts and a slide table ----
    for (const [x, z] of [[3, 3], [-3, 3], [3, -3], [-3, -3]]) k.box(x, 0, z, 1.2, 3.2, 1.2, YEL);
    slab(k, 0, 1.6, 5.5, 3, 1.6, WHITE, { t: 0.4 });                  // slide under (1.2) or hop on
    posts(k, [[-1.3, 4.85], [1.3, 4.85], [-1.3, 6.15], [1.3, 6.15]], 0, 1.2, '#b9a9c9', 0.25);
    k.box(-5.5, 0, -0.6, 0.6, 1, 3, WHITE);                           // vault wall

    // ---- on the seams (each one is shared with the next tile) ----
    // east/west seam: a slide bar between two posts, and staggered vault walls
    k.box(HW, 1.2, 0, 0.4, 0.4, 5, '#5b4e6e');
    posts(k, [[HW, -2.7], [HW, 2.7]], 0, 1.6, '#5b4e6e', 0.4);
    k.box(HW - 2.5, 0, 6.6, 3, 1, 0.6, WHITE);
    k.box(HW + 2.5, 0, -6.6, 3, 1, 0.6, WHITE);
    // north/south seam: a crate stack to climb and circle
    k.box(0, 0, HW, 3, 1.4, 3, CRATE);
    k.box(2.4, 0, HW + 2.6, 2.2, 2.8, 2.2, CRATE);
    k.box(-2.9, 0, HW - 2.4, 1.4, 1, 1.4, CRATE);
    // the corner: a little hut with a doorway straight through it
    k.box(HW, 0, HW - 1.8, 5, 3.8, 1.2, LILAC);
    k.box(HW, 0, HW + 1.8, 5, 3.8, 1.2, LILAC);
    k.box(HW, 3.8, HW, 5, 0.4, 5, PINK);
    k.box(HW - 2, 0, HW, 1, 1.6, 2.4, MINT);                          // low window sill to vault in

    // ---- crate piles: a 2.8 crate with a 1.4 step beside it, set against a balcony or block (4) or out in a
    // street. They split the wide streets into lanes, and every one is a way up: 1.4 -> 2.8 -> 4.
    // Placed in pairs, turned half a turn round the middle, like everything else on the tile ----
    const pile = (x, z, sx, sz) => {
      for (const s of [1, -1]) {
        k.box(s * x, 0, s * z, 2.4, 2.8, 2.4, CRATE);
        k.box(s * (x + sx * 2.4), 0, s * (z + sz * 2.4), 2.4, 1.4, 2.4, CRATE);
      }
    };
    pile(T - 4.5, T + 3.4, 0, 1);       // against the blue tower's west balcony (north end)
    pile(T - 5.2, -T + 2.5, -1, 0);     // against the pink block's west face, beside its bridge
    pile(T + 4.5, T - 3.2, 0, -1);      // against the blue tower's east balcony (south end)
    pile(T + 4, -T - 9, 0, -1);         // out in the seam street south of the pink block
    // lamp posts with a soft glow
    for (const [x, z] of [[7.2, 7.2], [-7.2, -7.2]]) {
      k.box(x, 0, z, 0.3, 4.6, 0.3, '#5b4e6e');
      k.deco(x, 4.6, z, 0.7, 0.4, 0.7, '#fff3c4', { emissive: '#ffd27a' });
    }
  },
});

;
/* ==== js/maps/climb.js ==== */
// CLOUD SPIRE - race. A square spiral of floating platforms winding three laps up around a
// tall white spire, alone in an empty sky. Every side of every lap is a different obstacle,
// and they get harder as you climb. Fall off and you're back at the start line.
//
// SPINNING PLATFORMS: the yellow turntables, the rotating bridge, the carousel and the propeller
// turn while you stand on them - and they turn your view with them. Re-aim before you jump off.
//
//   lap 1 (0 -> 12)    stepping stones - three plus-shaped turntables - sweeper bridge -
//                      slide gate + kick chimney.  Jump pad up to lap 2
//   lap 2 (16 -> 28)   the rotating bridge (cross when it lines up, or ride it around) -
//                      spinning stairs - spinner stones (or the gappy outside rail) -
//                      tall kick chimney.  Kick up the orange corner to lap 3
//   lap 3 (32 -> 44)   small stones + the carousel - piston alley - the propeller - the great chimney
//   finale             sweeper bridge to the cannon pad, which fires you onto the spire top (52)
//
// Laps sit right on top of each other 16m apart, so you see the racers ahead above you.
// Each side runs between two corner blocks; positions below are in side-local coordinates:
// a = meters along the side from its start corner, v = sideways (+ = outward).
defineMap({
  id: 'climb',
  kind: 'race',
  accent: ['#7ed6c8', '#c3a6ff'],
  name: 'Cloud Spire',
  blurb: 'Three laps up a spiral of floating obstacles in an empty sky. Spinning platforms turn you around. Fall and you start over.',
  env: 'fog',
  sky: '#a9d6ff',
  fog: [150, 420],
  hemi: ['#eef6ff', '#8090a8', 1.9],
  sun: [1.2, 60, 110, 40],
  size: 34,
  killY: -18,
  menuCam: { r: 62, y: 42 },
  spawns: [-26, -23.3, -20.7, -18].flatMap((x) => [18.5, 22, 25.5].map((z) => [x, 0, z])),
  seekerSpawn: [-22, 0, 22],
  race: {
    yaw: -Math.PI / 2,
    finish: { x: 0, y: 52, z: 0, w: 4, h: 3, d: 4 },
    route: [
      [-22, 0, 22], [22, 3, 22], [22, 6, -22], [-22, 9, -22], [-22, 13.5, 8], [-22, 12, 22],
      [-16, 16, 22], [22, 19, 22], [22, 22, -22], [-22, 25, -22], [-22, 31, 0], [-22, 28, 22],
      [-16, 32, 22], [22, 35, 22], [22, 38, -22], [-22, 41, -22], [-22, 47.5, -3], [-22, 47.5, 14], [-22, 44, 22],
      [0, 44, 22], [0, 52, 0],
    ],
  },

  build(k) {
    const R = 22;
    const WHITE = '#f2f4f7', PINK = '#ff8fa3', GOLD = '#ffb37a';
    const LAP = ['#7ed6c8', '#8fb4ff', '#c3a6ff'];
    const KICK = { tex: 'kick' };
    // the four sides of the square, walked counter-clockwise (seen from above)
    const F = [
      { c: [-R, R], u: [1, 0], n: [0, 1] },     // south, heading +x
      { c: [R, R], u: [0, -1], n: [1, 0] },     // east, heading -z
      { c: [R, -R], u: [-1, 0], n: [0, -1] },   // north, heading -x
      { c: [-R, -R], u: [0, 1], n: [-1, 0] },   // west, heading +z
    ];
    const at = (s, a, v) => [F[s].c[0] + F[s].u[0] * a + F[s].n[0] * v, F[s].c[1] + F[s].u[1] * a + F[s].n[1] * v];
    const ax = (s) => F[s].u[0] !== 0;
    // block from a0 to a1 along side s, `wid` wide centered on v, top at `top`, `t` thick
    const span = (s, a0, a1, v, wid, top, t, col, o) => {
      const [x, z] = at(s, (a0 + a1) / 2, v), L = a1 - a0;
      k.box(x, top - t, z, ax(s) ? L : wid, t, ax(s) ? wid : L, col, o);
    };
    // moving block centered at (a, v), bottom y. Slides are given along/sideways (da, dv, dy)
    const mov = (s, a, v, len, wid, y, h, col, mo) => {
      const [x, z] = at(s, a, v), m = Object.assign({}, mo);
      if (mo.type === 'slide') {
        m.dx = F[s].u[0] * (mo.da || 0) + F[s].n[0] * (mo.dv || 0);
        m.dz = F[s].u[1] * (mo.da || 0) + F[s].n[1] * (mo.dv || 0);
      }
      k.mover(x, y, z, ax(s) ? len : wid, h, ax(s) ? wid : len, col, m);
    };
    const spinner = (s, a, top, len, speed, phase = 0) => mov(s, a, 0, 0.45, len, top, 0.6, PINK, { type: 'spin', speed, phase });
    // a whole platform that spins (top at `top`): a plain square, a plus, or an octagon (two
    // squares turned 45 degrees apart). Standing on it turns you - and your view - with it.
    const SPIN = '#ffd166';
    const turntable = (s, a, top, shape, size, speed, phase = 0, wid = 2.4) => {
      const [x, z] = at(s, a, 0), t = 0.6;
      if (shape === 'plus') {
        k.mover(x, top - t, z, size, t, wid, SPIN, { type: 'spin', speed, phase });
        k.mover(x, top - t, z, size, t, wid, SPIN, { type: 'spin', speed, phase: phase + Math.PI / 2 });
      } else {
        k.mover(x, top - t, z, size, t, size, SPIN, { type: 'spin', speed, phase });
        if (shape === 'oct') k.mover(x, top - t, z, size, t, size, SPIN, { type: 'spin', speed, phase: phase + Math.PI / 4 });
      }
      k.deco(x, top - t - 2.4, z, 0.5, 2.4 - 0.05, 0.5, '#59606e', { tex: 'none' });   // the axle under it
    };
    // a long bar that spins flat - a bridge when it lines up with the side, a ride when it doesn't
    const bar = (s, a, top, len, wid, speed, col = SPIN) => {
      const [x, z] = at(s, a, 0);
      k.mover(x, top - 0.6, z, len, 0.6, wid, col, { type: 'spin', speed, phase: ax(s) ? 0 : Math.PI / 2 });
      k.deco(x, top - 3, z, 0.6, 2.35, 0.6, '#59606e', { tex: 'none' });
    };
    // corner block (6x6, 3 thick) at the START corner of side s
    const corner = (s, top, col = WHITE) => span(s, -3, 3, 0, 6, top, 3, col);

    // --- the spire, with a colored band at each lap ---
    k.box(0, -34, 0, 10, 86, 10, WHITE);
    LAP.forEach((c, i) => k.deco(0, 16 * i + 6, 0, 10.3, 1.2, 10.3, c, { tex: 'none' }));
    k.deco(0, 49, 0, 10.3, 1.2, 10.3, GOLD, { tex: 'none' });
    // clouds
    for (const [x, y, z, w, d] of [[-48, 6, -30, 14, 8], [44, 14, 30, 18, 9], [52, 30, -40, 12, 10], [-46, 38, 36, 16, 8],
                                   [10, -10, 52, 20, 10], [-20, 58, -52, 16, 9], [36, 50, 46, 12, 7]]) {
      k.deco(x, y, z, w, 1.6, d, '#ffffff', { tex: 'none', noShadow: true });
      k.deco(x + 2, y + 1.6, z - 1, w * 0.55, 1.4, d * 0.6, '#ffffff', { tex: 'none', noShadow: true });
    }

    // ================= LAP 1 (mint) =================
    const C1 = LAP[0];
    k.box(-R, -3, R, 12, 3, 12, WHITE);                                   // start platform (top 0)
    k.deco(-R + 6.02, -0.4, R, 0.06, 0.4, 12, GOLD, { tex: 'none' });     // start line strip
    // south: stepping stones 0 -> 3
    for (let i = 0; i < 7; i++) span(0, 8.1 + i * 4.7, 10.7 + i * 4.7, [0, 0.8, -0.8][i % 3], 2.6, 3 * (i + 1) / 8, 1, C1);
    corner(1, 3);
    // east: three plus-shaped turntables, each spinning a little faster, alternating direction
    span(1, 3, 9, 0, 3, 3, 1, C1);
    turntable(1, 14, 3, 'plus', 7, 0.5);
    turntable(1, 22, 3, 'plus', 7, -0.6, 0.4);
    turntable(1, 30, 3, 'plus', 7, 0.7, 0.9);
    span(1, 35, 41, 0, 3, 3, 1, C1);
    corner(2, 6);
    // north: sweeper bridge, then steps up to 9
    span(2, 3, 33, 0, 3, 6, 1, C1);
    spinner(2, 12, 6, 6.5, 1.5);
    spinner(2, 24, 6, 6.5, -1.9, 0.8);
    span(2, 33, 37, 0, 3, 7.2, 2.2, C1);
    span(2, 37, 41, 0, 3, 8.4, 3.4, C1);
    corner(3, 9);
    // west: slide gate, kick chimney up to a 13.5 ledge, drop to the corner at 12
    span(3, 3, 30, 0, 3, 9, 1, C1);
    span(3, 9.5, 10.5, 0, 3, 13, 2.95, PINK);                             // gate: bottom at 10.05 - slide under
    span(3, 22, 30, 1.65, 0.5, 14.5, 5.5, C1, KICK);
    span(3, 22, 30, -1.65, 0.5, 14.5, 5.5, C1, KICK);
    span(3, 30, 38, 0, 3, 13.5, 4.5, C1);
    corner(0, 12);                                                        // lap 1 ends above the start
    k.pad(-21.5, 12, R, 1.4, 1.4, 16, {});          // up to lap 2

    // ================= LAP 2 (blue) =================
    const C2 = LAP[1];
    span(0, 3, 9, 0, 6, 16, 2, C2);                                       // lap 2 start (top 16)
    // south: the rotating bridge. When it lines up you can sprint straight across; otherwise hop
    // on as its end swings past and ride it round to the far ledge
    bar(0, 18, 16.5, 14, 2.6, 0.55);
    span(0, 27, 34, 0, 3, 17, 1, C2);
    span(0, 34, 37.5, 0, 3, 18, 2, C2);
    span(0, 37.5, 41, 0, 3, 18.8, 2.8, C2);
    corner(1, 19);
    // east: spinning stairs - four square turntables climbing to 22, alternating direction
    span(1, 3, 8, 0, 3, 19, 1, C2);
    [[12, 19.6, 0.7], [19, 20.2, -0.8], [26, 20.8, 0.9], [33, 21.4, -1.0]].forEach(([a, top, sp], i) => turntable(1, a, top, 'square', 4.5, sp, i));
    span(1, 37, 41, 0, 3, 22, 1, C2);
    corner(2, 22);
    // north: spinner stones 22 -> 25, or the gappy rail along the outside
    for (let i = 0; i < 7; i++) {
      const a = 5.6 + i * 5.2, top = 22.4 + i * 0.4;
      span(2, a - 1.5, a + 1.5, 0, 3, top, 1, C2);
      if (i % 2) spinner(2, a, top, 4, [2.2, -2.6, 3.0][(i - 1) / 2], i * 0.7);
      span(2, a - 1.6, a + 1.6, 2.7, 0.6, top, 0.5, GOLD);                // rail piece
    }
    corner(3, 25);
    // west: tall kick chimney up to a 31 ledge, then down to the corner at 28
    span(3, 3, 12, 0, 3, 25, 1, C2);
    span(3, 12, 18, 1.65, 0.5, 31.5, 6.5, C2, KICK);
    span(3, 12, 18, -1.65, 0.5, 31.5, 6.5, C2, KICK);
    span(3, 18, 27, 0, 3, 31, 6, C2);
    span(3, 28.5, 37.5, 0, 3, 29.5, 1, C2);
    corner(0, 28);
    // up to lap 3: kick between the orange wall and the orange end of the lap 3 start
    k.box(-23.65, 28, R, 0.5, 6, 6, C2, KICK);

    // ================= LAP 3 (lilac) =================
    const C3 = LAP[2];
    k.box(-19.8, 28, R, 1.6, 4, 6, C3, KICK);                             // its kickable end (x -20.6..-19)
    span(0, 3, 9, 0, 6, 32, 2, C3);                                       // lap 3 start (top 32)
    // south: small stones, then the carousel - a big fast octagon. Land, turn back around, jump off
    [32.5, 33, 33.5].forEach((top, i) => span(0, 10.2 + i * 4.4, 12.2 + i * 4.4, 0, 2, top, 1, C3));
    turntable(0, 27, 33.5, 'oct', 7.4, 1.0);
    span(0, 32.5, 41, 0, 3, 34, 1, C3);
    corner(1, 35);
    // east: piston alley - blocks sweep across a 2m bridge, then steps to 38
    span(1, 3, 36, 0, 2, 35, 1, C3);
    [10, 17, 24, 31].forEach((a, i) => {
      mov(1, a, -5, 2, 2, 35, 1.6, GOLD, { type: 'slide', dv: 10, period: 3.6, phase: i * 0.25 });
      span(1, a - 1.2, a + 1.2, -6.4, 0.8, 37.5, 4, WHITE);              // piston housings
      span(1, a - 1.2, a + 1.2, 6.4, 0.8, 37.5, 4, WHITE);
    });
    span(1, 36, 38.5, 0, 3, 36.2, 2.2, C3);
    span(1, 38.5, 41, 0, 3, 37.4, 3.4, C3);
    corner(2, 38);
    // north: the propeller - a fast spinning bar across the gap. Time the jump on and off
    span(2, 3, 14, 0, 3, 38, 1, C3);
    bar(2, 21, 38, 12, 3, 0.65, GOLD);
    span(2, 28.5, 34, 0, 3, 38.4, 1, C3);
    span(2, 34, 37.5, 0, 3, 39.4, 2, C3);
    span(2, 37.5, 41, 0, 3, 40.2, 2.8, C3);
    corner(3, 41);
    // west: the great chimney up to 47.5, a balance beam, drop to the corner at 44
    span(3, 3, 10, 0, 3, 41, 1, C3);
    span(3, 10, 16, 1.65, 0.5, 48.5, 7.5, C3, KICK);
    span(3, 10, 16, -1.65, 0.5, 48.5, 7.5, C3, KICK);
    span(3, 16, 22, 0, 3, 47.5, 6.5, C3);
    span(3, 22, 36, 0, 1, 47.5, 1, C3);
    span(3, 36, 38, 0, 3, 46, 1, C3);
    corner(0, 44, GOLD);

    // ================= FINALE =================
    k.box(-11, 43, R, 16, 1, 3, GOLD);                                    // sweeper bridge x -19..-3
    mov(0, 8, 0, 0.45, 6, 44, 0.6, PINK, { type: 'spin', speed: 2.5 });
    mov(0, 14, 0, 0.45, 6, 44, 0.6, PINK, { type: 'spin', speed: -3, phase: 1 });
    k.box(0, 43, R, 6, 1, 6, GOLD);                                       // cannon platform
    k.pad(0, 44, 20.5, 1.6, 1.6, 28, { color: '#ff6bd6' });
    // parapet around the far sides of the spire top, so the cannon can't fling you off
    k.box(0, 52, -5.4, 10.8, 1, 0.8, GOLD);
    k.box(-5.4, 52, 0.4, 0.8, 1, 9.2, GOLD);
    k.box(5.4, 52, 0.4, 0.8, 1, 9.2, GOLD);
  },
});

;
/* ==== js/maps/chambers.js ==== */
// THE CHAMBERS - race through a chain of clean white test chambers. Each room is one test;
// doorways lead from one to the next, climbing as you go. Pits drop into the void (back to start).
//
//   0  start            the line-up room
//   1  pistons          orange and blue pistons punch in from the walls - time your run
//   2  ferries          two lanes over a pit: a slow wide platform, or a fast small one
//   3  faith plates     blue launch plates fling you across the pit, plate to plate
//   4  kick chimney     orange walls up to a door 8m up
//   5  sweepers         a narrow bridge over a pit with two spinning sweeper bars to jump
//   6  lasers           glowing gates: jump the low ones, slide under the high ones, time the moving one
//   7  lift             ride the blue lift up to the next door
//   8  the final test   steps over the pit, a ferry, a last kick chimney onto the finish balcony
//
// Walls are built from 4m panels so their outlines draw the seams.
defineMap({
  id: 'chambers',
  kind: 'race',
  accent: ['#ff9a3c', '#4aa3ff'],
  name: 'The Chambers',
  blurb: 'A chain of white test chambers: pistons, ferries, launch plates, lasers, a lift. Fall in a pit and you start over.',
  env: 'fog',
  sky: '#15171c',
  fog: [90, 220],
  hemi: ['#ffffff', '#a0a8b4', 1.45],
  sun: [0.9, 12, 60, 24],
  size: 185,   // (covers the whole course, so the shadows reach the end too)
  killY: -12,
  menuCam: { path: [[27, 4.5, -5], [46, 4.5, -5]] },
  spawns: [-12, -9, -6, -3].flatMap((x) => [-3, 0, 3].map((z) => [x, 0, z])),
  seekerSpawn: [-7, 0, 0],
  race: {
    rev: 2,   // bump to wipe the record boards without changing the course
    yaw: -Math.PI / 2,
    finish: { x: 179.4, y: 28, z: 8.2, w: 4.4, h: 3, d: 3.4 },
    route: [
      [-7, 0, 0], [25, 0, 0], [48, 0, 0], [53, 0, 0], [62, 2, 0], [71, 3, 0], [76, 3, 0],
      [78, 11, 0], [84, 11, 0], [105, 11, 0], [128, 11, 0], [147, 11, 0], [147, 19, 0], [153, 19, 0],
      [158, 19, -7.5], [170, 22.6, -7.5], [174, 22.6, -7], [174, 22.6, 9], [174.5, 28, 9], [179, 28, 8.2],
    ],
  },

  build(k) {
    const PANEL = '#e8ebef', FLOOR = '#9da4ae', CEIL = '#f4f6f8', FRAME = '#30343c';
    const OR = '#ff8a1f', BL = '#2f8cff', LASER = { emissive: '#ff2a10' }, GLOW = { emissive: '#fff1c8' };
    const T = 0.5;

    // fill a box region with panels at most `step` long on each of its long axes (thin axes stay whole)
    const panels = (x0, x1, y0, y1, z0, z1, col, o, step = 4) => {
      const cuts = (a, b) => {
        const L = b - a;
        if (L < 1.01) return [[a, b]];
        const n = Math.max(1, Math.round(L / step)), out = [];
        for (let i = 0; i < n; i++) out.push([a + L * i / n, a + L * (i + 1) / n]);
        return out;
      };
      for (const [a0, a1] of cuts(x0, x1)) for (const [b0, b1] of cuts(y0, y1)) for (const [c0, c1] of cuts(z0, z1)) {
        k.box((a0 + a1) / 2, b0, (c0 + c1) / 2, a1 - a0, b1 - b0, c1 - c0, col, o);
      }
    };
    // one wall, split around its openings. ax = 'x' (wall runs along x) or 'z'; at = its center line.
    // holes: [{ c, w, y, h, frame }] along the wall
    const wall = (ax, at, a0, a1, y0, y1, holes, col = PANEL) => {
      const br = [a0, a1];
      for (let a = a0 + 4; a < a1 - 0.5; a += 4) br.push(a);
      for (const h of holes) br.push(h.c - h.w / 2, h.c + h.w / 2);
      const pts = [...new Set(br.map((v) => Math.round(v * 1000) / 1000))].sort((p, q) => p - q);
      const put = (b0, b1, c0, c1) => {
        if (b1 - b0 < 0.01 || c1 - c0 < 0.01) return;
        if (ax === 'x') panels(b0, b1, c0, c1, at - T / 2, at + T / 2, col, {}, 8);
        else panels(at - T / 2, at + T / 2, c0, c1, b0, b1, col, {}, 8);
      };
      for (let i = 0; i < pts.length - 1; i++) {
        const b0 = pts[i], b1 = pts[i + 1], m = (b0 + b1) / 2;
        const h = holes.find((q) => m > q.c - q.w / 2 && m < q.c + q.w / 2);
        if (!h) { put(b0, b1, y0, y1); continue; }
        put(b0, b1, y0, h.y);
        put(b0, b1, h.y + h.h, y1);
      }
      // dark frames around doorways (a little deeper than the wall, so no faces line up)
      for (const h of holes) {
        if (!h.frame) continue;
        const f = 0.15, D = T + 0.1;
        if (ax === 'x') {
          k.box(h.c - h.w / 2 + f / 2, h.y, at, f, h.h, D, FRAME);
          k.box(h.c + h.w / 2 - f / 2, h.y, at, f, h.h, D, FRAME);
          k.box(h.c, h.y + h.h - f, at, h.w - 2 * f, f, D, FRAME);
        } else {
          k.box(at, h.y, h.c - h.w / 2 + f / 2, D, h.h, f, FRAME);
          k.box(at, h.y, h.c + h.w / 2 - f / 2, D, h.h, f, FRAME);
          k.box(at, h.y + h.h - f, h.c, D, f, h.w - 2 * f, FRAME);
        }
      }
    };
    // a chamber. Interior x0..x1, z0..z1, floor top y, ceiling at y + h. Walls reach `deep` below the
    // floor so pits look like shafts. floor: list of [x0, x1, z0, z1] solid floor pieces (default all).
    // doors: { s: '-x' | '+x', c: z center, y: sill height, w, h, col: accent stripe }
    // slots: extra openings with no frame (for pistons): { s: '+z' | '-z', c: x center, w, y, h }
    const room = (x0, x1, z0, z1, y, h, o = {}) => {
      const deep = o.deep || 0.5, yb = y - deep, yt = y + h;
      const doors = o.doors || [{ s: '-x', c: 0 }, { s: '+x', c: 0 }];
      const hole = (side) => doors.filter((d) => d.s === side).map((d) => ({ c: d.c, w: d.w || 3, y: d.y === undefined ? y : d.y, h: d.h || 3.2, frame: true }))
        .concat((o.slots || []).filter((q) => q.s === side));
      wall('z', x0 - T / 2, z0 - T, z1 + T, yb, yt, hole('-x'));
      wall('z', x1 + T / 2, z0 - T, z1 + T, yb, yt, hole('+x'));
      wall('x', z0 - T / 2, x0, x1, yb, yt, hole('-z'));
      wall('x', z1 + T / 2, x0, x1, yb, yt, hole('+z'));
      k.box((x0 + x1) / 2, yt, (z0 + z1) / 2, x1 - x0 + 2 * T, 0.5, z1 - z0 + 2 * T, CEIL, { noShadow: true });
      // light strips under the ceiling
      for (const s of [-1, 1]) k.deco((x0 + x1) / 2, yt - 0.06, (z0 + z1) / 2 + s * (z1 - z0) / 4, x1 - x0 - 2, 0.06, 0.35, '#fffdf5', GLOW);
      for (const [a0, a1, b0, b1] of o.floor || [[x0, x1, z0, z1]]) panels(a0, a1, y - 0.5, y, b0, b1, FLOOR);
      // accent stripe over every doorway
      for (const d of doors) {
        const dy = (d.y === undefined ? y : d.y) + (d.h || 3.2) + 0.25, xs = d.s === '-x' ? x0 + 0.03 : x1 - 0.03;
        k.deco(xs, dy, d.c, 0.06, 0.3, (d.w || 3) + 1, d.col || (d.s === '-x' ? BL : OR), { emissive: d.s === '-x' ? '#123a66' : '#663000' });
      }
    };

    // ---------------- 0: start ----------------
    room(-14, 0, -6, 6, 0, 6, { doors: [{ s: '+x', c: 0 }] });
    k.deco(-0.6, 0.01, 0, 0.5, 0.02, 8, OR, { tex: 'none' });            // start line

    // ---------------- 1: pistons ----------------
    // slots in the side walls; pistons rest flush with the wall and punch 3.6m in
    const PX = [[6, '+z', OR], [11, '-z', BL], [16, '+z', OR], [21, '-z', BL]];
    room(1, 25, -3, 3, 0, 5, { slots: PX.map(([x, s]) => ({ s, c: x, w: 2.6, y: 0, h: 2.6 })) });
    PX.forEach(([x, s, col], i) => {
      const sg = s === '+z' ? 1 : -1;
      k.mover(x, 0, sg * 5, 2.4, 2.5, 4, col, { type: 'slide', dz: -sg * 3.6, period: 2.4, phase: i * 0.25 });
    });

    // ---------------- 2: ferries over a pit ----------------
    room(26, 48, -6, 6, 0, 7, { deep: 4, floor: [[26, 30, -6, 6], [44, 48, -6, 6]] });
    k.mover(33, -0.5, -3, 4, 0.5, 4, BL, { type: 'slide', dx: 8, period: 6 });          // slow wide lane
    k.mover(31.5, -0.5, 3, 3, 0.5, 3, OR, { type: 'slide', dx: 9, period: 4, phase: 0.5 });   // fast lane
    for (const z of [-3, 3]) k.deco(29.7, 0.01, z, 0.5, 0.02, 3, z < 0 ? BL : OR, { tex: 'none' });

    // ---------------- 3: faith plates ----------------
    room(49, 71, -6, 6, 0, 10, { deep: 4, floor: [[49, 53, -6, 6]], doors: [{ s: '-x', c: 0 }, { s: '+x', c: 0, y: 3 }] });
    k.box(60, -0.5, 0, 6, 5, 6, PANEL);                                    // island (top 4.5) - too high to jump: take the plate
    k.box(68, -0.5, 0, 6, 3.5, 12, PANEL);                                 // exit shelf (top 3)
    k.pad(51.4, 0, 0, 1.6, 1.6, 17, { color: BL });

    // ---------------- 4: kick chimney ----------------
    room(72, 84, -6, 6, 3, 12, { doors: [{ s: '-x', c: 0 }, { s: '+x', c: 0, y: 11 }] });
    for (const s of [-1, 1]) k.box(77.5, 3, s * 1.65, 5, 8.5, 0.5, OR, { tex: 'kick' });   // walls 2.8 apart, to 11.5
    k.box(77.5, 3, 0, 5, 1.5, 2.8, PANEL);                                 // a step up into it (4.5): 6.5m of kicking
    k.box(82, 3, 0, 4, 8, 4, PANEL);                                       // exit ledge (top 11)

    // ---------------- 5: sweepers ----------------
    room(85, 105, -7, 7, 11, 6, { deep: 4, floor: [[85, 88, -7, 7], [88, 102, -1.5, 1.5], [89, 93, -2, -1.5], [89, 93, 1.5, 2], [97, 101, -2, -1.5], [97, 101, 1.5, 2], [102, 105, -7, 7]] });
    k.mover(91, 11, 0, 11, 0.6, 0.45, OR, { type: 'spin', speed: 1.5 });
    k.mover(99, 11, 0, 11, 0.6, 0.45, BL, { type: 'spin', speed: -1.8, phase: 1 });

    // ---------------- 6: lasers ----------------
    room(106, 140, -2.5, 2.5, 11, 4.5);
    // a gate of thin glowing bars from y0 to y1 (too close together to squeeze through)
    const beam = (x, y0, y1, gap = 0.32) => { for (let y = y0; y < y1 - 0.05; y += gap) k.box(x, y, 0, 0.12, Math.min(0.09, y1 - y), 5, '#ff3a1c', LASER); };
    beam(111, 11.1, 11.7, 0.25);                                            // jump
    beam(117, 12.25, 15.5);                                                 // slide under
    beam(123, 11.1, 11.7, 0.25);
    beam(129, 12.25, 15.5);
    k.mover(135, 11, 0, 0.2, 0.55, 5, '#ff3a1c', { type: 'slide', dy: 2.6, period: 2.8 }, LASER);   // up and down
    for (const x of [111, 117, 123, 129, 135]) for (const s of [-1, 1]) k.deco(x, 11, s * 2.42, 0.6, 4.5, 0.16, FRAME, { tex: 'none' });

    // ---------------- 7: lift ----------------
    room(141, 153, -6, 6, 11, 14, { doors: [{ s: '-x', c: 0 }, { s: '+x', c: 0, y: 19 }] });
    k.mover(147, 10.5, 0, 3, 0.5, 3, BL, { type: 'slide', dy: 8, period: 7 });
    k.box(151.5, 11, 0, 3, 8, 4, PANEL);                                    // exit ledge (top 19)
    k.deco(147, 11.01, 0, 3.4, 0.02, 3.4, BL, { tex: 'none' });

    // ---------------- 8: the final test ----------------
    room(154, 182, -10, 10, 19, 18, { deep: 6, floor: [[154, 159, -10, 10]], doors: [{ s: '-x', c: 0 }] });
    [[162, 20.2], [166, 21.4]].forEach(([x, top]) => k.box(x, 16, -7.5, 2, top - 16, 3, PANEL));   // steps
    k.box(172.25, 16, -7.3, 5.5, 22.6 - 16, 5.4, PANEL);                    // platform P (top 22.6)
    k.mover(174, 22.1, -2.5, 3, 0.5, 3, OR, { type: 'slide', dz: 8, period: 6 });   // ferry to the chimney
    k.box(174.75, 16, 8.7, 2.8, 22.6 - 16, 2.6, PANEL);                      // chimney floor (top 22.6)
    k.box(173.1, 16, 8.7, 0.5, 28.6 - 16, 2.6, OR, { tex: 'kick' });         // chimney wall, 2.8m from the balcony face
    k.box(176.4, 16, 8, 0.5, 28 - 16, 4, OR, { tex: 'kick' });               // the balcony's kickable face
    k.box(179.3, 16, 8, 5.3, 28 - 16, 4, PANEL);                             // finish balcony (top 28)
    k.box(179.3, 28, 5.8, 5.3, 1, 0.4, FRAME);                               // little rail
    // an observation window high on the far wall
    k.deco(181.96, 30, 0, 0.06, 4, 10, '#2a3a4c', { emissive: '#0a1420' });
  },
});

;
/* ==== js/maps/volcano.js ==== */
// THE VOLCANO - race. A blocky volcano rising out of a sea of lava. Climb three laps around it
// (counter-clockwise, seen from above) to the crater at the top. Touch the lava and you're back
// on the beach - there are no checkpoints.
//
//   lap 1 (0 -> 10)    stepping stones over the lava (two of them bob up and down) - mantle up a
//                      ledge - orange kick chimney up the east cliff
//   lap 2 (10 -> 20)   on the mountain's shoulder: a rope bridge over a chasm - a lava tube you
//                      have to slide through - rising basalt columns - a geyser that blasts you
//                      up to the next shoulder
//   lap 3 (20 -> 31)   two rotating rock platforms (they turn you with them) - a ferry rock
//                      across the north chasm - the final kick chimney up to the crater rim
//   finish             drop into the crater
//
// The mountain is built in rings: an inner core (+-5, up to the crater at 30), the lap 3
// shoulder (+-5..9, top 20) and the lap 2 shoulder (+-9..13, top 10). Gaps in the shoulders are
// chasms straight down to the lava. Lap 1 runs on ledges outside, +-13..19. Each shoulder has an
// overhanging lip, so the only ways up are the chimneys and the geyser.
defineMap({
  id: 'volcano',
  kind: 'race',
  accent: ['#ff5a1f', '#3a3536'],
  name: 'The Volcano',
  blurb: 'Climb a volcano out of a lava sea: bobbing stones, chimneys, a lava tube, spinning rocks, a geyser. Touch lava, start over.',
  env: 'fog',
  sky: '#2a0f0b',
  fog: [50, 160],
  hemi: ['#ffc9a8', '#5a2414', 1.1],
  sun: [0.8, 30, 60, 20],
  size: 30,
  killY: -1.3,
  menuCam: { r: 46, y: 30 },
  spawns: [-25.5, -23, -20.5, -18].flatMap((x) => [16, 19, 22].map((z) => [x, 0, z])),
  seekerSpawn: [-21.5, 0, 19],
  race: {
    yaw: -Math.PI / 2,
    finish: { x: 0, y: 30, z: 0, w: 4, h: 3, d: 4 },
    route: [
      [-21, 0, 15], [-11.5, 0.4, 15], [10.7, 2.8, 15], [16, 3, 15], [15, 5, 8.5], [14.8, 5, -2],
      [14.8, 10, -6], [15, 10, -10], [11, 10, -11], [1, 10, -11], [-5, 10, -11], [-11, 10, -11],
      [-11, 10, -6], [-11, 10, 2], [-11, 10, 11], [-8, 10, 11], [-1, 10, 11], [6, 10, 11],
      [6, 20, 7], [7.5, 20, 7], [7.5, 20, 2.5], [7.5, 20, -2.5], [7.5, 20, -7], [3.5, 20, -7],
      [-6.5, 20, -7], [-7, 20, -3], [-7, 31, -3], [0, 30, 0],
    ],
  },

  build(k) {
    const ROCK = '#3b3332', DARK = '#2c2627', ASH = '#4d4441', BASALT = '#232226', SAND = '#2a2324';
    const LAVA = '#c9300a', GLOW = { emissive: '#e84a0c' }, KICK = { tex: 'kick' };
    // a block given by its x/z range and y range
    const blk = (x0, x1, z0, z1, y0, y1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);

    // --- the lava sea, glowing, with dark crust floating on it ---
    k.deco(0, -1.4, 0, 300, 0.4, 300, LAVA, GLOW);
    let seed = 7;
    const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
    for (let i = 0; i < 46; i++) {
      const a = rnd() * Math.PI * 2, r = 24 + rnd() * 60, w = 2 + rnd() * 6, d = 1.5 + rnd() * 5;
      k.deco(Math.cos(a) * r, -1.02 + i * 0.0005, Math.sin(a) * r, w, 0.06, d, '#3a1a12', { tex: 'none' });
    }

    // --- the mountain ---
    blk(-5, 5, -5, 5, -6, 30, DARK);                         // core, up to the crater
    // lap 3 shoulder (top 20), with chasms where the spinners and the ferry are
    blk(3, 9, 5, 9, -6, 20, ROCK);                           // S: geyser landing
    blk(5, 9, -9, -5, -6, 20, ROCK);                         // NE corner (after the spinners)
    blk(-9, -4, -9, -5, -6, 20, ROCK);                       // NW corner (after the ferry)
    blk(-9, -5, -5, -1, -6, 20, ROCK);                       // W: foot of the final chimney
    // lap 2 shoulder (top 10)
    blk(9, 13, -13, -1, -6, 10, ASH);                        // E (where lap 1's chimney comes out)
    blk(1, 9, -13, -9, -6, 10, ASH);                         // N, east of the rope bridge
    blk(-13, -5, -13, -9, -6, 10, ASH);                      // N, west of the bridge
    blk(-13, -9, -9, 13, -6, 10, ASH);                       // W, under the lava tube, round to the SW corner
    blk(-9, -8, 9, 13, -6, 10, ASH);                         // S, edge before the basalt columns
    blk(-1, 13, 9, 13, -6, 10, ASH);                         // S, geyser ledge, round to the SE corner
    // Overhanging lips along the top edge of every shoulder (1.5m out): you can't wall-kick from
    // one lap straight up onto the next - only up the orange chimneys and the geyser.
    const lip = (x0, x1, z0, z1, top, col) => blk(x0, x1, z0, z1, top - 0.8, top, col);
    for (const [x0, x1, z0, z1] of [[13, 14.5, -14.5, -13], [1, 13, -14.5, -13], [-14.5, -5, -14.5, -13], [-14.5, -13, -13, 14.5],
      [-13, -8, 13, 14.5], [-1, 14.5, 13, 14.5], [13, 14.5, 9, 13]]) lip(x0, x1, z0, z1, 10, ASH);
    for (const [x0, x1, z0, z1] of [[3, 10.5, 9, 10.5], [9, 10.5, 5, 9], [9, 10.5, -10.5, -5], [5, 9, -10.5, -9], [-9, -4, -10.5, -9],
      [-10.5, -9, -10.5, -1]]) lip(x0, x1, z0, z1, 20, ROCK);
    for (const [x0, x1, z0, z1] of [[5, 6.5, -6.5, 6.5], [-6.5, 5, 5, 6.5], [-6.5, 5, -6.5, -5], [-6.5, -5, -1, 5]]) lip(x0, x1, z0, z1, 30, DARK);

    // --- the beach (start) ---
    blk(-27, -15, 13, 25, -6, 0, SAND);
    for (const [x, z, s, h] of [[-26, 24, 1.2, 0.6], [-16, 24.2, 0.9, 0.4], [-26.3, 13.6, 0.8, 0.5]]) k.box(x, 0, z, s, h, s, BASALT);

    // ===== LAP 1 =====
    // stepping stones east along the south cliff, gently rising; two of them bob up and down
    const SX = [-11.5, -7.8, -4.1, -0.4, 3.3, 7, 10.7];
    SX.forEach((x, i) => {
      const top = 0.4 + i * 0.4;
      if (i === 2 || i === 4) k.mover(x, top - 6, 15, 2.2, 6, 2.2, BASALT, { type: 'slide', dy: 1.0, period: 3.2, phase: i * 0.21 });
      else k.box(x, -6, 15, 2.2, top + 6, 2.2, BASALT);
    });
    blk(13, 19, 13, 19, -6, 3, ROCK);                        // SE corner rock
    blk(13, 17, -8, 11, -6, 5, ROCK);                        // ledge: jump + pull up (2m), north along the cliff
    // kick chimney up the east cliff, at the far (north) end of the ledge: two orange walls 2.8 apart,
    // out onto the shoulder at 10. (It used to stand next to lap 2's geyser ledge: from the top of its
    // walls you could jump across to the geyser and skip all of lap 2.)
    blk(13, 13.4, -8, -3, 5, 10, '#ff6a3d', KICK);
    blk(16.2, 16.7, -8, -3, 5, 10, '#ff6a3d', KICK);
    blk(13, 17, -13, -8, -6, 10, ROCK);                      // top of the chimney

    // ===== LAP 2 =====
    // rope bridge over the north chasm
    k.box(-2, 9.75, -11, 6, 0.25, 0.9, '#8a6a48');
    for (const x of [-5, 1]) for (const z of [-11.6, -10.4]) k.deco(x, 10, z, 0.18, 1.2, 0.18, '#6b5443', { tex: 'none' });
    for (const z of [-11.6, -10.4]) k.deco(-2, 11.05, z, 6, 0.06, 0.06, '#c9a36b', { tex: 'none' });
    // lava tube: a rock overhang on the west shoulder, 1.2m clear - slide or crouch through
    blk(-13, -9, -6, 2, 11.2, 13.5, BASALT);
    k.deco(-11, 11.15, -6.02, 4, 0.05, 0.03, LAVA, GLOW);    // glowing lip at each mouth
    k.deco(-11, 11.15, 2.02, 4, 0.05, 0.03, LAVA, GLOW);
    // a basalt column rising and falling in the middle of the south chasm (one, wide: two of them
    // stood 1m apart, and a 1m slot is a lift - kick between them from the lava to the shoulder)
    k.mover(-4.5, -3, 11, 3, 12, 2, BASALT, { type: 'slide', dy: 2, period: 3.4, phase: 0 });
    // geyser: blasts you up onto the lap 3 shoulder
    k.pad(6, 10, 12.6, 1.6, 1.6, 30, { color: '#ff8a3d' });

    // lava falls: the walls down inside the chasms that meet in a corner run with lava, and you
    // can't kick off lava. Two walls meeting in a corner (or the column and a chasm wall) are a
    // ladder: without these you could kick straight up from the stepping stones to the geyser, or
    // from lap 2 to the foot of the final chimney. Each is a glowing sheet over an invisible no-kick
    // wall 0.5 thick (you can't get within kicking reach of the rock behind it). The ones under the
    // spinners and the ferry stop 2m below them (nobody stands up into them); the low ones stop 1.4m
    // under lap 2's rim.
    for (const [x0, x1, z0, z1, top] of [
      [5, 9, 4.5, 5, 17], [5, 9, -5, -4.5, 17],               // east chasm: both lap 3 corners against the core
      [-4, -3.5, -9, -5, 17], [4.5, 5, -9, -5, 17],           // north chasm: likewise
      [2.5, 3, 5, 9, 19.2], [-9, -5, -1, -0.5, 19.2],         // the hollow under lap 3's SW corner: likewise
      [9, 9.5, 5, 9, 19.2],                                    // lap 3 shoulder, east face over the pit
      [-8, -7.5, 9, 13, 8.6], [-1.5, -1, 9, 13, 8.6],          // the south chasm's sides
      [-9, -8.5, -0.5, 9, 8.6], [-1, 2.5, 8.5, 9, 8.6],        // lap 2's faces into the hollow
    ]) {
      k.deco((x0 + x1) / 2, -1.2, (z0 + z1) / 2, x1 - x0, top + 1.2, z1 - z0, LAVA, GLOW);
      k.wall((x0 + x1) / 2, -1.2, (z0 + z1) / 2, x1 - x0, top + 1.2, z1 - z0);
    }

    // ===== LAP 3 =====
    // two rotating rock platforms across the east chasm (they turn you as they spin)
    // (far enough out that their corners never sweep you into the core: 0.8m clear at the closest)
    k.mover(8.1, 19, 2.5, 3.2, 1, 3.2, BASALT, { type: 'spin', speed: 0.7, phase: 0 });
    k.mover(8.1, 19, -2.5, 3.2, 1, 3.2, BASALT, { type: 'spin', speed: -0.7, phase: 0.6 });
    // ferry rock across the north chasm
    k.mover(3.5, 19, -7.4, 2.6, 1, 2.6, ASH, { type: 'slide', dx: -6, period: 6, phase: 0 });   // (1.1m off the core: no pinching gap)
    // final kick chimney: orange wall on the core + one 2.8 out. The outer wall runs well past the
    // crater rim (31.2) and a bit wider, so the last kicks funnel you over the rim into the crater
    blk(-5.4, -5, -4.5, -1, 20, 31.2, '#ff6a3d', KICK);
    blk(-8.6, -8.2, -5, -0.5, 20, 34, '#ff6a3d', KICK);

    // ===== the crater =====
    blk(-5, 5, -5, -3.8, 30, 31.2, ROCK);
    blk(-5, 5, 3.8, 5, 30, 31.2, ROCK);
    blk(-5, -3.8, -3.8, 3.8, 30, 31.2, ROCK);
    blk(3.8, 5, -3.8, 3.8, 30, 31.2, ROCK);
    for (const [x, z] of [[-2.6, -2.6], [2.6, 2.6], [2.6, -2.6], [-2.6, 2.6]]) k.deco(x, 30, z, 0.7, 0.04, 0.7, LAVA, GLOW);

    // --- looks: glowing cracks in the rock, lava falls down the chasms, smoke vents ---
    for (const [x, y, z, w, h, d] of [
      [0, 2, 13.03, 6, 0.12, 0.04], [-9, 5, 13.03, 0.12, 3, 0.04], [19.03, 1, 16, 0.04, 0.12, 4],
      [13.03, 7.5, -2, 0.04, 0.12, 1.6], [-13.03, 4, 5, 0.04, 2.5, 0.12], [-13.03, 7, -3, 0.04, 0.12, 6],
      [-9.03, 14, -7, 0.04, 2, 0.12], [0, 25, 5.03, 3, 0.12, 0.04], [5.03, 24, 0, 0.04, 0.12, 4],
    ]) k.deco(x, y, z, w, h, d, LAVA, GLOW);
    // scattered lava rocks on the sea
    for (const [x, z, s, h] of [[-34, -8, 3, 1.4], [30, 28, 4, 2], [32, -26, 2.6, 1.2], [-30, -30, 3.4, 1.8], [8, 34, 2.8, 1.1], [-8, -36, 3, 1.5]]) {
      k.box(x, -2, z, s, h + 2, s, BASALT);
    }
  },
});

;
/* ==== js/maps/express.js ==== */
// THE EXPRESS - freight trains (2 to 4 of them, longer in bigger lobbies) racing side by side through the desert, forever. You play on
// the roofs and flatcars; the trains never stop and never end.
//   trains     2 to 4 parallel trains of 5 to 10 cars, sized for the number of players (tracks 6m apart,
//              3m gaps between them - a running jump across the car): locomotives, boxcars and passenger cars (4-4.2m up), tankers and
//              hoppers (3.4-3.7m), flatcars (1.6m) with crates, pipes or a container on them.
//              Cars are 1.6m apart. Flatcar -> roof is a jump + mantle
//   the ground touching it is like falling into the void: back you come
//   tunnels    every ~25s a tunnel comes rushing at you from the front. Its roof is 6.3m up: you
//              fit under it standing on the tallest roofs, but if you're mid-jump up there when the
//              mouth arrives, it shoves you off the back of the car (and usually onto the ground)
//   couplers   the links between cars are solid: a narrow beam you can walk across
// The trains really stand still: the ground, the poles, the hills and the tunnels slide past them
// (k.scroll + a looping mover), so running and jumping feel exactly like everywhere else.
const EXP_SPEED = 22;   // m/s the world goes by
// car types: length, top of the floor/roof, width
const EXP_CAR = {
  loco: { len: 12, top: 4.2, w: 3 },
  box: { len: 11, top: 4.2, w: 3 },
  passenger: { len: 13, top: 4.0, w: 3 },
  tank: { len: 10, top: 3.7, w: 2.8 },
  hopper: { len: 9, top: 3.4, w: 3 },
  flat: { len: 10, top: 1.6, w: 3 },
};
// front (+x) to back. Flatcars carry a load: crates, pipes or a container. A small game uses the
// first few cars of the first few trains (see EXP_SIZE)
const EXP_TRAINS = [
  ['loco', 'box', 'flat:crates', 'tank', 'hopper', 'flat:container', 'passenger', 'box', 'flat:pipes', 'hopper'],
  ['loco', 'passenger', 'flat:pipes', 'passenger', 'box', 'tank', 'flat:crates', 'hopper', 'box', 'flat:container'],
  ['loco', 'hopper', 'flat:crates', 'box', 'flat:pipes', 'tank', 'box', 'passenger', 'flat:crates', 'tank'],
  ['loco', 'tank', 'flat:container', 'box', 'hopper', 'flat:crates', 'passenger', 'tank', 'box', 'flat:pipes'],
];
const EXP_GAP = 1.6;
// how big the trains are for n players: [trains, cars each]
const EXP_SIZE = (n) => (n <= 3 ? [2, 5] : n <= 6 ? [3, 7] : n <= 9 ? [3, 9] : [4, 10]);
// where every car sits for a size key ('t3c7'): { type, load, x (center), z, len, top, w, train }
function expLayout(key) {
  const [, nt, nc] = /^t(\d)c(\d+)$/.exec(key || 't3c7').map(Number), out = [];
  for (let ti = 0; ti < nt; ti++) {
    const z = (ti - (nt - 1) / 2) * 6;   // tracks 6m apart
    const cars = EXP_TRAINS[ti].slice(0, nc).map((c) => { const [type, load] = c.split(':'); return Object.assign({ type, load: load || '' }, EXP_CAR[type]); });
    const total = cars.reduce((sum, c) => sum + c.len, 0) + EXP_GAP * (cars.length - 1);
    let front = total / 2 + (ti % 2 ? 3 : -2);   // the trains are staggered a little
    for (const c of cars) {
      out.push(Object.assign(c, { x: front - c.len / 2, z, train: ti }));
      front -= c.len + EXP_GAP;
    }
  }
  return out;
}
// spawns and the seeker's spot for a size
function expPlaces(key) {
  const L = expLayout(key), mid = Math.floor((Math.max(...L.map((c) => c.train)) + 1) / 2);
  const flats = L.filter((c) => c.type === 'flat'), home = flats.find((c) => c.train === mid) || flats[0];
  // spawns: the back end of every flatcar (always clear of its load) and a few roofs
  const spawns = L.filter((c, i) => c.type === 'flat' || i % 3 === 1).map((c) => [c.x - (c.type === 'flat' ? c.len / 2 - 0.8 : 0), c.top, c.z]);
  const spot = [home.x - home.len / 2 + 0.8, 1.6, home.z];
  return { spawns, seekerSpawn: spot, centerSpot: spot };
}
let EXP_LAYOUT = expLayout('t3c7');   // (the one being played - set when the map is built)

defineMap({
  id: 'express',
  accent: ['#f2b300', '#b8453a'],
  name: 'The Express',
  blurb: 'Trains racing through the desert, forever - more and longer ones in bigger lobbies. Touch the ground and you\'re out - and don\'t jump when a tunnel comes, or it shoves you off.',
  env: 'fog',
  sky: '#ffd9ae',
  fog: [35, 125],
  hemi: ['#fff4e6', '#a07a58', 1.25],
  sun: [1.0, 25, 45, -20],
  size: 55,
  killY: 0.5,
  menuCam: { path: [[-40, 5.6, -10.8], [40, 5.4, -10.8]] },   // inside the tunnel's clearance, so tunnels pass around it
  // the trains grow with the lobby: 2 short trains for a few players, up to 4 long ones
  variant: (n) => { const [t, c] = EXP_SIZE(n); return `t${t}c${c}`; },
  layout: expPlaces,
  spawns: expPlaces('t3c7').spawns,
  seekerSpawn: expPlaces('t3c7').seekerSpawn,
  centerSpot: expPlaces('t3c7').centerSpot,

  build(k, key) {
    EXP_LAYOUT = expLayout(key);
    const tracks = [...new Set(EXP_LAYOUT.map((c) => c.z))];
    const SAND = '#e9c896', GRAVEL = '#a8998a', RAIL = '#6b6f78', DARK = '#2a2d33';
    const COLORS = { box: ['#b8453a', '#3f6fb5', '#8f5530'], passenger: ['#2f8f8a', '#6a4fa3'], tank: ['#c8ccd2', '#2f343c'], hopper: ['#5b8a4e', '#c9a227'], flat: ['#7a6a58'], loco: ['#f2b300'] };
    let seed = 7;
    const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
    const pick = (l) => l[Math.floor(rnd() * l.length)];

    // the ground far below the cars (looks only - nothing to stand on: touching it = the void)
    k.deco(0, -0.6, 0, 700, 0.3, 420, SAND, { tex: 'none', outline: false });
    for (const z of tracks) {
      k.deco(0, -0.3, z, 700, 0.3, 4.2, GRAVEL, { tex: 'none', outline: false });
      for (const s of [-0.72, 0.72]) k.deco(0, 0.12, z + s, 700, 0.14, 0.1, RAIL, { tex: 'none', outline: false });
    }

    // --- the trains ---
    for (const c of EXP_LAYOUT) {
      const col = pick(COLORS[c.type]), x1 = c.x + c.len / 2;
      // wheels / bogies and couplers (looks)
      for (const e of [-1, 1]) k.deco(c.x + e * (c.len / 2 - 1.8), 0.25, c.z, 2.6, 0.8, 2.2, DARK, { tex: 'none' });
      // the coupler to the car behind (solid: you can walk across it)
      const behind = EXP_LAYOUT.find((q) => q.train === c.train && Math.abs(q.x + q.len / 2 - (c.x - c.len / 2 - EXP_GAP)) < 0.01);
      if (behind) k.box(c.x - c.len / 2 - EXP_GAP / 2, 1.0, c.z, EXP_GAP + 0.1, 0.3, 0.4, DARK, { tex: 'none' });
      if (c.type === 'flat') {
        k.box(c.x, 1.0, c.z, c.len, 0.6, c.w, col);
        if (c.load === 'crates') {
          k.box(c.x - 2.2, 1.6, c.z - 0.6, 1.8, 1.4, 1.6, '#c49a63');
          k.box(c.x - 2.2, 3.0, c.z - 0.6, 1.4, 1.0, 1.4, '#b38955');
          k.box(c.x + c.len / 2 - 0.9, 1.6, c.z + 0.7, 1.6, 1.0, 1.4, '#c49a63');   // a step up to the next car
        } else if (c.load === 'pipes') {
          for (const dz of [-0.9, 0, 0.9]) k.box(c.x - 0.5, 1.6, c.z + dz, 6, 0.8, 0.8, '#7f8c99');
          k.box(c.x - 0.5, 2.4, c.z - 0.45, 6, 0.8, 0.8, '#7f8c99');
          k.box(c.x - 0.5, 2.4, c.z + 0.45, 6, 0.8, 0.8, '#7f8c99');
        } else if (c.load === 'container') {
          k.box(c.x, 1.6, c.z, 6, 2.6, 2.5, '#23408e', { tex: 'ribs' });
        }
        continue;
      }
      // the car body: solid from 1m up to its roof
      k.box(c.x, 1.0, c.z, c.len, c.top - 1.0, c.w, col, { tex: c.type === 'hopper' || c.type === 'box' ? 'ribs' : 'grid' });
      const side = (y, h, color, inset = 0.6) => { for (const s of [-1, 1]) k.deco(c.x, y, c.z + s * (c.w / 2 + 0.01), c.len - inset * 2, h, 0.02, color, { tex: 'none', outline: false }); };
      if (c.type === 'box') for (const s of [-1, 1]) k.deco(c.x, 1.3, c.z + s * (c.w / 2 + 0.01), 2.4, 2.4, 0.02, shade(col, 0.75), { tex: 'none' });
      if (c.type === 'passenger') side(2.5, 0.8, '#1f2a3a');
      if (c.type === 'tank') side(2.2, 0.25, '#ffd23f', 0.3);
      if (c.type === 'loco') {
        side(2.8, 0.9, '#1f2a3a', 4);
        k.deco(x1 + 0.01, 2.6, c.z, 0.02, 1.0, 2.2, '#1f2a3a', { tex: 'none' });   // windscreen
        k.deco(x1 + 0.02, 1.5, c.z, 0.02, 0.5, 2.4, '#e23a3a', { tex: 'none' });   // red nose stripe
      }
    }

    // --- the world going by: sleepers, poles, rocks and far-off mesas, repeated forever ---
    k.scroll({ speed: EXP_SPEED, len: 160 }, (add) => {
      for (const z of tracks) for (let x = -80; x < 80; x += 1.6) add(x, 0, z, 0.3, 0.12, 2.6, '#5a4632');
      for (let x = -80; x < 80; x += 40) for (const z of [-12.5, 12.5]) {
        add(x, -0.3, z, 0.3, 9, 0.3, '#6b5a48');
        add(x, 7.6, z, 0.2, 0.2, 2.4, '#6b5a48');
      }
      for (let i = 0; i < 26; i++) {
        const s = rnd() < 0.5 ? -1 : 1, z = s * (15 + rnd() * 18), w = 0.6 + rnd() * 2;
        add(-80 + rnd() * 160, -0.3, z, w, 0.4 + rnd() * 1.2, w * (0.6 + rnd()), rnd() < 0.5 ? '#c79a6a' : '#7d8a4a');
      }
      for (let i = 0; i < 9; i++) {
        const s = i % 2 ? -1 : 1, w = 14 + rnd() * 26, h = 6 + rnd() * 22;
        add(-80 + (i + rnd() * 0.6) * (160 / 9), -0.3, s * (55 + rnd() * 35), w, h, 10 + rnd() * 16, rnd() < 0.5 ? '#d9a06b' : '#c98b5a');
      }
    });

    // --- tunnels: a cliff with a tunnel mouth, a 36m tunnel behind it. It all slides past on the
    // shared clock (everyone sees the same tunnel at the same moment). The roof is 6.3m up ---
    const ROCK = '#9c6b4a', INSIDE = '#3b3430', X0 = 260, DX = -560;
    const loop = { type: 'loop', dx: DX, period: -DX / EXP_SPEED, phase: 0 }, SH = { shove: true };
    k.mover(X0, 6.3, 0, 2, 17, 100, ROCK, loop, SH);             // cliff over the mouth: it shoves you off the back
    for (const s of [-1, 1]) k.mover(X0, -0.3, s * 31, 2, 6.6, 38, ROCK, loop, SH);  // cliff beside the mouth
    k.mover(X0 + 19, 6.3, 0, 36, 4, 24, INSIDE, loop, SH);       // tunnel roof (behind the mouth: it all moves toward -x)
    for (const s of [-1, 1]) k.mover(X0 + 19, -0.3, s * 12.5, 36, 6.6, 1, INSIDE, loop, SH);   // tunnel walls
  },
});

;
/* ==== js/maps/castle.js ==== */
// THE CASTLE - a roofless, ivy-covered Gothic ruin in an autumn wood, painted in broad strokes.
// A square ruin (32m) on a 2m grid, every floor and wall top at 0 / 4 / 8 / 12:
//   court        12m open court in the middle, ringed by a broken wall at 4 (gaps to jump, doors under)
//   ranges       four roofless ranges round it, 6m wide; outer walls at 8 (walk the tops), a fallen
//                breach at 4 in the back wall with an earth bank up to it from outside
//   SW tower     square, battlemented, roof 12: a kick chimney 0 -> 8 inside, floor 8 (doors out onto
//                the W and S wall walks), stairs 8 -> 12
//   S gable      a stepped gable (8 -> 12) with a tall doorway; jump onto it from the tower roof
//   SE turrets   two slim round turrets (12), close enough to kick up between them, 0 -> 12
// Ways up: 0 -> 4  two rubble slopes in the court, the earth bank outside the back
//          0 -> 8  two piles of fallen masonry against the W and E outer walls (2.6, 5.2, then 8)
//          4 -> 8  rubble banks in the NW and NE corners, the tower (0 -> 8)
//          8 -> 12 tower stairs, the turret chimney (from the ground)
defineMap({
  id: 'castle',
  accent: ['#ebd999', '#b85e00'],
  name: 'The Castle',
  blurb: 'A roofless Gothic ruin in an autumn wood: run the broken walls, take the tower, kick up between the turrets.',
  env: 'fog',
  sky: '#d6cbb2',                       // one flat, warm overcast haze: the woods melt into it (cream, not khaki)
  fog: [110, 330],                     // far out: flat fields of color, not a haze
  hemi: ['#fbf1da', '#6e6650', 1.15],   // warm sky, darker ground: the walls get a lit top and a shaded side
  sun: [0.8, 25, 60, 30],
  outlineColor: '#1b3644',              // slate, not black
  size: 30,
  menuCam: { r: 42, y: 26 },
  spawns: [
    [0, 0, 21], [-21.5, 0, -4], [21, 0, -6], [12, 0, -20.5], [-12, 0, -20.5], [21.5, 0, 21.5], [-21.5, 0, -18],
    [-5, 0, 11], [-11, 0, 0.5], [11, 0, 3], [6, 0, -11], [6, 0, 11],
    [-13, 8, 10], [-15, 8, -9], [10, 8, -15], [2.8, 12, 15],
  ],
  seekerSpawn: [0, 0, 0],

  build(k) {
    // Wada 243 (Raw Sienna, Ivory Buff, Olive Green, Slate Color) + 249 (Ecru, Olive Ocher, Dark
    // Medici Blue), the ivy from 94 (Ivory Buff + Dusky Green) - a few nudged off them since.
    // One meaning each: sandstone faces, green (moss) on everything you stand on, tan rubble and
    // stairs, deep green ivy, orange kick walls
    // (color correction: the sandstone a touch less yellow, the moss less acid, the gold trees warmer
    // and the ivy a warm deep green instead of a cold blue-green, so nothing fights the olive)
    const IVORY = '#edd8a2', ECRU = '#c4b495', OLIVE = '#5a7a26', SIENNA = '#b85e00', SLATE = '#1b3644';
    const OCHER = '#cf9f22', MEDICI = '#41706a', DUSKY = '#2c5a2a', TOP = OLIVE;
    const KICK = { tex: 'kick' }, NO = { tex: 'none' }, SOFT = { tex: 'none', outline: false, noShadow: true };

    // a box by its extents
    const B = (x0, x1, z0, z1, y0, y1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    // mossy coping on a stone top (looks only): 2cm proud and 2cm wider, so no face is shared
    const cap = (x, y, z, w, d, rot) => k.deco(x, y, z, w + 0.04, 0.02, d + 0.04, TOP, Object.assign({ tex: 'none' }, rot ? { rot } : {}));
    const S = (x0, x1, z0, z1, y0, y1) => { B(x0, x1, z0, z1, y0, y1, IVORY); cap((x0 + x1) / 2, y1, (z0 + z1) / 2, x1 - x0, z1 - z0); };
    // a run of wall (x0..x1, z0..z1, 0..top) with holes [a0, a1, y0, y1] along its long axis:
    // cut into as few boxes as it takes
    const wall = (x0, x1, z0, z1, top, holes = [], col = IVORY) => {
      const ax = x1 - x0 >= z1 - z0, A0 = ax ? x0 : z0, A1 = ax ? x1 : z1;
      const cuts = [...new Set([A0, A1, ...holes.flatMap((h) => [h[0], h[1]])])].filter((c) => c >= A0 && c <= A1).sort((a, b) => a - b);
      const cols = [];
      for (let i = 0; i < cuts.length - 1; i++) {
        const a = cuts[i], b = cuts[i + 1];
        let runs = [[0, top]];
        for (const [h0, h1, y0, y1] of holes) if (h0 < b - 0.01 && h1 > a + 0.01)
          runs = runs.flatMap(([r0, r1]) => [[r0, Math.min(r1, y0)], [Math.max(r0, y1), r1]]).filter(([r0, r1]) => r1 - r0 > 0.01);
        for (const r of runs) {
          const prev = cols.find((c) => c.b === a && c.r[0] === r[0] && c.r[1] === r[1]);
          if (prev) prev.b = b; else cols.push({ a, b, r });
        }
      }
      for (const { a, b, r } of cols) ax ? S(a, b, z0, z1, r[0], r[1]) : S(x0, x1, a, b, r[0], r[1]);
    };
    const slab = (x0, x1, z0, z1, top, col = TOP) => B(x0, x1, z0, z1, top - 0.4, top, col);
    // big flat ivy panel 0.02 off a face: face = '+x' | '-x' | '+z' | '-z' at coordinate f
    const ivy = (face, f, a0, a1, y0, y1, col = DUSKY) => {
      const o = f + (face[0] === '+' ? 0.04 : -0.04);
      if (face[1] === 'x') B(o - 0.02, o + 0.02, a0, a1, y0, y1, col, Object.assign({ ghost: true }, NO));
      else B(a0, a1, o - 0.02, o + 0.02, y0, y1, col, Object.assign({ ghost: true }, NO));
    };
    const deco = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);

    // ===== the clearing, the boundary =====
    ground(k, 50, 50, OLIVE);
    for (const s of [-1, 1]) { k.wall(0, -2, s * 25.5, 52, 60, 1); k.wall(s * 25.5, -2, 0, 1, 60, 50); }
    // a dark hedge right along that invisible wall, so you can see where the clearing ends
    for (const s of [-1, 1]) { B(-25.5, 25.5, s * 25 - 0.5, s * 25 + 0.5, 0, 2.4, DUSKY, NO); B(s * 25 - 0.5, s * 25 + 0.5, -24.5, 24.5, 0, 2.38, DUSKY, NO); }

    // ===== the outer walls (2m thick, tops at 8) =====
    wall(-16, -14, -14, 8, 8, [[-2, 2, 0, 3]]);                        // W, a door under the wall walk
    wall(-16, 16, -16, -14, 8, [[-4, 4, 4, 8]]);                       // N, the fallen breach (4)
    wall(14, 16, -14, 4.6, 8, [[-2, 2, 0, 3]]);                        // E, a door, up to the turret
    // S: the gable (8, a stepped peak to 12, a tall doorway), a broken stretch at 4 to the turret
    wall(-8, 6, 14, 16, 8, [[-2, 2, 0, 6]]);
    S(-4, 4, 14, 16, 8, 12);
    S(6, 12.6, 14, 16, 0, 4);
    S(-1.2, 1.2, 14, 16, 12, 14.4);                             // the peak
    deco(-1.2, 1.2, 16.02, 16.06, 9, 11, SLATE);                       // the empty rose window
    // the earth bank outside the breach (0 -> 4)
    k.ramp(0, -20.02, 8, 7.96, 0, 4, '+z', OLIVE);

    // ===== fallen masonry in the clearing (the same sandstone, moss on top): two stepped piles
    // against the outer walls (0 -> 2.6 -> 5.2 -> the wall walk at 8) and low blocks to vault =====
    S(-18, -16, -10, -7, 0, 5.2); S(-20.5, -18, -10, -7, 0, 2.6);      // W
    S(16, 18, -12, -9, 0, 5.2); S(18, 20.5, -12, -9, 0, 2.6);          // E
    S(-22, -19.5, 3, 4, 0, 1); S(19.5, 22, 0, 1, 0, 1);                // low blocks
    S(-10, -9, -21, -18.5, 0, 1); S(9, 10, -21, -18.5, 0, 1);
    S(-6, -3.5, 20, 21, 0, 1);

    // ===== the court ring and cross walls (tops at 4) =====
    wall(-14, 14, -8, -6, 4, [[-10, -8, 0, 4], [2, 4, 0, 4], [8, 10, 0, 4]]);   // N cross wall
    wall(-8, 14, 6, 8, 4, [[-2, 2, 0, 4]]);                                     // S cross wall
    wall(-8, -6, -6, 6, 4, [[2, 4, 0, 4]]);                                     // W court wall
    wall(6, 8, -6, 6, 4, [[-4, -2, 0, 4]]);                                     // E court wall
    slab(-3, -1, -14, -8, 4);                                                   // a beam: breach -> court ring
    // rubble slopes: two in the court (0 -> 4), two banks in the back corners (4 -> 8)
    k.ramp(-4.49, -1.99, 2.98, 7.98, 0, 4, '-z', ECRU);
    k.ramp(4.49, 1.99, 2.98, 7.98, 0, 4, '+z', ECRU);
    k.ramp(-12, -11, 3.96, 5.96, 4, 8, '-z', ECRU);
    k.ramp(12, -11, 3.96, 5.96, 4, 8, '-z', ECRU);

    // ===== THE TOWER (SW): x -18..-8, z 8..18, roof 12 =====
    wall(-18, -8, 8, 9, 12, [[-12, -10, 0, 3], [-16, -14, 8, 11]]);             // N: door, the W walk comes in
    wall(-9, -8, 9, 17, 12, [[10, 12, 0, 3], [14, 16, 8, 11]]);                 // E: door, the S walk comes in
    wall(-18, -8, 17, 18, 12, [[-17, -15, 0, 3]]);                              // S: door out to the clearing
    wall(-18, -17, 9, 17, 12);
    slab(-17, -9, 9, 13.6, 8);                                                  // floor 8, round the chimney
    slab(-17, -15, 13.6, 17, 8);
    slab(-11, -9, 13.6, 17, 8);
    B(-15, -11, 13.6, 13.9, 0, 8, '#ff6a3d', KICK);                             // the kick chimney (0 -> 8)
    B(-15, -11, 16.7, 17, 0, 8, IVORY);                                         // (its other side: plain, on the S wall - kickable anyway)
    stairs(k, -16, 12, '+x', 2, 8, 12, ECRU, { run: 0.6 });                    // 8 -> 12
    slab(-17, -9, 9, 11, 12);                                                   // the roof
    slab(-17, -9, 13, 17, 12);
    slab(-17, -16, 11, 13, 12);
    for (const [x, z] of [[-17, 9], [-9, 9], [-17, 17], [-9, 17]]) S(x - 1, x + 1, z - 1, z + 1, 12, 13.2);

    // ===== THE TURRETS (SE): octagons (four strips 45 degrees apart), a kick chimney between (plain stone) =====
    const turret = (cx, cz, s, top) => {
      for (let i = 0; i < 4; i++) {
        k.box(cx, 0, cz, s, top - i * 0.03, s * 0.414, IVORY, { rot: i * Math.PI / 4 });
        cap(cx, top - i * 0.03, cz, s, s * 0.414, i * Math.PI / 4);
      }
      for (let i = 0; i < 4; i++) {
        const a = Math.PI / 4 + i * Math.PI / 2, r = s / 2 - 0.75;
        k.box(cx + Math.cos(a) * r, top - 0.1, cz + Math.sin(a) * r, 1, 1.3, 1, IVORY, { rot: a });   // sunk a little: no shared face
        cap(cx + Math.cos(a) * r, top + 1.2, cz + Math.sin(a) * r, 1, 1, a);
      }
    };
    turret(15, 15, 5, 12);
    turret(15, 6.6, 5, 12);
    B(14, 16, 12.2, 12.5, 0, 12, IVORY);
    B(14, 16, 9.1, 9.4, 0, 12, IVORY);

    // ===== ivy: a few big flat panels, mostly over the middle and the right =====
    ivy('+z', 16, -8, -2, 0, 7.6);                  // the gable front: a big mass left of the door...
    ivy('+z', 16, -4, -1.2, 7.6, 11.6);             // ...climbing the step
    ivy('+z', 16, 2, 12.6, 0, 3.6);                 // the low stretch to the turret
    ivy('+z', 16, 2, 6, 3.6, 7.6);
    ivy('+x', 16, -14, -2, 0, 7.6);                 // the E range: the outer wall...
    ivy('+x', 16, 2, 4, 0, 7.6);
    ivy('+z', -6, -2.6, 2, 0, 3.6);                 // the court side of the N cross wall
    ivy('-z', -16, 4, 16, 0, 7.6);                  // the back wall, outside

    // ===== the wood: broad masses of autumn color all round (looks only), a hill behind to the right =====
    deco(-360, 360, -360, 360, -0.62, -0.02, OLIVE, SOFT);
    const mass = (x, z, w, d, h, col) => {
      deco(x - w / 2, x + w / 2, z - d / 2, z + d / 2, 0, 2.5 + h, col, SOFT);
      deco(x - w * 0.3, x + w * 0.3, z - d * 0.3, z + d * 0.3, 2.5 + h, 3.5 + h * 1.25, col, SOFT);
    };
    const spruce = (x, z, h) => {
      for (let i = 0; i < 4; i++) deco(x - 2.6 + i * 0.6, x + 2.6 - i * 0.6, z - 2.6 + i * 0.6, z + 2.6 - i * 0.6, 1.5 + i * h, 1.5 + (i + 1) * h, MEDICI, SOFT);
    };
    // front (south)
    mass(-24, 34, 16, 9, 7, OCHER); mass(-6, 33, 14, 8, 6, SIENNA); mass(10, 35, 16, 10, 8, OCHER); mass(27, 33, 12, 9, 6, SIENNA);
    // sides
    mass(-34, 16, 9, 16, 7, SIENNA); mass(-35, -4, 10, 14, 8, OCHER); mass(-33, -22, 9, 12, 6, SIENNA);
    mass(34, 18, 9, 14, 6, OCHER); mass(35, 1, 10, 14, 7, SIENNA);
    // back: the hillside climbs away to the right, woods on it
    deco(-10, 360, -360, -46, -0.6, 7, OLIVE, SOFT);
    deco(14, 360, -360, -56, -0.6, 16, OLIVE, SOFT);
    mass(-18, -34, 16, 8, 7, SIENNA); mass(2, -36, 14, 8, 8, OCHER); mass(24, -42, 18, 10, 9, SIENNA);
    mass(34, -22, 9, 14, 7, SIENNA); mass(40, -48, 16, 10, 8, OCHER);
    spruce(-27, 27, 2.6); spruce(29, -28, 3); spruce(-8, -31, 2.8); spruce(31, 26, 2.4); spruce(-30, -8, 2.6);
  },
});

;
/* ==== js/maps/airport.js ==== */
// AIRPORT - one gate on a sunny apron, painted in a few broad fields of color.
// THE RULE: every building floor sits at 0, 4, 8 or 12 (stairs, pads, the kick wall and the baggage
// steps at 0.9 / 2.5 join them), the buildings snap to a 2m grid, and each height has one color:
//   0  the apron (Ecru)     4  Antwarp Blue     8  Cream Yellow     12  Deep Indigo
// The jet is the one exception: it stays its own pale Nile Blue (fin and engines Antwarp Blue) so it
// reads as one big shape against the Salvia Blue sky. Terminal and jet-bridge walls are
// Salvia Blue, so they melt into the sky; stairs Neutral Gray.
//
//   terminal   along the north side, x -24..24: an open hall (0), the upper floor (4), the roof (8)
//   jet        parked side-on in front of it, nose west. Two jet bridges join the upper floor to its
//              front and rear doors (a loop at 4), and their roofs join the terminal roof to the
//              jet's roof (a loop at 8). Over-wing doors onto both wings (4), airstairs and a slide
//              down the south side, the tailplanes out at 8
//   tower      in the south-east: an ops annex (4), the tower block (8), the glass cab (12)
//   baggage    the one repeated toy: luggage trains (grey tug + dollies, empty = a 0.9 vault, loaded
//              with a white or blue can = a 2.5 step) parked in 3-4m lanes all over the apron. Every
//              can is one jump + mantle from the ground and one more from the 4 level (wings, the
//              terminal's open front, the annex). Inside the terminal, check-in islands (a glass
//              screen with a counter each side) split each hall into two lanes; roof units on top.
//
// Ways up:  0 -> 4  terminal stairs x2, airstairs, both engines, annex stairs, any loaded dolly
//           4 -> 8  terminal stairs x2, a pad on each wing (onto the jet roof), annex -> tower stairs
//           0 -> 8  the orange kick wall off the tower's north face
//           8 -> 12 the tower's stairs;  4 -> 12  the big pad on the annex roof
// Colors: Wada 302 (Cream Yellow, Ecru, Nile Blue, Antwarp Blue) + 139 (Salvia Blue, Deep Indigo,
// Neutral Gray) - every color in the map is one of those seven.
defineMap({
  id: 'airport',
  accent: ['#008aa1', '#ffb852'],
  name: 'Airport',
  blurb: 'A sunny gate: run through the parked jet and over its wings, along the roofs, up the control tower and down the evacuation slide.',
  env: 'fog',
  sky: '#96bfe6',
  fog: [70, 200],
  hemi: ['#ffffff', '#c0b490', 1.35],
  sun: [0.8, -20, 55, 30],
  outlineColor: '#000831',
  size: 30,
  menuCam: { path: [[-15, 19, 33], [-13, 16, 29]] },
  spawns: [
    [-17.7, 0, 16], [-6, 0, 18], [6, 0, 12], [18.5, 0, 7.5], [0, 0, -10], [-16, 0, -16], [12, 0, -16],
    [-8, 4, -20], [16, 4, -20], [-8, 4, 0], [0, 4, 7], [8, 4, 20],
    [-16, 8, -19], [-6, 8, 0], [21, 8, 17],
    [20, 12, 21],
  ],
  seekerSpawn: [-7, 0, 11],

  build(k) {
    // Wada 302 + 139
    const CREAM = '#ffb852', ECRU = '#c0b490', NILE = '#bfffe6', ANTWARP = '#008aa1';
    const SALVIA = '#96bfe6', INDIGO = '#000831', GRAY = '#b5d1cc';
    const NO = { tex: 'none', outline: false };
    const L4 = ANTWARP, L8 = CREAM, L12 = INDIGO, JET = NILE;

    // ===================== the apron, the fence, the airfield =====================
    ground(k, 48.8, 48.8, ECRU);
    // a low kerb on three sides (the terminal closes the north), invisible walls above it
    k.box(0, 0, 24.2, 48.8, 1, 0.4, ANTWARP);
    for (const s of [-1, 1]) k.box(s * 24.2, 0, 5, 0.4, 1, 38, ANTWARP);
    k.wall(0, 1, 24.2, 48.8, 50, 0.4);
    for (const s of [-1, 1]) k.wall(s * 24.2, 1, 0, 0.4, 50, 49);
    k.wall(0, 8, -24.2, 48.8, 50, 0.4);
    // beyond: one soft field and the runway (looks only)
    k.deco(0, -0.7, 0, 500, 0.1, 500, GRAY, NO);
    k.deco(0, -0.6, 50, 500, 0.06, 24, ECRU, NO);
    // the stand's lead-in line (one stroke of color, 2cm proud of the apron)
    k.deco(-2, 0, 0, 40, 0.02, 0.5, CREAM, NO);

    // ===================== the terminal: x -24..24, z -24..-14 =====================
    k.box(0, 0, -24.2, 48.8, 8, 0.4, SALVIA);                               // back wall (sky-colored glass)
    for (const s of [-1, 1]) k.box(s * 24.2, 0, -19, 0.4, 8, 10, SALVIA);      // end walls
    // upper floor (4) with the two ground-floor stair holes
    slabHole(k, -24, 0, -24, -14, 4, [-22, -18, -22, -14], L4);
    slabHole(k, 0, 24, -24, -14, 4, [18, 22, -22, -14], L4);
    stairs(k, -20, -14.8, '-z', 4, 0, 4, L4);
    stairs(k, 20, -14.8, '-z', 4, 0, 4, L4);
    // roof (8) with the holes the upper stairs come up through
    slabHole(k, -24, 4, -24, -14, 8, [-6, -2, -22, -14], L8);
    slabHole(k, 4, 24, -24, -14, 8, [10, 14, -22, -14], L8);
    stairs(k, -4, -14.8, '-z', 4, 4, 8, L8);
    stairs(k, 12, -14.8, '-z', 4, 4, 8, L8);
    posts(k, [[-16, -14.6], [-8, -14.6], [0, -14.6], [8, -14.6], [16, -14.6]], 0, 7.6, SALVIA, 0.6);
    // the departures board: one dark field with three soft lines of light
    k.deco(4, 4.9, -23.98, 12, 2.4, 0.02, INDIGO, NO);
    for (let i = 0; i < 3; i++) k.deco(4, 5.3 + i * 0.6, -23.95, 10.4, 0.25, 0.02, CREAM, NO);

    // ===================== the jet: fuselage along x, z -2.4..2.4, nose west =====================
    // cabin floor (4), roof (8), a blue belly under it (walk under at 2.4)
    slab(k, -2, 4, 0, 24, 4.8, L4, { t: 0.4 });
    slab(k, -2, 8, 0, 24, 4.8, JET, { t: 0.4 });
    k.box(-2, 2.4, 0, 24, 1.2, 4, ANTWARP);
    // side walls with four doors each side: jet bridge / airstairs, over-wing, rear
    for (const z of [-2.2, 2.2]) {
      for (const [a, b] of [[-14, -13.6], [-10.4, -4], [-1, 4.4], [7.6, 10]]) k.box((a + b) / 2, 4, z, b - a, 3.6, 0.4, JET);
    }
    // cockpit (its top is part of the roof at 8), then a nose that tapers in three steps (looks only),
    // with the dark windscreen band wrapped round its first step
    k.box(-15.5, 2.6, 0, 3, 5.4, 4.8, JET);
    k.deco(-17.8, 3, 0, 1.6, 4.2, 4, JET, { tex: 'none' });
    k.deco(-19.2, 3.5, 0, 1.2, 3, 3, JET, { tex: 'none' });
    k.deco(-20.2, 4.1, 0, 0.8, 1.8, 1.8, JET, { tex: 'none' });
    k.deco(-17.71, 6.2, 0, 1.62, 0.7, 4.04, INDIGO, NO);
    // tail cone: the top stays at 8, the belly rises and the sides narrow in three steps
    k.box(12.5, 3.6, 0, 5, 4.4, 4.8, JET);
    k.box(16, 5, 0, 2, 3, 3.6, JET);
    k.box(17.8, 6.2, 0, 1.6, 1.8, 2.4, JET);
    // horizontal tailplane (8), swept in two steps, and the fin - the jet's one bold stroke
    for (const s of [-1, 1]) {
      slab(k, 13, 8, s * 3.9, 4, 3, JET, { t: 0.4 });
      slab(k, 14, 8, s * 6.4, 3, 2, JET, { t: 0.4 });
    }
    k.box(14.5, 8, 0, 5, 4.4, 0.8, ANTWARP);
    k.box(16.6, 12.4, 0, 3.6, 3.6, 0.8, ANTWARP);
    // wings (top at 4), swept back in three steps, 9.6m out from each side
    for (const s of [-1, 1]) {
      const root = s * 2.4;
      slab(k, -3, 4, root + s * 3, 10, 6, JET, { t: 0.5 });
      slab(k, -1, 4, root + s * 7.2, 8, 2.4, JET, { t: 0.5 });
      slab(k, 0.75, 4, root + s * 9, 5.5, 1.2, JET, { t: 0.5 });
      // engine under the inner panel, sticking out ahead of it: a round-ish nacelle of two crossed
      // boxes, a dark intake and an exhaust. Hop on (3.3), then up onto the wing
      const ez = root + s * 3;
      k.box(-7.5, 0.9, ez, 5, 2, 2.4, ANTWARP);
      k.box(-7.5, 0.5, ez, 4.9, 2.8, 1.6, ANTWARP);
      k.deco(-10.01, 1.1, ez, 0.02, 1.6, 1.4, INDIGO, NO);
      k.box(-4.6, 1.3, ez, 0.8, 1.2, 1.2, INDIGO);
      // a pad on each wing root: up onto the jet's roof
      k.pad(-2, 4, root + s * 1.8, 1.4, 1.4, 17, { aim: [-2, 0, 2.6] });
    }
    // landing gear (looks)
    // landing gear: solid legs (circle them, they break the long look under the belly)
    k.box(-15, 0, 0, 0.8, 2.4, 0.8, INDIGO);
    for (const z of [-1.3, 1.3]) k.box(0, 0, z, 1.6, 2.4, 1, INDIGO);
    // airstairs to the south front door, the evacuation slide from the south rear door
    stairs(k, -12, 9.4, '-z', 3, 0, 4, GRAY);
    k.ramp(6, 5.9, 3.2, 7, 0, 4, '-z', CREAM, { slick: true });

    // ===================== jet bridges: upper floor (4) -> the north doors =====================
    for (const x of [-12, 6]) {
      slab(k, x, 4, -8.2, 4, 11.6, L4, { t: 0.4 });
      slab(k, x, 8, -8.2, 4, 11.6, L8, { t: 0.4 });
      for (const e of [-1, 1]) k.box(x + e * 1.8, 4, -8.2, 0.4, 3.6, 11.6, SALVIA);
      k.box(x, 0, -8.2, 0.8, 3.6, 0.8, INDIGO);                              // the bridge's leg
    }

    // ===================== the tower (south-east corner, flush with the fence) =====================
    // ops annex (4): stairs up its west end, a baggage cart against its north face
    k.box(11, 0, 21, 10, 3.7, 6, CREAM);
    k.box(11, 3.7, 21, 10, 0.3, 6, L4);
    stairs(k, -1, 21, '+x', 3, 0, 4, GRAY);
    k.box(12, 0, 17.2, 4, 1.6, 1.6, ANTWARP);
    // tower block (8)
    k.box(20, 0, 20, 8, 8, 8, CREAM);
    stairs(k, 9, 19.2, '+x', 2.4, 4, 8, L8);                                    // annex roof -> block
    // the kick wall 2.8m off the block's north face: ground -> 8
    k.box(20, 0, 12.95, 6, 8.5, 0.5, ECRU, { tex: 'kick' });
    // the cab (12): fills the block's south part right up to the fence, on four posts, with a
    // band of glass along the two fence sides (high up - walk under it) and a roof
    slab(k, 20, 12, 21, 8, 6, L12, { t: 0.4 });
    posts(k, [[16.3, 18.3], [23.7, 18.3], [16.3, 23.7], [23.7, 23.7]], 8, 15.6, INDIGO, 0.4);
    k.box(20, 14, 23.8, 7.4, 1.6, 0.2, NILE);
    k.box(23.8, 14, 21, 0.2, 1.6, 5.4, NILE);
    k.box(20, 15.6, 21, 8, 0.5, 6, ANTWARP);
    k.wall(20, 16.1, 21, 8, 30, 6);   // the cab roof isn't a floor (a kick off the cab's edge used to reach it - a perch no CPU could follow you to)
    stairs(k, 16.3, 17, '+x', 2, 8, 12, L12);                               // block -> cab
    k.pad(14, 4, 22.6, 1.4, 1.4, 23, { aim: [19, 22.6, 3] });               // annex roof -> cab
    k.deco(20, 16.1, 21, 0.3, 3, 0.3, INDIGO, { tex: 'none' });              // antenna

    // ===================== baggage trains: the apron's one repeated toy =====================
    // A train is a grey tug and a line of grey dollies, 1m apart (slip between them). An empty
    // dolly (0.9) is a vault; a loaded one carries a luggage can (top 2.5) - one jump + mantle up,
    // and one more onto anything at 4 (wings, the upper floor's open front, the annex).
    //   cars: T tug, u empty dolly, W white can, B blue can.  (x, z) = the first car's center,
    //   a = heading (0 = east, PI/2 = north), skewed trains break the grid.
    const train = (x, z, a, cars) => {
      const cx = Math.round(Math.cos(a) * 1e6) / 1e6, cz = -Math.round(Math.sin(a) * 1e6) / 1e6;
      const ns = !cx, o = a && !ns ? { rot: a } : {};    // straight north / south: no rotation, just turned
      const put = (px, y, pz, l, h, w, col, deco) => (deco ? k.deco : k.box)(px, y, pz, ns ? w : l, h, ns ? l : w, col, ns ? { tex: 'none' } : Object.assign({ tex: 'none' }, o));
      let s = 0;
      for (const c of cars) {
        const L = c === 'T' ? 2 : 2.6, px = x + cx * (s + L / 2), pz = z + cz * (s + L / 2);
        if (s) put(x + cx * (s - 0.5), 0.35, z + cz * (s - 0.5), 1.2, 0.12, 0.12, INDIGO, true);   // tow bar (looks)
        if (c === 'T') put(px, 0, pz, 2, 1.4, 1.6, GRAY);
        else {
          put(px, 0, pz, 2.6, 0.9, 2, GRAY);
          if (c !== 'u') put(px, 0.9, pz, 2.2, 1.6, 1.8, c === 'B' ? ANTWARP : JET);
        }
        s += L + 1;
      }
    };
    const N = Math.PI / 2;
    // the south apron: columns with 3-4m lanes between them, one skewed, one along the fence
    train(-20, 11.5, -N, 'TWB');
    train(-15.5, 21.5, N, 'TBW');
    train(-11, 12.5, -0.4, 'TuW');
    train(-12.5, 21, 0, 'TWB');
    // the east apron: past the slide, a skewed one under the tailplane, one up the fence
    train(1, 13.5, 0, 'TBW');
    train(10, 5.5, 0.3, 'TWB');
    train(21, 11, N, 'TBW');
    train(21, -1, N, 'TW');
    train(9.5, 10.5, 0, 'TW');
    train(-3, 17.5, 0, 'TuB');
    // the north side, in front of the terminal: cans to climb onto the upper floor's open front (4)
    train(-22, -11, 0, 'TWu');
    train(-9, -8, N, 'TW');
    train(9, -11, 0, 'TBuW');
    // by the nose
    train(-21.5, 10, N, 'TWu');
    // under the nose and under the tailplane
    train(-23, -6, 0, 'TW');
    train(10, -6, 0, 'TWB');

    // ===================== the terminal's insides: check-in islands =====================
    // a glass screen floor to ceiling with a counter (vault) along each face: two 3.5m lanes
    // through each hall instead of one 10m-wide room
    const island = (x, y, w) => {
      k.box(x, y, -19, w, 3.6, 0.6, SALVIA);
      for (const e of [-1, 1]) k.box(x, y, -19 + e * 1.0, w - 1, 0.9, 1.4, GRAY);
    };
    for (const x of [-13, -5, 3, 11]) island(x, 0, 6);      // ground hall
    for (const x of [-13, 4]) island(x, 4, 6);              // upper floor (the gates)
    // roof units on the terminal roof (8): small perches at 9.6
    for (const [x, z, c] of [[-17, -21, JET], [-12, -17, ANTWARP], [-9.5, -21, JET], [1, -17, ANTWARP], [3, -21, JET], [7.5, -17, JET], [17, -21, ANTWARP], [21, -17, JET]]) k.box(x, 8, z, 2.2, 1.6, 1.8, c);
  },
});

;
/* ==== js/maps/windmill.js ==== */
// WINDMILL ISLAND - a small breezy island village round one big old tower mill, painted in a few
// broad, soft planes of color. One rule: a 7x7 grid of 7m cells (49m square), and every floor at
// 0, 4, 8 or 12. Each cell is a street at its terrace's level or a plain block house one floor up.
//   row 0-1   THE HILL (8, green). The mill in the middle: an octagonal tower with a wide timber
//             STAGE round it at 12 (cream), shading the hill under it (3.6m headroom)
//   row 2-4   THE TOWN (4, the village green, light grass): the sails sweep over its open back street, where two mill
//             steps climb to the hill; a row of three houses (roofs 8) across the middle, joined
//             into one high street at 8 by footbridges, with bridges at 8 back to the hill
//   row 5-6   THE QUAY (0, ecru): harbor steps up the middle, two houses (roofs 4), a slipway, a
//             and the lighthouse (just looks)
// Every house has one outside stair up its front.
// Sheds (small coral blocks, 2.4 tall) and 1m stone garden walls split the wide streets into lanes:
// a shed set against a house or the stage is a jump + mantle up to it; a garden wall is a vault.
// THE SAILS: four lattice sails turn slowly on a horizontal axle over the town street (looks only -
// nothing to ride, so nobody camps up there). Nothing stands in the band they sweep.
// Ways up (none the only one):
//   0 -> 4   harbor steps, slipway (W), a wall kick in the corner by the E quay house, the quay houses' stairs
//   4 -> 8   stairs (W), ramp (E), the two mill steps under the sails, the town houses' stairs
//   8 -> 12  stairs (W), back stairs (N, behind the tower), kick chimney (E)
// Loops: the quay and town round their houses; at 8 the hill -> bridge -> high street -> bridge
// -> hill ring; at 12 round the tower.
// Grass on every terrace above the harbor: the town green (MEADOW, light) at 4 and the hill
// (OIL, deeper) at 8, with a grassy bank (the east ramp) between them.
// Colors: Wada combinations 320 (Coral Red, Sulpher Yellow, Oil Green, Light Glaucous Blue) and
// 302 (Cream Yellow, Ecru, Antwarp Blue).
defineMap({
  id: 'windmill',
  accent: ['#ff7399', '#008aa1'],
  name: 'Windmill Island',
  blurb: 'A breezy island village round an old windmill. Climb to the mill stage, run the terraces down to the harbor.',
  env: 'fog',
  sky: '#a6e6db',                  // one flat Light Glaucous Blue sky over a clear blue sea
  fog: [110, 380],
  hemi: ['#ffffff', '#ffffff', 1.35],
  sun: [0.6, 30, 50, 20],
  size: 32,
  killY: -4,
  outlineColor: '#008aa1',
  menuCam: { path: [[-6, 7, 40], [-3, 10, 27]] },
  spawns: [
    [-6, 0, 21], [6, 0, 21], [-21, 0, 21], [6, 0, 13],
    [-7, 4, 7], [7, 4, 7], [-21, 4, 5], [21, 4, 5],
    [-14, 8, 0], [14, 8, 0],
    [-20, 8, -21], [20, 8, -21], [0, 8, -21.5], [-6, 8, -13],
    [-7, 12, -16], [7, 12, -16],
  ],
  seekerSpawn: [0, 4, -6],
  centerSpot: [0, 4, -6],

  build(k) {
    const CORAL = '#ff7399', SULPHER = '#f5f5b8', OIL = '#6ea900', GLAUCOUS = '#a6e6db';   // 320
    const CREAM = '#ffb852', ECRU = '#c0b490', ANTWARP = '#008aa1';                        // 302
    const MEADOW = '#a9d65e';                          // the town green: a lighter grass than the hill
    const STONE = CREAM;                               // the terrace walls: warm sunlit bands
    const FLAT = { tex: 'none', outline: false };
    const C = 7;                                        // cell size
    const oct = (x, y, z, r, h, col, solid = true) => {   // an octagon: two boxes, the second 2cm lower
      const f = solid ? k.box : k.deco;
      f(x, y, z, 2 * r * 0.83, h, 2 * r, col);
      f(x, y, z, 2 * r, h - 0.02, 2 * r * 0.83, col);
    };

    // ===== the sea: clear blue, like Lighthouse Rocks' - pale shallows round the island and the boat,
    // one white line of foam where the water meets them - and one boat =====
    const DEEP = '#13609a', SHALLOW = '#2f9cc0', FOAM = '#f2fbff';
    const SURF = { tex: 'none', outline: false, noShadow: true };
    k.deco(0, -2.1, 0, 600, 0.1, 600, DEEP, FLAT);
    k.deco(0, -2.0, 0, 49 + 3.2, 0.02, 49 + 3.2, SHALLOW, SURF);
    k.deco(0, -1.98, 0, 49 + 1.0, 0.02, 49 + 1.0, FOAM, SURF);
    k.deco(-9, -2.0, 29, 2.2 + 1.2, 0.02, 5 + 1.2, SHALLOW, SURF);
    k.deco(-9, -1.98, 29, 2.2 + 0.4, 0.02, 5 + 0.4, FOAM, SURF);
    k.deco(-9, -2.1, 29, 2.2, 0.8, 5, SULPHER, { tex: 'none' });
    k.deco(-9, -1.3, 29.4, 0.2, 3.2, 0.2, ECRU, { tex: 'none' });

    // ===== the terraces: quay (0), town (4), hill (8) =====
    k.box(0, -6, 17.5, 49, 6, 14, ECRU);                // quay   z 10.5..24.5
    k.box(0, -6, 0, 49, 9.6, 21, STONE);                // town   z -10.5..10.5
    k.box(0, 3.6, 0, 49, 0.4, 21, MEADOW);
    k.box(0, -6, -17.5, 49, 13.6, 14, STONE);           // hill   z -24.5..-10.5
    k.box(0, 7.6, -17.5, 49, 0.4, 14, OIL);
    // low parapets round the island's edge, and an invisible wall above them
    k.box(0, 8, -24.25, 49, 0.7, 0.5, STONE);
    k.box(0, 0, 24.25, 49, 0.7, 0.5, STONE);
    for (const s of [-1, 1]) {
      k.box(s * 24.25, 8, -17.25, 0.5, 0.7, 13.5, STONE);
      k.box(s * 24.25, 4, 0, 0.5, 0.7, 21, STONE);
      k.box(s * 24.25, 0, 17.25, 0.5, 0.7, 13.5, STONE);
      k.wall(s * 25, -6, 0, 1, 50, 51);
      k.wall(0, -6, s * 25, 51, 50, 1);
    }

    // ===== houses: a plain block one floor up, its roof the color of the floor it's level with,
    // one door, and an outside stair up the front =====
    const house = (cx, cz, y0, roof, stairDir) => {
      k.box(cx, y0, cz, C, 3.7, C, CORAL);
      k.box(cx, y0 + 3.7, cz, C, 0.3, C, roof);
      k.deco(cx + (stairDir === '+x' ? 1.6 : -1.6), y0, cz + C / 2 + 0.02, 1.2, 2.2, 0.04, SULPHER, { tex: 'none' });
      stairs(k, cx - (stairDir === '+x' ? 1 : -1) * C / 2, cz + C / 2 + 1.3, stairDir, 2.4, y0, y0 + 4, CORAL);
    };
    house(-14, 0, 4, OIL, '+x');                     // town houses (roofs 8)...
    house(0, 0, 4, OIL, '+x');
    house(14, 0, 4, OIL, '-x');
    bridge(k, -14, -10.5, -14, -3.5, 8, 2.4, OIL);   // ...their bridges to the hill...
    bridge(k, 14, -10.5, 14, -3.5, 8, 2.4, OIL);
    bridge(k, -10.5, 0, -3.5, 0, 8, 2.4, OIL);       // ...and the footbridges between them
    bridge(k, 3.5, 0, 10.5, 0, 8, 2.4, OIL);
    house(-14, 14, 0, MEADOW, '+x');                       // quay houses (roofs 4, turfed like the green)
    house(14, 14, 0, MEADOW, '-x');

    // ===== quay -> town =====
    stairs(k, 0, 17.5, '-z', 5, 0, 4, ECRU);             // the harbor steps
    k.ramp(-21, 14, 3, 7, 0, 4, '-z', ECRU);              // the slipway

    // ===== town -> hill =====
    stairs(k, -21, -3.5, '-z', 3, 4, 8, STONE);
    k.ramp(21, -7, 3, 7, 4, 8, '-z', OIL);                 // a grassy bank
    for (const s of [-1, 1]) stairs(k, s * 7, -3.5, '-z', 2.4, 4, 8, STONE);   // the mill steps (clear of the sails)

    // ===== THE MILL =====
    const TZ = -14.5, RZ = -8.3, SP = 0.26, Y0 = 16;   // tower z, sail plane z, sail speed, axle height
    // the tower: through the stage up to the cap (nobody perches on top)
    oct(0, 8, TZ, 2.5, 10, SULPHER);
    k.deco(0, 8, TZ + 2.52, 1.2, 2.4, 0.04, ANTWARP, { tex: 'none' });
    oct(0, 18, TZ, 2.7, 1.2, ANTWARP, false);            // the cap
    oct(0, 19.2, TZ, 1.8, 1.0, ANTWARP, false);
    k.wall(0, 18, TZ, 6, 30, 6);
    // the stage at 12, round the tower, on posts
    slab(k, 0, 12, -14.5, 21, 8, CREAM, { t: 0.4 });
    posts(k, [[-10.2, -18.2], [10.2, -18.2], [-10.2, -10.8], [10.2, -10.8], [-5, -18.2], [5, -18.2]], 8, 11.6, ECRU, 0.4);
    stairs(k, -17.5, -15, '+x', 2.5, 8, 12, STONE);
    stairs(k, 3.5, -19.8, '-x', 2.4, 8, 12, STONE);       // the back stairs, behind the tower
    kickShaft(k, 12.5, -15, 'x', 4, 8, 12, CREAM);
    // the windshaft (looks: 3.9m over the stage) and the four lattice sails
    k.deco(0, Y0 - 0.2, (TZ + 2 + RZ) / 2, 0.8, 0.8, RZ - TZ - 2, ANTWARP, { tex: 'none' });
    k.wheel(0, Y0 + 0.2, RZ, 'z', SP, 0, (add) => {
      add(0, 0, -0.4, 1.5, 1.5, 0.8, ANTWARP);
      for (let i = 0; i < 4; i++) {
        const a = i * Math.PI / 2;
        add(4.2, 0, 0, 7.2, 0.35, 0.3, ANTWARP, a);                 // the stock
        add(4.7, 1.0, 0.06, 6.0, 1.7, 0.1, SULPHER, a);             // the cloth
        for (const r of [2.2, 4.7, 7.2]) add(r, 1.0, -0.12, 0.22, 1.9, 0.14, ANTWARP, a);   // lattice bars
        add(4.7, 1.9, -0.12, 5.2, 0.16, 0.14, ANTWARP, a);
      }
    });

    // ===== sheds and garden walls: the same plain blocks, smaller - a shed is a coral block 2.4 tall
    // (a jump + mantle; set against a house or the stage it's the step up to it), a garden wall is a
    // 1m stone wall to vault. They split the wide streets into lanes and give cover =====
    const shed = (x0, x1, z0, z1, y0, roof) => {
      k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, 2.1, z1 - z0, CORAL);
      k.box((x0 + x1) / 2, y0 + 2.1, (z0 + z1) / 2, x1 - x0, 0.3, z1 - z0, roof);
    };
    const gwall = (x0, x1, z0, z1, y0) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, 1, z1 - z0, STONE);
    for (const s of [-1, 1]) {
      const X = (a, b) => s < 0 ? [-b, -a] : [a, b];
      shed(...X(7.5, 10.5), 14.5, 17.5, 0, ECRU);       // quay: against the quay house -> its roof (4)
      shed(...X(12.5, 15.5), 7.5, 10.5, 4, MEADOW);     // town front street, on its edge
      // hill: against the stage -> the stage (12) (W: kept 1.2m clear of the stage stairs' side)
      if (s > 0) shed(10.5, 13, -19.2, -16.9, 8, OIL); else shed(-13, -10.5, -20, -17.5, 8, OIL);
      shed(...X(18.5, 21.5), -18, -15, 8, OIL);          // hill: out in the field
      shed(...X(18.5, 21.5), 0, 3, 4, MEADOW);          // town: beside the end house -> its roof (8)
      gwall(...X(12.5, 15.5), 22, 23, 0);                // quay
      gwall(...X(5.5, 8.5), 9, 10, 4);                  // town front street
      gwall(...X(17, 18), -8.5, -5.5, 4);               // town back street
      gwall(...X(17, 20), -12, -11, 8);                 // hill
    }
    gwall(-2, 2, 21, 22, 0);                             // quay, below the harbor steps

    // ===== the lighthouse (just looks; nobody perches on top) =====
    oct(21, 0, 21, 1.7, 13, SULPHER);
    oct(21, 13, 21, 1.2, 1.6, CREAM, false);
    oct(21, 14.6, 21, 1.5, 0.7, ANTWARP, false);
    k.wall(21, 13, 21, 3.6, 30, 3.6);
  },
});

;
/* ==== js/maps/aqueduct.js ==== */
// THE AQUEDUCT - race. One giant three-tier aqueduct across a bottomless gorge, between two towers.
// You run its length three times, a tier higher each time: east along the bottom arcade, back west
// along the middle one, then east again down the open water channel on top, and leap off its end
// into the basin on the east tower. Fall into the gorge and you're back at the start; drop through
// a hole in the middle tier and you land on the bottom one.
//
//   tier 1 (floor 0, eastbound)    the broken deck (three gaps) - weirs and sluice gates (jump, slide
//                                  under) - the spillway (a water chute down, a gap, back up) - the
//                                  floats (drifting stepping stones) - three revolving doors.
//                                  East tower: kick up the orange shaft to tier 2
//   tier 2 (floor 10, westbound)   kick alley (zig-zag between orange walls over a hole) - the siphon
//                                  (the floor dives under a dam: slide) - the cornice (out along a
//                                  ledge on the outside of the bridge, over two gaps) - the fountains
//                                  (jets throw you over three dams) - the baffles (weave).  West tower:
//                                  through it and ride the water wheel up to its roof
//   tier 3 (top, eastbound)        the cascade, stepping down from 30 to 20: a water chute - sluice beam
//                                  and weir - a slot - two sweepers - a chute - two stepping posts over
//                                  a pit - a slot - a sluice beam - the long last chute, broken once,
//                                  and the leap into the basin
//
// Every tier stands right on top of the one before and the towers are exactly as wide as the bridge
// (no corners outside to climb), so the only ways up are the east tower's shaft and the west
// tower's wheel. Positions in build() are in bridge meters u (0 = the west tower's face, 168 = the
// east tower's); x = u - 84.
// Colors: Wada 296 (Sulpher Yellow, Ochraceous Salmon, Pale Raw Umber, Slate Color) and
// 330 (Nile Blue, Salvia Blue, Green Blue). Everything you walk on is yellow, the stone is salmon,
// everything that blocks you or turns (weirs, gates, dams, doors, sweepers, the wheel) is umber,
// water (slides, jets) is green-blue, things that carry you (floats, the wheel's buckets) are pale Nile Blue.
defineMap({
  id: 'aqueduct',
  kind: 'race',
  accent: ['#2dbc94', '#d99e73'],
  name: 'The Aqueduct',
  blurb: 'Three tiers of a giant aqueduct over a gorge: east along the bottom, back along the middle, then down the water channel on top. Fall and you start over.',
  env: 'fog',
  sky: '#96bfe6',
  fog: [160, 460],
  hemi: ['#ffffff', '#ffffff', 2.0],
  sun: [0.5, 30, 60, 20],
  outlineColor: '#1b3644',
  size: 112,
  killY: -8,
  menuCam: { path: [[-148, 10, -41], [-138, 10.3, -36.6]] },
  spawns: [3, 5.5, 8].flatMap((u) => [-3, -1, 1, 3].map((z) => [u - 84, 0, z])),
  seekerSpawn: [-78.5, 0, 0],
  race: {
    yaw: -Math.PI / 2,
    finish: { x: 91, y: 17, z: 0, w: 12.4, h: 4.5, d: 8.4 },
    route: [
      [3, 0, 0], [74, 0, 0], [82, -3, 0], [98, -3, 0], [104, 0, 0], [178, 0, 0], [178, 10, 0], [170, 10, 0],
      [140, 10, 0], [136, 8.8, 0], [128, 8.8, 0], [125, 10, 0], [114, 10, 0], [114, 10, 6.4], [90, 10, 6.4],
      [90, 10, 0], [82, 10, 0], [40, 8.8, 0], [37, 10, 0], [-14, 10, 0], [-17, 10, 0], [-17, 30, 0],
      [0, 30, 0], [10, 26, 0], [62, 26, 0], [70, 23.5, 0], [122, 23.5, 0], [168, 20.5, 0], [175, 17, 0],
    ].map(([u, y, z]) => [u - 84, y, z]),
  },

  build(k) {
    const STONE = '#d99e73', FLOOR = '#f5f5b8', GATE = '#5e4017';     // Wada 296
    const WATER = '#2dbc94', RIDE = '#bfffe6';                       // Wada 330
    const KICK = { tex: 'kick' };
    const SH = -84, W = 5;   // x = u + SH; the bridge is 10 wide (z -5..5)
    const blk = (u0, u1, y0, y1, z0, z1, col, o) => k.box((u0 + u1) / 2 + SH, y0, (z0 + z1) / 2, u1 - u0, y1 - y0, z1 - z0, col, o);
    const ramp = (u0, u1, z0, z1, lo, hi, dir, col, o) => k.ramp((u0 + u1) / 2 + SH, (z0 + z1) / 2, u1 - u0, z1 - z0, lo, hi, dir, col, o);
    // something you walk on: one yellow block (one box, so its edge is a clean ledge to pull up onto)
    const floor = (u0, u1, top, bottom, z0 = -W, z1 = W) => blk(u0, u1, bottom, top, z0, z1, FLOOR);
    // one pier line of a tier: a column on each edge of the deck and the arch shoulders across the top
    const pier = (u, y0, ceil) => {
      for (const s of [-1, 1]) blk(u - 0.6, u + 0.6, y0, ceil - 1.4, s > 0 ? 3.4 : -W, s > 0 ? W : -3.4, STONE);
      blk(u - 3, u + 3, ceil - 1.4, ceil, -W, W, STONE);
    };
    const halfArches = (ceil) => { blk(0, 3, ceil - 1.4, ceil, -W, W, STONE); blk(165, 168, ceil - 1.4, ceil, -W, W, STONE); };

    // ===================== the piers (looks: they hold the bottom deck up, out of the fog) =====================
    for (const u of [24, 48, 72, 96, 120, 144]) blk(u - 2, u + 2, -70, u === 96 ? -3.4 : -2, -W, W, STONE);

    // ===================== TIER 1 (floor 0, eastbound) =====================
    // the broken deck: three gaps, 3.5 / 4 / 4m
    floor(0, 14, 0, -2);
    floor(17.5, 30, 0, -2);
    floor(34, 40, 0, -2);
    floor(44, 74, 0, -2);
    // sluice gates (slide under: 1.1m clear) and weirs (jump)
    for (const u of [49, 64]) blk(u - 0.25, u + 0.25, 1.1, u === 49 ? 7.2 : 8.6, -W, W, GATE);
    for (const u of [55, 70]) blk(u - 0.25, u + 0.25, 0, 0.9, -W, W, GATE);
    // the spillway: a water chute down 3m, a 5m gap, and back up
    ramp(74, 82, -3.4, 3.4, -3, 0, '-x', WATER, { slick: true, base: -3.4 });
    floor(82, 88, -3, -3.4, -3.4, 3.4);
    floor(93, 98, -3, -3.4, -3.4, 3.4);
    ramp(98, 104, -3.4, 3.4, -3, 0, '+x', FLOOR, { base: -3.4 });
    // the floats: the deck's gone for two bays - two big stepping stones drift from side to side across it
    floor(104, 110, 0, -2);
    [[115.5, -1.4, 2.8], [123.5, 1.4, -2.8]].forEach(([u, z, dz], i) =>
      k.mover(u + SH, -1.6, z, 5, 1.6, 3.6, RIDE, { type: 'slide', dz, period: 3.2, phase: i * 0.3 }));
    floor(128.5, 168, 0, -2);
    // columns and arches (the spillway's and the floats' stand on lower ground)
    for (let u = 12; u < 168; u += 12) pier(u, u === 84 ? -3.4 : u === 96 ? -3 : u === 120 ? -2 : 0, 8.6);
    halfArches(8.6);
    // three revolving doors in the last doorways - one panel each, turning (it leaves a 1m slot at each
    // side: nothing can pin you against a column)
    [[132, 0], [144, 1.9], [156, 3.8]].forEach(([u, ph]) => k.mover(u + SH, 0.05, 0, 0.5, 7, 4.8, GATE, { type: 'spin', speed: 1.2, phase: ph }));

    // ===================== TIER 2 (floor 10, westbound) =====================
    // the deck (it's tier 1's ceiling), with its holes and troughs
    floor(155, 168, 10, 8.6);
    floor(140, 145, 10, 8.6);
    floor(82, 125, 10, 8.6);
    floor(0, 37, 10, 8.6);
    // kick alley: the floor's gone - zig-zag between the orange walls (or drop to tier 1)
    for (const s of [-1, 1]) blk(145, 155, 9, 13.6, s > 0 ? 1.4 : -1.9, s > 0 ? 1.9 : -1.4, STONE, KICK);
    // the siphon: a water chute down into a pipe under a dam, and up again
    ramp(136, 140, -W, W, 8.8, 10, '+x', WATER, { slick: true, base: 8.6 });
    floor(128, 136, 8.8, 8.6);
    ramp(125, 128, -W, W, 8.8, 10, '-x', FLOOR, { base: 8.6 });
    blk(129, 135, 10, 18.6, -W, W, GATE);                                   // the dam: 1.2m clear under it
    // the cornice: two bays walled up solid - out the north arch, along the ledge, back in
    blk(95, 109, 10, 18.6, -W, W, STONE);
    floor(85.5, 96.5, 10, 9, W, 7.8);
    floor(100, 104, 10, 9, W, 7.8);
    floor(107.5, 118.5, 10, 9, W, 7.8);
    // the fountains: a trough 1.2m down, split by three dams; the jets throw you over them
    floor(40, 82, 8.8, 8.6);
    ramp(37, 40, -W, W, 8.8, 10, '-x', FLOOR, { base: 8.6 });
    for (const u of [48, 60, 72]) blk(u - 1, u + 1, 8.8, 12.8, -3.4, 3.4, GATE);
    for (const u of [77, 65, 53]) k.pad(u + SH, 8.8, 0, 2.6, 2.6, 16, { color: WATER });
    // the baffles: walls from alternate sides - weave through
    [[33, 1], [28.5, -1], [19, 1], [15.5, -1]].forEach(([u, s]) => blk(u - 0.3, u + 0.3, 10, 15, s > 0 ? -1.6 : -W, s > 0 ? W : 1.6, GATE));
    // columns and arches
    for (const u of [12, 24, 36, 48, 60, 72, 84, 120, 144, 156]) pier(u, u >= 48 && u <= 72 ? 8.8 : 10, 18.6);
    halfArches(18.6);
    // the roof
    blk(0, 168, 18.6, 20, -W, W, STONE);

    // ===================== TIER 3 (the channel on top, eastbound) =====================
    // a pool: a block whose top is the channel floor, with a low wall along each side
    const pool = (u0, u1, top) => {
      floor(u0, u1, top, 20);
      for (const s of [-1, 1]) blk(u0, u1, top, top + 1, s > 0 ? 4.4 : -W, s > 0 ? W : -4.4, STONE);
    };
    const chute = (u0, u1, hi, lo) => {
      ramp(u0, u1, -4.4, 4.4, lo, hi, '-x', WATER, { slick: true, base: 20 });
      for (const s of [-1, 1]) ramp(u0, u1, s > 0 ? 4.4 : -W, s > 0 ? W : -4.4, lo + 1, hi + 1, '-x', STONE, { base: 20 });
    };
    // a sluice beam across the channel (1.1m clear: slide under), on posts standing on the side walls
    const beam = (u, top) => {
      blk(u - 0.5, u + 0.5, top + 1.1, top + 4.6, -4.4, 4.4, GATE);
      for (const s of [-1, 1]) blk(u - 0.5, u + 0.5, top + 1, top + 4.6, s > 0 ? 4.4 : -W, s > 0 ? W : -4.4, STONE);
    };
    chute(0, 10, 30, 26);
    pool(10, 30, 26);
    beam(17, 26);
    blk(23.75, 24.25, 26, 26.9, -4.4, 4.4, GATE);                           // weir
    floor(30, 35, 23, 20);                                                  // slot (3m down)
    pool(35, 62, 26);
    k.mover(43 + SH, 26, 0, 7, 0.6, 0.45, GATE, { type: 'spin', speed: 1.8 });              // sweepers (0.9m clear
    k.mover(53 + SH, 26, 0, 7, 0.6, 0.45, GATE, { type: 'spin', speed: -2.2, phase: 1 });   //  of the side walls)
    chute(62, 70, 26, 23.5);
    pool(70, 78, 23.5);
    floor(78, 95, 20.5, 20);                                                // the pit, with two stepping posts
    [[83, -1.2], [90, 1.2]].forEach(([u, z]) => floor(u - 2, u + 2, 23.5, 20.5, z - 1.5, z + 1.5));
    pool(95, 100, 23.5);
    floor(100, 105, 20.5, 20);                                              // slot
    pool(105, 122, 23.5);
    beam(114, 23.5);
    chute(122, 146, 23.5, 22);                                              // the last chute, broken once -
    chute(151, 168, 21.6, 20.5);                                            // - and the leap

    // ===================== the west tower (the wheel) =====================
    blk(-14, 0, -70, 9.6, -W, W, STONE);
    blk(-14, 0, 9.6, 10, -2, 2, FLOOR);                                     // tunnel through at tier 2
    for (const s of [-1, 1]) blk(-13.95, 0, 9.6, 29.6, s > 0 ? 2 : -W, s > 0 ? W : -2, STONE);
    blk(-13.95, 0, 14, 29.6, -2, 2, STONE);
    blk(-14, 0, 29.6, 30, -W, W, FLOOR);                                    // the roof (30)
    for (const s of [-1, 1]) blk(-14, 0, 30, 31, s > 0 ? 4.4 : -W, s > 0 ? W : -4.4, STONE);
    // a ledge outside the tunnel, and a basin under the wheel to catch a missed step
    floor(-14.95, -14, 10, 5, -11, 11);                                    // (as wide as the basin: climb out at its ends,
    for (const s of [-1, 1]) blk(-14, -13.4, 10, 11.2, s > 0 ? W : -11, s > 0 ? 11 : -W, STONE);   //  where the buckets pass high)
    floor(-26, -14.95, 7.4, 5, -11, 11);
    blk(-26, -25.4, 7.4, 8.4, -11, 11, STONE);
    for (const s of [-1, 1]) blk(-25.4, -14.95, 7.4, 8.4, s > 0 ? 10.4 : -11, s > 0 ? 11 : -10.4, STONE);
    // the wheel: twelve buckets ride a 10m circle from the ledge (10) up to the roof (30). Along the
    // bottom they pass the ledge almost end to end, so stepping on is easy
    const R = 10, SP = 0.65, N = 12, WU = -19.3;
    for (let i = 0; i < N; i++) {
      const o = { type: 'orbit', axis: 'x', radius: R, speed: SP, phase: i * 2 * Math.PI / N };
      k.mover(SH - 17, 19.4, 0, 4, 0.6, 4.4, RIDE, o);                    // a bucket: its floor...
      k.mover(SH - 18.85, 19.4, 0, 0.3, 1.8, 4.4, RIDE, o);               // ...and its back (so you can't run off)
    }
    k.wheel(SH + WU, 19.7, 0, 'x', SP, 0, (add) => {
      add(0, 0, 0, 1.2, 1.8, 1.8, GATE);                                                // hub
      for (let i = 0; i < N; i++) {
        const a = i * 2 * Math.PI / N;
        if (i % 2 === 0) add(0, 0, R / 2, 0.5, 0.5, R, GATE, a);                         // spoke
        add(0, 0, R * Math.cos(Math.PI / N), 0.6, 2 * R * Math.sin(Math.PI / N), 0.6, GATE, a + Math.PI / N);   // rim
      }
    });
    k.deco(SH + (WU - 14) / 2, 19.3, 0, -14 - WU, 0.8, 0.8, GATE, { tex: 'none' });      // the axle into the tower

    // ===================== the east tower (the shaft, and the finish basin on its roof) =====================
    blk(168, 182, -70, -0.4, -W, W, STONE);
    blk(168.8, 181.2, -0.4, 0, -4.2, 4.2, FLOOR);
    blk(168, 168.8, -0.4, 0, -2, 2, FLOOR);                                 // door sill
    for (const s of [-1, 1]) blk(168, 168.8, -0.4, 20, s > 0 ? 2 : -W, s > 0 ? W : -2, STONE);
    blk(168, 168.8, 4, 10, -2, 2, STONE);                                   // between the two doors
    blk(168, 168.8, 14, 20, -2, 2, STONE);
    blk(181.2, 182, -0.4, 19.5, -W, W, STONE);
    for (const s of [-1, 1]) blk(168.8, 181.2, -0.4, 19.5, s > 0 ? 4.2 : -W, s > 0 ? W : -4.2, STONE);
    // inside: a landing at tier 2 over the hall, and the kick shaft beside it
    floor(168.8, 175, 10, 9, -4.2, 4.2);
    for (const s of [-1, 1]) {
      floor(175, 181.2, 10, 0, s > 0 ? 1.9 : -4.2, s > 0 ? 4.2 : -1.9);
      blk(175, 181.2, 0, 10.5, s > 0 ? 1.4 : -1.9, s > 0 ? 1.9 : -1.4, STONE, KICK);
    }
    // the roof: the finish basin
    floor(168.8, 181.2, 17, 16.4, -4.2, 4.2);
  },
});

;
/* ==== js/maps/lighthouse.js ==== */
// LIGHTHOUSE ROCKS - a cluster of rocky islets round a tall red-and-white lighthouse, over clear
// blue water. About 47m across, and no two sides alike, so you can tell where you are:
//   middle  the Light Rock (pale stone, 0), the lighthouse standing a little north-west of the
//           map's middle on it: run round its foot
//   N       the SHELF: a big low shelf at 2 (pale stone) right against the Light Rock - just mantle
//           up - with a tor at 4.4 and boulders on it; its east end rises (the Knuckle, 4)
//   NE      the SEA STACK (8): a wide timber bridge from the Knuckle into a bent sea cave through it,
//           stairs up its side, a step at 6; the cave comes out south onto a narrow bridge
//   E       the ARCH islet (4): a broken rock arch (run under it, climb its legs, hop the gap at the
//           top), a step at 6 up to the stack, a timber ramp down a spit to the Light Rock
//   SE      open water (a lagoon), skirted by stepping stones down to the reef
//   S       the LONG REEF: a low ridge of stones at 1.4-2.6, a causeway back to the Light Rock
//   SW      the NEEDLE: a turf islet at 4 with a tall narrow stack (8) standing out of the sea at
//           its south end, a step at 6 beside it
//   W       the TIMBER side: a turf islet at 4 joined by bridges to the Needle islet and to the West
//           Tor (4, on the end of the shelf), and by stairs down a spit to the Light Rock
// No invisible walls round the edge: the sea is the edge - jump off and you're sent back like a fall.
// THE LIGHTHOUSE is looks only: nobody goes up it. Its foot is walled in invisibly, band by band, to
// exactly its own outline (nothing to kick, and too tall to grab: the first ledge is at 5).
// The rocks: straight blocks plus 45-degree blocks on some corners, so outlines are chamfered. Plain
// grey faces, no detail. Round every rock the water goes pale (shallows) with a white line of foam.
// Every climb is a jump + mantle (<= 2.6m) or stairs / a ramp - never a 4m wall.
// Look: minimal, like Container Yard - a light sky, form-giving light (dark hemi ground), big plain
// shapes in few colors: blue water, grey rock, green turf / pale stone tops, timber, the
// red-and-white tower; yellow edge lines on the bridges, dark outlines.
defineMap({
  id: 'lighthouse',
  accent: ['#a8322d', '#13609a'],
  name: 'Lighthouse Rocks',
  blurb: 'Rocky islets round a tall red-and-white lighthouse, every side different: a low shelf, a sea stack with a cave, a broken arch, a long reef, a needle, timber bridges.',
  env: 'sky',
  sky: '#a9d6ff',
  fog: [300, 3000],
  hemi: ['#eaf4ff', '#5a6470', 0.9],
  sun: [1.0, 30, 55, 20],
  sea: -8,                          // (the engine's own sea, hidden under ours)
  size: 32,
  killY: -4,
  outlineColor: '#1f2a36',
  menuCam: { path: [[-6, 11, 46], [-5, 10, 39]] },
  spawns: [
    [-9.5, 0, -5.5], [-8.5, 0, 3.5],
    [-7, 2, -17.5], [-12, 2, -13],
    [3, 4, -19], [14, 4, -18], [17, 8, -22],
    [16, 4, -6], [21, 4, 0.5],
    [11, 2.8, 9.8], [1, 2.2, 17.2], [-6.3, 1.4, 17.5],
    [-19.5, 4, 15], [-15, 4, 11.5],
    [-20, 4, -2], [-18, 4, -13.5],
  ],
  seekerSpawn: [1.5, 0, 0.5],
  centerSpot: [1.5, 0, 0.5],

  build(k) {
    const DEEP = '#13609a', SHALLOW = '#2f9cc0', FOAM = '#f2fbff';              // water
    const ROCK = '#6b6862';                                                     // rock: one plain grey
    const STONE = ROCK, TURF = '#4a8a3c';                                         // tops: plain rock low down, turf from 4 up
    const WOOD = '#a8682f', PILE = '#4a2f1a', EDGE = '#ffd23f';                  // timber, edge lines
    const WHITE = '#e8e6df', RED = '#a8322d', LAMP = '#ffc93a', DARK = '#2b2f3a';  // the lighthouse
    const NO = { tex: 'none' };
    const D45 = Math.PI / 4;
    const TX = -4, TZ = -2;                          // the lighthouse

    // ===== rock: solid pieces (straight blocks, or 45-degree "diamonds" that chamfer corners), each
    // remembered so its shallows and foam can be laid round it afterwards =====
    const pieces = [];
    // (8m tops: a thinner skin, so it stays well clear of the cave roof's underside at 7.6)
    const piece = (cx, cz, w, d, rot, y0, y1, cap, capT = y1 > 6 ? 0.25 : 0.38) => {
      // one solid block of rock; the colored top is a skin over its last 40cm (looks only)
      // (the turned pieces aren't outlined: their edges would cross the flat tops)
      const ro = rot ? { rot, outline: false } : {};
      k.box(cx, y0, cz, w, y1 - y0, d, ROCK, ro);
      if (cap) k.deco(cx, y1 - capT, cz, w + 0.04, capT + 0.01, d + 0.04, cap, Object.assign({ tex: 'none', outline: false }, ro));   // (the rock's own outline edges it)
      pieces.push({ cx, cz, w, d, rot, y0 });
    };
    // a block by its extents (from the sea floor at -6 unless y0 says otherwise)
    const R = (x0, x1, z0, z1, y1, cap, y0 = -6) => piece((x0 + x1) / 2, (z0 + z1) / 2, x1 - x0, z1 - z0, 0, y0, y1, cap);
    // a diamond: a square turned 45 degrees round (x, z), reaching h out along x and z
    const Dm = (x, z, h, y1, cap, y0 = -6) => piece(x, z, h * Math.SQRT2, h * Math.SQRT2, D45, y0, y1, cap);
    // a plain box by its extents (timber, roofs)
    const B = (x0, x1, z0, z1, y0, y1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    // a timber bridge at 4 (x0..x1 by z0..z1), with yellow edge lines along its long sides and piles
    const bridge = (x0, x1, z0, z1, piles) => {
      B(x0, x1, z0, z1, 3.6, 4, WOOD);
      const G = Object.assign({ ghost: true }, NO);
      if (x1 - x0 < z1 - z0) for (const x of [x0, x1 - 0.2]) B(x, x + 0.2, z0, z1, 4, 4.02, EDGE, G);
      else for (const z of [z0, z1 - 0.2]) B(x0, x1, z, z + 0.2, 4, 4.02, EDGE, G);
      for (const [x, z] of piles) B(x - 0.2, x + 0.2, z - 0.2, z + 0.2, -2.6, 3.6, PILE, G);
    };

    // ===== the Light Rock (0): a chamfered block 14 x 14, the lighthouse on its north-west part =====
    R(-11, 3, -7, 3, 0, STONE);
    R(-9, 1, -9, 5, 0, STONE);
    for (const [x, z] of [[-9, -7], [1, -7], [-9, 3], [1, 3]]) Dm(x, z, 2, 0, STONE);
    Dm(1.8, -6.2, 0.8, 1, STONE, 0);                 // boulders to circle (two, not evenly placed)
    Dm(-10, 0.5, 0.8, 1, STONE, 0);
    Dm(-2, 3.8, 0.8, 1, STONE, 0);
    Dm(-6.5, -7.8, 0.8, 1, STONE, 0);
    // (nothing taller than 1m near the lighthouse: from there its first ledge, at 5, is out of reach)

    // ===== N: the Shelf (2) - big, low, right against the Light Rock =====
    R(-15, 0, -21, -11, 2, STONE);
    Dm(-15, -21, 2, 2, STONE);                       // its chamfered north-west corner
    R(-8, -3.5, -11, -8.6, 2, STONE);                // where it meets the Light Rock: just mantle up
    Dm(-12.5, -8, 1.3, 1, STONE);                    // a stepping stone at 1 off its south-west
    R(-12, -9, -20, -17, 4.4, TURF, 2);              // a tor (2.4 up)
    Dm(-5, -14, 1, 3, STONE, 2);                     // boulders to vault
    Dm(-3, -19, 1, 3, STONE, 2);
    R(-2.5, 0, -13.5, -11, 4.4, TURF, 2);            // a second tor, by the Knuckle
    // the Knuckle: the shelf's east end, rising to 4
    R(0, 6, -23, -15, 4, TURF);
    Dm(3, -15, 2, 4, TURF);
    // the Teeth: a ridge stepping off the Knuckle's nose (6, then 3.6) toward the east spit
    R(4.5, 8, -15, -9, 6, TURF);
    R(5.5, 9, -9, -5.5, 3.6, STONE);

    // ===== NE: the Sea Stack (8): x 12..24, z -24..-12, both outer corners cut off, with a bent sea
    // cave through it at 4: in from the west (x = 12, z -20..-16), round the bend, out south (z = -12,
    // x 16..20) =====
    R(12, 21.5, -24, -20, 8, TURF);                  // the walls round the cave, sea to top
    R(20, 24, -21.5, -12, 8, TURF);
    R(12, 16, -16, -14, 8, TURF);
    R(14, 16, -14, -12, 8, TURF);
    Dm(21.5, -21.5, 2.5, 8, TURF);
    Dm(14, -14, 2, 8, TURF);
    R(12, 20, -20, -16, 4, STONE);                   // under the cave: its floor
    R(16, 20, -16, -12, 4, STONE);
    B(12, 20, -20, -16, 7.6, 8, ROCK);               // the roof over the cave (turf on top only)
    B(16, 20, -16, -12, 7.6, 8, ROCK);
    B(12, 20, -20, -16, 8, 8.01, TURF, { ghost: true, tex: 'none', outline: false });
    B(16, 20, -16, -12, 8, 8.01, TURF, { ghost: true, tex: 'none', outline: false });
    Dm(16.5, -17.5, 1, 9, TURF, 8);                  // a boulder on top (no tor up here: a perch over everything was a trap)
    // the Knuckle -> the stack: a wide timber bridge into the cave, stairs up the stack beside it
    B(6, 12, -24, -16, 3.6, 4, WOOD);
    B(6, 12, -16.2, -16, 4, 4.02, EDGE, Object.assign({ ghost: true }, NO));
    B(6, 12, -24, -23.8, 4, 4.02, EDGE, Object.assign({ ghost: true }, NO));
    for (const z of [-23.4, -16.6]) B(8.8, 9.2, z - 0.2, z + 0.2, -2.6, 3.6, PILE, Object.assign({ ghost: true }, NO));
    stairs(k, 6, -22, '+x', 4, 4, 8, WOOD, { run: 0.6 });
    R(9.6, 12, -15.8, -13.4, 6, TURF);               // a step at 6 against the stack, beside the bridge
    // out of the cave: a narrow timber bridge south to the Arch islet
    bridge(16.6, 19.4, -12, -8, [[18, -10]]);

    // ===== E: the Arch islet (4) =====
    R(14, 23, -8, 2, 4, TURF);
    Dm(14, 2, 1.5, 4, TURF);
    Dm(23, 2, 1.5, 4, TURF);
    R(20.5, 23.5, -12, -8, 6, TURF);                 // a step at 6 up the stack's south face
    // the broken arch: two legs (2.4 up), their tops reaching toward each other with a gap between;
    // 2m clear underneath to run through
    R(15, 17, -4, -1.5, 6.4, TURF, 4);
    R(20, 22, -4, -1.5, 6.4, TURF, 4);
    R(17, 18.1, -4, -1.5, 6.4, TURF, 6.0);
    R(19.1, 20, -4, -1.5, 6.4, TURF, 6.0);
    Dm(18.5, -6, 0.9, 5, TURF, 4);                   // a boulder to vault
    // down to the Light Rock: a rock spit with a timber ramp, and a stepping stone at 2 beside it
    R(3, 14, -3, 1, 0, STONE);
    k.ramp(11, -1, 6, 4, 0, 4, '+x', WOOD);
    R(9, 12, 1.4, 4.4, 2, STONE);
    R(5.5, 9, 3.5, 8, 4.4, TURF);                    // the Thumb: a lone rock out in the lagoon

    // ===== SE: stepping stones round the lagoon, from the Arch islet down to the reef =====
    R(15, 19, 2, 5.5, 3, STONE);
    R(12.5, 16, 5, 8.5, 2.2, STONE);
    R(9, 13, 8, 11.5, 2.8, STONE);
    R(4, 9.5, 11.5, 16, 1.6, STONE);

    // ===== S: the Long Reef - a low ridge at 1.4-2.6, and a causeway back to the Light Rock =====
    R(-2, 5, 15.5, 19, 2.2, STONE);
    R(-7, -2, 16, 19.5, 1.4, STONE);
    R(-12, -7, 15, 18.5, 2.6, STONE);
    Dm(-9.5, 16.7, 0.8, 3.6, STONE, 2.6);            // a boulder on the reef
    R(-5.5, -3, 16.5, 19, 3.8, TURF, 1.4);           // a tor on its low middle (2.4 up)
    R(-4, -1, 5, 12, 1, STONE);                      // the causeway: 0 -> 1 -> 1.8 -> the reef
    R(-3.5, -0.5, 12, 15.5, 1.8, STONE);

    // ===== SW: the Needle - a turf islet at 4, a tall narrow stack (8) out of the sea at its south end =====
    R(-22, -13, 10, 19, 4, TURF);
    Dm(-22, 10, 1.5, 4, TURF);
    Dm(-13, 10, 1.5, 4, TURF);
    R(-20, -16, 19, 23, 8, TURF);                    // the Needle
    R(-16, -13.6, 17, 21, 6, TURF);                  // steps at 6 either side of it
    R(-22.4, -20, 17.5, 21, 6, TURF);
    Dm(-17.5, 12.5, 0.9, 5, TURF, 4);                // a boulder to vault

    // ===== W: the timber side - a turf islet at 4, bridges north and south, stairs to the Light Rock =====
    R(-23, -17, -5, 3, 4, TURF);
    Dm(-23, -5, 1.5, 4, TURF);
    Dm(-23, 3, 1.5, 4, TURF);
    Dm(-20, 0.8, 0.9, 5, TURF, 4);                   // a boulder to vault
    R(-21, -15, -16, -11, 4, TURF);                  // the West Tor: the shelf's west end, at 4
    bridge(-21, -18, -11, -5, [[-19.5, -8]]);        // W islet -> the West Tor
    bridge(-21, -18, 3, 10, [[-19.5, 6.5]]);         // W islet -> the Needle islet
    R(-17, -11, -3, 1, 0, STONE);                    // a spit from the Light Rock, stairs up it
    stairs(k, -11, -1, '-x', 4, 0, 4, WOOD, { run: 0.6 });

    // ===== the water: deep blue, pale shallows round every rock, a clean line of foam =====
    k.deco(0, -2.1, 0, 1000, 0.1, 1000, DEEP, { tex: 'none', outline: false });
    for (const p of pieces) {
      if (p.y0 > -2) continue;
      const o = () => Object.assign({ tex: 'none', outline: false, noShadow: true }, p.rot ? { rot: p.rot } : {});
      k.deco(p.cx, -2.0, p.cz, p.w + 3.2, 0.02, p.d + 3.2, SHALLOW, o());
      k.deco(p.cx, -1.98, p.cz, p.w + 1.0, 0.02, p.d + 1.0, FOAM, o());
    }

    // ===== THE LIGHTHOUSE - its walls are solid, so you can wall-kick off it (nothing climbs it: it
    // stands alone, and above the gallery an invisible wall keeps anyone off the top) =====
    const oct = (y, r, h, col, y0 = y, solid = false) => {      // an octagon: two crossed boxes
      if (solid) {
        k.box(TX, y0, TZ, 2 * r * 0.83, y + h - y0, 2 * r, col, NO);
        k.box(TX, y0, TZ, 2 * r, y + h - y0 - 0.01, 2 * r * 0.83, col, NO);
        return;
      }
      k.deco(TX, y, TZ, 2 * r * 0.83, h, 2 * r, col, NO);
      k.deco(TX, y, TZ, 2 * r, h - 0.01, 2 * r * 0.83, col, NO);
      k.wall(TX, y0, TZ, 2 * r * 0.83, y + h - y0, 2 * r);
      k.wall(TX, y0, TZ, 2 * r, y + h - y0, 2 * r * 0.83);
    };
    // the tower, tapering a little, in broad white and red bands (the lowest reaches below the rock)
    const bands = [[0, 5, 3.0, WHITE], [5, 8.5, 2.85, RED], [8.5, 12.5, 2.7, WHITE], [12.5, 16, 2.55, RED], [16, 19, 2.4, WHITE]];
    for (const [y0, y1, r, col] of bands) oct(y0, r, y1 - y0, col, y0 === 0 ? -2 : y0, true);
    k.wall(TX, 19, TZ, 6.4, 40, 6.4);                                  // (nobody stands on the gallery or the lamp)
    oct(19, 3.0, 0.5, DARK);                                           // the gallery
    oct(19.5, 1.8, 2.8, LAMP);                                         // the lantern
    oct(22.3, 2.2, 0.6, RED);                                          // the cap
    oct(22.9, 1.2, 1.0, RED);
    k.deco(TX, 23.9, TZ, 0.3, 1.2, 0.3, DARK, NO);
  },
});

;
/* ==== js/maps/dam.js ==== */
// THE DAM - a pale concrete dam wedged into a dark canyon, painted in a few broad fields of color.
// THE RULE: every floor sits at 0, 4, 8 or 12 and every footprint snaps to a 2m grid
// (48 x 46m in all). Between them stand 2m concrete blocks, 1.2 tall (vault them) or 2.4 (a step:
// jump + mantle onto one, then hop the last 1.6 onto the 4m level it stands against).
// Light against dark: pale concrete and pale tops against dark rock, a black road and deep blue water.
//   the road   along the crest (12), black with a pale center line. It comes out of a tunnel in the
//              canyon wall at each end - closed: a striped steel shutter and road barriers across
//              each tunnel mouth - the map's two ends
//   the dam    x -24..24, z -14..-6. A parapet along its upstream side: the reservoir lies far below
//              it, out of bounds. Two galleries run through the dam: G0 (0) with three portals out to the
//              valley floor, and G4 (4) that opens on two balconies on the face and turns south through
//              both abutments, out onto the terraces
//   spillway   down the middle of the face, a water slide from the crest (12) to the valley floor,
//              on piers - run under it - and on under the footbridge
//   the basin  the valley floor, set with baffle blocks: a sill of two blocks and a pipe (slide under
//              it) either side of the chute, steps, cover, vaults
//   abutments  either side of the valley: roofs at 8, terraces at 4 to the south, the footbridge (4)
//              across between the terraces along the south end, its parapet closing the valley
// Enclosed all round: canyon rock east and west, the crest parapet north, the bridge parapet south.
// Ways up:  0 -> 4   both balcony stairs, the W terrace ramp, the E terrace stairs, and the 2.4
//                    blocks against both balconies, both abutment doors and the footbridge
//           4 -> 8   the stairs on both terraces;  0 -> 8  the orange kick wall off the E abutment
//           8 -> 12  the stairs on both abutment roofs;  4 -> 12  the orange chimney on the W balcony,
//                    the pad on the E balcony
// Down fast: the spillway (12 -> 0), the abutment doors (4 -> 0), any edge.
// Colors: three hues that sit together - warm cream concrete, sandstone canyon, deep teal water
// (and teal-painted steel: balconies, footbridge, tunnel portals) - on neutral grey ground and a dark
// asphalt road, with one accent: warm yellow for every edge and marking. Light gives every block a
// bright top and a darker side. Looks only (no collision): the crest's coping and lamps, the
// spillway's gate piers, the tunnel surrounds, the canyon's broken skyline and strata.
defineMap({
  id: 'dam',
  accent: ['#2f6f7e', '#f2c14e'],
  name: 'The Dam',
  blurb: 'A concrete dam in a dark canyon: run the road along its crest, the galleries inside it, and ride the spillway down.',
  env: 'fog',
  sky: '#bfe0f2',
  fog: [300, 3000],                 // (a crisp horizon)
  hemi: ['#f2f7ff', '#5a5650', 0.9],
  sun: [1.0, 25, 55, 35],
  outlineColor: '#22262c',
  size: 32,
  killY: -4,
  menuCam: { path: [[-14, 18, 40], [-8, 15, 30]] },
  spawns: [
    [-12, 0, 8], [12, 0, 8], [-7, 0, 15], [7, 0, 15],
    [-6, 0, -10], [6, 0, -10],
    [-8, 4, -3], [10, 4, -2],
    [0, 4, -10],
    [-20, 4, 19], [20, 4, 19], [0, 4, 20.5],
    [-20, 8, 6], [20, 8, 6],
    [-12, 12, -9], [12, 12, -9],
  ],
  seekerSpawn: [0, 0, 14],
  centerSpot: [0, 0, 16],

  build(k) {
    const CON = '#e2dac6', CON2 = '#cbc1a9', ROCK = '#b8764f', ROCK2 = '#9c6040';
    // water like Lighthouse Rocks': clear blue, pale shallows along every wall, one white line of foam
    const WATER = '#3294ce', SHALLOW = '#5fc0d8', FOAM = '#ffffff';
    const SLIDE = SHALLOW, ROAD = '#34383e', FLOOR = '#8c8880', STEEL = '#2f5f6b', EDGE = '#f2c14e';
    const DARK = '#15181e', TOP = CON;
    const D = (x0, x1, z0, z1, y0, y1, col, o = { tex: 'none' }) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const BLACK = DARK, INSIDE = '#3d434d', ROOF = '#20242b';
    const FLAT = { tex: 'none', outline: false };
    // a box by its extents
    const B = (x0, x1, z0, z1, y0, y1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    // a parapet (with a yellow cap) along x from x0 to x1, z0..z1, standing on `y`; nothing gets over it
    const parapet = (x0, x1, z0, z1, y0, y) => {
      B(x0, x1, z0, z1, y0, y + 1.2, CON);
      B(x0, x1, z0, z1, y + 1.2, y + 1.4, EDGE);
      k.wall((x0 + x1) / 2, y + 1.4, (z0 + z1) / 2, x1 - x0, 60, z1 - z0);
    };

    // ===== the valley floor, the reservoir and the river (far below, out of bounds) =====
    B(-24, 24, -14, 22.4, -2, 0, FLOOR);                               // valley floor (0)
    k.deco(0, -2.2, -400, 48, 0.1, 772, WATER, FLAT);                  // the reservoir
    k.deco(0, -2.2, 400, 48, 0.1, 755, WATER, FLAT);                   // the river
    // where the water meets the dam, the canyon walls, the intake tower and the valley floor's end:
    // a band of shallows (2cm up) and a line of foam (2cm more) - looks only
    const SURF = { tex: 'none', outline: false, noShadow: true };
    const shore = (x0, x1, z0, z1, col, y) => k.deco((x0 + x1) / 2, y, (z0 + z1) / 2, x1 - x0, 0.02, z1 - z0, col, SURF);
    const lap = (wide, thin) => { shore(...wide, SHALLOW, -2.1); shore(...thin, FOAM, -2.08); };
    lap([-24, 24, -17.2, -15.6], [-24, 24, -16.1, -15.6]);          // the dam's upstream face
    lap([-24, 24, 22.4, 24], [-24, 24, 22.4, 22.9]);                // the river, under the bridge end
    for (const s of [-1, 1]) {                                          // the canyon walls
      const X = (a, b) => s > 0 ? [-b, -a] : [a, b];
      lap([...X(-24, -22.4), -786, -15.6], [...X(-24, -23.5), -786, -15.6]);
      lap([...X(-24, -22.4), 22.4, 777.5], [...X(-24, -23.5), 22.4, 777.5]);
    }
    lap([-5.6, 5.6, -42.6, -31.4], [-4.5, 4.5, -41.5, -32.5]);      // the intake tower's plinth
    // the south end: the bridge parapet, down to the valley floor
    parapet(-24, 24, 22, 22.4, 0, 4);

    // ===== the canyon: dark rock east and west, the road tunnels through it at 12 =====
    for (const s of [-1, 1]) {
      const X = (a, b) => s > 0 ? [-b, -a] : [a, b];                  // mirror an x range
      const R = (a, b, z0, z1, y0, y1, col, o) => { const [p, q] = X(a, b); B(p, q, z0, z1, y0, y1, col, o); };
      R(-30, -24, -800, -14, -4, 18, ROCK);                           // inner tier, either side of the tunnel
      R(-30, -24, -6, 800, -4, 18, ROCK);
      R(-30, -24, -14, -6, -4, 11.6, ROCK);                           // under the road
      R(-30, -24, -14, -6, 16.4, 18, ROCK);                           // over the tunnel
      R(-46, -30, -800, 800, -4, 26, ROCK2);                          // outer tier
      k.wall(s * 35, 18, 0, 22, 100, 1600);                           // nobody stands on the canyon
      // the tunnel: black lining, blocked 4m in; a pale concrete portal round its mouth
      R(-28, -24, -14, -13.6, 12, 16.4, BLACK);
      R(-28, -24, -6.4, -6, 12, 16.4, BLACK);
      R(-28, -24, -13.6, -6.4, 16, 16.4, BLACK);
      R(-30, -28, -14, -6, 12, 16, BLACK);
      R(-24.4, -24, -14.4, -13.6, 12, 16.4, STEEL);
      R(-24.4, -24, -6.4, -5.6, 12, 16.4, STEEL);
      R(-24.4, -24, -14.4, -5.6, 16.4, 17.4, STEEL);
      const RD = (a, b, z0, z1, y0, y1, col, o) => { const [p, q] = X(a, b); D(p, q, z0, z1, y0, y1, col, o); };
      // the road is closed here: a steel shutter just inside the portal with a striped warning board
      // across it, and a row of concrete road barriers at its foot (solid: the crest ends at a gate,
      // not in an empty dead end)
      R(-25, -24.6, -13.6, -6.4, 12, 16, STEEL);
      for (let i = 0; i < 12; i++) RD(-24.6, -24.58, -13.6 + i * 0.6, -13 + i * 0.6, 14.2, 14.8, i % 2 ? DARK : EDGE, FLAT);
      for (const [z0, z1] of [[-13.5, -11.2], [-11.15, -8.85], [-8.8, -6.5]]) {
        R(-24.6, -23.8, z0, z1, 12, 12.3, CON);                       // a jersey barrier: a wide foot...
        R(-24.45, -23.95, z0, z1, 12.3, 12.9, CON);                   // ...and a narrower wall on it
      }
      // ...set in a deep concrete surround with a yellow clearance band (looks)
      RD(-24, -23.2, -15.2, -14, 11.6, 18.4, CON2);
      RD(-24, -23.2, -6, -4.8, 11.6, 18.4, CON2);
      RD(-24, -23.2, -15.2, -4.8, 17.4, 18.4, CON2);
      RD(-24, -23.98, -13.6, -6.4, 16.5, 16.8, EDGE);
      // the canyon's broken skyline and a darker stratum (looks; all out of reach)
      for (const [z0, z1, h] of [[-120, -62, 3], [-62, -30, 1.5], [-30, -16, 4.5], [-4, 12, 2.5], [12, 36, 5], [36, 90, 2]]) RD(-30, -25.5, z0, z1, 18, 18 + h, ROCK);
      for (const [z0, z1, h] of [[-200, -70, 5], [-70, -10, 2.5], [-10, 30, 6], [30, 200, 3]]) RD(-46, -31.5, z0, z1, 26, 26 + h, ROCK2);
      RD(-24.02, -24, -800, -15.2, 14.2, 14.8, ROCK2);
      RD(-24.02, -24, -4.8, 800, 14.2, 14.8, ROCK2);
      RD(-30, -29.98, -800, 800, 22.4, 23, ROCK);
    }

    // ===== THE DAM: x -24..24, z -14..-6 =====
    B(-24, 24, -14, -12, -4, 11.6, CON);                               // upstream wall
    B(-24, 24, -12, -6, 8, 11.6, CON);                                 // the top, over G4
    B(-28, 28, -14, -6, 11.6, 12, ROAD);                               // the road (12), into the tunnels
    for (let x = -26; x <= 26; x += 4) k.deco(x, 12, -10, 2, 0.02, 0.3, CON, FLAT);   // center line
    // the crest's coping, just proud of the face (gaps for the spillway and the kick chimney)
    for (const [a, b] of [[-16, -14], [-10.2, -3.8], [3.8, 16]]) D(a, b, -6, -5.7, 11.1, 11.98, CON2);
    // lamps along the parapet, every 8m (looks: the parapet is out of bounds above its cap)
    for (let x = -20; x <= 20; x += 8) {
      D(x - 0.09, x + 0.09, -13.89, -13.71, 13.4, 15.6, STEEL);
      D(x - 0.06, x + 0.06, -13.71, -13.1, 15.48, 15.6, STEEL);
      D(x - 0.2, x + 0.2, -13.3, -12.9, 15.3, 15.48, '#fff1c4', { tex: 'none', emissive: '#ffe7a0' });
    }
    // the spillway's gate piers either side of the chute, a yellow band at the lip
    for (const s of [-1, 1]) D(s * 3.04 - (s > 0 ? 0 : 0.6), s * 3.04 + (s > 0 ? 0.6 : 0), -6, -4.2, 4, 12.8, CON2);
    D(-3, 3, -6, -5.98, 11.4, 11.98, EDGE);
    // the upstream face steps out under the water (seen from the crest)
    D(-24, 24, -15.6, -14, -3.9, 0.5, CON2);
    parapet(-24, 24, -14, -13.6, 12, 12);                              // the reservoir side
    B(-24, 24, -12, -6, 3.6, 4, TOP);                                  // G4's floor
    // G0 (0): x -16..16, portals to the valley at x -16..-12, -2..2, 12..16
    for (const [a, b] of [[-24, -16], [-12, -2], [2, 12], [16, 24]]) B(a, b, -8, -6, 0, 3.6, CON);
    for (const s of [-1, 1]) B(s > 0 ? 16 : -24, s > 0 ? 24 : -16, -12, -8, 0, 3.6, CON);
    // G4 (4): x -22..22, openings to the abutment tunnels (+-18..22) and the balconies (+-5..9)
    for (const [a, b] of [[-24, -22], [-18, -9], [-5, 5], [9, 18], [22, 24]]) B(a, b, -8, -6, 4, 8, CON);
    for (const s of [-1, 1]) B(s > 0 ? 22 : -24, s > 0 ? 24 : -22, -12, -8, 4, 8, CON);

    // ===== inside: dark walls and ceilings, a bright floor with a yellow line down the middle, so the
    // way through (and the daylight at the exits) reads at a glance. Panels 2cm off the faces (looks) =====
    const P = (x0, x1, z0, z1, y0, y1, col) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, FLAT);
    const IN = 0.02;
    // G0
    P(-16, 16, -12, -8, 3.6 - IN, 3.6, ROOF);                        // ceiling
    P(-16, 16, -12, -12 + IN, 0, 3.6 - IN, INSIDE);                    // back wall
    for (const [a, b] of [[-12, -2], [2, 12]]) P(a, b, -8 - IN, -8, 0, 3.6 - IN, INSIDE);
    for (const s of [-1, 1]) P(s * 16 - (s > 0 ? IN : 0), s * 16 + (s > 0 ? 0 : IN), -12, -8, 0, 3.6 - IN, INSIDE);
    P(-16, 16, -12, -8, 0, IN, CON);                                   // floor
    P(-16, 16, -10.15, -9.85, IN, 2 * IN, EDGE);
    // G4 and the abutment tunnels
    P(-22, 22, -12, -8, 8 - IN, 8, ROOF);
    P(-22, 22, -12, -12 + IN, 4, 8 - IN, INSIDE);
    for (const [a, b] of [[-18, -9], [-5, 5], [9, 18]]) P(a, b, -8 - IN, -8, 4, 8 - IN, INSIDE);
    P(-22, 22, -10.15, -9.85, 4, 4 + IN, EDGE);
    for (const s of [-1, 1]) {
      const X = (a, b) => s > 0 ? [-b, -a] : [a, b];
      const Q = (a, b, z0, z1, y0, y1, col) => { const [p, q] = X(a, b); P(p, q, z0, z1, y0, y1, col); };
      Q(-22, -22 + IN, -12, -6, 4, 8 - IN, INSIDE);                    // outer wall, all the way round
      Q(-22, -22 + IN, -6, 10, 4, 7.6 - IN, INSIDE);
      Q(-18 - IN, -18, -8, -6, 4, 8 - IN, INSIDE);                     // inner wall, either side of the door
      Q(-18 - IN, -18, -6, 0, 4, 7.6 - IN, INSIDE);
      Q(-18 - IN, -18, 3, 10, 4, 7.6 - IN, INSIDE);
      Q(-22, -18, -8, -6, 8 - IN, 8, ROOF);                          // ceilings
      Q(-22, -18, -6, 10, 7.6 - IN, 7.6, ROOF);
      Q(-20.15, -19.85, -10, 10, 4 + IN, 4 + 2 * IN, EDGE);            // the line, round the corner
    }

    // ===== the balconies (4) on the face, stairs down to the valley =====
    for (const s of [-1, 1]) {
      B(s > 0 ? 4 : -14, s > 0 ? 14 : -4, -6, -1, 3.6, 4, STEEL);
      B(s > 0 ? 4 : -14, s > 0 ? 14 : -4, -1, -0.8, 3.4, 4, EDGE);     // a yellow edge under the lip
      stairs(k, s * 6, 6, '-z', 2, 0, 4, CON);
    }
    kickShaft(k, -12.1, -4, 'z', 4, 4, 12, CON);                       // W: the chimney up to the crest
    k.pad(11.5, 4, -3, 1.4, 1.4, 23, { aim: [11.5, -10, 5.5] });       // E: a pad up to the crest

    // ===== THE SPILLWAY: a water slide from the crest down the middle, on piers, then under the bridge =====
    k.ramp(0, -1, 6, 10, 4.5, 12, '-z', SLIDE, { slick: true, base: 4 });
    k.ramp(0, 7, 6, 6, 0, 4.5, '-z', SLIDE, { slick: true });
    for (const s of [-1, 1]) B(s * 2.6 - 0.4, s * 2.6 + 0.4, 1, 2, 0, 4, CON);

    // ===== the abutments: roofs at 8 over the G4 tunnels, terraces at 4 to the south =====
    for (const s of [-1, 1]) {
      const X = (a, b) => s > 0 ? [-b, -a] : [a, b];
      const W = (a, b, z0, z1, y0, y1, col) => { const [p, q] = X(a, b); B(p, q, z0, z1, y0, y1, col); };
      W(-24, -16, -6, 10, 0, 4, CON);                                  // the base
      const [t0, t1] = X(-22, -18);
      k.deco((t0 + t1) / 2, 4, 2, 4, 0.02, 16, CON, FLAT);             // the tunnel floor
      W(-24, -22, -6, 10, 4, 7.6, CON);                                // tunnel walls; the inner one
      W(-18, -16, -6, 0, 4, 7.6, CON);                                 // has a door out over the valley
      W(-18, -16, 3, 10, 4, 7.6, CON);
      W(-24, -16, -6, 10, 7.6, 8, TOP);                                // the roof (8)
      W(-16.2, -16, -6, 10, 7.4, 8, EDGE);                             // its yellow edge over the valley
      stairs(k, s * 20, 1, '-z', 3, 8, 12, CON);                       // roof -> crest
      W(-24, -16, 10, 22, 0, 3.6, CON);                                // the terrace (4)
      W(-24, -16, 10, 22, 3.6, 4, TOP);
      stairs(k, s * 23, 17, '-z', 2, 4, 8, CON);                       // terrace -> roof
    }
    k.ramp(-12.5, 16, 7, 4, 0, 4, '-x', CON);                          // valley -> W terrace
    stairs(k, 9, 16, '+x', 4, 0, 4, CON);                              // valley -> E terrace
    B(12.7, 13.2, 4, 9, 0, 8, CON, { tex: 'kick' });                   // the kick wall off the E abutment

    // ===== the footbridge (4) between the terraces, along the south end =====
    B(-16, 16, 19, 22, 3.6, 4, STEEL);
    B(-16, 16, 19, 19.2, 3.4, 4, EDGE);
    for (const s of [-1, 1]) B(s * 8 - 0.5, s * 8 + 0.5, 20, 21, 0, 3.6, CON);

    // ===== the stilling basin: concrete baffle blocks on the valley floor (2m grid) =====
    // 2.4 tall ones are steps (jump + mantle, then a hop onto the 4m balconies, doors, terrace and
    // bridge they stand against) and cover from the crest; 1.2 ones are vaults. A pipe between the
    // sill blocks: slide under it or hop it.
    const block = (x, z, h) => B(x - 1, x + 1, z - 1, z + 1, 0, h, CON);
    for (const s of [-1, 1]) {
      block(s * 11, 0, 2.4);                                           // up onto the balcony
      block(s * 15, 1, 2.4);                                           // up into the abutment door
      block(s * 9, 7, 2.4);                                            // cover in the basin
      block(s * 13, 12, 2.4);                                          // the sill: two blocks...
      block(s * 9, 12, 2.4);
      B(s > 0 ? 10 : -12, s > 0 ? 12 : -10, 11.8, 12.2, 1.25, 1.65, STEEL);   // ...and a pipe between them
      block(s * 5, 12, 1.2);                                           // vaults in front of the chute
      block(s * 9, -3, 1.2);                                           // vaults under the balconies
      block(s * 5, 18, 2.4);                                           // up onto the footbridge
      block(s * 13, -3, 1.2);
      // and the same 1.2 blocks up top: in both galleries, on the terraces, roofs and the road
      const vault = (x, y, z) => B(x - 1, x + 1, z - 1, z + 1, y, y + 1.2, CON);
      vault(s * 10, 0, -10);                                           // G0
      vault(s * 13, 4, -10);                                           // G4
      vault(s * 19, 4, 13);                                            // terrace
      vault(s * 18, 8, 8);                                             // roof
      vault(s * 16, 12, -8);                                           // the road
      // a gate-hoist house on the crest, against the parapet: cover up there, a small top at 14.4
      B(s * 9 - 1, s * 9 + 1, -13.6, -11.6, 12, 14.4, CON2);
    }
    B(-1, 1, -13.6, -11.6, 12, 14.4, CON2);

    // ===== the intake tower, out in the reservoir (looks only - nobody gets out there) =====
    B(-3, 3, -40, -34, -4, 22, CON);
    B(-3.5, 3.5, -40.5, -33.5, 22, 23, STEEL);
    D(-4, 4, -41, -33, -3.9, -0.6, CON2);                                // its plinth at the waterline
    D(-0.5, 0.5, -33.98, -33.96, 4, 19, DARK);                         // the intake slot
    D(-1.8, 1.8, -38.8, -35.2, 23, 25, STEEL);                         // the gate house on top
  },
});

;
/* ==== js/maps/desert.js ==== */
// SANDSTORM - a sandstone step pyramid in the middle of a walled desert yard (64 x 64), with a
// mud-brick village, temple ruins, two sphinxes and two gateways packed round it.
// THE RULE: one 2m step everywhere on the pyramid and one color per job:
//   sand (0)        the ground and the pyramid's inside floors
//   sandstone       every face that stops you (pyramid, sphinxes, gateways, walls)
//   cream           every top you can stand on (steps, roofs, ledges, balconies)
//   clay            the village houses; pale grey stone the ruined columns; wood the crates
//   teal / coral    cloth: awnings and stall canopies (stand on them); orange = kick walls
//
//   THE PYRAMID  28m square, 7 steps of 2m (each 1.5m in from the one below), summit 14 (10m square).
//                Climb the outside step by step (each one is a jump + pull-up).
//     inside     four ground doors (3m wide, 4m tall), one near a corner of every face, run into
//                THE HALL (12m square, 10m tall). Two corners have a side chamber round a pillar
//                that links two doors without going through the hall - a loop to lose a chaser in
//     balcony    a 2m ledge at 4 round the hall: two stairs up it, and crate steps (1.4 -> 2.8)
//     upper doors  from the balcony out to the step at 4 on the +z and -z faces
//     the top    a lift pad in the middle of the hall throws you up through the open shaft (oculus)
//                onto the summit; drop back down the shaft and the pad bounces you up again
//   VILLAGE      (NE + SW corners) three flat-roofed houses you run through, crate steps up to the
//                roofs (2.8, 4), an awning, a stall, palms
//   RUINS        (NW + SE corners) a colonnade: one row with a lintel walk at 5.6 (fallen blocks up
//                its end: 1.4, 2.8), one broken row to hop up (1.4, 2.8, 4.2, 5.2); the rows are
//                2.8m apart - kick up between them
//   SPHINXES     (E + W) paws 1.2 -> back 2.8 -> chest 4.4 -> head 6.8
//   GATEWAYS     (N + S) two 6m towers and a 4m-tall door through them, big steps up one tower
//                (1.4, 2.8, 4.2), an orange kick wall behind the other, obelisks either side
//   THE WALL     9m all round, too tall to climb (so nobody hides along its top); nothing stands
//                closer than 2m to it, so there are no slots behind things to get stuck in
// Everything outside the pyramid comes in pairs, turned half a turn round the middle.
// (The +z face is "south" here: the upper doors are on the +z / -z faces, the sphinxes on +x / -x.)
const DES_HALF = 14, DES_STEP = 2, DES_IN = 1.5, DES_TIERS = 7;

defineMap({
  id: 'desert',
  accent: ['#c98f45', '#23408e'],
  name: 'Sandstorm',
  blurb: 'A step pyramid in a sandstorm: run through its halls, climb out the top, or race over the village roofs and temple ruins.',
  env: 'fog',
  // a sandstorm: the sky a yellow haze of sand, and the fog the same - the far side of the yard is softened,
  // and past the wall everything melts into it (no horizon). Container Yard's strong, form-giving light
  sky: '#e3c47e',
  fog: [20, 115],
  hemi: ['#fff1d2', '#6a5636', 1.35],
  sun: [2.0, 130, 60, 60],
  outlineColor: '#2a1d10',
  size: 36,
  killY: -6,
  menuCam: { r: 44, y: 26 },
  spawns: [
    // round the yard (pairs, half a turn apart)
    [19, 0, 12], [-19, 0, -12],
    [13.5, 0, 20], [-13.5, 0, -20],
    [28, 0, 23], [-28, 0, -23],
    [28, 0, -14.5], [-28, 0, 14.5],
    [20, 0, -25.5], [-20, 0, 25.5],
    [10, 0, 27], [-10, 0, -27],
    // inside the pyramid's hall
    [-3, 0, -3], [3, 0, 3],
  ],
  seekerSpawn: [0, 14, -3.5],
  centerSpot: [0, 14, -3.5],

  build(k) {
    // (a soft, few-color palette: pale sand, warm sandstone, bright cream tops, clay houses, cool pale-stone
    // ruins, wood - and only two accents, teal and coral, for the cloth; gold just on the summit and the bars)
    // (darker than they look: the strong light brightens them - like Container Yard's colors)
    const SAND = '#a8834c', STONE = '#a96d38', TOP = '#e6cf9c', MUD = '#9c4430', GRANITE = '#8c9497';
    const WOOD = '#7a5a36', BLUE = '#17696a', RED = '#a8382a', GOLD = '#e0b40c', GREEN = '#2a6c44';
    const DARK = '#2e241b', TRUNK = '#6a4c30';
    const NO = { tex: 'none' }, KICK = { tex: 'kick' }, SOFT = { tex: 'none', outline: false, noShadow: true };

    // a box by its extents (y0 = bottom)
    const B = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    // a cream top on a block (looks only, 2cm proud)
    const cap = (x0, x1, z0, z1, y) => D(x0, x1, z0, z1, y, y + 0.02, TOP);
    // a block with a cream top
    const S = (x0, x1, z0, z1, y0, y1, col = STONE) => { B(x0, x1, z0, z1, y0, y1, col); cap(x0, x1, z0, z1, y1); };

    // ===================== THE PYRAMID =====================
    // Built on a 0.5m grid, step by step: each 2m step is its square minus whatever is carved out of
    // it, cut into as few boxes as it takes. Carved spaces: [x0, x1, z0, z1, y0, y1] (y in whole steps)
    const half = (t) => DES_HALF - DES_IN * t;
    const carve = [];
    const hole = (x0, x1, z0, z1, y0, y1) => carve.push([x0, x1, z0, z1, y0, y1]);
    const HALL = 6;
    hole(-HALL, HALL, -HALL, HALL, 0, 10);                // the hall
    hole(-2, 2, -2, 2, 10, 14);                           // the shaft up to the summit
    // ground doors (half a turn apart): +x near +z, +z near +x, and the same turned round
    for (const s of [1, -1]) {
      const p = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      hole(...p(HALL, 15), ...p(3, HALL), 0, 4);         // +x door
      hole(...p(3, HALL), ...p(HALL, 15), 0, 4);         // +z door
      // side chamber in the corner between those two doors (a pillar in the middle)
      hole(...p(HALL, 10.5), ...p(HALL, 10.5), 0, 4);
      // upper door: from the balcony (4) out through the north / south face, onto the step at 4
      hole(-1.5, 1.5, ...p(HALL, 15), 4, 8);
    }
    const PILLAR = [7.5, 9];                               // left standing in each side chamber
    const G = 0.5, N = (2 * DES_HALF) / G;
    const cx = (i) => -DES_HALF + G * (i + 0.5);
    const solid = (t, i, j) => {
      if (t >= DES_TIERS) return false;
      const x = cx(i), z = cx(j), h = half(t), y0 = t * DES_STEP, y1 = y0 + DES_STEP;
      if (Math.abs(x) > h || Math.abs(z) > h) return false;
      for (const s of [1, -1]) if (s * x > PILLAR[0] && s * x < PILLAR[1] && s * z > PILLAR[0] && s * z < PILLAR[1] && y1 <= 4) return true;
      for (const c of carve) if (x > c[0] && x < c[1] && z > c[2] && z < c[3] && y0 >= c[4] - 1e-6 && y1 <= c[5] + 1e-6) return false;
      return true;
    };
    // greedy rectangles over a cell test
    const rects = (test) => {
      const used = [...Array(N)].map(() => new Array(N).fill(false)), out = [];
      for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
        if (used[j][i] || !test(i, j)) continue;
        let i1 = i; while (i1 + 1 < N && !used[j][i1 + 1] && test(i1 + 1, j)) i1++;
        let j1 = j;
        for (;;) {
          if (j1 + 1 >= N) break;
          let ok = true;
          for (let a = i; a <= i1 && ok; a++) if (used[j1 + 1][a] || !test(a, j1 + 1)) ok = false;
          if (!ok) break;
          j1++;
        }
        for (let b = j; b <= j1; b++) for (let a = i; a <= i1; a++) used[b][a] = true;
        out.push([-DES_HALF + G * i, -DES_HALF + G * (i1 + 1), -DES_HALF + G * j, -DES_HALF + G * (j1 + 1)]);
      }
      return out;
    };
    for (let t = 0; t < DES_TIERS; t++) {
      const y0 = t * DES_STEP, y1 = y0 + DES_STEP;
      for (const [x0, x1, z0, z1] of rects((i, j) => solid(t, i, j))) B(x0, x1, z0, z1, y0, y1, STONE);
      // cream wherever this step's top is open to the sky (or to a room above)
      for (const [x0, x1, z0, z1] of rects((i, j) => solid(t, i, j) && !solid(t + 1, i, j))) cap(x0, x1, z0, z1, y1);
    }
    // a gold rim round the summit and round the shaft
    const TOPY = DES_TIERS * DES_STEP, hs = half(DES_TIERS - 1);
    for (const s of [1, -1]) {
      D(-hs - 0.03, hs + 0.03, s * hs - 0.3, s * hs + 0.03, TOPY, TOPY + 0.04, GOLD);
      D(s * hs - 0.3, s * hs + 0.03, -hs, hs, TOPY, TOPY + 0.04, GOLD);
      D(-2.3, 2.3, s * 2 - 0.15, s * 2 + 0.15, TOPY, TOPY + 0.04, GOLD);
      D(s * 2 - 0.15, s * 2 + 0.15, -2, 2, TOPY, TOPY + 0.04, GOLD);
    }

    // ----- the hall's fittings -----
    // balcony (top 4) round the walls, 2m wide, minus the two stairs
    const BAL = 4;
    for (const s of [1, -1]) {
      const p = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      // the +z side, its two corners (the -x corner stops where the -x stair arrives)
      B(...p(-4, 4), ...p(4, HALL), BAL - 0.4, BAL, TOP);
      B(...p(4, HALL), ...p(3.0, HALL), BAL - 0.4, BAL, TOP);
      B(...p(-HALL, -4), ...p(4.7, HALL), BAL - 0.4, BAL, TOP);
      // the stair up the +x wall: from z = 2.3 (floor) toward -z, to 4 at the -z corner
      stairs(k, s * 5, s * 2.3, s > 0 ? '-z' : '+z', 2, 0, BAL, TOP, { run: 0.7 });
      // crate steps against the +z balcony: 1.4 -> 2.8 -> pull up onto 4
      B(...p(-2.4, 0), ...p(1.6, 4), 0, 2.8, WOOD);
      B(...p(0, 2.4), ...p(1.6, 4), 0, 1.4, WOOD);
      // torches on the walls, above the balcony
      const T = { emissive: '#ff9a2a', tex: 'none' }, w = HALL - 0.12;
      D(...p(w, HALL), ...p(-0.3, 0.3), 6, 6.6, '#ff9a2a', T);
      D(...p(-3.3, -2.7), ...p(w, HALL), 6, 6.6, '#ff9a2a', T);
      D(...p(2.7, 3.3), ...p(w, HALL), 6, 6.6, '#ff9a2a', T);
    }
    // the lift pad under the shaft: straight up to the summit (14)
    k.pad(0, 0, 0, 1.6, 1.6, Math.sqrt(52 * (TOPY + 3.5)), { lift: true });

    // ===================== THE YARD =====================
    ground(k, 68, 68, SAND);
    // a tall sandstone wall all round (too tall to climb: no hiding along its top), invisible wall above it
    const YARD_WALL = 9;   // (2m over the sphinx's head: nothing up high is a jump away from it)
    for (const s of [1, -1]) {
      B(-34, 34, s > 0 ? 32 : -34, s > 0 ? 34 : -32, 0, YARD_WALL, STONE);
      B(s > 0 ? 32 : -34, s > 0 ? 34 : -32, -32, 32, 0, YARD_WALL, STONE);
      k.wall(0, -2, s * 34.5, 70, 62, 1);
      k.wall(s * 34.5, -2, 0, 1, 62, 68);
      // nobody stands on the wall's top (or pulls up onto it - a kick up beside it gets you to its edge): an
      // invisible block sits on it, from just under its top, reaching a little past its inner edge
      k.wall(0, YARD_WALL - 0.2, s * 33.45, 70, 53, 3.1);
      k.wall(s * 33.45, YARD_WALL - 0.2, 0, 3.1, 53, 68);
    }

    // a palm: a trunk you can't walk through, fronds overhead (looks only)
    // (a 0.5m trunk top is no perch: an invisible cap over it)
    const palm = (x, z, h = 5.5) => {
      B(x - 0.25, x + 0.25, z - 0.25, z + 0.25, 0, h, TRUNK);
      k.wall(x, h, z, 0.5, 4, 0.5);
      D(x - 2.2, x + 2.2, z - 0.5, z + 0.5, h, h + 0.25, GREEN, SOFT);
      D(x - 0.5, x + 0.5, z - 2.2, z + 2.2, h, h + 0.25, GREEN, SOFT);
      D(x - 0.8, x + 0.8, z - 0.8, z + 0.8, h + 0.25, h + 0.6, GREEN, SOFT);
    };
    // slide rack: a bar 1.2m up between two posts (slide under or jump over)
    const rack = (x0, x1, z0, z1) => {
      const alongX = x1 - x0 > z1 - z0;
      if (alongX) { B(x0, x0 + 0.3, z0, z1, 0, 1.5, DARK); B(x1 - 0.3, x1, z0, z1, 0, 1.5, DARK); B(x0 + 0.3, x1 - 0.3, z0, z1, 1.2, 1.5, GOLD); }
      else { B(x0, x1, z0, z0 + 0.3, 0, 1.5, DARK); B(x0, x1, z1 - 0.3, z1, 0, 1.5, DARK); B(x0, x1, z0 + 0.3, z1 - 0.3, 1.2, 1.5, GOLD); }
    };
    // a canopy on four posts (top `top`, cloth you can stand on)
    const canopy = (x0, x1, z0, z1, top, col) => {
      for (const [x, z] of [[x0 + 0.2, z0 + 0.2], [x1 - 0.2, z0 + 0.2], [x0 + 0.2, z1 - 0.2], [x1 - 0.2, z1 - 0.2]]) B(x - 0.12, x + 0.12, z - 0.12, z + 0.12, 0, top - 0.2, DARK);
      B(x0, x1, z0, z1, top - 0.2, top, col);
    };
    // an obelisk with a pale tip (not a perch: an invisible cap over the tip, so nobody stands in it)
    const obelisk = (x, z, h = 8) => {
      B(x - 0.8, x + 0.8, z - 0.8, z + 0.8, 0, 0.6, STONE);
      B(x - 0.6, x + 0.6, z - 0.6, z + 0.6, 0.6, h, STONE);
      D(x - 0.35, x + 0.35, z - 0.35, z + 0.35, h, h + 0.5, TOP);
      k.wall(x, h, z, 1.2, 4, 1.2);
    };

    // everything below is placed twice: as written (s = 1) and turned half a turn (s = -1)
    for (const s of [1, -1]) {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      const Bs = (x0, x1, z0, z1, y0, y1, col, o) => B(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ds = (x0, x1, z0, z1, y0, y1, col, o) => D(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ss = (x0, x1, z0, z1, y0, y1, col) => S(...X(x0, x1), ...X(z0, z1), y0, y1, col);
      const P = (x, z) => [s * x, s * z];
      const cloth = s > 0 ? RED : BLUE;
      // (palms, racks, canopies and obelisks turned round too - not placed twice on the same spot)
      const palmS = (x, z, h) => palm(...P(x, z), h);
      const rackS = (x0, x1, z0, z1) => rack(...X(x0, x1), ...X(z0, z1));
      const obeliskS = (x, z, h) => obelisk(...P(x, z), h);
      const canopyS = (x0, x1, z0, z1, top, c) => canopy(...X(x0, x1), ...X(z0, z1), top, c);

      // ----- VILLAGE (the +x +z corner) -----
      // a house: walls 0.4 thick, a roof slab, doorways [side, from, to] (2.6 tall), all on its outline
      const house = (x0, x1, z0, z1, h, doors, win) => {
        const t = 0.4, dh = 2.6;
        const wallRun = (side) => {
          const ax = side === '-z' || side === '+z';
          const a0 = ax ? x0 : z0 + t, a1 = ax ? x1 : z1 - t;
          const cuts = doors.filter((d) => d[0] === side).map((d) => [d[1], d[2], 0, dh]).concat(win && win[0] === side ? [[win[1], win[2], 1.0, dh]] : []);
          let a = a0;
          const seg = (b0, b1, y0, y1) => {
            if (b1 - b0 < 0.01 || y1 - y0 < 0.01) return;
            if (ax) { const zz = side === '-z' ? [z0, z0 + t] : [z1 - t, z1]; Bs(b0, b1, ...zz, y0, y1, MUD); }
            else { const xx = side === '-x' ? [x0, x0 + t] : [x1 - t, x1]; Bs(...xx, b0, b1, y0, y1, MUD); }
          };
          for (const [c0, c1, y0, y1] of cuts.sort((p, q) => p[0] - q[0])) {
            seg(a, c0, 0, h - 0.4);
            seg(c0, c1, 0, y0);
            seg(c0, c1, y1, h - 0.4);
            a = c1;
          }
          seg(a, a1, 0, h - 0.4);
        };
        for (const side of ['-x', '+x', '-z', '+z']) wallRun(side);
        Ss(x0, x1, z0, z1, h - 0.4, h, MUD);
      };
      house(17, 23, 17, 23, 4, [['-x', 18.5, 20.5], ['+x', 18.5, 20.5]], ['-z', 19, 21]);
      house(26, 30, 16.5, 21.5, 2.8, [['-z', 27, 29], ['+z', 27, 29]]);
      house(16.5, 21.5, 26, 30, 2.8, [['-x', 27, 29], ['+x', 27, 29]]);
      // crate steps: 1.4 -> 2.8 -> the big house roof (4); a 1.4 up to the small house roof (2.8)
      Bs(23, 25.4, 20.8, 23.2, 0, 2.8, WOOD);
      Bs(23, 25.4, 23.2, 25.6, 0, 1.4, WOOD);
      Bs(18.2, 20.6, 23.6, 26, 0, 1.4, WOOD);
      // awning between the big house and the house to the east (stand on it: 2.6)
      canopyS(23.6, 26, 15.2, 18.2, 2.6, cloth);
      // a stall: a cloth roof (2.6, stand on it), just past the crate step (1.4 -> hop onto it)
      canopyS(24.5, 28.8, 25.8, 29.8, 2.6, cloth);
      palmS(29.6, 23, 5.5);

      // ----- SPHINX (the +x side, looking out) -----
      Ss(17, 24, -9, -3.5, 0, 2.8);                    // back
      Ss(23, 27, -8.5, -4, 0, 4.4);                    // chest
      Ss(25, 28, -7.6, -4.9, 4.4, 6.8);                // head (overhangs the chest at the front)
      Ss(27, 30, -8.5, -7.1, 0, 1.2);                  // paws
      Ss(27, 30, -5.4, -4.0, 0, 1.2);
      // a face
      Ds(28.0, 28.04, -7.0, -6.4, 5.7, 6.0, DARK);
      Ds(28.0, 28.04, -6.1, -5.5, 5.7, 6.0, DARK);
      // casing blocks fallen off the pyramid round its foot (vault them)
      Ss(16, 17.4, -13, -11, 0, 1.0);
      Ss(15.5, 17, 9, 10.4, 0, 1.0);
      Ss(9, 11, 15.6, 17, 0, 1.0);
      Ss(-12, -10.6, 15.5, 17.5, 0, 1.4);
      // a stall and crates by the sphinx's tail
      canopyS(19.5, 24.5, 5.5, 9.5, 2.6, cloth);
      Bs(20.2, 23.8, 9.9, 10.7, 0, 1.0, WOOD);
      Bs(27, 29.4, 3, 5.4, 0, 2.8, WOOD);
      Bs(27, 29.4, 5.4, 7.8, 0, 1.4, WOOD);
      palmS(29, 11.5, 5.2);
      palmS(17.5, 1.5, 4.8);
      rackS(19.2, 19.5, -1.4, 1.8);
      // a well in front of the sphinx, a low wall to vault by the stall, crates by the pyramid's corner
      Ss(27.5, 30, -1.6, 0.9, 0, 1.0);
      Bs(23.4, 25.8, -1.4, 1.0, 0, 1.4, WOOD);
      Ss(20, 24, 12, 12.6, 0, 1.0);
      Bs(15.6, 18, 14.6, 17, 0, 2.8, WOOD);
      Bs(15.6, 18, 12.2, 14.6, 0, 1.4, WOOD);
      Ss(6.5, 9, 18.6, 19.2, 0, 1.0);
      Ss(-9.5, -7.5, 16.2, 17.4, 0, 1.4);

      // ----- RUINS (the +x -z corner) -----
      const col = (x, z, h) => Ss(x - 0.6, x + 0.6, z - 0.6, z + 0.6, 0, h, GRANITE);
      const CX = [18, 21.6, 25.2, 28.8];
      // north row: whole, with a lintel walk along the top (5.6)
      for (const x of CX) col(x, -19.5, 5.2);
      Ss(17.4, 29.4, -20.1, -18.9, 5.2, 5.6, GRANITE);
      // south row (2.8m from the north row's faces: kick up between them): broken, a step-up
      [1.4, 2.8, 4.2, 5.2].forEach((h, i) => col(CX[i], -23.5, h));
      // fallen blocks against the west end of the lintel walk: 1.4 -> 2.8 -> the lintel (5.6)
      Ss(15.2, 17.4, -20.1, -18.9, 0, 2.8, GRANITE);
      Ss(13.0, 15.2, -20.1, -18.9, 0, 1.4, GRANITE);
      // a beam across from the last south column to the north row's lintel
      Ss(28.2, 29.4, -24.1, -20.1, 5.2, 5.6, GRANITE);
      // fallen drums (vault) and an obelisk
      Bs(25.5, 26.5, -16.6, -14.4, 0, 1.0, GRANITE);
      obeliskS(27.5, -28, 9);
      Ss(16.5, 18.9, -29, -26.6, 0, 2.8, STONE);
      Ss(14.1, 16.5, -29, -26.6, 0, 1.4, STONE);
      palmS(29.5, -12, 5);
      // a stretch of the temple's back wall (2.8) with a step at its end, and more fallen blocks
      Ss(18.9, 24.4, -28.4, -27.6, 0, 2.8, GRANITE);
      Ss(24.4, 25.6, -28.4, -27.0, 0, 1.4, GRANITE);
      Bs(16, 17.2, -17.5, -15.1, 0, 1.0, GRANITE);
      Bs(22.4, 24.4, -15.6, -14.6, 0, 1.4, STONE);

      // ----- GATEWAY (the +z side) -----
      Ss(-7, -2, 22, 25, 0, 6);                        // west tower
      Ss(2, 7, 22, 25, 0, 6);                          // east tower
      Ss(-2, 2, 22, 25, 4, 6);                         // over the door (4m tall)
      // big steps up the west tower: 1.4 -> 2.8 -> 4.2 -> 6
      Ss(-6.5, -4.3, 20.2, 22, 0, 4.2);
      Ss(-6.5, -4.3, 18.4, 20.2, 0, 2.8);
      Ss(-6.5, -4.3, 16.6, 18.4, 0, 1.4);
      // orange kick wall behind the east tower (2.8m off it): kick up to the top
      Bs(2.5, 6.5, 27.8, 28.3, 0, 6, STONE, KICK);
      obeliskS(-10.5, 19.5, 8);
      obeliskS(10.5, 19.5, 8);
      palmS(-11, 28.5, 5.4);
      Bs(-4, -1.6, 27.6, 30, 0, 1.4, WOOD);
      Bs(-1.6, 0.8, 27.6, 30, 0, 2.8, WOOD);
      rackS(8.6, 12.4, 24.6, 24.9);
    }

    // ===================== FAR AWAY (looks only) =====================
    D(-400, 400, -400, 400, -0.6, -0.03, SAND, SOFT);
    // dunes: low stacked mounds all round
    const dune = (x, z, w, d, h, c = '#b48e56') => {
      D(x - w / 2, x + w / 2, z - d / 2, z + d / 2, 0, h * 0.5, c, SOFT);
      D(x - w * 0.32, x + w * 0.32, z - d * 0.32, z + d * 0.32, h * 0.5, h, c, SOFT);
    };
    for (const [x, z, w, d, h] of [[-52, -20, 30, 14, 5], [-48, 22, 22, 16, 4], [50, -30, 26, 14, 6], [55, 18, 30, 18, 4],
      [10, -56, 34, 14, 5], [-20, 54, 30, 16, 6], [26, 52, 20, 14, 3], [-34, -52, 22, 14, 4], [70, 60, 40, 22, 8], [-75, -65, 44, 24, 9]]) dune(x, z, w, d, h);
    // two more pyramids on the horizon
    const far = (x, z, b, steps) => { for (let i = 0; i < steps; i++) { const w = b * (1 - i / steps); D(x - w / 2, x + w / 2, z - w / 2, z + w / 2, i * b / steps / 1.6, (i + 1) * b / steps / 1.6, i % 2 ? '#b07c44' : '#aa7640', SOFT); } };
    far(-120, -170, 60, 12);
    far(150, -110, 44, 10);
  },
});

;
/* ==== js/maps/skilodge.js ==== */
// SKI LODGE - a timber village on a mountain col (57 x 60), packed round a rocky crag: two big log
// lodges, two red ski huts, two patrol huts and two chalets ring the crag, tied together by wooden
// bridges. Rock cliffs close the north and south ends; east and west a log fence over the drop, and
// snow haze over the valley.
// THE RULE: one 1.4m step everywhere (1.4 -> 2.8 -> 4.2 -> 5.6 -> 7.0 -> 8.4 ...), one color per job:
//   blue-grey snow (0)  the ground                 pale snow   every top you can stand on
//   slate rock          the crag and the cliffs - faces that stop you
//   dark log            lodge / patrol hut / chalet walls and roof steps   red   the ski huts
//   honey wood          bridges, balconies, porches, firewood stacks, stairs; orange = kick walls
//
//   THE CRAG    (middle) a 3 x 3 block of rock columns (5m each), stepped round in a spiral:
//               corner 2.8 -> side 4.2 -> corner 5.6 -> side 8.4 -> summit 11.2 (and the same turned round).
//               An ice cave runs through it both ways (2.8 tall); a pad in the cave's middle throws you
//               up the shaft onto the summit
//   LODGES      (N + S) run-through fireplace halls (doors on every side, stairs up inside onto the
//               roof). Roof steps 4.2 -> 5.6 -> ridge 7.0 -> chimney 9.8; a porch (2.8) out the front,
//               a dormer at the back where the bridge from the crag (5.6) lands
//   SKI HUTS    (SE + NW) red, run through both ways, roof 4.2 / 5.6; firewood (1.4, 2.8) and an orange
//               kick wall up; a bridge (4.2) to the lodge
//   PATROL HUTS (E + W) run through both ways, roof 4.2: bridges to the crag, to the ski hut and to
//               the chalet's balcony - so there's a loop at 4.2 all the way round the map
//   CHALETS     (NE + SW) tall (roof 5.6, ridge 7.0), a balcony (4.2), a bridge (5.6) to the other lodge,
//               firewood steps and a kick wall up
//   PONDS       (E + W) frozen, by the fence; snowbanks, ski racks (slide under, 1.2) and rocks to vault
// Everything except the crag's middle comes in pairs, turned half a turn round the middle.
// (+z is "south")
defineMap({
  id: 'skilodge',
  accent: ['#9a2c27', '#23408e'],
  name: 'Ski Lodge',
  blurb: 'A log-cabin village round a rocky crag: run through the lodges, over the bridges and roofs, and up to the summit.',
  env: 'fog',
  // drifting snow: the sky a cool haze, the fog the same - the valley and far peaks melt into it.
  // Container Yard's strong, form-giving light, so the snow is deeper than it looks in the game
  sky: '#aebdcf',
  fog: [32, 150],
  hemi: ['#eef4ff', '#4a5a78', 1.35],
  sun: [2.0, 70, 75, 45],
  outlineColor: '#1c2230',
  size: 36,
  killY: -6,
  menuCam: { r: 44, y: 26 },
  spawns: [
    [11, 0, 7], [-11, 0, -7],
    [24, 0, 12.5], [-24, 0, -12.5],
    [4, 0, 26.3], [-4, 0, -26.3],
    [4.5, 0, 19.5], [-4.5, 0, -19.5],
    [0, 0, 2.2], [0, 0, -2.2],
    [16, 0, -1.2], [-16, 0, 1.2],
  ],
  seekerSpawn: [0, 11.2, -1.85],
  centerSpot: [0, 11.2, -1.85],

  build(k) {
    // (darker than they look: the strong light brightens them)
    const SNOW = '#56667b', CAP = '#7b8ca2', ROCK = '#3a414d', LOG = '#4f2a14', WOOD = '#7c4c22';
    const STONE = '#565a63', RED = '#82231e', BLUE = '#23408e', ICE = '#4f7f98', PINE = '#1b4430';
    const TRUNK = '#4a2f1d', DARK = '#262a33', FIRE = '#ff8a2a';
    const NO = { tex: 'none' }, KICK = { tex: 'kick' }, SOFT = { tex: 'none', outline: false, noShadow: true };
    const GLOW = { tex: 'none', emissive: '#ff5a10' };
    const B = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const cap = (x0, x1, z0, z1, y) => D(x0, x1, z0, z1, y, y + 0.03, CAP);
    const S = (x0, x1, z0, z1, y0, y1, col = ROCK) => { B(x0, x1, z0, z1, y0, y1, col); cap(x0, x1, z0, z1, y1); };
    const DH = 2.6;   // doorways

    // ===================== THE GROUND AND THE EDGES =====================
    ground(k, 57, 60, SNOW);
    const CLIFF = 9.8;
    for (const s of [1, -1]) {
      // rock cliffs north and south (nobody stands on them: an invisible block sits on each top)
      B(-28.5, 28.5, s > 0 ? 28 : -30, s > 0 ? 30 : -28, 0, CLIFF, ROCK);
      k.wall(0, CLIFF - 0.2, s * 29.45, 58, 53, 3.1);
      k.wall(0, -2, s * 30.5, 60, 72, 1);
      // a log fence along the drop east and west, an invisible wall over it
      const fx = s > 0 ? [27.6, 28] : [-28, -27.6];
      B(...fx, -28, 28, 0.7, 1.0, LOG);
      for (let z = -26; z <= 26; z += 4) B(...fx, z - 0.15, z + 0.15, 0, 1.2, LOG);
      k.wall(s * 28.35, -2, 0, 1.7, 72, 58);   // (from just inside the fence: nobody stands on its rail)
    }

    // ===================== THE CRAG =====================
    // 3 x 3 columns of 5m, heights [north row, middle row, south row] west -> east
    //   5.6  8.4  2.8
    //   4.2 11.2  4.2
    //   2.8  8.4  5.6
    // the ice cave: tunnels 3m wide, 2.8 tall, through the middle row and column; the middle column's
    // cave is 4.2 tall, with a shaft (2.4 square) up to the summit
    const CAVE = 2.8, MID = 4.2, TOP = 11.2;
    for (const s of [1, -1]) {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      const Bs = (x0, x1, z0, z1, y0, y1, col, o) => B(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ds = (x0, x1, z0, z1, y0, y1, col, o) => D(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ss = (x0, x1, z0, z1, y0, y1, col) => S(...X(x0, x1), ...X(z0, z1), y0, y1, col);
      Ss(2.5, 7.5, -7.5, -2.5, 0, 2.8);                    // NE corner 2.8
      Ss(2.5, 7.5, 2.5, 7.5, 0, 5.6);                      // SE corner 5.6
      // E side 4.2, the tunnel through it
      Bs(2.5, 7.5, -2.5, -1.5, 0, CAVE, ROCK); Bs(2.5, 7.5, 1.5, 2.5, 0, CAVE, ROCK);
      Ss(2.5, 7.5, -2.5, 2.5, CAVE, 4.2);
      // S side 8.4, the tunnel through it
      Bs(-2.5, -1.5, 2.5, 7.5, 0, CAVE, ROCK); Bs(1.5, 2.5, 2.5, 7.5, 0, CAVE, ROCK);
      Ss(-2.5, 2.5, 2.5, 7.5, CAVE, 8.4);
      // the summit round the shaft (each half builds one long side and one short side of the ring)
      Ss(-2.5, 2.5, 1.2, 2.5, MID, TOP);
      Ss(1.2, 2.5, -1.2, 1.2, MID, TOP);
      // a boulder up onto the NE corner (1.4)
      Ss(7.5, 9.6, -6.6, -4.0, 0, 1.4);
      // icicles over the tunnel mouths (looks only), a lantern in the cave
      for (const z of [-1.2, -0.4, 0.4, 1.2]) Ds(7.42, 7.52, z - 0.06, z + 0.06, CAVE - 0.5, CAVE, '#b8d4e4', SOFT);
      for (const x of [-1.2, -0.4, 0.4, 1.2]) Ds(x - 0.06, x + 0.06, 7.42, 7.52, CAVE - 0.5, CAVE, '#b8d4e4', SOFT);
      D(...X(2.3, 2.45), ...X(-1.9, -1.5), 2.2, 2.7, FIRE, { tex: 'none', emissive: '#ffb050' });
    }
    // the pad under the shaft: up onto the summit - it always drops you on the ring's north side (a
    // pad straight up could drop you back down the shaft onto itself, bouncing for ever)
    // (a strip just south of the middle: from anywhere on it you clear the shaft and land on the ring)
    k.pad(0, 0, 0.4, 1.6, 0.6, Math.sqrt(52 * (TOP + 3.5)), { aim: [0, -1.85, 1.6] });
    D(-0.85, 0.85, 0.05, 0.75, 0, 0.02, '#f1c40f', SOFT);
    // a flag on the summit (looks only)
    D(1.9, 2.05, -2.3, -2.15, TOP, TOP + 3.2, DARK, SOFT);
    D(2.05, 3.4, -2.26, -2.19, TOP + 2.2, TOP + 3.1, RED, SOFT);

    // ===================== DECOR HELPERS =====================
    const pine = (x, z, h = 6) => {
      B(x - 0.3, x + 0.3, z - 0.3, z + 0.3, 0, h * 0.5, TRUNK);
      k.wall(x, h * 0.5, z, 0.6, h + 2, 0.6);   // (the trunk runs on up through the branches: nobody perches on it)
      for (let i = 0; i < 3; i++) {
        const r = 1.7 - i * 0.5, y0 = 1.8 + i * (h - 1.8) / 3, t = (h - 1.8) / 3 * 0.85;
        D(x - r, x + r, z - r, z + r, y0, y0 + t, PINE, SOFT);
        D(x - r * 0.75, x + r * 0.75, z - r * 0.75, z + r * 0.75, y0 + t, y0 + t + 0.1, CAP, SOFT);
      }
    };
    // snowbank: vault it (1.0)
    const bank = (x, z, w, d) => { S(x - w / 2, x + w / 2, z - d / 2, z + d / 2, 0, 0.7, CAP); D(x - w / 3, x + w / 3, z - d / 3, z + d / 3, 0.7, 1.0, CAP); };
    // ski rack: a bar at 1.2 between two posts (slide under or jump over), skis leaning on it
    const rack = (x0, x1, z0, z1) => {
      const alongX = x1 - x0 > z1 - z0, SK = [RED, BLUE, '#f1c40f', RED, BLUE];
      if (alongX) {
        const z = (z0 + z1) / 2;
        B(x0, x0 + 0.3, z - 0.15, z + 0.15, 0, 1.5, DARK); B(x1 - 0.3, x1, z - 0.15, z + 0.15, 0, 1.5, DARK);
        B(x0 + 0.3, x1 - 0.3, z - 0.1, z + 0.1, 1.2, 1.45, DARK);
        for (let x = x0 + 0.6, i = 0; x < x1 - 0.5; x += 0.45, i++) D(x - 0.06, x + 0.06, z + 0.12, z + 0.26, 0, 1.75, SK[i % 5], SOFT);
      } else {
        const x = (x0 + x1) / 2;
        B(x - 0.15, x + 0.15, z0, z0 + 0.3, 0, 1.5, DARK); B(x - 0.15, x + 0.15, z1 - 0.3, z1, 0, 1.5, DARK);
        B(x - 0.1, x + 0.1, z0 + 0.3, z1 - 0.3, 1.2, 1.45, DARK);
        for (let z = z0 + 0.6, i = 0; z < z1 - 0.5; z += 0.45, i++) D(x + 0.12, x + 0.26, z - 0.06, z + 0.06, 0, 1.75, SK[i % 5], SOFT);
      }
    };

    // ===================== THE VILLAGE (twice, half a turn apart) =====================
    for (const s of [1, -1]) {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      const Bs = (x0, x1, z0, z1, y0, y1, col, o) => B(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ds = (x0, x1, z0, z1, y0, y1, col, o) => D(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ss = (x0, x1, z0, z1, y0, y1, col) => S(...X(x0, x1), ...X(z0, z1), y0, y1, col);
      const caps = (x0, x1, z0, z1, y) => cap(...X(x0, x1), ...X(z0, z1), y);
      const flip = (d) => (s > 0 ? d : (d[0] === '+' ? '-' : '+') + d[1]);
      const wood = (x0, x1, z0, z1, h) => Ss(x0, x1, z0, z1, 0, h, WOOD);
      const pineS = (x, z, h) => pine(s * x, s * z, h);
      const bankS = (x, z, w, d) => bank(s * x, s * z, w, d);
      const rackS = (x0, x1, z0, z1) => rack(...X(x0, x1), ...X(z0, z1));
      // walls 0.4 thick round x0..x1 / z0..z1, from y0 to y1, with doorways [side, from, to] (DH tall)
      const walls = (x0, x1, z0, z1, y0, y1, doors, col) => {
        const t = 0.4;
        for (const side of ['-x', '+x', '-z', '+z']) {
          const ax = side[1] === 'z', a0 = ax ? x0 : z0 + t, a1 = ax ? x1 : z1 - t;
          const seg = (b0, b1, ya, yb) => {
            if (b1 - b0 < 0.01 || yb - ya < 0.01) return;
            if (ax) Bs(b0, b1, ...(side === '-z' ? [z0, z0 + t] : [z1 - t, z1]), ya, yb, col);
            else Bs(...(side === '-x' ? [x0, x0 + t] : [x1 - t, x1]), b0, b1, ya, yb, col);
          };
          let a = a0;
          for (const [, c0, c1] of doors.filter((d) => d[0] === side).sort((p, q) => p[1] - q[1])) {
            seg(a, c0, y0, y1); seg(c0, c1, y0 + DH, y1); a = c1;
          }
          seg(a, a1, y0, y1);
        }
      };

      // ----- THE LODGE (south): x -8..8, z 12..22 -----
      walls(-8, 8, 12, 22, 0, 3.8, [['-z', -6, -3.4], ['+z', -5.2, -2.6], ['+z', 2.6, 5.2], ['-x', 17.4, 20], ['+x', 12.8, 15.4]], LOG);
      Ds(-7.6, 7.6, 12.4, 21.6, 0, 0.02, '#6a4020');   // plank floor
      // the roof (4.2) with the stairwell, the stairs up along the back wall (toward -x)
      const hole = [-3.0, 1.0, 12.4, 14.0];
      {
        const [hx0, hx1] = X(hole[0], hole[1]), [hz0, hz1] = X(hole[2], hole[3]);
        slabHole(k, ...X(-8, 8), ...X(12, 22), 4.2, [hx0, hx1, hz0, hz1], LOG, { tex: 'none' });
      }
      stairs(k, s * 3.6, s * 13.4, flip('-x'), 1.8, 0, 4.2, WOOD, { run: 0.6, tex: 'none' });
      caps(-8, 8, 20, 22, 4.2); caps(-8, -3, 12, 14, 4.2); caps(1, 8, 12, 14, 4.2); caps(-3, 1, 12, 12.4, 4.2);
      // roof steps: 5.6, the ridge 7.0
      Ss(-8, 8, 14, 20, 4.2, 5.6, LOG);
      Ss(-8, 8, 15.8, 18.2, 5.6, 7.0, LOG);
      // the dormer at the back, where the bridge from the crag lands (5.6)
      Ss(3.2, 5.8, 12, 14, 4.2, 5.6, LOG);
      Bs(3.4, 5.6, 7.5, 12, 5.2, 5.6, WOOD);
      // the fireplace on the east wall: a stone hearth (1.4) with the fire in it, the chimney (9.8)
      Ss(6.2, 7.6, 15.6, 18.4, 0, 1.4, STONE);
      Ds(6.12, 6.2, 16.2, 17.8, 0.15, 1.15, FIRE, GLOW);
      Bs(6.8, 7.6, 15.8, 18.2, 1.4, 3.8, STONE);
      Ss(7.6, 9.0, 16.0, 18.0, 0, 9.8, STONE);
      // a long table (vault it) and benches
      Bs(-3, 3, 16.9, 18.1, 0, 0.9, WOOD);
      Bs(-2.6, 2.6, 15.6, 16.1, 0, 0.5, LOG); Bs(-2.6, 2.6, 18.9, 19.4, 0, 0.5, LOG);
      // windows (looks only)
      for (const x of [-7, 0.2, 6.8]) Ds(x - 0.6, x + 0.6, 22.0, 22.04, 1.2, 2.3, '#ffcf7a', { tex: 'none', emissive: '#8a5a20' });
      // the porch (2.8) along the front, on posts; firewood steps up at its east end (1.4)
      Ss(-6.5, 6.5, 22, 24.6, 2.4, 2.8, WOOD);
      for (const x of [-6.2, 0, 6.2]) Bs(x - 0.15, x + 0.15, 24.15, 24.45, 0, 2.4, LOG);
      wood(7.2, 9.6, 22, 24.6, 1.4);   // (against the wall, clear of the porch: no slot too narrow to pass, open air to hop up)
      // in front: a ski rack and a snowbank against the cliff
      rackS(-4.6, -0.6, 26.4, 26.7);
      bankS(-7.5, 26.4, 2.6, 1.2);

      // ----- SKI HUT (south-east): x 14..22, z 15..22, red -----
      walls(14, 22, 15, 22, 0, 3.8, [['-x', 17.2, 19.8], ['+x', 17.2, 19.8], ['-z', 16.7, 19.3], ['+z', 16.7, 19.3]], RED);
      Ss(14, 22, 15, 22, 3.8, 4.2, RED);
      Ss(14, 22, 17.3, 19.7, 4.2, 5.6, RED);
      Ds(17.2, 18.8, 22.0, 22.04, 2.8, 3.4, '#e8dcc0');   // sign
      // bridge to the lodge's front eaves (4.2)
      Bs(8, 14, 20.1, 22, 3.8, 4.2, WOOD);
      // firewood up the south side: 1.4 -> 2.8 -> roof
      wood(19.6, 22, 22, 23.2, 2.8);
      wood(19.6, 22, 23.2, 24.4, 1.4);
      // orange kick wall 2.8m off the east wall
      Bs(24.8, 25.3, 15.5, 21.5, 0, 4.2, LOG, KICK);
      rackS(14.5, 18.5, 24.6, 24.9);
      pineS(25.5, 25.5, 6.5);
      pineS(11.8, 25.6, 5.5);

      // ----- PATROL HUT (east): x 13..19, z -3..3 -----
      walls(13, 19, -3, 3, 0, 3.8, [['-x', -1.3, 1.3], ['+x', -1.3, 1.3], ['-z', 14.7, 17.3], ['+z', 14.7, 17.3]], LOG);
      Ss(13, 19, -3, 3, 3.8, 4.2, LOG);
      Ds(15.6, 16.4, -0.4, 0.4, 4.2, 4.5, RED);   // a first-aid box on the roof (looks only)
      // bridges (4.2): to the crag's east side, to the ski hut, to the chalet's balcony
      Bs(7.5, 13, -1, 1, 3.8, 4.2, WOOD);
      Bs(15, 17, 3, 15, 3.8, 4.2, WOOD);
      Bs(15, 17, -13, -3, 3.8, 4.2, WOOD);
      for (const z of [9, -8]) for (const x of [15.1, 16.9]) Bs(x - 0.12, x + 0.12, z - 0.12, z + 0.12, 0, 3.8, LOG);

      // ----- CHALET (north-east): x 14..22, z -21..-15, tall -----
      walls(14, 22, -21, -15, 0, 5.2, [['+z', 16.7, 19.3], ['-x', -19.3, -16.7], ['+x', -19.3, -16.7]], LOG);
      Ss(14, 22, -21, -15, 5.2, 5.6, LOG);
      Ss(16.8, 19.2, -21, -15, 5.6, 7.0, LOG);
      // the balcony (4.2) on the south face, on posts
      Ss(14, 22, -15, -13, 3.8, 4.2, WOOD);
      for (const x of [14.2, 21.8]) Bs(x - 0.15, x + 0.15, -13.4, -13.1, 0, 3.8, LOG);
      // bridge from its roof (5.6) to the north lodge's roof step (5.6)
      Bs(8, 14, -20, -18.4, 5.2, 5.6, WOOD);
      // firewood up to the balcony: 1.4 -> 2.8 -> 4.2
      wood(22, 24.6, -15, -12.6, 2.8);
      wood(22, 24.6, -12.6, -10.4, 1.4);
      // orange kick wall 2.8m off the north wall: kick up onto the roof
      Bs(15, 21, -24.3, -23.8, 0, 5.6, LOG, KICK);
      // inside: a firewood stack (1.4, 2.8) by the back wall
      wood(16.2, 19.8, -20.6, -19.4, 2.8);
      wood(16.2, 19.8, -19.4, -18.2, 1.4);
      // a rock outcrop between the chalet and the north lodge (1.4 -> 2.8)
      Ss(9, 12.4, -28, -25, 0, 2.8);
      Ss(9, 12.4, -25, -23.4, 0, 1.4);
      pineS(25.5, -26, 6.5);

      // ----- POND (east) -----
      Ds(21, 27, -9, 9, 0, 0.03, ICE);
      Ds(21.3, 26.7, -8.7, 8.7, 0.03, 0.04, '#5d8ea8');
      Ss(23.2, 25.4, -1.3, 1.3, 0, 1.4);
      Ss(25.4, 26.6, -0.6, 0.8, 0, 0.8);
      bankS(21.6, -10.5, 1.2, 2.4);
      bankS(26.4, 9.8, 2.4, 1.2);
      pineS(26.2, -6.5, 5.5);
      pineS(25.8, 5.5, 5);

      // ----- between the huts and the crag -----
      rackS(8.8, 12.4, 9.6, 9.9);
      bankS(10.5, 4.8, 2.4, 1.2);
      bankS(11.4, -9.8, 2.6, 1.2);
      rackS(11.4, 11.7, -6.8, -3.2);
      wood(9.2, 11.6, -14.5, -12.1, 1.4);
    }

    // ===================== FAR AWAY (looks only) =====================
    // the valley floor far below the fences, and peaks all round in the haze
    for (const s of [1, -1]) D(s > 0 ? 28.4 : -400, s > 0 ? 400 : -28.4, -400, 400, -30, -29.9, '#7d8da0', SOFT);
    D(-28.4, 28.4, -400, 400, -30, -29.9, '#7d8da0', SOFT);
    for (const s of [1, -1]) D(s > 0 ? 28.4 : -29.4, s > 0 ? 29.4 : -28.4, -30, 30, -30, -1.2, ROCK, SOFT);
    const peak = (x, z, b, h, n = 7) => {
      for (let i = 0; i < n; i++) {
        const w = b * (1 - i / n), y0 = -30 + (h + 30) * i / n, y1 = -30 + (h + 30) * (i + 1) / n;
        D(x - w / 2, x + w / 2, z - w / 2, z + w / 2, y0, y1, i >= n - 3 ? '#a7b4c4' : '#4b5568', SOFT);
      }
    };
    peak(-30, -110, 90, 60); peak(50, -95, 70, 40); peak(0, -170, 130, 95, 9);
    peak(30, 110, 90, 55); peak(-50, 95, 70, 38); peak(0, 170, 130, 90, 9);
    peak(120, 20, 80, 30); peak(-120, -20, 80, 30); peak(150, -90, 100, 50); peak(-150, 90, 100, 50);
  },
});

;
/* ==== js/maps/subway.js ==== */
// SUBWAY - (concept) a New York-style subway station under a street corner, with an el over it (44 x 40).
// Trains run through the station: out of one tunnel, across, into the other, on a loop. A train that
// hits you is the void - back to a spawn.
// THE RULE: one color per job:
//   concrete            floors (platforms, sidewalks, el decks);  asphalt the road;  dark ballast = the trackbed (danger)
//   white tile / brick  walls that stop you (the station's walls / the buildings round the street)
//   cream               every top you can stand on (cab roofs, kiosk canopies, newsstands, fire escapes)
//   dark green steel    columns, el legs and deck, kiosk rails
//   silver + lights     the trains (headlights in front, red at the back);  amber = a train is coming
//   orange              kick walls;  yellow = the platform edge and the cabs / trucks
//
//   BELOW (y 0 - 9.4): THE STATION, under the whole road
//     tracks      a trackbed (0) between two side platforms (1.2), one track each way. Trains come out
//                 of the dark tunnels at both ends every ~8s, alternating tracks. Before one arrives an
//                 amber light races along the ceiling over its track. Between the two tracks a 3m strip
//                 is safe. The trackbed is the shortcut between the platforms - the only one down here.
//                 The trains are too tall to climb onto (4.2m over the platform), and nothing overhangs them
//     stairs      one long stair up each platform's back wall to a kiosk on the street
//     kick shaft  an orange alcove in each back wall: kick up from the platform to the sidewalk
//     lift pads   one on each platform, up through a hole in the road (drop back down through it)
//   ABOVE (y 10): THE STREET
//     kiosks      green railed entrances round the two stairs (canopies are perches, 13)
//     the road    cabs and box trucks to vault and climb, newsstands on the sidewalks
//     THE EL      a steel deck (16) on green legs crossing the street (along z) in the middle, side
//                 platforms; up to it: a stair and an orange kick shaft each side, a fire escape at each end
//   THE EDGE    buildings all round, 14m over the street - too tall to climb, an invisible block on top
// Everything comes in pairs, turned half a turn round the middle.
const SUB_ST = 10;          // the street (top of the road slab)

defineMap({
  id: 'subway',
  accent: ['#e0a800', '#1f4a35'],
  name: 'Subway',
  blurb: 'A subway station under a street corner, with an el above. Trains come through - watch for the amber light, and don\'t get hit.',
  env: 'fog',
  sky: '#b3bfcc',
  fog: [30, 130],
  hemi: ['#f4f1ea', '#4a4640', 1.35],
  sun: [2.0, 40, 70, 25],
  outlineColor: '#1a1a1e',
  size: 30,
  // (just under the trackbed: the CPUs' map scan skips floors below killY + 1, so they keep off the tracks)
  killY: -0.8,
  menuCam: { r: 40, y: 30 },
  spawns: [
    // the platforms
    [-15, 1.2, -7], [15, 1.2, 7], [-1, 1.2, -10.5], [1, 1.2, 10.5], [-8, 1.2, -6.5], [8, 1.2, 6.5],
    // the street and sidewalks
    [-17, SUB_ST, -4.5], [17, SUB_ST, 4.5], [7, SUB_ST, -14], [-7, SUB_ST, 14], [-8, SUB_ST, -3.5], [8, SUB_ST, 3.5],
    // the el
    [0, 16, -10], [0, 16, 10],
  ],
  seekerSpawn: [0, 16, 0],
  centerSpot: [0, 16, 0],

  build(k) {
    // (darker than they look: the strong light brightens them)
    const TILE = '#c4c0b2', BRICK = '#7a3f2c', FLOOR = '#7a756a', ROAD = '#45474d', BED = '#34302d';
    const TOP = '#e6d8b0', STEEL = '#1f4a35', BLACK = '#2a2a2e', CAB = '#e0a800', EDGE = '#d9a90c';
    const TRAIN = '#b9bec6', GLASS = '#1d2630', TUNNEL = '#17181b', RAIL = '#8a8c90', KICKC = '#ff6a3d';
    const NO = { tex: 'none' }, KICK = { tex: 'kick' }, SOFT = { tex: 'none', outline: false, noShadow: true };
    const LIGHT = { tex: 'none', emissive: '#fff4d6', outline: false, noShadow: true };
    const ST = SUB_ST, PL = 1.2, CEIL = ST - 0.6, EL = 16;

    // a box by its extents (y0 = bottom)
    const B = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const cap = (x0, x1, z0, z1, y, col = TOP) => D(x0, x1, z0, z1, y, y + 0.02, col);
    const S = (x0, x1, z0, z1, y0, y1, col) => { B(x0, x1, z0, z1, y0, y1, col); cap(x0, x1, z0, z1, y1); };
    // a slab x0..x1 / z0..z1 (y0..y1) minus rectangular holes, cut on a 0.5m grid into as few boxes as it takes
    const holed = (x0, x1, z0, z1, y0, y1, holes, col) => {
      const G = 0.5, NX = Math.round((x1 - x0) / G), NZ = Math.round((z1 - z0) / G);
      const solid = (i, j) => { const x = x0 + G * (i + 0.5), z = z0 + G * (j + 0.5); return !holes.some((h) => x > h[0] && x < h[1] && z > h[2] && z < h[3]); };
      const used = [...Array(NZ)].map(() => new Array(NX).fill(false));
      for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++) {
        if (used[j][i] || !solid(i, j)) continue;
        let i1 = i; while (i1 + 1 < NX && !used[j][i1 + 1] && solid(i1 + 1, j)) i1++;
        let j1 = j;
        for (;;) { if (j1 + 1 >= NZ) break; let ok = true; for (let a = i; a <= i1 && ok; a++) if (used[j1 + 1][a] || !solid(a, j1 + 1)) ok = false; if (!ok) break; j1++; }
        for (let b = j; b <= j1; b++) for (let a = i; a <= i1; a++) used[b][a] = true;
        B(x0 + G * i, x0 + G * (i1 + 1), z0 + G * j, z0 + G * (j1 + 1), y0, y1, col);
      }
    };
    // a stair with solid tile under it (nobody walks underneath): (x, z) = middle of its bottom edge
    const stair = (x, z, dir, w, y0, y1, col, fill) => {
      stairs(k, x, z, dir, w, y0, y1, col);
      const n = Math.ceil((y1 - y0) / 0.4), sg = dir[0] === '+' ? 1 : -1;
      for (let j = 1; j < n / 2; j++) {
        const a = x + sg * 1.4 * j, b = x + sg * 1.4 * (j + 1), top = y0 + (y1 - y0) * (2 * j) / n - 0.05;
        if (dir[1] === 'x') B(Math.min(a, b), Math.max(a, b), z - w / 2, z + w / 2, y0, top, fill);
      }
    };
    // everything comes in pairs: f(s) with s = 1 and s = -1 (half a turn round the middle)
    const pair = (f) => { f(1); f(-1); };

    // ===================== THE STATION (below) =====================
    ground(k, 48, 44, BED);
    // the platforms (1.2), a yellow edge strip
    pair((s) => {
      B(-22, 22, s > 0 ? 5 : -12, s > 0 ? 12 : -5, 0, PL, FLOOR);
      D(-22, 22, s > 0 ? 5 : -5.6, s > 0 ? 5.6 : -5, PL, PL + 0.02, EDGE);
    });
    // rails (looks only)
    for (const zc of [-3.1, 3.1]) for (const e of [-0.72, 0.72]) D(-24, 24, zc + e - 0.06, zc + e + 0.06, 0, 0.12, RAIL, SOFT);
    // the back walls (the fill under the sidewalks), each with an orange kick alcove up to the sidewalk
    pair((s) => {
      const z0 = s > 0 ? 12 : -20, z1 = s > 0 ? 20 : -12, a0 = s > 0 ? -12.4 : 9.6, a1 = a0 + 2.8;   // the alcove (x a0..a1, 3m deep)
      const zb = s > 0 ? [12, 15] : [-15, -12];
      B(-22, a0 - 0.5, z0, z1, 0, ST, TILE); B(a1 + 0.5, 22, z0, z1, 0, ST, TILE);
      B(a0 - 0.5, a1 + 0.5, s > 0 ? 15 : -20, s > 0 ? 20 : -15, 0, ST, TILE);
      B(a0 - 0.5, a0, ...zb, 0, ST, KICKC, KICK); B(a1, a1 + 0.5, ...zb, 0, ST, KICKC, KICK);
      B(a0, a1, ...zb, 0, PL, FLOOR);
    });
    // the end walls: a tunnel mouth (z -5..5, 6m tall) over the trackbed; the buildings above them
    pair((s) => {
      const x0 = s > 0 ? 22 : -24, x1 = x0 + 2;
      B(x0, x1, -20, -5, 0, ST, TILE); B(x0, x1, 5, 20, 0, ST, TILE); B(x0, x1, -5, 5, 6, ST, TILE);
      B(x0, x1, -20, 20, ST, 24, BRICK);
    });
    // columns down each platform
    for (const x of [-12, -4, 4, 12]) pair((s) => B(x - 0.25, x + 0.25, s * 8.5 - 0.25, s * 8.5 + 0.25, PL, CEIL, STEEL));
    // light strips under the road over the platforms (looks only)
    for (const x of [-16, -8, 0, 8, 16]) pair((s) => D(x - 2, x + 2, s * 6.8 - 0.4, s * 6.8 + 0.4, CEIL - 0.06, CEIL - 0.01, '#fff4d6', LIGHT));

    // ----- THE TUNNELS: a short stub you can walk into (an invisible wall 3m in), then dark to 112 -----
    const TEND = 112;
    pair((s) => {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      B(...X(24, 27), -5, 5, -1.2, 0, BED);
      B(...X(24, 27), -6, -5, 0, 6.6, TUNNEL); B(...X(24, 27), 5, 6, 0, 6.6, TUNNEL); B(...X(24, 27), -6, 6, 6, 6.6, TUNNEL);
      k.wall(s * 27.2, 0, 0, 0.4, 6, 10);
      D(...X(27, TEND), -5, 5, -0.3, 0, TUNNEL, SOFT);
      D(...X(27, TEND), -6, -5, 0, 6.6, TUNNEL, SOFT); D(...X(27, TEND), 5, 6, 0, 6.6, TUNNEL, SOFT); D(...X(27, TEND), -6, 6, 6, 6.6, TUNNEL, SOFT);
      D(...X(TEND, TEND + 1), -6, 6, -0.3, 6.6, TUNNEL, SOFT);
      for (let x = 34; x < TEND; x += 12) D(...X(x, x + 0.4), -4.98, -4.9, 4.6, 4.9, '#6d6a5e', LIGHT);   // dim lamps down the tunnel wall
    });

    // ----- THE TRAINS: one track each way (north +x, south -x), half a loop apart -----
    // Each train is 26m long, 3.2m wide, 5.4m tall (too tall to climb from the platform). It loops
    // from behind one tunnel's far end to behind the other's (hidden both ends). Every piece is deadly.
    const TL = 26, TW = 3.2, TH = 5.4, SPEED = 16, X0 = TEND + TL / 2 + 1, PERIOD = (2 * X0) / SPEED, DIE = { deadly: true };
    pair((s) => {
      const z = -s * 3.1, dir = s, phase = s > 0 ? 0 : 0.5;
      const loop = { type: 'loop', dx: dir * 2 * X0, period: PERIOD, phase };
      // a piece at offset (along the train from its middle, +ahead) / height / sideways, size
      const part = (ax, y, az, w, h, d, col, o = {}) => k.mover(-dir * X0 + dir * ax, y, z + az, w, h, d, col, loop, Object.assign({ tex: 'none' }, DIE, o));
      part(0, 0.15, 0, TL, TH - 0.15, TW, TRAIN);
      for (const e of [-1, 1]) part(0, 2.7, e * (TW / 2 + 0.03), TL - 2, 1.2, 0.06, GLASS);              // window bands
      part(TL / 2 + 0.03, 2.7, 0, 0.06, 1.2, TW - 0.8, GLASS);                                             // windscreen
      part(TL / 2 + 0.03, 4.4, 0, 0.06, 0.5, 1.6, '#fff4d6', { emissive: '#fff0c0' });                    // route sign
      for (const e of [-1, 1]) {
        part(TL / 2 + 0.06, 1.3, e * 1.05, 0.12, 0.5, 0.6, '#ffffff', { emissive: '#fff6d8' });          // headlights
        part(-TL / 2 - 0.05, 1.3, e * 1.1, 0.1, 0.4, 0.4, '#ff3a2a', { emissive: '#ff2a1a' });           // tail lights
      }
      // the warning: an amber light 40m long racing along the ceiling just ahead of the train - it
      // reaches the station 2.5s before the train does (nobody can get up there)
      const WL = 40;
      part(TL / 2 + WL / 2, CEIL - 0.16, 0, WL, 0.14, 0.7, '#ffb21a', { emissive: '#ff9a00', deadly: false });
      D(-22, 22, z - 0.45, z + 0.45, CEIL - 0.02, CEIL, '#1a1a1e', SOFT);   // the dark slot it runs in
    });

    // ----- the stairs: one up each platform's back wall, to a kiosk on the street -----
    // (22 steps: 15.4m, a pocket at its foot to step on from; the hole in the road over its top end, 4..10.5)
    pair((s) => stair(s * 20.3, s * 11, s > 0 ? '-x' : '+x', 2, PL, ST, FLOOR, TILE));
    // a handrail along the open side of each stair's foot: you step on at the end, not up its side
    pair((s) => B(...(s > 0 ? [17, 20.6] : [-20.6, -17]), ...(s > 0 ? [9.8, 10] : [-10, -9.8]), PL, PL + 1.1, STEEL));

    // ===================== THE STREET (above) =====================
    // the road (its underside is the station's ceiling), with holes: the two stairs and the two pads
    holed(-22, 22, -12, 12, CEIL, ST, [[4, 10.5, 10, 12], [-10.5, -4, -12, -10], [6, 10.5, -11, -8], [-10.5, -6, 8, 11]], ROAD);
    for (let x = -18; x <= 18; x += 4) if (Math.abs(x) > 4) D(x - 1, x + 1, -0.08, 0.08, ST, ST + 0.02, '#d8c25a', SOFT);   // lane marks
    // the sidewalks: the station's fill tops (the kick alcoves open onto them)
    pair((s) => {
      const z0 = s > 0 ? 12 : -18, z1 = s > 0 ? 18 : -12, a0 = s > 0 ? -12.4 : 9.6, a1 = a0 + 2.8;
      D(-22, a0 - 0.5, z0, z1, ST, ST + 0.02, FLOOR, SOFT); D(a1 + 0.5, 22, z0, z1, ST, ST + 0.02, FLOOR, SOFT);
      D(a0 - 0.5, a1 + 0.5, s > 0 ? 15 : -18, s > 0 ? 18 : -15, ST, ST + 0.02, FLOOR, SOFT);
    });
    // the lift pads: from each platform up through its hole, onto the road (flying along the road, never toward the tracks)
    pair((s) => k.pad(s * 9.3, PL, -s * 9.5, 1.6, 1.6, Math.sqrt(52 * (ST - PL + 3)), { aim: [s * 2, -s * 9.5, 3.5] }));

    // ----- kiosks round the stair holes: green rails, open at the top of the stair, a canopy (a perch, 13) -----
    pair((s) => {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]), Z = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      B(...X(4, 10.7), ...Z(9.8, 10), ST, ST + 1.1, STEEL);       // road side
      B(...X(10.5, 10.7), ...Z(10, 12), ST, ST + 1.1, STEEL);       // far end
      for (const [x, z] of [[4.1, 9.9], [10.6, 9.9], [4.1, 12.1], [10.6, 12.1]]) B(s * x - 0.1, s * x + 0.1, s * z - 0.1, s * z + 0.1, ST, ST + 2.8, STEEL);
      S(...X(3.8, 10.9), ...Z(9.6, 12.4), ST + 2.8, ST + 3.0, STEEL);
      D(s * 4.1 - 0.2, s * 4.1 + 0.2, s * 9.9 - 0.2, s * 9.9 + 0.2, ST + 1.2, ST + 1.6, '#7ee08a', { tex: 'none', emissive: '#3aa04a', outline: false });
    });

    // ----- cabs, box trucks, newsstands -----
    const cab = (x, z, alongX) => {
      const [w, d] = alongX ? [4.4, 1.9] : [1.9, 4.4], [cw, cd] = alongX ? [2.2, 1.7] : [1.7, 2.2];
      B(x - w / 2, x + w / 2, z - d / 2, z + d / 2, ST, ST + 1.1, CAB);
      S(x - cw / 2, x + cw / 2, z - cd / 2, z + cd / 2, ST + 1.1, ST + 1.6, CAB);
    };
    pair((s) => {
      cab(s * 14, s * 7, true);
      cab(s * 12, s * 1, false);
      cab(s * 18.5, -s * 2, false);
      S(s * 15 - 2.5, s * 15 + 2.5, -s * 8 - 1.1, -s * 8 + 1.1, ST, ST + 2.4, CAB);           // box truck (12.4)
      S(s * 14.75 - 1.25, s * 14.75 + 1.25, s * 15.25 - 1.25, s * 15.25 + 1.25, ST, ST + 2.6, STEEL);   // newsstand (12.6)
    });

    // ----- the buildings round the street -----
    pair((s) => {
      B(-22, 22, s > 0 ? 18 : -20, s > 0 ? 20 : -18, ST, 24, BRICK);
      for (let x = -19; x <= 19; x += 4) for (const y of [ST + 4, ST + 8, ST + 11.5]) D(x - 0.8, x + 0.8, s > 0 ? 17.97 : -18.0, s > 0 ? 18.0 : -17.97, y, y + 1.8, GLASS, SOFT);
      // nobody stands on the buildings: an invisible block on top, and walls round the outside
      k.wall(0, 23.8, s * 19.4, 50, 30, 3.2);
      k.wall(s * 23, 23.8, 0, 3.2, 30, 46);
      k.wall(0, -2, s * 20.5, 50, 62, 1);
      k.wall(s * 24.5, -2, 0, 1, 62, 46);
    });

    // ===================== THE EL (along z over x -3..3, deck 16) =====================
    B(-3, 3, -18, 18, EL - 0.6, EL, STEEL); cap(-3, 3, -18, 18, EL, FLOOR);
    for (const xc of [-1.5, 1.5]) for (const e of [-0.72, 0.72]) D(xc + e - 0.06, xc + e + 0.06, -18, 18, EL + 0.02, EL + 0.12, RAIL, SOFT);
    for (const z of [-15, -9, -3, 3, 9, 15]) for (const x of [-2.7, 2.7]) B(x - 0.3, x + 0.3, z - 0.3, z + 0.3, ST, EL - 0.6, STEEL);
    pair((s) => {
      // a side platform, a stair up to it from the road, an orange kick shaft beside it
      B(...(s > 0 ? [3, 5.5] : [-5.5, -3]), -6, 6, EL - 0.5, EL, STEEL); cap(...(s > 0 ? [3, 5.5] : [-5.5, -3]), -6, 6, EL, FLOOR);
      stair(s * 16, -s * 4.2, s > 0 ? '-x' : '+x', 1.6, ST, EL, FLOOR, STEEL);
      kickShaft(k, s * 7.2, 0, 'z', 3, ST, EL, KICKC);
      // a fire escape on the building at each end of the el: balconies 12.4 and 15.2, then a step onto the deck
      // (side by side, not stacked: open sky over the low one, so you can jump and pull up onto the high one)
      const f = -s * 18, zo = (dd) => (s > 0 ? [f, f + dd] : [f - dd, f]), X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      S(...X(6, 9.5), ...zo(2.4), ST + 2.2, ST + 2.4, BLACK);
      S(...X(3, 6), ...zo(2.4), ST + 5.0, ST + 5.2, BLACK);
    });

    // ===================== FAR AWAY (looks only) =====================
    pair((s) => {
      D(-300, 300, s > 0 ? 20 : -300, s > 0 ? 300 : -20, ST - 0.6, ST - 0.05, '#55585e', SOFT);
      D(s > 0 ? 24 : -300, s > 0 ? 300 : -24, -20, 20, ST - 0.6, ST - 0.05, '#55585e', SOFT);
    });
    for (const [x, z, w, d, h] of [[-40, -30, 14, 16, 34], [-38, 10, 12, 18, 26], [42, -20, 16, 14, 40], [40, 22, 14, 18, 30],
      [0, -42, 30, 12, 36], [-10, 44, 26, 12, 28], [30, 44, 14, 12, 44], [-36, 42, 14, 14, 22]]) {
      D(x - w / 2, x + w / 2, z - d / 2, z + d / 2, ST, ST + h, '#7d7a76', SOFT);
    }
  },
});

;
/* ==== js/maps/toyroom.js ==== */
// TOY ROOM - you're tiny, in a kid's bedroom (60 x 60): a wooden-block castle on the rug in the middle,
// a toy train looping round it, and the furniture and toys round the walls.
// THE RULE: steps of 1.4 everywhere (1.4 -> 2.8 -> 4.2 -> 5.6 ...), a small vocabulary (plain blocks,
// books, rulers, cars) and one color per job:
//   honey wood (0)  the floor; deep blue the rug (floor too)
//   sage            the room's walls - too tall to climb, nobody stands on them
//   purple          furniture (bed frame, desk, bookshelf, chair) - its faces stop you
//   red/blue/yellow/green   toys (blocks, books, train, cars); pink the soft things (bed, keep, erasers)
//   a pale tint of the body color on every top you can stand on (like a painted toy's lighter lid)
//   orange = kick walls
//
//   CASTLE     (middle) four block towers (5.6), walls between them (4.2) with an arch through each,
//              a keep in the courtyard (8.4): the pads in two courtyard corners throw you onto it.
//              Steps up the outside of every wall (1.4 -> 2.8 -> wall 4.2 -> tower 5.6)
//   TRAIN      a track loop round the castle (13m out); a parked train on the east side to vault,
//              a tunnel on the west side (its roof 4.2, a jump from the castle's west wall)
//   BED        (NW) top 4.2: climb the blanket hanging off its side, or the book steps at its foot;
//              pillows 5.4, headboard 7.0; run underneath it (2.2 high)
//   RULERS     two rulers at 4.2 link bed -> toy chest -> the desk's drawers along the north wall
//   DESK       (NE) the drawers are pulled out as steps (1.4, 2.8, 4.2) up to the desk top (5.6);
//              under it is open, a chair in front to run under; a lamp on top
//   BOOKSHELF  (E wall) rows at 0.4, 2.8, 5.6 to run along inside, top 8.4: the desk top runs straight
//              into the 5.6 row; two orange bookends 2.8 apart in front of it - kick up them to the top
//   GARAGE     (E) a toy garage to run through (roof 4.2), a car track ramp up the east wall onto it
//   PLAYROOM   (S, SW, W, SE) a book staircase (to 5.6), a block stack in the corner (1.4, 2.8, 5.6),
//              a crayon box (5.6), toy cars to run under, a ring stacker, pencils laid on erasers
//              (slide under, 1.2), crayons to hop
// (+z is "south"; the door is on the south wall)
defineMap({
  id: 'toyroom',
  accent: ['#c0392b', '#2a5db0'],
  name: 'Toy Room',
  blurb: "You're tiny in a kid's bedroom: a block castle, a toy train, and the bed, desk and bookshelf to climb.",
  env: 'fog',
  // a soft, pale day outside (not a hard blue lid over the room); strong, form-giving light (like Container Yard / Sandstorm), so the
  // colors below are deeper than they look in the game
  sky: '#b4d4ea',
  fog: [60, 190],
  hemi: ['#fff6e8', '#6a5a48', 1.35],
  sun: [2.0, 70, 80, 45],
  outlineColor: '#241a2e',
  size: 36,
  killY: -6,
  menuCam: { r: 42, y: 26 },
  spawns: [
    [-10, 0, -17], [10, 0, 17],
    [19, 0, -12], [-19, 0, 12],
    [19.5, 0, 6], [-17, 0, -6],
    [-4, 0, 20], [4, 0, -18],
    [-24, 0, 18.5], [25, 0, -14.5],
    [0, 0, 3.5], [0, 0, -3.5],
  ],
  seekerSpawn: [0, 8.4, 0],
  centerSpot: [0, 8.4, 0],

  build(k) {
    const FLOOR = '#87582c', RUG = '#1d5683', WALLP = '#3d7f6a', FURN = '#4f3a8e';
    const RED = '#ae2a1c', BLUE = '#1c4b9e', YEL = '#d48a08', GRN = '#277f34', PINK = '#bc4a74';
    const WHITE = '#d8d0c0', DARK = '#2a2430';
    const NO = { tex: 'none' }, SOFT = { tex: 'none', outline: false, noShadow: true };
    // the top of a block: its body color lifted a third of the way to a warm white (a painted toy's lighter lid)
    const lift = (hex, t = 0.36) => {
      const a = parseInt(hex.slice(1), 16), b = 0xfff1dc;
      const m = (sh) => Math.round(((a >> sh) & 255) * (1 - t) + ((b >> sh) & 255) * t);
      return '#' + [16, 8, 0].map((sh) => m(sh).toString(16).padStart(2, '0')).join('');
    };

    // a box by its extents (y0 = bottom)
    const B = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    // a tinted top on a block (looks only, 2cm proud)
    const cap = (x0, x1, z0, z1, y, col) => D(x0, x1, z0, z1, y, y + 0.02, lift(col));
    // a block with a tinted top (books and alphabet blocks are plain blocks too)
    const S = (x0, x1, z0, z1, y0, y1, col) => { B(x0, x1, z0, z1, y0, y1, col); cap(x0, x1, z0, z1, y1, col); };

    // ===================== THE ROOM =====================
    ground(k, 64, 64, FLOOR);   // flush with the walls' outer faces (no floor lip showing outside the room)
    // the rug under the castle and the train (an octagon)
    k.deco(0, 0.004, 0, 34, 0.02, 34, RUG, SOFT);
    k.deco(0, 0.004, 0, 34, 0.02, 34, RUG, Object.assign({ rot: Math.PI / 4 }, SOFT));

    // the walls: 13m (2.6m over the bookshelf top, the highest place to stand), invisible above
    const WALL_H = 13;
    for (const s of [1, -1]) {
      B(-32, 32, s > 0 ? 30 : -32, s > 0 ? 32 : -30, 0, WALL_H, WALLP);
      B(s > 0 ? 30 : -32, s > 0 ? 32 : -30, -30, 30, 0, WALL_H, WALLP);
      k.wall(0, -2, s * 32.5, 66, 62, 1);
      k.wall(s * 32.5, -2, 0, 1, 62, 66);
      // nobody stands on (or pulls up onto) the wall's top: an invisible block on it, reaching past its inner edge
      k.wall(0, WALL_H - 0.2, s * 31.45, 66, 53, 3.1);
      k.wall(s * 31.45, WALL_H - 0.2, 0, 3.1, 53, 66);
    }
    // the window (north wall, over the toy chest): sky panes in a white frame
    const SKYP = { tex: 'none', emissive: '#8ec8ee', outline: false };
    D(-7.5, 3.5, -29.93, -29.9, 6, 12, '#bfe4ff', SKYP);
    for (const x of [-7.5, -2, 3.5]) D(x - 0.25, x + 0.25, -29.9, -29.85, 6, 12, WHITE);
    for (const y of [6, 9, 12]) D(-7.75, 3.75, -29.9, -29.85, y - 0.25, y + 0.25, WHITE);
    // the door (south wall, east of the book stairs)
    D(10, 16, 29.9, 29.94, 0, 10, WHITE);

    // ===================== THE CASTLE (middle) =====================
    // everything here is placed four times, turned a quarter turn each time. Local coords: t along the
    // wall, n out from the middle (the +z side is the one written)
    const TOWER = [RED, BLUE, YEL, GRN], WALLC = [YEL, GRN, RED, BLUE], STEP = [BLUE, RED, GRN, YEL];
    for (let q = 0; q < 4; q++) {
      // local (t, n) -> world (x, z): q = 0 is the +z side
      const rot = (t, n) => [[t, n], [n, -t], [-t, -n], [-n, t]][q];
      const R = (t0, t1, n0, n1) => {
        const [ax, az] = rot(t0, n0), [bx, bz] = rot(t1, n1);
        return [Math.min(ax, bx), Math.max(ax, bx), Math.min(az, bz), Math.max(az, bz)];
      };
      const Sq = (t0, t1, n0, n1, y0, y1, col) => S(...R(t0, t1, n0, n1), y0, y1, col);
      // the tower at this side's +t end
      Sq(5, 8, 5, 8, 0, 5.6, TOWER[q]);
      // the wall: two pillars and a lintel over a 3.2m arch (2.8 tall)
      Sq(-5, -1.6, 5, 8, 0, 4.2, WALLC[q]);
      Sq(1.6, 5, 5, 8, 0, 4.2, WALLC[q]);
      Sq(-1.6, 1.6, 5, 8, 2.8, 4.2, TOWER[(q + 1) % 4]);
      // steps up the outside: 1.4 by the tower, 2.8 by the arch -> the wall top (4.2)
      Sq(4.8, 7.6, 8, 10.6, 0, 1.4, STEP[q]);
      Sq(2.0, 4.8, 8, 10.6, 0, 2.8, STEP[(q + 2) % 4]);
    }
    // the keep (8.4), pads in two courtyard corners throw you onto it
    S(-2, 2, -2, 2, 0, 8.4, PINK);
    for (const s of [1, -1]) k.pad(s * 3.5, 0, s * 3.5, 1.2, 1.2, 25, { aim: [0, 0, 3.3] });
    // a flag on the keep (looks only)
    D(-1.75, -1.55, -1.75, -1.55, 8.4, 12, DARK);
    D(-1.55, 0.6, -1.7, -1.6, 10.8, 12, RED);

    // ===================== THE TRAIN =====================
    // the track: a loop 13m out (looks only), just its two rails
    const TR = 13;
    for (const s of [1, -1]) for (const o of [-0.6, 0.6]) {
      D(s * TR + o - 0.1, s * TR + o + 0.1, -TR - 0.7, TR + 0.7, 0.02, 0.1, DARK, SOFT);
      D(-TR - 0.7, TR + 0.7, s * TR + o - 0.1, s * TR + o + 0.1, 0.02, 0.1, DARK, SOFT);
    }
    // the tunnel (west side): run through along the track, its roof 4.2 (block steps up its west side)
    S(-15, -14.2, -4, 4, 0, 3, GRN);
    S(-11.8, -11, -4, 4, 0, 3, GRN);
    S(-15, -11, -4, 4, 3, 4.2, GRN);
    S(-17.8, -15, -4, -1.2, 0, 2.8, YEL);
    S(-20.6, -17.8, -4, -1.2, 0, 1.4, RED);
    // the train (east side, parked): engine, a flatbed with a block on it, an open wagon
    const TX = TR;
    B(TX - 1, TX + 1, -6, -1, 0.3, 1.4, RED);                            // engine chassis
    B(TX - 1.1, TX + 1.1, -6, -3, 0, 0.3, DARK);
    B(TX - 1.1, TX + 1.1, -2.6, -1.4, 0, 0.3, DARK);
    S(TX - 0.8, TX + 0.8, -6, -3, 1.4, 2.6, RED);                          // boiler
    S(TX - 1, TX + 1, -3, -1, 1.4, 3.4, BLUE);                             // cab
    // flatbed
    B(TX - 1, TX + 1, -0.4, 4.6, 0.3, 1.4, YEL);
    cap(TX - 1, TX + 1, -0.4, 1.6, 1.4, YEL);
    S(TX - 1, TX + 1, 1.6, 3.6, 1.4, 2.8, BLUE);
    cap(TX - 1, TX + 1, 3.6, 4.6, 1.4, YEL);
    B(TX - 0.9, TX + 0.9, -0.4, 4.6, 0, 0.3, DARK);
    // open wagon
    B(TX - 1, TX + 1, 5.2, 10.2, 0, 0.4, DARK);
    S(TX - 1, TX + 1, 5.2, 10.2, 0.4, 1.4, GRN);

    // ===================== THE BED (NW) =====================
    S(-30, -15.5, -30, -28.5, 0, 7.0, FURN);                               // headboard
    // frame (2.2 -> 3.0) on legs, mattress + blanket (3.0 -> 4.2): run underneath (2.2 high)
    B(-30, -15.5, -28.5, -18, 2.2, 3.0, FURN);
    B(-30, -15.5, -28.5, -18, 3.0, 4.2, PINK);
    cap(-30, -15.5, -28.5, -18, 4.2, PINK);
    for (const [x, z] of [[-29.4, -18.6], [-16.1, -18.6], [-16.1, -27.9]]) B(x - 0.6, x + 0.6, z - 0.6, z + 0.6, 0, 2.2, FURN);
    // the blanket hangs down the east side: climb it (0 -> 4.2)
    k.ramp(-12.25, -22, 6.5, 6, 0, 4.2, '-x', PINK);
    // pillows (5.4) -> headboard (7.0)
    S(-29.5, -24.3, -28.4, -25.4, 4.2, 5.4, PINK);
    S(-22.8, -17.6, -28.4, -25.4, 4.2, 5.4, PINK);
    // book steps at the foot of the bed: 1.4 -> 2.8 -> the bed (4.2)
    S(-25.2, -22.2, -18, -15.4, 0, 1.4, BLUE);
    S(-25.0, -22.4, -18, -15.6, 1.4, 2.8, YEL);
    S(-22.2, -19, -17.8, -15.2, 0, 1.4, GRN);

    // ===================== THE NORTH WALL: rulers, toy chest =====================
    S(-8, 2, -30, -23, 0, 4.2, RED);                                       // toy chest (4.2)
    // big blocks up to it: 1.4 -> 2.8 -> the chest (4.2)
    S(-6.6, -3.8, -23, -20.2, 0, 2.8, BLUE);
    S(-6.6, -3.8, -20.2, -18.8, 0, 1.4, GRN);
    // rulers at 4.2: bed -> chest, chest -> the top drawer
    S(-15.5, -8, -27.6, -26, 3.9, 4.2, YEL);
    S(2, 10, -27.6, -26, 3.9, 4.2, YEL);

    // ===================== THE DESK (NE) =====================
    S(13, 17.5, -30, -21.5, 0, 5.0, FURN);                                // drawer pedestal
    // the drawers, pulled out to the west as steps: 1.4 -> 2.8 -> 4.2 -> the desk top (5.6)
    S(7, 13, -29.4, -22.1, 0, 1.4, FURN);
    S(8.5, 13, -29.4, -22.1, 1.4, 2.8, FURN);
    S(10, 13, -29.4, -22.1, 2.8, 4.2, FURN);
    S(13, 26.5, -30, -21.5, 5.0, 5.6, FURN);                             // the top
    B(25.3, 26.5, -22.7, -21.5, 0, 5.0, FURN);                            // legs
    B(25.3, 26.5, -30, -28.8, 0, 5.0, FURN);
    // a lamp on the desk (light only up high)
    S(21.6, 24.6, -29.6, -27.0, 5.6, 6.0, YEL);
    B(22.9, 23.3, -28.5, -28.1, 6.0, 9.4, YEL);
    const GLOW = { tex: 'none', emissive: '#ffcf5a', outline: false, noShadow: true };
    D(21.3, 24.9, -30, -26.6, 9.4, 10.0, '#ffe08a', GLOW);
    D(21.8, 24.4, -29.6, -27.0, 10.0, 10.6, '#ffe08a', GLOW);
    // the shade is solid and nothing stands on it or on the post (it'd be the room's highest perch, a jump off
    // the bookshelf top): an invisible block from the shade up
    k.wall(23.1, 9.4, -28.3, 3.6, 30, 3.4);
    // the chair in front (seat 2.8 on legs: run under it), its back 6.0
    B(19, 23.5, -18.6, -14.6, 2.2, 2.8, FURN);
    cap(19, 23.5, -18.6, -14.6, 2.8, FURN);
    for (const [x, z] of [[19.3, -18.3], [23.2, -18.3], [19.3, -14.9], [23.2, -14.9]]) B(x - 0.3, x + 0.3, z - 0.3, z + 0.3, 0, 2.2, FURN);
    B(19, 23.5, -15.0, -14.4, 2.8, 6.0, FURN);

    // ===================== THE BOOKSHELF (E wall) =====================
    // rows to run along inside (0.4, 2.8, 5.6), top 8.4; open on the west side
    const SX0 = 26.5, SZ0 = -30, SZ1 = -4;
    S(SX0, 30, SZ0, SZ1, 0, 0.4, FURN);
    for (const y of [2.8, 5.6, 8.4]) S(SX0, 30, SZ0, SZ1, y - 0.3, y, FURN);
    S(SX0, 30, SZ1 - 0.6, SZ1, 0, 8.4, FURN);                            // end panel
    S(SX0, 30, -17.3, -16.7, 0, 8.4, FURN);                               // middle divider
    // a row of books standing in the shelf, one color a row (can't stand on them - too close under the next shelf)
    const shelfBooks = (z0, n, y0, col) => B(27.2, 30, z0, z0 + n * 0.6 - 0.04, y0, y0 + 2.0, col);
    shelfBooks(-14.2, 6, 0.4, BLUE);
    shelfBooks(-29.4, 5, 2.8, RED);
    shelfBooks(-8.2, 5, 2.8, GRN);
    shelfBooks(-15.8, 7, 5.6, YEL);
    shelfBooks(-21.6, 7, 0.4, RED);   // up to the divider: no pocket shut in behind the book step
    // orange bookends in front of the shelf, 2.8 apart: kick up between them to the top (8.4)
    kickShaft(k, 24.75, -10.6, 'x', 3.5, 0, 8.4, '#ff7340');
    // a book step in front: 1.4 -> the first row (2.8)
    S(23.6, 26.5, -20.4, -17.8, 0, 1.4, RED);

    // ===================== THE GARAGE + CAR TRACK (E) =====================
    // a toy garage (roof 4.2): doors on its west and north sides
    const GX0 = 22, GX1 = 30, GZ0 = -1, GZ1 = 6, GT = 0.6, GD = 2.8;
    B(GX0, GX0 + GT, GZ0, 0.6, 0, 3.6, YEL);                              // west wall, door z 0.6..4.4
    B(GX0, GX0 + GT, 4.4, GZ1, 0, 3.6, YEL);
    B(GX0, GX0 + GT, 0.6, 4.4, GD, 3.6, YEL);
    B(GX0 + GT, 24.6, GZ0, GZ0 + GT, 0, 3.6, YEL);                        // north wall, door x 24.6..27.8
    B(27.8, GX1, GZ0, GZ0 + GT, 0, 3.6, YEL);
    B(24.6, 27.8, GZ0, GZ0 + GT, GD, 3.6, YEL);
    B(GX0 + GT, GX1, GZ1 - GT, GZ1, 0, 3.6, YEL);                         // south wall
    S(GX0, GX1, GZ0, GZ1, 3.6, 4.2, RED);                                 // roof
    // the car track: up the east wall from the floor (z 24) onto the garage roof (4.2)
    k.ramp(28, 15, 4, 18, 0, 4.2, '-z', BLUE);

    // ===================== THE PLAYROOM (S, SW, W, SE) =====================
    // the book staircase against the south wall: 1.4 -> 2.8 -> 4.2 -> 5.6
    S(-9.5, 3.5, 23.6, 30, 0, 1.4, BLUE);
    S(-8.2, 2.2, 25.0, 30, 1.4, 2.8, RED);
    S(-6.6, 0.8, 26.4, 30, 2.8, 4.2, GRN);
    S(-5.0, -0.8, 27.8, 30, 4.2, 5.6, YEL);
    // blocks stacked in the SW corner: 1.4 -> 2.8 -> a wide top at 5.6 (no lonely perch above it)
    S(-30, -27.2, 21.6, 24.4, 0, 2.8, RED);
    S(-27.2, -24.4, 21.6, 24.4, 0, 2.8, BLUE);
    S(-27.2, -24.4, 24.4, 27.2, 0, 2.8, YEL);
    S(-27.2, -24.4, 27.2, 30, 0, 2.8, GRN);
    S(-30, -27.2, 24.4, 30, 0, 5.6, BLUE);
    S(-24.4, -21.6, 21.6, 23.0, 0, 1.4, GRN);
    S(-27.2, -24.4, 19.0, 21.6, 0, 1.4, YEL);
    // the crayon box (W wall, 5.6); book steps up (1.4, 2.8, 4.2)
    S(-30, -26, -3, 3, 0, 5.6, YEL);
    S(-26, -23.2, -3, 0, 0, 4.2, GRN);
    S(-23.2, -20.6, -3, 0, 0, 2.8, BLUE);
    S(-23.2, -20.6, 0, 2.8, 0, 1.4, RED);
    // toy cars: a body on wheels (run or slide under it, 1.2 high), a cab on top (2.6)
    const car = (cx, cz, alongX, col) => {
      const L = 2.6, W = 1.5;
      // (a along the car, b across it)
      const P = (a0, a1, b0, b1, y0, y1, c, f = S) => (alongX ? f(cx + a0, cx + a1, cz + b0, cz + b1, y0, y1, c) : f(cx + b0, cx + b1, cz + a0, cz + a1, y0, y1, c));
      P(-L, L, -W, W, 1.2, 1.8, col);                                      // body
      P(-0.8, 1.6, -W + 0.2, W - 0.2, 1.8, 2.6, col);                      // cab
      for (const a of [-L + 0.3, L - 1.1]) for (const b of [-W, W - 0.5]) P(a, a + 0.8, b, b + 0.5, 0, 1.2, DARK, B);   // wheels
    };
    car(-21, -10, false, RED);
    car(-21, 9.5, true, BLUE);
    car(6, 20.5, true, GRN);
    // two blocks (2.8 and 1.4) and a ring stacker in the SE corner
    S(14.1, 16.9, 24.1, 26.9, 0, 2.8, RED);
    S(11.9, 13.3, 25.5, 26.9, 0, 1.4, BLUE);
    // ring stacker: square rings (1.4 -> 2.8), a solid cap on top (4.2); each rim a metre wide, so CPUs climb it too
    const rings = (x, z) => {
      [[0, 1.4, 6.2, RED], [1.4, 2.8, 4.2, YEL]].forEach(([y0, y1, w, c]) => {
        const h = w / 2, n = w * 0.3;
        S(x - h, x + h, z - h + n, z + h - n, y0, y1, c);
        S(x - h + n, x + h - n, z - h, z - h + n, y0, y1, c);
        S(x - h + n, x + h - n, z + h - n, z + h, y0, y1, c);
      });
      S(x - 1, x + 1, z - 1, z + 1, 2.8, 4.2, GRN);
    };
    rings(21, 21);
    // pencils laid on two erasers: slide under (1.2) or hop over (1.5)
    const pencil = (x0, x1, z0, z1) => {
      const alongX = x1 - x0 > z1 - z0;
      if (alongX) { B(x0, x0 + 0.5, z0, z1, 0, 1.5, PINK); B(x1 - 0.5, x1, z0, z1, 0, 1.5, PINK); B(x0 + 0.5, x1 - 0.5, z0 + 0.1, z1 - 0.1, 1.2, 1.5, YEL); }
      else { B(x0, x1, z0, z0 + 0.5, 0, 1.5, PINK); B(x0, x1, z1 - 0.5, z1, 0, 1.5, PINK); B(x0 + 0.1, x1 - 0.1, z0 + 0.5, z1 - 0.5, 1.2, 1.5, YEL); }
    };
    pencil(-3, 3, -17.6, -17.0);
    pencil(17.4, 18.0, -3, 3);
    pencil(-6, 0, 17.6, 18.2);
    pencil(-17.4, -16.8, -14, -10);
    // crayons lying on the floor (hop them, 0.8)
    const crayon = (x, z, len, a, col) => k.box(x, 0, z, len, 0.8, 0.8, col, { tex: 'none', rot: a });
    crayon(-17, 22, 5, 0.4, BLUE);
    crayon(18, 14, 5, -0.6, GRN);
    crayon(-14.5, -26.5, 4, 0.2, YEL);
    crayon(7, -14.5, 4, 1.2, RED);
    // more blocks round the room (steps and things to vault)
    S(17, 19.8, 9, 11.8, 0, 2.8, RED);
    S(19.8, 21.2, 9, 11.8, 0, 1.4, BLUE);
    S(-19.4, -16.6, 14.8, 17.6, 0, 2.8, GRN);
    S(-16.6, -15.2, 14.8, 17.6, 0, 1.4, YEL);
    S(8.4, 11.2, 22.6, 25.4, 0, 1.4, YEL);
    // block arches: two block pillars and a long block across (2.8 -> 4.2): run through or climb over
    S(15, 17.8, -9, -6.2, 0, 2.8, YEL);
    S(20.6, 23.4, -9, -6.2, 0, 2.8, GRN);
    S(15, 23.4, -9, -6.2, 2.8, 4.2, RED);
    S(13.6, 15, -9, -6.2, 0, 1.4, BLUE);
    S(-16, -13.2, 18, 20.8, 0, 2.8, BLUE);
    S(-16, -13.2, 24, 26.8, 0, 2.8, RED);
    S(-16, -13.2, 18, 26.8, 2.8, 4.2, YEL);
    S(-16, -13.2, 26.8, 28.2, 0, 1.4, GRN);
  },
});

;
/* ==== js/maps/ship.js ==== */
// THE SHIP - a double-ended cargo ferry at sea (65 x 27): both ends are a bow, so the ship is the same
// turned half a turn round its middle - every route, perch and stair on one half has its twin on the other.
// THE RULE: the heights the movement likes (deck 0, steps 1.4 -> 2.8 -> 4, top deck 8) and one color per job:
//   grey            the floors (main deck, hold floor)
//   white           every wall that stops you (deckhouse, bridge, the raised ends)
//   teak            every top you can stand on up high (boat deck, bridge roof, forecastle tops, stairs)
//   navy            ship's steel: the hull and the hatch coamings
//   yellow          cargo gear and crates to climb (crane, booms, step crates, funnels)
//   red/blue/green  containers; white rails; orange = kick walls
//
//   DECKHOUSE  (middle, 14 x 12, top 4) a doorway in all four sides, a pillar inside, and two stairs up
//              through the roof onto the BOAT DECK (4), which runs out over both sides as wings
//              (walkways under them). Lifeboats on the wings (5.4), a funnel on each wing
//   BRIDGE     (on the boat deck, 6 x 6, roof 8) run through it (two doors); crate steps up its outside
//              (5.4 -> 6.8 -> roof) on two sides
//   BOOMS      from the bridge roof a 1.2m crane boom runs out along the middle to each end, to the crane
//              cab (8) on the forecastle: the top deck is one long loop, reached from four places
//   CARGO DECK (each half) a hatch (1.4) with three containers on it (4) - one hollow, run through it;
//              walkways down both sides with a slide bar across each; crate steps to the boat deck
//   FORECASTLE (each end, top 4) stairs up one side, crate steps up the other, and an orange kick chimney
//              between it and the end container
//   THE HOLD   (-4) under the whole cargo deck, end to end: pillars and crates for cover. Six ways in
//              and out: two stairs and a hatch with crate steps in each half
//   THE SEA    rails all round (1.1m): jump them and you're overboard
// (+x is one end, -x the other; everything below is built twice, the second time turned half a turn)
defineMap({
  id: 'ship',
  accent: ['#23408e', '#d9a514'],
  name: 'The Ship',
  blurb: 'A double-ended cargo ferry at sea: run its hold end to end, climb the containers and forecastles, race along the crane booms to the bridge.',
  env: 'sky',
  sky: '#a9d6ff',
  fog: [120, 400],
  hemi: ['#eaf4ff', '#5a6470', 0.9],
  sun: [1.0, 30, 55, 20],
  size: 36,
  sea: -8,
  killY: -10,
  outlineColor: '#1a2233',
  menuCam: { r: 50, y: 28 },
  spawns: [
    [8.3, 0, 1], [-8.3, 0, -1],
    [21.6, 0, 6], [-21.6, 0, -6],
    [15.5, 0, 7.3], [-15.5, 0, -7.3],
    [12, 0, -8.5], [-12, 0, 8.5],
    [0, 0, 9], [0, 0, -9],
    [3, 0, 2], [-3, 0, -2],
    [28, 4, -6], [-28, 4, 6],
    [16, -4, 0], [-16, -4, 0],
  ],
  seekerSpawn: [0, 8, 0],
  centerSpot: [0, 8, 0],

  build(k) {
    // (deeper than they look: the strong light brightens them - like Container Yard's colors)
    const DECK = '#646a73', WHITE = '#c9ccd1', TEAK = '#9c7a4c', NAVY = '#23408e', BOOT = '#8e2a24';
    const YEL = '#d9a514', RED = '#a8322d', BLUE = '#2a4c9e', GREEN = '#2f7d4f', RAIL = '#e8ebef';
    const GLASS = '#1b2430', DARK = '#2b2f35';
    const NO = { tex: 'none' }, KICK = { tex: 'kick' };

    // a box by its extents (y0 = bottom)
    const B = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, z0, z1, y0, y1, col, o = NO) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const W = (x0, x1, z0, z1, y0, y1) => k.wall((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0);
    // a plate x0..x1 / z0..z1 (top y1) with rectangular holes, cut into as few boxes as it takes
    const plate = (x0, x1, z0, z1, y0, y1, holes, col) => {
      const xs = [...new Set([x0, x1, ...holes.flatMap((h) => [h[0], h[1]])])].filter((v) => v >= x0 && v <= x1).sort((a, b) => a - b);
      const zs = [...new Set([z0, z1, ...holes.flatMap((h) => [h[2], h[3]])])].filter((v) => v >= z0 && v <= z1).sort((a, b) => a - b);
      const nx = xs.length - 1, nz = zs.length - 1;
      const open = (i, j) => { const cx = (xs[i] + xs[i + 1]) / 2, cz = (zs[j] + zs[j + 1]) / 2; return holes.some((h) => cx > h[0] && cx < h[1] && cz > h[2] && cz < h[3]); };
      const used = [...Array(nz)].map(() => new Array(nx).fill(false));
      for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) {
        if (used[j][i] || open(i, j)) continue;
        let i1 = i; while (i1 + 1 < nx && !used[j][i1 + 1] && !open(i1 + 1, j)) i1++;
        let j1 = j;
        for (;;) {
          if (j1 + 1 >= nz) break;
          let ok = true;
          for (let a = i; a <= i1 && ok; a++) if (used[j1 + 1][a] || open(a, j1 + 1)) ok = false;
          if (!ok) break;
          j1++;
        }
        for (let b = j; b <= j1; b++) for (let a = i; a <= i1; a++) used[b][a] = true;
        B(xs[i], xs[i1 + 1], zs[j], zs[j1 + 1], y0, y1, col);
      }
    };
    // a rail along a line (1.1 tall): an invisible wall with a solid white top bar, posts and a mid bar to look at
    const rail = (x0, x1, z0, z1, y) => {
      const alongX = x1 - x0 > z1 - z0;
      const c = alongX ? (z0 + z1) / 2 : (x0 + x1) / 2, t = 0.06;
      const R = (a0, a1, y0, y1, solid) => (alongX ? (solid ? B : D)(a0, a1, c - t, c + t, y0, y1, RAIL) : (solid ? B : D)(c - t, c + t, a0, a1, y0, y1, RAIL));
      const a0 = alongX ? x0 : z0, a1 = alongX ? x1 : z1;
      if (alongX) W(x0, x1, c - t, c + t, y, y + 0.98); else W(c - t, c + t, z0, z1, y, y + 0.98);
      R(a0, a1, y + 0.98, y + 1.1, true);
      R(a0, a1, y + 0.5, y + 0.56, false);
      const n = Math.max(1, Math.round((a1 - a0) / 2));
      for (let i = 0; i <= n; i++) { const a = a0 + (a1 - a0) * i / n; R(Math.max(a0, a - 0.05), Math.min(a1, a + 0.05), y, y + 0.98, false); }
    };

    // ===================== HULL =====================
    // the cargo deck runs x -23..23 at full beam (z -13..13); the raised ends (forecastles, top 4) taper
    const BANDS = [[23, 26, 13.4], [26, 29, 11], [29, 31, 8.5], [31, 32.6, 5.5]];   // [x0, x1, half beam]
    // sides of the midship hull (solid, from under the sea to the deck), with a red band at the waterline
    for (const s of [1, -1]) {
      B(-23, 23, s > 0 ? 13 : -13.4, s > 0 ? 13.4 : -13, -9, 0, NAVY);
      D(-23.02, 23.02, s > 0 ? 13.38 : -13.42, s > 0 ? 13.42 : -13.38, -9, -6.6, BOOT);
    }
    // the hold's floor (-4) on the bottom of the hull
    B(-23, 23, -13, 13, -9, -4.3, NAVY);
    B(-23, 23, -13, 13, -4.3, -4, DECK);

    // the main deck (0), with the holes for the hold's stairs and hatches (added below)
    const deckHoles = [];

    // ===================== DECKHOUSE + BOAT DECK (middle) =====================
    // walls 0.4 thick from 0 to 3.6 (the boat deck's 0.4 slab on top). Doorways 3m wide, 3m tall
    const wallRun = (x0, x1, z0, z1, door) => {   // a straight wall with an optional doorway [a0, a1] along it
      const alongX = x1 - x0 > z1 - z0;
      const seg = (a0, a1, y0, y1) => (alongX ? B(a0, a1, z0, z1, y0, y1, WHITE) : B(x0, x1, a0, a1, y0, y1, WHITE));
      const a0 = alongX ? x0 : z0, a1 = alongX ? x1 : z1;
      if (!door) return seg(a0, a1, 0, 3.6);
      seg(a0, door[0], 0, 3.6); seg(door[1], a1, 0, 3.6); seg(door[0], door[1], 3.0, 3.6);
    };
    wallRun(6.6, 7, -6, 6, [-1.5, 1.5]);
    wallRun(-7, -6.6, -6, 6, [-1.5, 1.5]);
    wallRun(-6.6, 6.6, -6, -5.6, [2.5, 5]);
    wallRun(-6.6, 6.6, 5.6, 6, [-5, -2.5]);
    B(-0.6, 0.6, -0.6, 0.6, 0, 3.6, WHITE);   // pillar in the middle
    // the boat deck: the deckhouse roof and its wings out over both sides, with the two stairwells
    plate(-7, 7, -12.6, 12.6, 3.6, 4, [[-6.6, 0.8, -5.8, -4.0], [-0.8, 6.6, 4.0, 5.8]], TEAK);
    // wing posts
    for (const sx of [1, -1]) for (const sz of [1, -1]) B(sx * 6.75 - 0.2, sx * 6.75 + 0.2, sz * 12.35 - 0.2, sz * 12.35 + 0.2, 0, 3.6, WHITE);

    // ----- the bridge (4 -> roof 8) -----
    const bw = (x0, x1, z0, z1, door) => {
      const alongX = x1 - x0 > z1 - z0;
      const seg = (a0, a1, y0, y1) => (alongX ? B(a0, a1, z0, z1, y0, y1, WHITE) : B(x0, x1, a0, a1, y0, y1, WHITE));
      const a0 = alongX ? x0 : z0, a1 = alongX ? x1 : z1;
      if (!door) seg(a0, a1, 4, 7.6);
      else { seg(a0, door[0], 4, 7.6); seg(door[1], a1, 4, 7.6); seg(door[0], door[1], 6.6, 7.6); }
    };
    bw(2.7, 3, -3, 3, [-2.4, -0.6]);
    bw(-3, -2.7, -3, 3, [0.6, 2.4]);
    bw(-2.7, 2.7, -3, -2.7);
    bw(-2.7, 2.7, 2.7, 3);
    B(-3, 3, -3, 3, 7.6, 8, TEAK);
    // windows all round (looks only)
    for (const sg of [1, -1]) {
      D(-2.6, 2.6, sg * 3 - 0.03, sg * 3 + 0.03, 5.8, 7.0, GLASS);
      D(sg * 3 - 0.03, sg * 3 + 0.03, sg > 0 ? 0.4 : -2.8, sg > 0 ? 2.8 : -0.4, 5.8, 7.0, GLASS);
    }
    // a radar mast on the roof (looks only)
    D(-0.15, 0.15, -0.15, 0.15, 8, 11, DARK);
    D(-1.2, 1.2, -0.15, 0.15, 10.4, 10.6, DARK);

    // ===================== EACH HALF (as written, s = 1; then turned half a turn, s = -1) =====================
    for (const s of [1, -1]) {
      const X = (a, b) => (s > 0 ? [a, b] : [-b, -a]);
      const Bs = (x0, x1, z0, z1, y0, y1, col, o) => B(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ds = (x0, x1, z0, z1, y0, y1, col, o) => D(...X(x0, x1), ...X(z0, z1), y0, y1, col, o);
      const Ws = (x0, x1, z0, z1, y0, y1) => W(...X(x0, x1), ...X(z0, z1), y0, y1);
      const Rs = (x0, x1, z0, z1, y) => rail(...X(x0, x1), ...X(z0, z1), y);
      const St = (x, z, dir, w, y0, y1) => stairs(k, s * x, s * z, s > 0 ? dir : (dir[0] === '+' ? '-' : '+') + dir[1], w, y0, y1, TEAK, { run: 0.7 });
      const Ct = (x, y, z, orient, L, hollow, col) => container(k, s * x, y, s * z, orient, L, hollow, col);
      const hole = (x0, x1, z0, z1) => deckHoles.push([...X(x0, x1), ...X(z0, z1)]);
      const crate = (x0, x1, z0, z1, y0, y1) => Bs(x0, x1, z0, z1, y0, y1, YEL);

      // ----- deckhouse stairs up to the boat deck (along its -z wall, climbing +x) -----
      St(-5.5, -4.9, '+x', 1.8, 0, 4);

      // ----- bridge crate steps (+x side): 5.4 -> 6.8 -> the roof (8) -----
      crate(3, 4.6, 1.0, 3.0, 4, 6.8);
      crate(4.6, 6.2, 1.0, 3.0, 4, 5.4);

      // ----- wings: lifeboats (5.4) on davits, a funnel, the rail -----
      for (const sz of [1, -1]) {
        const z0 = sz > 0 ? 9.8 : -12.0, z1 = sz > 0 ? 12.0 : -9.8;
        Bs(1.8, 6.4, z0, z1, 4, 5.0, WHITE);
        Bs(1.9, 6.3, z0 + 0.1, z1 - 0.1, 5.0, 5.4, RED);
        for (const dx of [1.5, 6.5]) {
          Ds(dx, dx + 0.2, z0 + 0.9, z1 - 0.9, 4, 6.2, YEL);
          Ds(dx, dx + 0.2, sz > 0 ? z0 + 0.9 : z0 - 0.4, sz > 0 ? z1 + 0.4 : z1 - 0.9, 6.0, 6.2, YEL);
        }
      }
      Bs(-1.1, 1.1, 7.2, 9.6, 4, 10, YEL);           // funnel (not a perch: see the cap)
      Ds(-1.12, 1.12, 7.18, 9.62, 9.2, 10.02, DARK);
      // an invisible cap: a running jump off the bridge roof (8) still mantles onto the funnel's top (10) -
      // the highest spot on the ship, and one the CPUs can't follow you to
      Ws(-1.1, 1.1, 7.2, 9.6, 10, 14.5);
      Rs(-7, 7, 12.44, 12.56, 4);

      // ----- the cargo deck: a hatch (1.4) and three containers (4) -----
      Bs(10, 20.2, -6, 6, 0, 1.4, NAVY);
      Ct(13.4, 1.4, 4, 'x', 6, false, RED);
      Ct(17.2, 1.4, -4, 'x', 6, false, BLUE);
      Ct(15, 1.4, 0, 'x', 6, true, GREEN);
      // the kick chimney: the blue container's end and the forecastle's face, 2.6 apart
      Bs(20.2, 20.3, -5.2, -2.8, 0, 4, DARK, KICK);
      Bs(22.9, 23, -5.2, -2.8, 0, 4, DARK, KICK);

      // ----- walkways: crate steps up to the boat deck wing, slide bars across both sides -----
      crate(7, 9.4, 8.4, 10.8, 0, 2.8);
      crate(9.4, 11.8, 8.4, 10.8, 0, 1.4);
      const rack = (x, z0, z1) => {
        Bs(x - 0.15, x + 0.15, z0, z0 + 0.3, 0, 1.5, DARK);
        Bs(x - 0.15, x + 0.15, z1 - 0.3, z1, 0, 1.5, DARK);
        Bs(x - 0.15, x + 0.15, z0 + 0.3, z1 - 0.3, 1.2, 1.5, YEL);
      };
      rack(13.5, 6.1, 10.7);
      rack(17.5, -12.9, -6.1);

      // ----- the hold: two stairs down (one each side) and a hatch with crate steps -----
      St(9, 11.7, '+x', 1.8, -4, 0);
      hole(11, 15.3, 10.8, 12.6);
      St(9, -11.7, '+x', 1.8, -4, 0);
      hole(11, 15.3, -12.6, -10.8);
      hole(7.4, 9.6, -6.6, -2.0);
      crate(7.6, 9.4, -4.3, -2.2, -4, -1.2);
      crate(7.6, 9.4, -6.4, -4.3, -4, -2.6);
      // pillars and crates in the hold
      for (const [x, z] of [[4, 6.5], [4, -6.5], [12.5, 6.5], [12.5, -6.5], [20, 6.5], [20, -6.5]]) Bs(x - 0.4, x + 0.4, z - 0.4, z + 0.4, -4, -0.4, WHITE);
      // (low crates down here - 1m, a vault - so nobody bumps the ceiling jumping onto them)
      crate(17.5, 19.9, 2.5, 4.9, -4, -3);
      crate(1, 3.4, 8.4, 10.8, -4, -3);
      crate(15, 16.2, -9, -4, -4, -3);
      // a bulkhead across the hold under the deckhouse's end, three doorways through it (breaks the long view)
      for (const [a, b] of [[-13, -10], [-7, -2], [2, 7], [10.5, 13]]) Bs(6, 6.4, a, b, -4, -0.4, WHITE);
      for (const [a, b] of [[-10, -7], [-2, 2], [7, 10.5]]) Bs(6, 6.4, a, b, -1.0, -0.4, WHITE);
      // lights on the hold's ceiling (looks only)
      for (const x of [4, 12, 20]) Ds(x - 0.6, x + 0.6, -0.3, 0.3, -0.48, -0.4, '#fff3c4', { tex: 'none', emissive: '#fff3c4' });
      // the hold's end wall, a doorway into the chain locker tunnel
      Bs(22.6, 23, -13, -2, -4, 0, WHITE);
      Bs(22.6, 23, 2, 13, -4, 0, WHITE);

      // ----- the forecastle (top 4), solid from the sea up, tapering to the stem -----
      // THE CHAIN LOCKER: a tunnel (4 wide, 4 tall) from the hold's end wall out under the forecastle to a
      // shaft that opens in its deck near the stem: drop down it into the hold, or wall-kick up it (orange,
      // 2.6 apart) - so the tip of the bow is never a corner to be trapped in
      const SH = [29.5, 31.5], TW = 2;   // (the tunnel 4m wide - too wide to kick up - the shaft's kick walls inside it)
      for (const [x0, x1, hb] of BANDS) {
        Bs(x0, x1, -hb, hb, -9, -4, NAVY);
        Bs(x0, x1, -hb, -TW, -4, 3.7, NAVY);
        Bs(x0, x1, TW, hb, -4, 3.7, NAVY);
        // the tunnel's roof (none over the shaft)
        const a = Math.max(x0, SH[1]), b = Math.min(x1, SH[0]);
        if (b > x0) Bs(x0, b, -TW, TW, 0, 3.7, NAVY);
        if (x1 > a) Bs(a, x1, -TW, TW, -4, 3.7, NAVY);
        Ds(x0 - 0.02, x1 + 0.02, -hb - 0.02, hb + 0.02, -9, -6.6, BOOT);
      }
      for (const [x0, x1, hb] of BANDS) {
        const [p0, p1] = X(x0, x1), [q0, q1] = X(-hb, hb), [h0, h1] = X(SH[0], SH[1]), [g0, g1] = X(-TW, TW);
        plate(p0, p1, q0, q1, 3.7, 4, [[h0, h1, g0, g1]], TEAK);
      }
      Ds(22.97, 23, -13.4, 13.4, 0, 3.7, WHITE);   // the face you see from the cargo deck
      Bs(SH[0], SH[1], -TW, -1.3, -4, 4, DARK, KICK);
      Bs(SH[0], SH[1], 1.3, TW, -4, 4, DARK, KICK);
      Ds(23, SH[1], -TW, TW, -4, -3.98, DECK);
      // two crate steps at the shaft's foot (1.2 -> 2.4): the kick up it starts 2.4m higher (an 8m chimney was
      // where CPUs got stuck, kicking and falling back for half a round)
      crate(SH[0], 30.5, -1.3, 1.3, -4, -2.8);
      crate(30.5, SH[1], -1.3, 1.3, -4, -1.6);
      Ds(26.5 - 0.6, 26.5 + 0.6, -0.3, 0.3, -0.08, 0, '#fff3c4', { tex: 'none', emissive: '#fff3c4' });
      // rails round the forecastle
      let prev = 13.4;
      for (const [x0, x1, hb] of BANDS) {
        const zr = hb - 0.15;
        Rs(x0, x1, zr - 0.06, zr + 0.06, 4);
        Rs(x0, x1, -zr - 0.06, -zr + 0.06, 4);
        if (x0 > 23) {   // the step in where the hull narrows (off the 1m grid, so CPUs never plan a walk along a rail top)
          Rs(x0 - 0.21, x0 - 0.09, zr, prev - 0.15, 4);
          Rs(x0 - 0.21, x0 - 0.09, -prev + 0.15, -zr, 4);
        }
        prev = hb;
      }
      Rs(32.44, 32.56, -5.35, 5.35, 4);
      // stairs up one side (+z), crate steps up the other (-z): 1.4 -> 2.8 -> 4
      St(16, 9.5, '+x', 2, 0, 4);
      crate(18.2, 20.6, -9.6, -7.2, 0, 1.4);
      crate(20.6, 23, -9.6, -7.2, 0, 2.8);
      // a winch (vault it) beside the crane, on the side without its crate steps - the tip round the chain
      // locker stays open (winches out there boxed it into little corners to get caught in) - and bollards
      crate(26.6, 28.2, -5, -3.4, 4, 5.4);
      for (const z of [10, -10]) Bs(24.2, 25, z - 0.4, z + 0.4, 4, 4.8, DARK);

      // ----- the crane: pedestal (cab top 8), crate steps up it, boom back to the bridge roof -----
      Bs(26, 29, -1.5, 1.5, 4, 8, YEL);
      crate(26.2, 28.8, 1.5, 3.1, 4, 6.8);
      crate(26.2, 28.8, 3.1, 4.7, 4, 5.4);
      Bs(3, 26, -0.6, 0.6, 7.6, 8, YEL);
      Ds(25.6, 29.4, -1.9, 1.9, 8, 8.04, DARK);

      // ----- the main deck's side rails -----
      Rs(-23, 23, 13.14, 13.26, 0);
    }

    // the main deck plate, with every hole cut out
    plate(-22.6, 22.6, -13, 13, -0.4, 0, deckHoles, DECK);
    // the deck's edge stripe along the hull (looks only)
    for (const s of [1, -1]) D(-22.6, 22.6, s > 0 ? 12.6 : -13, s > 0 ? 13 : -12.6, 0, 0.02, '#ffd23f');
  },
});

;
/* ==== js/maps/gauntlet.js ==== */
// THE GAUNTLET - race. Three long railed lanes in the sky, run as an S: east along the bottom
// lane, back west along the middle one, east again along the top one to the finish. Every section
// has a SAFE line and a faster EXPERT line; the expert lines are marked with yellow take-off lips.
// Most expert lines fly over a lower grey floor (miss and you land on the slow line, not in the void);
// a few hang over the void (fall and you're back at the start - there are no checkpoints).
//
//  BOTTOM LANE (floor 0, eastbound, z -4..4)
//   1 gates        hurdles (jump) and slots (slide) - one gate lets you pick
//   2 the trough   three big gaps between slabs: slide-jump the first, slide under the beam on the
//                  slab, jump the second, slide-jump or kick off the orange panel over the third.
//                  Miss one: you drop into the grey trough - run it and climb out
//   3 wall-run     no floor (void): wall-run along the orange wall, or hop the low grey posts and
//                  climb out at the end
//   4 the climb    up 8m: kick up the orange chimney, or pull yourself up the switchback steps
//  MIDDLE LANE (westbound, z 10..18)
//   5 the chute    a slick yellow slide down 6m: slide under the beams, jump the hurdle
//   6 the split    the glass splits the lane: left, fly off the end of the chute over the void;
//                  right, a bridge with a block to pull yourself over
//   7 kick alley   the floor's gone: zig-zag kick between the orange walls, or drop to the grey
//                  trough and climb out
//   8 baffles      weave (or kick) past two walls and slide under a slot
//   9 the pad      launch up onto the top lane
//  TOP LANE (eastbound, z 24..32)
//  10 stones       rising stepping stones over the void
//  11 slot dash    a narrow bridge over the void: hurdle, slot, hurdle, slot, hurdle
//  12 the wall     4.6m: kick off the orange panel and pull up in one go, or use the step
//  13 the drop     leap from the top straight to the finish deck, or drop to the grey floor and climb out
//
// Lanes are bounded by invisible walls (to well above anything you can reach) with grey handrails
// marking them, so nothing can be skipped by going round the outside.
// Look: a clear sky, warm white floors, mid-grey low lines and rails, indigo obstacles, one accent
// (yellow: take-off lips, the chute, start and finish lines); kick walls the engine's orange, the
// split's no-kick glass the engine's cyan.
defineMap({
  id: 'gauntlet',
  kind: 'race',
  accent: ['#2e3f8f', '#ffc21a'],
  name: 'The Gauntlet',
  blurb: 'Three lanes in the sky. Every section has a safe line and a fast, risky one: slide-jumps, wall-runs, kick alleys, a chute. Fall in the void and you start over.',
  env: 'sky',
  sky: '#acd8ff',
  fog: [300, 3000],
  hemi: ['#eef6ff', '#525c6a', 0.9],
  sun: [1.0, 40, 70, 25],
  outlineColor: '#1d2533',
  sea: -40,                       // far below: the void
  size: 80,
  killY: -12,
  menuCam: { r: 70, y: 40 },
  spawns: [-67.5, -65, -62.5].flatMap((x) => [-3, -1, 1, 3].map((z) => [x, 0, z])),
  seekerSpawn: [-64, 0, 0],
  race: {
    yaw: -Math.PI / 2,
    finish: { x: 63.5, y: 8, z: 28, w: 9, h: 4, d: 7.6 },
    route: [
      [-64, 0, 0], [-28, 0, 0], [17, 0, 0], [50, 0, 0], [56, 8, -2], [64, 8, 7], [58, 8, 14],
      [30, 2, 14], [2, 2, 14], [-16, 2, 14], [-40, 2, 14], [-46, 2, 18], [-46, 8, 27], [-34, 8, 28],
      [-8, 12.8, 28], [20, 12.8, 28], [30, 17.4, 28], [38, 17.4, 28], [56, 8, 28], [63, 8, 28],
    ],
  },

  build(k) {
    const FLOOR = '#e9e5dc', LOW = '#8d939c', OBST = '#2e3f8f', ACC = '#ffc21a', RAIL = '#5d646e';
    const KICK = { tex: 'kick' };
    // boxes by their ranges
    const B = (x0, x1, y0, y1, z0, z1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, y0, y1, z0, z1, col, o = {}) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, Object.assign({ tex: 'none' }, o));
    const W = (x0, x1, y0, y1, z0, z1) => k.wall((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0);
    // the lane's edge: an invisible wall from far below to far above anything reachable, and a grey
    // handrail showing it (a rail at yt on posts down to yb, at most 4m apart). Along x (at z, `out` =
    // which side is outside: -1 or +1) or along z (at x)
    const Y0 = -30, Y1 = 45;
    const rail = (along, a, b, at, yb, yt) => {
      const bx = (a0, a1, y0, y1, w) => (along ? D(a0, a1, y0, y1, at - w, at + w, RAIL) : D(at - w, at + w, y0, y1, a0, a1, RAIL));
      bx(a, b, yt, yt + 0.12, 0.07);
      const n = Math.max(1, Math.ceil((b - a) / 4));
      for (let i = 0; i <= n; i++) { const p = a + (b - a) * i / n; bx(p - 0.05, p + 0.05, yb - 0.13, yt, 0.05); }   // (feet off any face)
    };
    const edgeX = (x0, x1, z, out, panes) => {
      W(x0, x1, Y0, Y1, out < 0 ? z - 0.5 : z, out < 0 ? z : z + 0.5);
      for (const [a, b, yb, yt] of panes) rail(true, a, b, z, yb, yt);
    };
    const edgeZ = (z0, z1, x, out, panes, ext = 0) => {   // (ext: overlap the side walls at an outside corner)
      W(out < 0 ? x - 0.5 : x, out < 0 ? x : x + 0.5, Y0, Y1, z0 - ext, z1 + ext);
      for (const [a, b, yb, yt] of panes) rail(false, a, b, x, yb, yt);
    };
    const lipAt = (x, y, z0, z1, w = 0.4) => D(x - w / 2, x + w / 2, y, y + 0.02, z0, z1, ACC);
    const hurdle = (x, y, z0, z1, h = 0.9) => B(x - 0.2, x + 0.2, y, y + h, z0, z1, OBST);
    const slot = (x, y, z0, z1, top) => B(x - 0.25, x + 0.25, y + 1.1, top, z0, z1, OBST);   // 1.1 clear: slide under

    // ======================= BOTTOM LANE (floor 0, eastbound, z -4..4) =======================
    // 0 start
    B(-70, -28, -3.4, 0, -4, 4, FLOOR);
    D(-60.3, -59.7, 0, 0.02, -4, 4, ACC);                                       // start line
    // 1 gates
    // (the last slide is 11m+ before the trough: a slide's boost needs 0.9s to come back for the first gap)
    hurdle(-56, 0, -4, 4);
    slot(-51, 0, -4, 4, 5.5);
    hurdle(-46, 0, -4, 0, 1.0);                                                 // pick: jump left, slide right
    slot(-46, 0, 0, 4, 5.5);
    slot(-41, 0, -4, 4, 5.5);
    hurdle(-35.5, 0, -4, 4);
    // 2 the trough: slabs over a grey trough (floor -3.4)
    B(-28, 21, -4.4, -3.4, -4, 4, LOW);
    for (const x of [-20, -4.5, 9]) hurdle(x, -3.4, -4, 4);
    lipAt(-28.2, 0, -4, 4);
    B(-16, -8, -0.4, 0, -4, 4, FLOOR);                                          // slab 1 (12m out: slide-jump)
    slot(-10, 0, -4, 4, 5.5);                                                   // ...with a slot on it
    lipAt(-8.2, 0, -4, 4);
    B(1, 6, -0.4, 0, -4, 4, FLOOR);                                             // slab 2 (9m)
    lipAt(5.8, 0, -4, 4);
    B(8, 16, -3.4, 5.5, -4, -3.6, '#000', KICK);                                // kick panel over the last gap (11m; too tall to climb onto)
    B(14, 17, -3.4, -1.7, 0, 4, LOW);                                           // the way out of the trough: a step...
    B(17, 21, -3.4, 0, -4, 4, FLOOR);                                           // ...and pull up
    // 3 wall-run: no floor from 21 to 41
    B(19, 43, -6, 5, -4, -3.6, '#000', KICK);
    lipAt(20.8, 0, -3.6, 0);
    [[24.5, 1.5], [29.5, -0.5], [34.5, 1.5], [39.5, -0.5]].forEach(([x, z]) => B(x - 1.5, x + 1.5, -7, -1.5, z - 1.5, z + 1.5, LOW));   // the low posts
    B(41, 58, -3.4, 0, -4, 4, FLOOR);
    // 4 the climb to the middle lane (8)
    for (const z of [-3.8, -0.6]) B(53, 58, 0, 8.5, z - 0.2, z + 0.2, '#000', KICK);  // chimney, 2.8 between
    B(52, 58, 0, 2.7, 1.8, 4, FLOOR);                                           // the steps: a switchback -
    B(52, 58, 0, 5.4, -0.4, 1.8, FLOOR);                                        //  up, turn left, up, turn right, up
    B(58, 70, 0, 8, -4, 4, FLOOR);                                              // the corner deck (8)
    B(58, 70, 7, 8, 4, 18, FLOOR);

    // ======================= MIDDLE LANE (westbound, z 10..18) =======================
    // 5 the chute: slick, 8 -> 2 over x 58 -> 30
    const CH = (x) => 2 + 6 * (x - 30) / 28;                                   // chute surface height
    k.ramp(44, 14, 28, 8, 2, 8, '+x', ACC, { slick: true, base: 1 });
    // (beams 1.05 clear of the chute where your body's uphill edge reaches them, and as wide as the chute)
    B(55.3, 55.7, CH(55.7) - 1, CH(55.7) + 0.6, 10, 18, OBST);                // a hurdle at the top,
    slot(45, CH(45.6) - 0.05, 10, 18, 12.5);                                   // then two beams
    slot(38, CH(38.6) - 0.05, 10, 18, 11.5);
    // 6 the split
    B(8, 36, -2, 9.5, 13.8, 14.2, '#000', { tex: 'nokick' });                 // the glass between the two lines
    lipAt(30.2, 2, 10, 13.8);
    B(8, 17, 1, 2, 10, 13.8, FLOOR);                                            // left: 13m off the end of the chute
    B(8, 30, 1, 2, 14.2, 18, FLOOR);                                            // right: the bridge
    B(19, 21, 2, 4.7, 14.2, 18, OBST);                                          //   with a block to climb over
    B(2, 8, 1, 2, 10, 18, FLOOR);
    // 7 kick alley over a trough (floor -1.4)
    B(-16, 2, -2.4, -1.4, 10, 18, LOW);
    lipAt(1.8, 2, 10, 18);
    for (const z of [12.4, 15.6]) B(-16, 2, -1.4, 6, z - 0.2, z + 0.2, '#000', KICK);   // 2.8 between
    B(-16, -13, -1.4, 0.3, 15.8, 18, LOW);                                      // out of the trough: a step and pull up
    B(-40, -16, -1.4, 2, 10, 18, FLOOR);
    // 8 baffles and a slot
    B(-21.3, -20.7, 2, 6, 10, 15.2, OBST);
    B(-27.3, -26.7, 2, 6, 12.8, 18, OBST);
    slot(-33, 2, 10, 18, 6);
    // 9 the pad, in the corner (x -52..-40), up to the top lane's start deck (8)
    B(-52, -40, -1.4, 2, 10, 22, FLOOR);
    k.pad(-46, 2, 19, 3, 2.4, 20, { color: ACC });
    B(-52, -40, 2, 8, 22, 32, FLOOR);
    B(-40, -34, 2, 8, 24, 32, FLOOR);

    // ======================= TOP LANE (eastbound, z 24..32) =======================
    // 10 stones over the void, rising
    lipAt(-34.2, 8, 24, 32);
    [[-30, 26.5, 9.2], [-24, 29.5, 10.4], [-18, 26.5, 11.6]].forEach(([x, z, top]) => B(x - 1.5, x + 1.5, top - 1.2, top, z - 1.5, z + 1.5, FLOOR));
    B(-12, -8, 11.8, 12.8, 25, 31, FLOOR);
    // 11 slot dash: a narrow bridge (z 26.5..29.5)
    B(-8, 20, 11.8, 12.8, 26.5, 29.5, FLOOR);
    hurdle(-4, 12.8, 26.5, 29.5);
    slot(1.5, 12.8, 24, 32, 17);
    hurdle(7, 12.8, 26.5, 29.5);
    slot(12.5, 12.8, 24, 32, 17);
    hurdle(18, 12.8, 26.5, 29.5);
    // 12 the wall (top 17.4)
    B(20, 30, 11.8, 12.8, 24, 32, FLOOR);
    B(30, 38, 11.8, 17.4, 24, 32, FLOOR);
    B(26.5, 30, 12.8, 15.1, 28.5, 32, OBST);                                    // the step
    B(24, 30, 12.8, 17, 24, 24.4, '#000', KICK);                                 // the kick panel
    // 13 the drop: leap from the top straight onto the finish deck (8), or drop to the grey floor
    // (4.6) and climb out
    lipAt(37.8, 17.4, 24, 32);
    B(38, 54, 3.6, 4.6, 24, 32, LOW);
    B(51, 54, 4.6, 6.3, 28.5, 32, LOW);                                         // a step, and pull up
    B(54, 70, 4.6, 8, 24, 32, FLOOR);                                           // the finish deck
    D(58.4, 59, 8, 8.02, 24, 32, ACC);                                        // finish line (the gate is the game's)

    // ======================= edges (invisible walls + handrails) =======================
    // rails: [from, to, post foot, rail height] - the rail 1.2 over the floor beside it
    const A = [[-70, -28, -0.3, 1.2], [-28, 21, -3.6, 1.2], [21, 41, -3, 1.2], [41, 58, -0.3, 1.2]];
    const chute = [0, 1, 2, 3, 4, 5, 6].map((i) => [30 + i * 4, 34 + i * 4, 1, CH(32 + i * 4) + 1.2]);
    const Bm = chute.concat([[8, 30, -1, 3.2], [-16, 8, -1.6, 3.2], [-40, -16, 1.7, 3.2]]);
    const Ct = [[-34, -12, 7, 14], [-12, 20, 11.5, 14], [20, 30, 11.5, 14], [30, 38, 11.5, 18.6], [38, 54, 3.3, 5.8], [54, 70, 7.7, 9.2]];
    // bottom lane
    edgeX(-70, 70, -4, -1, A.concat([[58, 70, 7.7, 9.2]]));
    edgeX(-70, 58, 4, 1, A);
    edgeZ(-4, 4, -70, -1, [[-4, 4, -0.3, 1.2]], 0.5);
    edgeZ(-4, 32, 70, 1, [[-4, 18, 7.7, 9.2], [24, 32, 7.7, 9.2]], 0.5);
    edgeZ(4, 10, 58, -1, [[4, 10, 7, 9.2]]);
    // middle lane
    edgeX(-52, 58, 10, -1, Bm.concat([[-52, -40, 1.7, 3.2]]));
    edgeX(-40, 70, 18, 1, Bm.concat([[58, 70, 7.7, 9.2]]));
    edgeZ(10, 32, -52, -1, [[10, 22, 1.7, 3.2], [22, 32, 7.7, 9.2]], 0.5);
    edgeZ(18, 24, -40, 1, [[18, 22, 1.7, 3.2], [22, 24, 7.7, 9.2]]);
    // top lane
    edgeX(-40, 70, 24, -1, [[-40, -34, 7.7, 9.2]].concat(Ct));
    edgeX(-52, 70, 32, 1, [[-52, -34, 7.7, 9.2]].concat(Ct));
  },
});

;
/* ==== js/maps/pipes.js ==== */
// PIPES - race. A tangle of glossy pipe networks spiralling up through a black void, like the old
// screensaver: square pipes, a cube joint at every elbow and junction, saturated colors. Two laps
// round a 40m square, rising 3m a side, then in along a spoke to the finish deck in the middle.
//
// Every side is two pipes - an inner and an outer strand, each its own network - that step up
// (pull up their risers), dip into U-bends (hop the gap or drop in and climb out) and get crossed
// by thin pipes that come up out of the void, cut across both strands and dive back down:
// slide under them, hop them, or pull up onto one and walk it across to the other strand. The
// strands rejoin at teal junction decks on the corners and split again. No line is marked - read
// the tangle and pick one. Lap 2 runs 12m over lap 1, so a fall from it usually lands on lap 1;
// a fall from lap 1 is back to the start.
//
// Nothing moves. Everything is solid. The finish deck (yellow edges) sits high in the middle and is
// only reached along the spoke: everything else is more than a running jump away or too low.
// Look: a black void, red / white / green / blue networks, teal decks, one warm accent (yellow:
// start, finish).
defineMap({
  id: 'pipes',
  kind: 'race',
  accent: ['#1a968c', '#f2c414'],
  name: 'Pipes',
  blurb: 'A tangle of pipe networks spiralling up through a black void. No marked path: read the pipes, pick a line, climb to the top. Fall off the bottom and you start over.',
  env: 'sky',
  sky: '#000000',
  seaColor: '#000000',
  fog: [300, 3000],
  hemi: ['#eef3ff', '#101216', 0.25],
  sun: [1.05, 50, 80, 30],
  outlineColor: '#07090e',
  sea: -60,
  size: 50,
  killY: -12,
  menuCam: { r: 60, y: 40 },
  spawns: [-30, -28, -26].flatMap((x) => [-23, -21, -19, -17].map((z) => [x, 0, z])),
  seekerSpawn: [-28, 0, -20],
  race: {
    rev: 2,   // bump to wipe the record board without changing the course (2: emptied when it opened to everyone)
    yaw: -Math.PI / 2,
    finish: { x: 0, y: 29, z: 0, w: 7, h: 4, d: 7 },
    // a typical line: round the inner strands, lap 1 then lap 2, then the spoke
    route: [
      [-28, 0, -20], [-17.8, 0, -17.8], [17.8, 3, -17.8], [17.8, 6, 17.8], [-17.8, 9, 17.8], [-17.8, 12, -17.8],
      [17.8, 15, -17.8], [17.8, 18, 17.8], [-17.8, 21, 17.8], [-17.8, 23, 0], [-16, 25, 0], [-8, 27, 0], [0, 29, 0],
    ],
  },

  build(k) {
    const TEAL = '#1a968c', GIRD = '#0b4a47', YEL = '#f2c414';
    const RED = '#c8302a', WHITE = '#d2d5da', GREEN = '#22a04a', BLUE = '#2450c0';
    const PW = 1.4, TW = 1.0, DEEP = -40, R = 20;
    const B = (x0, x1, y0, y1, z0, z1, col, o) => k.box((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, o);
    const D = (x0, x1, y0, y1, z0, z1, col) => k.deco((x0 + x1) / 2, y0, (z0 + z1) / 2, x1 - x0, y1 - y0, z1 - z0, col, { tex: 'none' });   // (flat decals only)
    // the four sides, walked counter-clockwise from the south-west corner: corner, along, outward
    const SIDE = [
      { c: [-R, -R], u: [1, 0], n: [0, -1] },
      { c: [R, -R], u: [0, 1], n: [1, 0] },
      { c: [R, R], u: [-1, 0], n: [0, 1] },
      { c: [-R, R], u: [0, -1], n: [-1, 0] },
    ];
    // a box in a side's own frame: a along it, v outward, y up
    const L = (s, a0, a1, v0, v1, y0, y1, col) => {
      const F = SIDE[s], p = (a, v) => [F.c[0] + F.u[0] * a + F.n[0] * v, F.c[1] + F.u[1] * a + F.n[1] * v];
      const [x0, z0] = p(a0, v0), [x1, z1] = p(a1, v1);
      B(Math.min(x0, x1), Math.max(x0, x1), y0, y1, Math.min(z0, z1), Math.max(z0, z1), col);
    };
    const run = (s, a0, a1, v, top, col, w = PW) => L(s, a0, a1, v - w / 2, v + w / 2, top - w, top, col);       // along the side
    const across = (s, a, v0, v1, top, col, w = TW) => L(s, a - w / 2, a + w / 2, v0, v1, top - w, top, col);   // across it
    const up = (s, a, v, y0, y1, col, w = PW) => L(s, a - w / 2, a + w / 2, v - w / 2, v + w / 2, y0, y1, col); // upright
    const joint = (s, a, v, y, col, w = PW + 0.4) => L(s, a - w / 2, a + w / 2, v - w / 2, v + w / 2, y - w / 2, y + w / 2, col);
    // a teal junction deck (top `top`), its beams, and a pipe holding it up from `foot`
    const deck = (x0, x1, z0, z1, top, foot, col) => {
      B(x0, x1, top - 1, top, z0, z1, TEAL);
      for (const z of [z0 + 1, z1 - 1]) B(x0 + 0.3, x1 - 0.3, top - 1.6, top - 1, z - 0.3, z + 0.3, GIRD);
      const cx = (x0 + x1) / 2, cz = (z0 + z1) / 2;
      B(cx - 0.8, cx + 0.8, foot, top - 1.6, cz - 0.8, cz + 0.8, col);
      B(cx - 1.1, cx + 1.1, top - 2.5, top - 1.6, cz - 1.1, cz + 1.1, col);       // (its joint into the beams)
    };

    // ---------- a side: two strands of pipe runs [a0, a1, rise], and the thin pipes across them ----------
    // runs that meet step up with a riser (pull up); runs with a gap between them dip into a U-bend
    const strand = (s, h, v, runs, col) => {
      runs.forEach(([a0, a1, dy], i) => {
        run(s, a0, a1, v, h + dy, col);
        const nx = runs[i + 1];
        if (!nx) return;
        const [b0, , ny] = nx, y = h + dy, yn = h + ny;
        if (b0 === a1) {            // riser: up from this run to the next, joints at both elbows
          up(s, a1 + PW / 2, v, y - PW, yn, col);
          joint(s, a1 + PW / 2, v, y - PW / 2, col);
          joint(s, a1 + PW / 2, v, yn - PW / 2, col);
        } else {                    // U-bend: down, along under the gap, up (its bottom 2m under the next run)
          const yb = Math.min(y, yn) - 1.2 < yn - 2 ? yn - 2 : Math.min(y, yn) - 1.2;
          up(s, a1 - PW / 2, v, yb - PW, y, col);
          up(s, b0 + PW / 2, v, yb - PW, yn, col);
          run(s, a1 - PW, b0 + PW, v, yb, col);
          for (const [a, yy] of [[a1 - PW / 2, y], [a1 - PW / 2, yb], [b0 + PW / 2, yb], [b0 + PW / 2, yn]]) joint(s, a, v, yy - PW / 2, col);
        }
      });
    };
    const hAt = (runs, h, a) => { const r = runs.find(([a0, a1]) => a >= a0 && a <= a1); return r ? h + r[2] : null; };
    // a thin network across a side at a (v -6..6), its legs at v = +-6: up out of the void (lap 1), or
    // up from the lap 1 pipe under it (lap 2) - so each pair of laps' crossings is one loop of pipe
    // threaded round both laps' strands. slide: 1.15 clear over the higher strand; hop: lying on the
    // lower one; bridge: flush with the higher strand's top (pull up onto it from the lower one)
    const OUT = 6, lowTop = {};
    const cross = (s, h, a, type, inner, outer, col) => {
      const hi = hAt(inner, h, a), ho = hAt(outer, h, a), top0 = Math.max(hi ?? -99, ho ?? -99), lo = Math.min(hi ?? 99, ho ?? 99);
      const top = type === 'slide' ? top0 + 1.15 + TW : type === 'hop' ? lo + TW : top0;
      const key = s + ':' + a, from = lowTop[key] === undefined ? DEEP : lowTop[key];
      lowTop[key] = top;
      across(s, a, -OUT, OUT, top, col);
      for (const v of [-OUT, OUT]) { joint(s, a, v, top - TW / 2, col, TW + 0.4); up(s, a, v, from, top - TW, col, TW); }
      // a junction cube wherever it runs through a strand
      for (const [v, hs] of [[-2.2, hi], [2.2, ho]]) if (hs !== null && top > hs - PW + 0.01 && top - TW < hs - 0.01) joint(s, a, v, Math.max(top - TW / 2, hs - PW / 2), col, PW + 0.4);
    };
    const side = (s, h, inner, outer, cr, cols) => {
      strand(s, h, -2.2, inner, cols[0]);
      strand(s, h, 2.2, outer, cols[1]);
      cr.forEach(([a, type], i) => cross(s, h, a, type, inner, outer, cols[2 + (i % 2)]));
    };

    // ---------- lap 1 (0 -> 12) ----------  (crossings at a = 11, 21, 29 on every side; the strands'
    // risers and U-bends keep a metre clear of them)
    const A = [[4, 14, 0], [17, 25, 1], [25, 36, 3]], Bp = [[4, 13, 0], [13, 24, 2], [26, 36, 3]];
    const C = [[4, 18, 0], [18, 26, 2], [26, 36, 4]], Dp = [[4, 14, 0], [17, 24, 2], [24, 36, 3]];
    side(0, 0, A, Bp, [[11, 'slide'], [21, 'bridge'], [29, 'hop']], [RED, WHITE, GREEN, BLUE]);
    side(1, 3, C, Dp, [[11, 'hop'], [21, 'bridge'], [29, 'slide']], [RED, WHITE, BLUE, GREEN]);
    side(2, 6, Bp, A, [[11, 'slide'], [21, 'bridge'], [29, 'hop']], [RED, WHITE, GREEN, BLUE]);
    side(3, 9, Dp, C, [[11, 'hop'], [21, 'slide'], [29, 'bridge']], [RED, WHITE, BLUE, GREEN]);
    // ---------- lap 2 (12 -> 23): the strands swap colors ----------
    side(0, 12, C, A, [[11, 'bridge'], [21, 'slide'], [29, 'hop']], [BLUE, GREEN, RED, WHITE]);
    side(1, 15, Bp, Dp, [[11, 'hop'], [21, 'bridge'], [29, 'slide']], [BLUE, GREEN, WHITE, RED]);
    side(2, 18, A, C, [[11, 'slide'], [21, 'hop'], [29, 'bridge']], [BLUE, GREEN, RED, WHITE]);
    side(3, 21, [[4, 13, 0], [13, 18, 2]], [[4, 13, 0], [13, 18, 1]], [[11, 'hop']], [BLUE, GREEN, WHITE]);

    // ---------- the corners: junction decks (8m), lap 2's standing on lap 1's ----------
    const cornerTops = [0, 3, 6, 9, 12, 15, 18, 21];
    cornerTops.forEach((top, i) => {
      const [cx, cz] = SIDE[i % 4].c;
      deck(cx - 4, cx + 4, cz - 4, cz + 4, top, i < 4 ? DEEP : cornerTops[i - 4], [GREEN, BLUE, WHITE, RED][i % 4]);
    });
    // the start: the south-west deck runs out west, a yellow start line at its east end
    B(-32, -24, -1, 0, -24, -16, TEAL);
    for (const z of [-23, -17]) B(-31.7, -24, -1.6, -1, z - 0.3, z + 0.3, GIRD);
    B(-29, -27.6, DEEP, -1.6, -20.7, -19.3, BLUE);
    D(-24.3, -23.7, 0, 0.02, -24, -16, YEL);

    // ---------- the spoke: from lap 2's west side in to the finish ----------
    // where lap 2's west strands end: a junction deck (23), then the spoke in along z = 0: up 2 onto
    // it (25), up its riser (27), and pull up onto the finish deck (29)
    // (the deck has no pipe under it: one would make a chimney with lap 1's west strands)
    B(-24, -16, 22, 23, -4, 3, TEAL);
    for (const z of [-3, 2]) B(-23.7, -16.3, 21.4, 22, z - 0.3, z + 0.3, GIRD);
    B(-16, -9, 23.6, 25, -0.7, 0.7, RED);
    B(-16.9, -15.1, 23, 25.2, -0.9, 0.9, RED);                   // (its elbow, sitting on the deck)
    B(-9, -7.6, 23.6, 27, -0.7, 0.7, RED);                       // the riser
    B(-9.2, -7.4, 23.4, 25.2, -0.9, 0.9, RED);
    B(-9.2, -7.4, 25.4, 27.2, -0.9, 0.9, RED);
    B(-9, -3.5, 25.6, 27, -0.7, 0.7, RED);
    // the finish deck, on a fat blue main up out of the void, yellow round its edge
    B(-3.5, 3.5, 28, 29, -3.5, 3.5, TEAL);
    B(-1.5, 1.5, DEEP, 28, -1.5, 1.5, BLUE);
    B(-3.5, 3.5, 26, 28, -3.5, 3.5, BLUE);                     // (its head: a big manifold block, so nothing slips under the deck)
    for (const [x0, x1, z0, z1] of [[-3.5, 3.5, -3.5, -3.1], [-3.5, 3.5, 3.1, 3.5], [-3.5, -3.1, -3.1, 3.1], [3.1, 3.5, -3.1, 3.1]]) D(x0, x1, 29, 29.02, z0, z1, YEL);


    const pair = (x0, x1, y0, y1, z0, z1, col) => {                  // two pipes side by side (1m x 2m)
      if (x1 - x0 > z1 - z0) { B(x0, (x0 + x1) / 2, y0, y1, z0, z1, col); B((x0 + x1) / 2, x1, y0, y1, z0, z1, col); }
      else { B(x0, x1, y0, y1, z0, (z0 + z1) / 2, col); B(x0, x1, y0, y1, (z0 + z1) / 2, z1, col); }
    };
    // ---------- the speedrun skip: under the south edge of the start corner, up to lap 2 ----------
    // Two pairs of pipes hang in the void just south of the start corner deck, 2.8m apart (z -27.8..-25,
    // x -21..-19): the north pair holds up the south edge of lap 2's first deck (12), the south pair runs
    // on up and away. A thin white pipe runs along between them a metre under the deck (top -1): drop off
    // the deck's south edge onto it (west of the north pair), walk it into the gap, then chain eight kicks
    // straight up, pull up onto the north pair's top (11) and onto the deck: all of lap 1 skipped. Hard to
    // find and to chain; but nothing moves, so once learned it works every time. Fall off the thin pipe
    // or miss a kick and you're in the void - back to the start, a few metres away.
    B(-36, -14, -2, -1, -26.9, -25.9, WHITE);
    for (const x of [-36, -14]) { B(x - 0.7, x + 0.7, -2.2, -0.8, -27.1, -25.7, WHITE); B(x - 0.5, x + 0.5, DEEP, -2.2, -26.9, -25.9, WHITE); }
    pair(-21, -19, DEEP, 12.6, -28.8, -27.8, GREEN);
    B(-21.2, -18.8, 12.4, 13.8, -29, -27.8, GREEN);                  // (its elbow, turning south)
    B(-20.5, -19.5, 12.6, 13.6, -34, -29, GREEN);
    B(-20.7, -19.3, 12.4, 13.8, -34.7, -33.3, GREEN);
    B(-20.5, -19.5, DEEP, 12.4, -34.5, -33.5, GREEN);              // (and down into the void)
    pair(-21, -19, DEEP, 11, -25, -24, BLUE);                         // the north pair, under the deck's edge

    // ---------- expert lines: kick chimneys in the inner ring, and bridges straight across the core ----------
    // Three pairs of pipes 2.8m apart (each a pair of pipes side by side, so the faces are 2m wide)
    // stand in the inner ring; four or five chained kicks up between them reach a pipe that crosses the
    // core to the far side, a side further round. Each bridge is 4m+ over anything near it and only
    // reachable by the kicks. A miss drops you into the void (lap 1) or back onto lap 1 (lap 2).
    // 1) lap 1, south -> north (x 3.5..6.3 at z -15.5..-13.5, from the south inner strand up to 8)
    pair(2.5, 3.5, DEEP, 7, -15.5, -13.5, GREEN);                    // the west pipes: they turn north and become...
    B(2.3, 3.5, 6.8, 8.2, -15.7, -13.3, GREEN);
    B(2.5, 3.5, 7, 8, -13.3, 17.1, GREEN);                           // ...the bridge across the core onto the north inner strand (8)
    pair(6.3, 7.3, DEEP, 7, -15.5, -13.5, BLUE);                     // the east pipes turn east into the a = 29 crossing's leg
    B(6.3, 7.5, 6.8, 8.2, -15.7, -13.3, BLUE);
    B(7.5, 8.5, 7, 8, -14.5, -13.5, BLUE);
    // 2) lap 1, east -> west (z -6.9..-4.1 at x 12.5..14.5, from the east inner strand up to 12)
    pair(12.5, 14.5, DEEP, 11, -7.9, -6.9, RED);                     // the south pipes turn west and become...
    B(12.3, 14.7, 10.8, 12.2, -8.1, -6.9, RED);
    B(-17.1, 12.3, 11, 12, -7.9, -6.9, RED);                         // ...the bridge across the core onto the west inner strand (12)
    pair(12.5, 14.5, DEEP, 10, -4.1, -3.1, WHITE);                   // the north pipes turn north into the a = 21 crossing's leg
    B(12.3, 14.7, 9.8, 11.2, -4.1, -2.9, WHITE);
    B(13, 14, 10, 11, -2.9, 0.5, WHITE);
    // 3) lap 2, south -> north (x -6.3..-3.5 at z -15.5..-13.5, hanging from the south inner strand (12) up to 19)
    pair(-3.5, -2.5, 11.6, 18, -15.5, -13.5, WHITE);                 // the east pipes turn north and become...
    B(-3.7, -2.5, 17.8, 19.2, -15.7, -13.3, WHITE);
    B(-3.5, -2.5, 18, 19, -13.3, 17.1, WHITE);                       // ...the bridge across the core onto the north inner strand (19)
    pair(-7.3, -6.3, 11.6, 17, -15.5, -13.5, RED);                   // the west pipes turn west and down into the a = 11 crossing
    B(-7.5, -6.3, 16.8, 18.2, -15.7, -13.3, RED);
    B(-8.5, -7.5, 17, 18, -14.5, -13.5, RED);
    B(-9.5, -8.5, 12.2, 18, -14.5, -13.5, RED);
    for (const x of [-6.8, -3]) { B(x - 0.5, x + 0.5, 10.6, 11.6, -17.1, -15.5, x < -5 ? RED : WHITE); B(x - 0.7, x + 0.7, 10.4, 11.8, -15.7, -13.3, x < -5 ? RED : WHITE); }   // (fed from under the strand)
  },
});

