          // the end of a narrow ledge before you got over the top) and move onto the ledge - keeping
          // about 60% of your running speed: a mantle slows you down, but never to a stop
          const keep = Math.max(2.5, Math.min(M.runSpeed * 0.65, Math.max(Math.hypot(v.x, v.z), this.recentSpeed || 0) * 0.6));
          v.x = -n.x * keep;
