      c.on('open', () => { const o = this.fast.get(c.peer); if (o && o !== c) { try { o.close(); } catch (e) {} } this.fast.set(c.peer, c); });
      c.on('data', (d) => { if (this.isHost && this.conns.has(c.peer)) this.onMessage(c.peer, d); });
      c.on('close', () => { if (this.fast.get(c.peer) === c) this.fast.delete(c.peer); });
      c.on('error', () => {});
