    // instead of trying for almost a minute)
    const sig = setTimeout(() => { if (!reached) fail('Could not reach the matchmaking server (0.peerjs.com). Your network may block it, or it may be down - try again in a minute, or another network.', false); }, 9000);
    const timer = setTimeout(() => fail(reached
      ? 'Found the lobby but could not connect to the host. One of your networks is blocking connections - try a phone hotspot, or another network.'
      : 'Could not reach the matchmaking server (0.peerjs.com). Your network may block it - try another network or a phone hotspot.', !reached), relay ? 20000 : 26000);

