    const total = w.reduce((a, b) => a + b, 0);
    let r = rnd() * total, ti = 0;
    for (; ti < TIERS.length - 1; ti++) { r -= w[ti]; if (r < 0 && w[ti] > 0) break; }
    const all = COLORS.filter((it) => it.tier === TIERS[ti].id), fresh = all.filter((it) => !have.has(it.id));
