    for (const id in inv.dupes || {}) { const c = byId[id]; if (c && c.kind === 'color') w += tier(c.tier).sell * Math.max(0, +inv.dupes[id] || 0); }
    for (const k in inv.crates || {}) w += crateWorth(k) * Math.max(0, +inv.crates[k] || 0);
