  // (about +5% more each time the number of rebirths doubles: 1 -> 5%, 3 -> 10%, 7 -> 15%, 15 -> 20%)
  const rebirthBonus = (n) => (n > 0 ? 0.05 * Math.log2(1 + n) : 0);
