const starSvg = (st) => `<svg viewBox="0 0 24 24" aria-hidden="true"><polygon points="${starPts(12, 12.8, 11, st.ranked).map((q) => q.map((v) => v.toFixed(2)).join(',')).join(' ')}" fill="${st.color === 'prism' ? 'url(#starPrism)' : st.color}" stroke="${st.ranked ? '#000' : '#1f2433'}" stroke-width="${st.ranked ? 2.4 : 1.1}" stroke-linejoin="miter" stroke-miterlimit="12"/></svg>`;
// what the star means, for its hover note: "#1 on: Wins, Collection, Cloud Spire record"
const boardName = (b) => b === 'wins' ? 'Wins' : b === 'collection' ? 'Collection' : b === 'networth' ? 'Net worth' : b === 'ranked' ? 'Ranked' : b.startsWith('race:') ? `${(getMap(b.slice(5)) || { name: b.slice(5) }).name} record` : 'a leaderboard';
const starTip = (name) => { const b = starBoards(name), st = starInfo(name); return `${st ? st.tier[0].toUpperCase() + st.tier.slice(1) : ''} star: #1 on ${b.map(boardName).join(', ')}${b.length > 1 ? ` (${b.length} boards)` : ''}. More boards, better star: ${starTiers().map((t) => t[1]).join(', ')}. #1 on Ranked: a sharp star with a black edge`; };
// every badge by a name: developer, then their star (one can have both)
