const starHtml = (name) => { const st = starInfo(name); return devHtml(name) + (st ? ` <span class="lb-star${st.ranked ? ' rk' : ''}" data-tip="${esc(starTip(name))}" aria-label="${esc(starTip(name))}">${starSvg(st)}</span>` : ''); };
// a developer: a green triangle by their name (only the account server says who - never a host)
