// #1 on the Ranked board: the server gave me today's free crate (see eloCrown in api/account.js) -
// fetch the inventory again and say so, once a day
function crownNote() {
  const c = Account.crown;
  if (!c || !Account.me || Account.loading || c.name !== Account.me.name.toLowerCase()) return;
  let seen = '';
  try { seen = localStorage.getItem('scamper-crown') || ''; } catch (e) {}
  if (seen === c.day) return;
  try { localStorage.setItem('scamper-crown', c.day); } catch (e) {}
  Account.reload();
  // (once per player, not once per device: the server says if another device already told them today)
  Account.note('crown:' + String(c.day).toLowerCase().replace(/[^a-z0-9-]/g, '')).then((first) => {
    if (first === false) return;
    if (inGame) addFeed('#1 on the Ranked board: a free crate is in your Shop');
    else showMsg('#1 on Ranked', 'You\'re the highest rated player, so today\'s free crate is yours - it\'s waiting in your Shop. Stay on top to get another one tomorrow.');
  });
}
