  if (!owns('ghost')) c.ghost = false;
  if (!owns('neon')) c.neon = false;
  if (!owns('cobra')) c.cobra = false;
  if (!owns('flags')) c.flag = '';   // (developer only for now - the Shop's Skins tab)
  if (!owns('glint')) c.glint = false;
  if (!owns('contrail')) c.trail = false;
  if (!owns('stardust')) c.dust = false;
  if (!owns('aurora')) c.aurora = false;
