function ensurePlayer(id, name, color, eye = '#ffffff', cos = null) {
  let p = players.get(id);
  const glowWas = !!(p && p.cos && p.cos.glow);
  if (p) p.cos = cos;
  if (!p) {
    p = { id, name, color, eye, cos, talk: false, tp: new THREE.Vector3(0, -100, 0), yaw: 0, pitch: 0, mode: 0, snapNext: true, avatar: null };
    players.set(id, p);
    if (id !== myId) p.avatar = makeAvatar(p);
  } else if (p.name !== name || p.color !== color || p.eye !== eye || glowWas !== !!(cos && cos.glow)) {
    p.name = name;
    p.color = color;
    p.eye = eye;
    if (p.avatar) { removeAvatar(p); p.avatar = makeAvatar(p); p.snapNext = true; }
  }
  return p;
}

function removePlayer(id) {
  const p = players.get(id);
  if (!p) return;
  if (p.avatar) removeAvatar(p);
  dropTrail(id);
  players.delete(id);
}

function setPose(p, s) {
  if (!Array.isArray(s) || s.length < 6) return;
  const dx = s[0] - p.tp.x, dy = s[1] - p.tp.y, dz = s[2] - p.tp.z, now = performance.now();
  if (dx * dx + dy * dy + dz * dz > 36) p.snapNext = true;
  // how fast they're going (between updates they're drawn carrying on at this speed, so they move
  // smoothly instead of stopping and jumping 20 times a second)
  const gap = (now - (p.tAt || 0)) / 1000;
  if (p.snapNext || gap > 0.3) { p.vx = p.vz = 0; }
  else if (gap > 0.015) { p.vx = dx / gap; p.vz = dz / gap; if (Math.hypot(p.vx, p.vz) > 30) p.vx = p.vz = 0; }
  p.tAt = now;
  p.tp.set(+s[0] || 0, +s[1] || 0, +s[2] || 0);
  p.yaw = +s[3] || 0;
  p.pitch = +s[4] || 0;
  if (s.length === 6) { p.mode = (s[5] | 0) & 3; p.talk = ((s[5] | 0) & 4) > 0; }
  else { p.mode = s[5] | 0; p.talk = !!s[6]; }
}

