const isHex = (c) => typeof c === 'string' && /^#[0-9a-f]{6}$/i.test(c);
function pickColor(want) { return isHex(want) ? nearestIn(ALL_HEX, want.toLowerCase()) : COLORS[Math.floor(Math.random() * COLORS.length)]; }
