    rnd: game.rnd ? { evs: game.rnd.evs, left: r2(game.rnd.left), seed: game.rnd.seed } : null,
    lastTag: H.lastTag ? { from: H.lastTag.from, to: H.lastTag.to, ago: (performance.now() - H.lastTag.time) / 1000 } : null,
