  if (!isPlaying() || game.mode !== 'race' || game.rl > 0 || !r || r !== w.race || r.done[id] !== undefined || performance.now() - w.at > 3000) { finishWait.delete(id); return; }
  const f = World.map.race.finish, s = 2.5;
  const inBox = (p) => p && Math.abs(p.x - f.x) <= f.w / 2 + s && Math.abs(p.z - f.z) <= f.d / 2 + s && p.y >= f.y - s && p.y <= f.y + f.h + s;
  // (and they must have been seen coming up to it - not just appearing on it)
  if (!H.nearFinish || !H.nearFinish[id] || performance.now() - H.nearFinish[id] < 400) return;
  if (players.get(id) && performance.now() - (players.get(id).warpAt || -1e9) < 8000) return;
  // where the host sees them now, or anywhere in the last 0.7s (they may already be past the line)
