  r.done[id] = Math.max(0, Math.round(t * 10) / 10);
  r.order.push(id);
  r.order.sort((x, y) => r.done[x] - r.done[y]);
  hostFeed(`${nameOf(id)} finished ${ord(r.order.indexOf(id) + 1)} - ${fmtRace(r.done[id])}`);
