    R.len = [0];
    for (let i = 1; i < R.length; i++) R.len.push(R.len[i - 1] + Math.hypot(R[i][0] - R[i - 1][0], R[i][1] - R[i - 1][1], R[i][2] - R[i - 1][2]));
