    if (p.vx || p.vz) { const ahead = Math.min(0.1, (performance.now() - p.tAt) / 1000); wrapTmp.x += p.vx * ahead; wrapTmp.z += p.vz * ahead; }
    World.nearestCopy(wrapTmp, a.root.position);
