const inkFor = (hex) => { const c = new THREE.Color(hex); return (0.299 * c.r + 0.587 * c.g + 0.114 * c.b) > 0.6 ? '#1f2433' : '#ffffff'; };
let palFor = '';   // which half the swatch palette is open for: 'body' | 'eye' | ''
