// Public lobby: the game's own ongoing lobbies, "Lobby 1", "Lobby 2"... Join the fullest one with room (so
// Lobby 1 fills up before Lobby 2 gets anyone); none: host the next free number. Like ranked, from the lobby
// list the Play page already loads - nothing extra for the server. A lobby only lives while people are in it
// (a host away 5 minutes leaves it - see HOST_AFK_MS), and a handover keeps its name
let autoLobby = '', publicSeek = false;   // (hosting one: its name; publicSeek: joining one - if it's gone, try again)
const AUTO_RE = /^Lobby (\d{1,3})$/;
async function publicLobbies(maxAge) {
  if (!lobbiesSeen.list || Date.now() - lobbiesSeen.at > maxAge) { const l = await Account.lobbies(); if (l) lobbiesSeen = { list: l, at: Date.now() }; }
  return (lobbiesSeen.list || []).filter((l) => !l.test && !l.hidden && !l.ranked && AUTO_RE.test(l.title || ''));
}
async function playPublic() {
  if (banned() || serverBlocks()) return;
  setStatus('Finding a public lobby…');
  menuBusy(true);
  const dead = rkDead();
  const pick = (all) => all.filter((l) => l.n < l.max && l.code !== Net.code && !(l.playing && l.mode === 'Duel') && !(Date.now() - (dead[l.code] || 0) < 180e3))
    .sort((a, b) => b.n - a.n || +AUTO_RE.exec(a.title)[1] - +AUTO_RE.exec(b.title)[1]);
  let all = await publicLobbies(15000), open = pick(all);
  if (!open.length) { all = await publicLobbies(0); open = pick(all); }   // (a fresh look before starting a new one)
  menuBusy(false);
  if (open.length) { publicSeek = true; fillCode(open[0].code); joinLobby(false); return; }
  // none with room: the next free number
  const used = new Set(all.map((l) => +AUTO_RE.exec(l.title)[1]));
  let n = 1;
  while (used.has(n)) n++;
  lobbyPublic = true; lobbyRanked = false; autoLobby = `Lobby ${n}`;
  hostGame();
}
$('publicBtn').onclick = () => playPublic();
// alone in a public lobby: if another one has people in it (or another lone one with a lower code), move
