function hostGame(solo) {
  audio();
  watchOnly = false;
  const name = getName();
  setStatus(solo ? 'Starting…' : 'Creating your lobby…');
  menuBusy(true);
  (solo ? Net.startSolo.bind(Net) : Net.host.bind(Net))((err) => {
    if (err) { setStatus(err, true); menuBusy(false); return; }
    myId = Net.id;
    // the lobby starts on a map that fits the mode you're hosting (the menu's backdrop may be a race
    // course while you're on Bomb Tag, or the other way round): a random one of the right kind
    const mk = modeInfo(hostSetup.mode).kind;
    if (mk !== 'gp' && (World.map.kind === 'race') !== (mk === 'race')) {
      const fit = MAPS_OK().filter((m) => (m.kind === 'race') === (mk === 'race') && !m.devOnly);
      if (fit.length) loadMap(fit[Math.floor(Math.random() * fit.length)].id);
    }
    ensurePlayer(myId, name, pickColor(settings.color), pickEye(settings.eye), myCos());
    game.scores[myId] = { it: 0, tags: 0 };
    const sp = randomSpawn();
    me.teleport(sp, faceCenter(sp));
    enterGame();
    pushState();
    sendSkin();
    lobbyBeat();
    if (solo) setTimeout(() => Account.here(hereId, false, settings.guestName, soloNow(), inGame), 3000);   // (the developer's list shows it)
  });
}

// this tab, for this page load: a host that sees the same tab come in twice (a join that went
// through twice) drops the older connection, so nobody gets a frozen copy of themselves
const TAB_ID = [...crypto.getRandomValues(new Uint8Array(6))].map((x) => x.toString(16).padStart(2, '0')).join('');
// what a joiner says first. A developer watching says only that (see hostHandle)
const helloMsg = (name) => (watchOnly ? { t: 'hello', v: CONFIG.version, spec: 1 }
  : { t: 'hello', v: CONFIG.version, name, color: settings.color, eye: settings.eye, cos: myCos(), acct: !!Account.me, gid: Account.guestId, tab: TAB_ID });
function join() { joinLobby(false); }
function watchLobby() { if (Account.me && Account.me.dev) joinLobby(true); }
let joinBusy = 0;   // (a join already on its way: don't start a second one - it would connect twice)
function joinLobby(watch) {
  if (Date.now() - joinBusy < 40000 && !inGame) return;
  audio();
  const code = $('codeInput').value.toUpperCase().replace(/[^A-Z]/g, '');
  if (code.length !== 4) { setStatus('Lobby codes are 4 letters.', true); return; }
  if ((!watch && banned()) || serverBlocks()) return;
  const name = getName();
  watchOnly = watch;
  setStatus(`${watch ? 'Watching' : 'Joining'} ${code}…`);
  menuBusy(true);
  joinBusy = Date.now();
  Net.join(code, (err) => {
    joinBusy = 0;
    if (err && rankedSeek) { rankedSeek = false; rkDeadAdd(code); hostRanked(); return; }   // (that ranked lobby's gone: start one)
    if (err && publicSeek) { publicSeek = false; rkDeadAdd(code); playPublic(); return; }   // (that public lobby's gone: the next one, or a new one)
    publicSeek = false;
    rankedSeek = false;
    if (err) {
      setStatus(err, true);
      menuBusy(false);
      syncCode();
      void $('codeBoxes').offsetWidth;
      $('codeBoxes').classList.add('bad');
      return;
    }
    myId = Net.id;
    const sp = randomSpawn();
    me.teleport(sp, faceCenter(sp));
    enterGame();
    hostSeal = '';
    Net.send(helloMsg(name));
    if (myImg() && !watchOnly) Net.send({ t: 'skin', img: myImg() });
    if (watchOnly) showBanner('<div class="big">WATCHING</div><div>Nobody can see you or knows you\'re here. Click to switch players</div>', 4);
  });
}
