$('visRow').innerHTML = '<span class="cpu-lbl">Who can join</span><div class="pills"><button class="pill" type="button" data-vis="public" title="Listed under Public lobbies on everyone\'s Play page">Public</button><button class="pill" type="button" data-vis="private" title="Only people with the code can join">Private</button></div>'
  + '<input id="lobbyName" maxlength="24" spellcheck="false" autocomplete="off" aria-label="Lobby name">';
const lobbyTitle = () => autoLobby || ITEMS.censor(String(settings.lobbyName || '').replace(/[^A-Za-z0-9 _'!?&.,-]/g, '').replace(/\s+/g, ' ').trim().slice(0, 24));
