  let list = await Account.lobbies();
  $('pubHead').textContent = Account.me && Account.me.dev ? 'Lobbies' : 'Public lobbies';   // (the developer sees private ones too)
  if (list === null) { ul.innerHTML = `<li class="pub-empty">Couldn't load the list${Account.down ? ' - the account server is down (see above)' : ' - try Refresh in a moment'}.</li>`; return; }
